
/* src/Components/AnnotationGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of annotations.
 */
class AnnotationGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param annotationGroupDom {Object} - D3 selector of the annotations group
     * @param annotationSelGroupDom {Object} - D3 selector of the selection shape group
     */
    constructor(opts, utils, annotationGroupDom, annotationSelGroupDom) {
        this.opts = opts;
        this.utils = utils;
        this.annotationGroupDom = annotationGroupDom;
        this.annotationSelGroupDom = annotationSelGroupDom;

        //Annotation object id -> selector
        this.labelToSelMap = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the text representation for a label within the SVG.
     *
     * @param labelId {Number} - the unique id of the label
     * @param label {String} - the text to show in the SVG
     * @param coordinates {Object} - the position of the center of the text (x-
     * and y-coordinates)
     * @param color {String} - valid CSS color for the text
     * @param structureId {Number} - id of structure to which this label belongs
     */
    drawLabel({id: labelId, label, coordinates, color, additionalInformation},
        structureId = undefined
    ) {
        const sels = {};
        const {
            sel: labelSel, x, y, width
        } = this.utils.text.placeCenteredText(this.annotationGroupDom, label, coordinates, color);
        if (this.opts.geomineMode && additionalInformation &&
            additionalInformation.nglFeatureType) {
            const styles = {
                'fill': additionalInformation.backgroundColor,
                'opacity': additionalInformation.opacity
            };
            if (additionalInformation.nglFeatureType !== 'point' &&
                additionalInformation.nglFeatureType !== 'angle') {
                styles['stroke'] = this.opts.colors.DEFAULT;
                styles['stroke-width'] = 0.5;
            }
            if (additionalInformation.nglFeatureType === 'secondarystructure') {
                styles['stroke-dasharray'] = '0 1.2';
                styles['stroke-linecap'] = 'round';
                styles['stroke-width'] = 0.9;
            }
            sels.backgroundSel = this.utils.circle.addCircleToSvg(this.annotationSelGroupDom,
                '',
                coordinates,
                additionalInformation.backgroundRadius,
                styles
            );
            if (additionalInformation.nglFeatureType === 'angle' ||
                additionalInformation.nglFeatureType === 'point') {
                sels.backgroundSel.lower();
            }
        }
        sels.labelSel = labelSel;
        const {mouseSels, selectorShapes} = this.utils.selector.drawTextLabelSelectors(label,
            coordinates,
            width,
            this.annotationSelGroupDom,
            ''
        );
        if (this.opts.geomineMode && additionalInformation &&
            additionalInformation.nglFeatureType &&
            (additionalInformation.nglFeatureType === 'angle' ||
            additionalInformation.nglFeatureType === 'point')) {
            mouseSels[0].lower();
        }
        sels.mouseSels = mouseSels;
        sels.selectorShapes = selectorShapes;
        sels.placementInfo = {
            x: x, y: y
        };
        sels.structureId = structureId;
        this.labelToSelMap[labelId] = sels;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies movement to a label's text element following given offsets.
     *
     * @param labelId {Number} - the unique id of the label
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveLabel(labelId, {x: xOffset, y: yOffset}) {
        const {
            labelSel, backgroundSel, mouseSels, placementInfo, selectorShapes
        } = this.labelToSelMap[labelId];
        this.utils.text.moveTextByPlacementInfo(labelSel, placementInfo, xOffset, yOffset);
        this.utils.selector.moveAllSelectors(mouseSels, selectorShapes, xOffset, yOffset);
        if (this.opts.geomineMode && backgroundSel) {
            const newPosition = selectorShapes[0].coordinates;
            this.utils.circle.moveCircleElement(backgroundSel.node(), newPosition.x, newPosition.y);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches the text element of a label from the DOM.
     *
     * @param labelId {Number} - the unique id of the label
     */
    removeLabelFromDOM(labelId) {
        const {labelSel, backgroundSel, mouseSels} = this.labelToSelMap[labelId];
        labelSel.remove();
        if (this.opts.geomineMode && backgroundSel) {
            backgroundSel.remove();
        }
        mouseSels.forEach(mouseSel => {
            mouseSel.remove();
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches the text element of a label to the DOM (to be called after
     * application of removeLabelFromDOM()).
     *
     * @param labelId {Number} - the unique id of the label
     */
    redrawLabel(labelId) {
        const {labelSel, backgroundSel, mouseSels} = this.labelToSelMap[labelId];
        this.annotationGroupDom.node().appendChild(labelSel.node());
        if (this.opts.geomineMode && backgroundSel) {
            this.annotationSelGroupDom.node().appendChild(backgroundSel.node());
        }
        mouseSels.forEach(mouseSel => {
            this.annotationSelGroupDom.node().appendChild(mouseSel.node());
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached information for a label's text element.
     *
     * @param labelId {Number} - the unique id of the label
     */
    purgeLabelFromCache(labelId) {
        delete this.labelToSelMap[labelId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves the saved bbox draw limits of the text element of a label.
     *
     * @param labelId {Number} - the unique id of the label
     * @returns {Array} - array of objects detailing draw limits
     */
    getLabelDrawLimits(labelId) {
        return [
            {
                limits: BaseUtils.convertBBoxToMaxes(BaseUtils.getSelBBox(this.labelToSelMap[labelId].labelSel))
            }
        ];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves the saved bbox of the text element of a label.
     *
     * @param labelId {Number} - the unique id of the label
     * @returns {Array} - array of objects detailing bbox
     */
    getLabelBBox(labelId) {
        return BaseUtils.getSelBBox(this.labelToSelMap[labelId].labelSel);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves information on the selector shape around a label.
     *
     * @param labelId {Number} - the unique id of the label
     * @returns {Array} - array containing an object describing the shape
     */
    getLabelSelShapes(labelId) {
        return this.labelToSelMap[labelId].selectorShapes;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Indicates that a label is hovered by the user by switching the color of
     * its corresponding selection shape to the hover color.
     *
     * @param labelId {Number} - the unique id of the label
     */
    hoverLabel(labelId) {
        const labelSels = this.labelToSelMap[labelId];
        this.utils.selector.switchTextLabelSelectorStatus(labelSels, SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an annotation in the draw area by switching the color of its
     * corresponding selection shape to the selection color.
     *
     * @param labelId {Number} - the unique id of the annotation to select
     */
    selectLabel(labelId) {
        const labelSels = this.labelToSelMap[labelId];
        this.utils.selector.switchTextLabelSelectorStatus(labelSels, SelectorStatus.select);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously hovered label, removes color from its corresponding
     * selection shape.
     *
     * @param labelId {Number} - the unique id of the label
     */
    unselectLabel(labelId) {
        const labelSels = this.labelToSelMap[labelId];
        this.utils.selector.switchTextLabelSelectorStatus(labelSels, SelectorStatus.unselect);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the color of an annotation's corresponding selection shape.
     *
     * @param labelId {Number} - the unique id of the label
     * @param color {String} - valid CSS color
     */
    recolorAnnotationSelector(labelId, color) {
        const labelSels = this.labelToSelMap[labelId];
        this.utils.selector.switchTextLabelSelectorColor(labelSels, color);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides annotations by changing the corresponding display properties of the
     * svg elements. Also hides the selectors.
     *
     * @param labelIds {Array} - id of labels to hide
     */
    hideAnnotations(labelIds) {
        for (const [labelId, labelObj] of Object.entries(this.labelToSelMap)) {
            if (labelIds.includes(parseInt(labelId))) {
                labelObj.labelSel.classed('ia-drawer-hide-elem', true);
                if (this.opts.geomineMode && labelObj.backgroundSel) {
                    labelObj.backgroundSel.classed('ia-drawer-hide-elem', true);
                }
                for (const mouseSel of labelObj.mouseSels) {
                    mouseSel.classed('ia-drawer-hide-elem', true);
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides annotations by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all annotations
     * @param label {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide annotations from
     * @param visibilityClass {String} - CSS class for show/hide
     */
    setVisibility(full, label, structureId, visibilityClass) {
        if (full || label) {
            for (const labelObj of Object.values(this.labelToSelMap)) {
                if (labelObj.structureId === structureId) {
                    labelObj.labelSel.classed(visibilityClass, true);
                    if (this.opts.geomineMode && labelObj.backgroundSel) {
                        labelObj.backgroundSel.classed(visibilityClass, true);
                    }
                    for (const mouseSel of labelObj.mouseSels) {
                        mouseSel.classed(visibilityClass, true);
                    }
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Converts annotation bbox object to object of minima
     * and maxima.
     *
     * @param id {Number} - id of Annotation object
     * @returns {Object} - minima and maxima of the bbox
     */
    getAnnotationMinMax(id) {
        return BaseUtils.convertBBoxToMaxes(this.getLabelBBox(id));
    }
}


/* src/Components/HydrophobicGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of hydrophobic contacts.
 */
class HydrophobicGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param hydrophobicGroupDom {Object} - D3 selector of the hydrophobic contacts group
     * @param hydrophobicSelGroupDom {Object} - D3 selector of the selection shape group
     */
    constructor(opts, utils, hydrophobicGroupDom, hydrophobicSelGroupDom) {
        this.opts = opts;
        this.utils = utils;
        this.hydrophobicGroupDom = hydrophobicGroupDom;
        this.hydrophobicSelGroupDom = hydrophobicSelGroupDom;

        //Structure object id -> hydrophobic contact id -> selectors
        this.hydrophobicToSelMap = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the spline representing a hydrophobic contact as a path element
     * within the SVG and circular selection shapes at the positions of control
     * points. Also creates the wrapper element for this type of intermolecular
     * forces if not done before.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param controlPoints {Array} - positions of control points
     * @param splinePath {String} - the path representing the shape of the
     * spline
     */
    drawHydrophobicContact(structureId, hydrophobicId, controlPoints, splinePath) {
        if (!this.hydrophobicToSelMap.hasOwnProperty(structureId)) {
            this.hydrophobicToSelMap[structureId] = {};
        }
        const hydrophobicMap = this.hydrophobicToSelMap[structureId];
        const controlSels = {};
        controlPoints.forEach((coords, idx) => {
            controlSels[idx] =
                this.utils.selector.drawCircleSelectionShape(this.hydrophobicSelGroupDom,
                    '',
                    coords
                ).sel;
        });
        hydrophobicMap[hydrophobicId] = {
            pathSel: LineUtils.addPathToSvg(
                this.hydrophobicGroupDom,
                '',
                splinePath,
                {
                    'stroke-width': this.opts.lineWidth + 'px',
                    'stroke': this.opts.colors.hydrophobicContacts
                }),
            controlSels: controlSels
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds new control points to a existing hydrophobic contact as circular
     * selection shapes within the SVG.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param controlPoints {Array} - positions of control points
     * @param addId {Number} - where to insert the given control points in the
     * controlSels array
     */
    addHydrophobicControlPoints(structureId, hydrophobicId, controlPoints, addId = undefined) {
        if (!this.hydrophobicToSelMap.hasOwnProperty(structureId)) {
            return;
        }

        const structureMap = this.hydrophobicToSelMap[structureId];
        if (!structureMap.hasOwnProperty(hydrophobicId)) {
            return;
        }

        const hydrophobicMap = structureMap[hydrophobicId];
        const startSels = [];
        const midSels = [];
        const endSels = [];
        for (const [idx, sel] of Object.entries(hydrophobicMap.controlSels)) {
            if (idx >= addId) {
                endSels.push(sel);
            } else {
                startSels.push(sel);
            }
        }
        controlPoints.forEach((coords, idx) => {
            midSels[idx] = this.utils.selector.drawCircleSelectionShape(this.hydrophobicSelGroupDom,
                '',
                coords
            ).sel;
        });
        hydrophobicMap.controlSels = {};
        [...startSels, ...midSels, ...endSels].forEach((sel, idx) => {
            hydrophobicMap.controlSels[idx] = sel;
        })
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves control points of a hydrophobic contact to new positions and set
     * a new path for the spline.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param controlPoints {Array} - positions of control points
     * @param splinePath {String} - the path representing the shape of the
     * spline
     */
    updateHydrophobicContact(structureId, hydrophobicId, controlPoints, splinePath) {
        const {pathSel, controlSels} = this.hydrophobicToSelMap
            [structureId][hydrophobicId];
        controlPoints.forEach((coords, idx) => {
            this.utils.circle.moveCircleElement(controlSels[idx].node(), coords.x, coords.y);
        });
        pathSel.attr('d', splinePath);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches the path element and selection shapes of a hydrophobic contact
     * from the DOM.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     */
    removeHydrophobicContactFromDOM(structureId, hydrophobicId) {
        const {pathSel, controlSels} = this.hydrophobicToSelMap
            [structureId][hydrophobicId];
        pathSel.remove();
        Object.values(controlSels).forEach(controlSel => {
            controlSel.remove();
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches the cached path element and selection shapes of a hydrophobic
     * contact to the DOM (after application of removeHydrophobicContactFromDOM()).
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     */
    redrawHydrophobicContact(structureId, hydrophobicId) {
        const splineGnode = this.hydrophobicGroupDom.node();
        const ctrlGnode = this.hydrophobicSelGroupDom.node();
        const {pathSel, controlSels} = this.hydrophobicToSelMap
            [structureId][hydrophobicId];
        splineGnode.appendChild(pathSel.node());
        Object.values(controlSels).forEach(controlSel => {
            ctrlGnode.appendChild(controlSel.node());
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches the selection shapes of a single control point of a hydrophobic
     * contact from the DOM. Note that this does not alter the spline so you
     * may have to redraw it.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param controlPointId {Number} - the id of the control point
     */
    removeHydrophobicControlPoint(structureId, hydrophobicId, controlPointId) {
        const controlSel = this.hydrophobicToSelMap
            [structureId][hydrophobicId].controlSels[controlPointId];
        controlSel.remove();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches the cached selection shapes of a single control point of a
     * hydrophobic contact to the DOM (after application of
     * removeHydrophobicControlPoint()). Note that this does not alter the spline
     * so you may have to redraw it.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param controlPointId {Number} - the id of the control point
     */
    redrawHydrophobicControlPoint(structureId, hydrophobicId, controlPointId) {
        const ctrlGnode = this.hydrophobicSelGroupDom.node();
        const controlSel = this.hydrophobicToSelMap
            [structureId][hydrophobicId].controlSels[controlPointId];
        ctrlGnode.appendChild(controlSel.node());
    }

    /*----------------------------------------------------------------------*/

    /**
     * To show the position of all control points of a hydrophobic contact,
     * changes the color of all such points' selection shapes to hover color.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     */
    hoverAllHydrophobicControlPoints(structureId, hydrophobicId) {
        const controlSels = this.hydrophobicToSelMap[structureId]
            [hydrophobicId].controlSels;
        Object.keys(controlSels).forEach(idx => {
            this.hoverHydrophobicControlPoint(structureId, hydrophobicId, idx);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Indicates that a hydrophobic contact's control point is hovered by the
     * user by switching the color of its corresponding selection shape to the
     * hover color.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param idx {Number} - index of the control point in the array of control
     * points within the Spline object representing the hydrophobic contact
     */
    hoverHydrophobicControlPoint(structureId, hydrophobicId, idx) {
        this.utils.selector.switchSelector(this.hydrophobicToSelMap[structureId]
            [hydrophobicId].controlSels[idx], 'circle', SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously hovered control point of a hydrophobic contact, removes
     * color from its corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     * @param idx {Number} - index of the control point in the array of control
     * points within the Spline object representing the hydrophobic contact
     */
    unselectHydrophobicControlPoint(structureId, hydrophobicId, idx) {
        this.utils.selector.switchSelector(this.hydrophobicToSelMap[structureId]
            [hydrophobicId].controlSels[idx], 'circle', SelectorStatus.unselect);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached information for a hydrophobic contact's elements.
     *
     * @param structureId {Number} - the unique id of the structure the
     * hydrophobic contact belongs to
     * @param hydrophobicId {Number} - the unique id of the hydrophobic
     * contact
     */
    purgeHydrophobicContactFromCache(structureId, hydrophobicId) {
        delete this.hydrophobicToSelMap[structureId][hydrophobicId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides hydrophobic contacts by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all hydrophobic contacts
     * @param hydrophobic {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide hydrophobic contacts from
     * @param visibilityClass {String} - CSS class for show/hide
     */
    setVisibility(full, hydrophobic, structureId, visibilityClass) {
        if ((full || hydrophobic) && this.hydrophobicToSelMap.hasOwnProperty(structureId)) {
            const hydrophobicToSelMap = this.hydrophobicToSelMap[structureId];
            for (const hydrophobicSel of Object.values(hydrophobicToSelMap)) {
                hydrophobicSel.pathSel.classed(visibilityClass, true);
                for (const controlSel of Object.values(hydrophobicSel.controlSels)) {
                    controlSel.classed(visibilityClass, true);
                }
            }
        }
    }
}

/* src/Components/IntermolecularGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of intermolecular edges.
 */
class IntermolecularGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing
     * utils.
     * Creates containers for the tracking/caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param distanceGroupDom {Object} - D3 selector of the intermolecular edge (distance)
     * @param interactionGroupDom {Object} - D3 selector of the intermolecular edge (interaction)
     * @param cationpiGroupDom {Object} - D3 selector of the intermolecular edge (cationpi)
     * @param pipiGroupDom {Object} - D3 selector of the intermolecular edge (pipi)
     * @param atomPairInteractionGroupDom {Object} - D3 selector of the intermolecular edge
     *     (atomPairInteraction)
     * @param distanceSelGroupDom {Object} - D3 selector of the selection shape group (distance)
     * @param interactionSelGroupDom {Object} - D3 selector of the selection shape group
     * (interaction)
     * @param cationpiSelGroupDom {Object} - D3 selector of the selection shape group (cationpi)
     * @param pipiSelGroupDom {Object} - D3 selector of the selection shape group (pipi)
     * @param atomPairInteractionSelGroupDom {Object} - D3 selector of the selection shape group
     *     (atomPairInteraction)
     */
    constructor(opts,
        utils,
        distanceGroupDom,
        interactionGroupDom,
        cationpiGroupDom,
        pipiGroupDom,
        atomPairInteractionGroupDom,
        distanceSelGroupDom,
        interactionSelGroupDom,
        cationpiSelGroupDom,
        pipiSelGroupDom,
        atomPairInteractionSelGroupDom
    ) {
        this.opts = opts;
        this.utils = utils;
        this.cationpiGroupDom = cationpiGroupDom;
        this.pipiGroupDom = pipiGroupDom;
        this.atomPairInteractionGroupDom = atomPairInteractionGroupDom;
        this.distanceGroupDom = distanceGroupDom;
        this.interactionGroupDom = interactionGroupDom;
        this.cationpiSelGroupDom = cationpiSelGroupDom;
        this.pipiSelGroupDom = pipiSelGroupDom;
        this.atomPairInteractionSelGroupDom = atomPairInteractionSelGroupDom;
        this.distanceSelGroupDom = distanceSelGroupDom;
        this.interactionSelGroupDom = interactionSelGroupDom;
        //IntermolecularEdge id -> selectors
        this.atomPairInteractionToSelMap = {};
        this.piStackToSelMap = {};
        this.cationPiStackToSelMap = {};
        this.distanceToSelMap = {};
        this.interactionToSelMap = {};
        //maps intermolecular type to groups
        //interGroup for intermolecular edge
        //selGroup for selection shape
        this.typeGroupMap = {
            'atomPairInteractions': {
                'interGroup': this.atomPairInteractionGroupDom,
                'selGroup': this.atomPairInteractionSelGroupDom
            },
            'piStackings': {'interGroup': this.pipiGroupDom, 'selGroup': this.pipiSelGroupDom},
            'cationPiStackings': {
                'interGroup': this.cationpiGroupDom, 'selGroup': this.cationpiSelGroupDom
            },
            'distances': {
                'interGroup': this.distanceGroupDom, 'selGroup': this.distanceSelGroupDom
            },
            'interactions': {
                'interGroup': this.interactionGroupDom, 'selGroup': this.interactionSelGroupDom
            }
        };
        this.typeSelectorMap = {
            'atomPairInteractions': this.atomPairInteractionToSelMap,
            'piStackings': this.piStackToSelMap,
            'cationPiStackings': this.cationPiStackToSelMap,
            'distances': this.distanceToSelMap,
            'interactions': this.interactionToSelMap
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the line and endpoint circles representing an intermolecular edge
     * within the SVG. Also creates the wrapper element for this
     * type of intermolecular edge if not done before.
     *
     * @param intermolecularEdge {IntermolecularEdge} - intermolecular edge to draw
     * @param intermolecularInfo {Object} - further draw information for the intermolecular edge
     * @param type {String} - type of the intermolecular edge
     */
    drawIntermolecular(intermolecularEdge, intermolecularInfo, type) {
        const {id, fromStructure, toStructure, color, additionalInformation} = intermolecularEdge;
        const {drawPoints, midpoints, selWidth} = intermolecularInfo;
        const groups = this.typeGroupMap[type];
        const interGroup = groups['interGroup'];
        const selGroup = groups['selGroup'];
        this.typeSelectorMap[type][id] = {};
        const intermolecularSels = this.typeSelectorMap[type][id];
        if (['atomPairInteractions', 'cationPiStackings', 'piStackings'].includes(type)) {
            const dashOff = this.utils.base.getBaseDashOffsetByMidpoints(midpoints);
            const lineSels = this.utils.line.addElementsByDrawPoints(interGroup, drawPoints, {
                styles: {
                    'stroke-dasharray': this.utils.line.dashArrString(),
                    'stroke-dashoffset': dashOff,
                    'stroke-width': this.opts.lineWidth + 'px',
                    'stroke': color,
                    'fill': color,
                    'stroke-linecap': 'round'
                }
            });
            const circleStyle = {'fill': color};
            if (!this.opts.geomineMode && type === 'cationPiStackings') {
                const circle = this.utils.circle.addCircleToSvg(interGroup,
                    '',
                    midpoints[0],
                    this.opts.piPiRadius,
                    circleStyle
                );
                intermolecularSels.circleSel = circle;
            } else if (!this.opts.geomineMode && type === 'piStackings') {
                const fromCircle = this.utils.circle.addCircleToSvg(interGroup,
                    '',
                    midpoints[0],
                    this.opts.piPiRadius,
                    circleStyle
                );
                const toCircle = this.utils.circle.addCircleToSvg(interGroup,
                    '',
                    midpoints[1],
                    this.opts.piPiRadius,
                    circleStyle
                );
                intermolecularSels.fromSel = fromCircle;
                intermolecularSels.toSel = toCircle;
            }
            intermolecularSels.lineSels = lineSels;
        } else if (this.opts.geomineMode && ['distances', 'interactions'].includes(type)) {
            const color = additionalInformation.color;
            const dashOff = this.utils.base.getPtoPdashOffsetByMidpoints(midpoints);
            let styles = {
                'stroke': color, 'fill': color, 'stroke-width': selWidth, 'opacity': 0.5
            };
            if (type === 'interactions') {
                styles['stroke-dasharray'] = this.utils.line.dashArrStringPtoP;
                styles['stroke-dashoffset'] = dashOff;
            }
            const lineSels = this.utils.line.addElementsByDrawPoints(interGroup, drawPoints, {
                styles: styles
            });
            intermolecularSels.lineSels = lineSels;
        }
        intermolecularSels.fromStructure = fromStructure;
        intermolecularSels.toStructure = toStructure;
        intermolecularSels.mouseSel =
            this.utils.selector.drawLineSelectionShape(selGroup, "", midpoints, selWidth).sel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the circles of an intermolecular edge to new endpoints and
     * updates the line between the circles accordingly.
     *
     * @param id {Number} - the unique id of the intermolecular edge
     * @param drawPoints {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @param midpoints {Array} - coordinates of line endpoints
     * @param type {String} - type of the intermolecular edge
     */
    moveIntermolecular(id, {drawPoints, midpoints}, type) {
        const intermolecularSels = this.typeSelectorMap[type][id];
        const dashOff = this.utils.base.getBaseDashOffsetByMidpoints(midpoints);
        intermolecularSels.lineSels.forEach((lineSel, idx) => {
            lineSel.style('stroke-dashoffset', dashOff);
            this.utils.line.updateLineByDrawpoints(lineSel.node(), drawPoints[idx]);
        });
        if (!this.opts.geomineMode && type === 'cationPiStackings') {
            this.utils.circle.moveCircleElement(intermolecularSels.circleSel.node(),
                midpoints[0].x,
                midpoints[0].y
            );
        } else if (!this.opts.geomineMode && type === 'piStackings') {
            this.utils.circle.moveCircleElement(intermolecularSels.fromSel.node(),
                midpoints[0].x,
                midpoints[0].y
            );
            this.utils.circle.moveCircleElement(intermolecularSels.toSel.node(),
                midpoints[1].x,
                midpoints[1].y
            );
        }
        const intermolecularSelectorsSel = intermolecularSels.mouseSel;
        this.utils.line.updateLineByDrawpoints(intermolecularSelectorsSel.node(), midpoints);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches the circle and line elements of a an intermolecular edge from the DOM.
     *
     * @param id {Number} - the unique id of the intermolecular edge
     * @param type {String} - type of the intermolecular edge
     */
    removeIntermolecularFromDOM(id, type) {
        const intermolecularSels = this.typeSelectorMap[type][id];
        intermolecularSels.lineSels.forEach(lineSel => {
            lineSel.remove();
        });
        if (!this.opts.geomineMode && type === 'cationPiStackings') {
            intermolecularSels.circleSel.remove();
        } else if (!this.opts.geomineMode && type === 'piStackings') {
            intermolecularSels.fromSel.remove();
            intermolecularSels.toSel.remove();
        }
        intermolecularSels.mouseSel.remove();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches the cached circle and line elements of an intermolecular edge to the
     * DOM (after application of removeIntermolecularFromDOM()).
     *
     * @param id {Number} - the unique id of the intermolecular edge
     * @param type {String} - type of the intermolecular edge
     */
    redrawIntermolecular(id, type) {
        const groups = this.typeGroupMap[type];
        const interGroupNode = groups['interGroup'].node();
        const selGroupNode = groups['selGroup'].node();
        const intermolecularSels = this.typeSelectorMap[type][id];
        intermolecularSels.lineSels.forEach(lineSel => {
            interGroupNode.appendChild(lineSel.node());
        });
        if (!this.opts.geomineMode && type === 'cationPiStackings') {
            interGroupNode.appendChild(intermolecularSels.circleSel.node());
        } else if (!this.opts.geomineMode && type === 'piStackings') {
            interGroupNode.appendChild(intermolecularSels.fromSel.node());
            interGroupNode.appendChild(intermolecularSels.toSel.node());
        }
        selGroupNode.appendChild(intermolecularSels.mouseSel.node());
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached information of intermolecular edge's elements.
     *
     * @param id {Number} - the unique id of the intermolecular edge type
     * @param type {String} - type of the intermolecular edge
     */
    purgeIntermolecularFromCache(id, type) {
        delete this.typeSelectorMap[type][id];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an intermolecular edge in the draw area by switching the color of its
     * corresponding selection shape to the selection color.
     *
     * @param id {Number} - the unique id of the intermolecular edge to select
     * @param type {String} - type of the intermolecular edge to select
     */
    selectIntermolecular(id, type) {
        const selector = this.typeSelectorMap[type][id].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.select);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Signals that an intermolecular edge is hovered in the draw area by switching the
     * color of its corresponding selection shape to the hover color.
     *
     * @param id {Number} - the unique id of the intermolecular edge to hover
     * @param type {String} - type of the intermolecular edge to hover
     */
    hoverIntermolecular(id, type) {
        const selector = this.typeSelectorMap[type][id].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously selected/hovered intermolecular edge, removes color from the
     * corresponding selection shape.
     *
     * @param id {Number} - the unique id of the intermolecular edge to unselect
     * @param type {String} - type of the intermolecular edge to unselect
     */
    unselectIntermolecular(id, type) {
        const selector = this.typeSelectorMap[type][id].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.unselect);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if a representation has already been created for a atom pair interaction.
     *
     * @param atomPairInteractionId {Number}- the unique id of the atom pair interaction
     * @returns {Boolean} - whether a representation exists
     */
    wasAtomPairInteractionDrawnBefore(atomPairInteractionId) {
        return this.atomPairInteractionToSelMap.hasOwnProperty(atomPairInteractionId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides intermolecular edges of a certain type by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all intermolecular edges of this type
     * @param toogleVisibility {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide intermolecular edges from
     * @param visibilityClass {String} - CSS class for show/hide
     * @param hiddenStructures {Array} - ids of structures which are currently
     * completely hidden in the draw area.
     * @param type {String} - intermolecular edge type
     */
    setVisibility(full, toogleVisibility, structureId, visibilityClass, hiddenStructures, type) {
        if (full || toogleVisibility) {
            for (const intermolecularObj of Object.values(this.typeSelectorMap[type])) {
                if ((intermolecularObj.fromStructure === structureId ||
                        intermolecularObj.toStructure === structureId) &&
                    !hiddenStructures.includes(intermolecularObj.fromStructure) &&
                    !hiddenStructures.includes(intermolecularObj.toStructure)) {
                    for (const lineSel of intermolecularObj.lineSels) {
                        lineSel.classed(visibilityClass, true);
                    }
                    if (!this.opts.geomineMode && type === 'cationPiStackings') {
                        intermolecularObj.circleSel.classed(visibilityClass, true);
                    } else if (!this.opts.geomineMode && type === 'piStackings') {
                        intermolecularObj.fromSel.classed(visibilityClass, true);
                        intermolecularObj.toSel.classed(visibilityClass, true);

                    }
                    intermolecularObj.mouseSel.classed(visibilityClass, true);
                }
            }
        }
    }
}

/* src/Components/Structure/AtomGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of atoms.
 */
class AtomGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param atomGroupDom {Object} - D3 selector of the atoms group
     * @param atomSelGroupDom {Object} - D3 selector of the selection shape group
     * @param atomDbgGroupDom {Object} - D3 selector of the debug label group
     * @param svgId {String} - DOM id of the SVG
     */
    constructor(opts, utils, atomGroupDom, atomSelGroupDom, atomDbgGroupDom, svgId) {
        this.opts = opts;
        this.utils = utils;
        this.atomGroupDom = atomGroupDom;
        this.atomSelGroupDom = atomSelGroupDom;
        this.atomDbgGroupDom = atomDbgGroupDom;
        this.svgId = svgId;

        //Structure object id -> (structureSel/debugSels) -> selectors /atomSels/ringSysSels
        //-> Atom/Ring object id -> selectors
        this.atomToSelMap = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the representation of an atom within the SVG. Each atom has its
     * own wrapper within the wrapper for all the atoms of this structure.
     * Inside this wrapper, there is another wrapper containing the drawing of
     * the atom (text or ball) and the selector (which is represented by a
     * circle around the atom). Access to the DOM elements (main atom wrapper,
     * wrapper of atom representation, and for the selector are mapped in the
     * atomToSelMap.
     *
     * @param structure {Structure} - the Structure object containing the atom
     * @param atom {Atom} - the Atom object to draw
     */
    drawAtom(structure, atom) {
        //create wrapper
        const structureId = structure.id;
        const {id: atomId, coordinates, element, ringSystem, label} = atom;
        const structureSels = this.atomToSelMap[structureId];

        //prepare container to put elements into and base for id strings
        const wrapperContainer = ringSystem ? structureSels.ringSysSels[ringSystem] : structureSels;
        const structAtomString = `${this.svgId}_s_${structureId}_a_${atomId}`;

        //create map entries (will be updated in individual drawing functions)
        const placementInfo = {
            atomText: {exists: false},
            chargeText: {exists: false},
            hText: {exists: false},
            hNumberText: {exists: false}
        };
        const atomSels = {
            groupSel: null, //to delete/hide entire group
            atomSel: null, //to change coordinates and color
            mouseSels: [], //to change coordinates
            selectorShapes: [], //to find out if something is on selector
            placementInfo: placementInfo, //for text and hydrogen
            debugSel: null, debugPosition: null //where debug text is positioned
        };

        structureSels.atomSels[atomId] = atomSels;
        //create the visualization step by step
        if (this.opts.atomMode === 'name') {
            if (element !== 'C') {
                this.drawAtomText(atom, wrapperContainer, atomSels, structAtomString);
                //correctly place hydrogens after drawing
                this.placeHByOrientation(structureId, atom, false);
            }
        }
        this.drawAtomSelector(label,
            coordinates,
            wrapperContainer,
            atomSels,
            placementInfo,
            structAtomString
        );
        if (this.opts.debug.atoms) {
            this.drawAtomDebugText(structureId, atom, wrapperContainer, atomSels);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creation of the representation of an atom within the SVG,
     * creates the main (element) text centered on given coordinates.
     *
     * @param atom {Atom} - the Atom object to represent, containing
     * information on coordinates, color, etc.
     * @param wrapperContainer {Object} - object holding SVG group elements to
     * add text elements within
     * @param atomSels {Object} - selector object used within the drawer to
     * cache selectors
     * @param structAtomString {String} - base string for ids of text
     * elements
     */
    drawAtomText(atom, wrapperContainer, atomSels, structAtomString) {
        const {coordinates, label, charge, hydrogenCount: hCount, color} = atom;
        const wrapper = GroupUtils.addGroupToSvg(wrapperContainer.structureSel,
            structAtomString + '_w',
            {
                'font-family': this.opts.fontFamily
            }
        );

        //add wrapper for text (as text group)
        const gId = structAtomString + '_text';
        const textG = GroupUtils.addGroupToSvg(wrapper, gId);

        //add main text element
        const {
            sel: atomText, width: labelWidth, x: labelX, y: labelY
        } = this.utils.text.placeCenteredText(textG, label, coordinates, color, true);

        //add charge text (if necessary)
        let chargeNode, chargeX, chargeY, chargeWidth;
        if (charge !== 0) {
            const fullCharge = Number.isInteger(charge);
            let chargeText;
            const chargeAbs = Math.abs(charge);
            const symbol = charge > 0 ? '+' : '-';
            if (fullCharge) {
                chargeText = (chargeAbs !== 1 && chargeAbs !== -1) ? symbol + chargeAbs : symbol;
            } else {
                chargeText = new Fraction(charge).simplify(0.01).toFraction(false);
                if (charge > 0) {
                    chargeText = symbol + chargeText;
                }
            }
            chargeNode = textG.append('text')
                .style('font-family', this.opts.fontFamily)
                .style('fill', color)
                .text(chargeText)
                .attr('y', coordinates.y)
                .attr('x', coordinates.x)
                .attr('font-size', this.opts.chargeFontSize + 'px')
                .attr('font-weight', 'bolder');
            //first center (on top of label), then move to correct position
            const chargeBbox = chargeNode.node().getBBox();
            chargeX = labelX + labelWidth;
            chargeY = BaseUtils.centerBBoxY(chargeBbox, coordinates);
            //bbox width is not correkt for chrome and edge
            chargeWidth = chargeNode.node().getSubStringLength(0, chargeText.length);
            chargeNode.attr('x', chargeX)
                .attr('y', chargeY)
                .attr('dy', -this.opts.chargeOffset + 'px');
        }

        //create text for hydrogens (if necessary)
        let hText, hY, hWidth, hNumberText, hNrY, hNrWidth;
        if (hCount > 0) {
            hText = textG.append('text')
                .style('font-family', this.opts.fontFamily)
                .style('fill', color)
                .text('H')
                .attr('x', coordinates.x)
                .attr('y', coordinates.y)
                .attr('font-size', this.opts.textSize + 'px');
            //place on top of label, real placement happens in
            //placeHByOrientation()
            const hBbox = hText.node().getBBox();
            hY = BaseUtils.centerBBoxY(hBbox, coordinates);
            hWidth = hBbox.width;
            hText.attr('y', hY);
            //draw hydrogen count
            if (hCount > 1) {
                hNumberText = textG.append('text')
                    .style('font-family', this.opts.fontFamily)
                    .style('fill', color)
                    .text(hCount)
                    .attr('x', coordinates.x)
                    .attr('y', coordinates.y)
                    .attr('font-size', this.opts.hNumberFontSize + 'px');
                //place only y coordinate correctly, real placement as above
                const hNumberBbox = hNumberText.node().getBBox();
                const hNrX = hBbox.x + hBbox.width;
                hNrY = BaseUtils.centerBBoxY(hNumberBbox, coordinates);
                hNrWidth = hNumberBbox.width;
                hNumberText.attr('x', hNrX)
                    .attr('y', hNrY)
                    .attr('dy', this.opts.hNumberOffset);
            }
        }

        //set the group selectors in the given selector map
        atomSels.groupSel = wrapper;
        atomSels.atomSel = textG;
        const placementInfo = atomSels.placementInfo;
        const updateInfo = (x, y, width, sel, field) => {
            if (y) {
                placementInfo[field] = {
                    exists: true, sel: sel, x: x, y: y, width: width
                };
            }
        };
        updateInfo(labelX, labelY, labelWidth, atomText, 'atomText');
        updateInfo(chargeX, chargeY, chargeWidth, chargeNode, 'chargeText');
        updateInfo(undefined, hY, hWidth, hText, 'hText');
        updateInfo(undefined, hNrY, hNrWidth, hNumberText, 'hNumberText');
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creation of the representation of an atom within the SVG,
     * creates debug text referencing the internal atom id on top of the main
     * text representation.
     *
     * @param structureId {Number} - id of structure the atom belongs to
     * @param atomId {Number} - id of the atom
     * @param coordinates {Object} - x- and y-coordinates to center text in
     * @param wrapperContainer {Object} - object holding SVG group elements to
     * add text elements within
     * @param atomSels {Object} - selector object used within the drawer to
     * cache selectors
     */
    drawAtomDebugText(structureId, {id: atomId, coordinates}, wrapperContainer, atomSels) {
        const debugSel = wrapperContainer.debugSel;
        const styles = {
            'dominant-baseline': 'central', 'font-size': this.opts.debug.textSize
        };
        if (!this.opts.debug.showAtoms) {
            styles['display'] = 'none';
        }
        atomSels.debugSel = this.utils.text.addTextToSvg(debugSel, '', atomId, coordinates, styles);
        atomSels.debugPosition = Object.assign({}, coordinates);
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creation of the representation of an atom within the SVG,
     * creates the selector shapes behind the atom text.
     *
     * @param label {String} - text that is drawn for the atom
     * @param coordinates {Object} - x- and y-coordinates to center text in
     * @param wrapperContainer {Object} - object holding SVG group elements to
     * add text elements within
     * @param atomSels {Object} - selector object used within the drawer to
     * cache selectors
     * @param placementInfo {Object} - bbox information of the different text
     * elements created for the atom
     * @param structAtomString {String} - base string for ids of text
     * elements
     */
    drawAtomSelector(label,
        coordinates,
        wrapperContainer,
        atomSels,
        placementInfo,
        structAtomString
    ) {
        const selId = structAtomString + '_selector';
        const {mouseSels, selectorShapes} = this.utils.selector.drawTextLabelSelectors(label,
            coordinates,
            placementInfo.atomText.width,
            wrapperContainer.selectorSel,
            selId
        );
        atomSels.mouseSels = mouseSels;
        atomSels.selectorShapes = selectorShapes;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches all DOM elements which are part of an atom's drawn
     * representation. These remain cached and can be reattached by use of the
     * redrawAtom() function.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to remove related
     * DOM elements for
     * @param unselect {Boolean} - whether to unselect the atom's selector
     * element prior to detaching it (if you plan to reattach it later)
     */
    removeAtom(structureId, atomId, unselect = true) {
        const structureSels = this.atomToSelMap[structureId];
        const atomSels = structureSels.atomSels[atomId];
        const mouseSels = atomSels.mouseSels;
        if (unselect) {
            mouseSels.forEach(selector => {
                this.utils.selector.switchSelector(selector, 'circle', SelectorStatus.unselect);
            });
        }
        if (atomSels.groupSel) atomSels.groupSel.remove();
        if (atomSels.debugSel) {
            atomSels.debugSel.remove();
        }
        mouseSels.forEach(selector => {
            selector.remove();
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches cached detached DOM elements which are part of an atom's
     * drawn representation (after application of removeAtom()).
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atom {Atom} - Atom object belonging to the atom to reattach DOM
     * elements for (requiring id and ring system information)
     */
    redrawAtom(structureId, atom) {
        const atomId = atom.id;
        const structureSels = this.atomToSelMap[structureId];
        const atomSels = structureSels.atomSels[atomId];
        //add back atom group to structure group
        let wrapper = structureSels;
        if (atom.ringSystem) {
            wrapper = structureSels.ringSysSels[atom.ringSystem];
        }
        if (atomSels.groupSel) {
            wrapper.structureSel.node().appendChild(atomSels.groupSel.node());
        }
        if (atomSels.debugSel) {
            structureSels.debugSel.node().appendChild(atomSels.debugSel.node());
        }
        atomSels.mouseSels.forEach(selector => {
            wrapper.selectorSel.node().appendChild(selector.node());
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies movement on the representation of an atom (i.e., on all text
     * elements drawn for this atom) by giving offsets to move in x- and y-
     * direction.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to move
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveAtom(structureId, atomId, {x: xOffset, y: yOffset}) {
        const atomSels = this.atomToSelMap[structureId].atomSels[atomId];
        const placementInfo = atomSels.placementInfo;

        //ATOM TEXT
        let curInfo;
        const updateCur = () => {
            if (curInfo.exists) {
                this.utils.text.moveTextByPlacementInfo(curInfo.sel, curInfo, xOffset, yOffset);
            }
        };

        //ATOM TEXT
        curInfo = placementInfo.atomText;
        updateCur();
        //CHARGE TEXT
        curInfo = placementInfo.chargeText;
        updateCur();
        //HYDROGEN TEXT
        curInfo = placementInfo.hText;
        updateCur();
        //HYDROGEN NUMBER TEXT
        curInfo = placementInfo.hNumberText;
        updateCur();

        //update created selector shapes
        this.utils.selector.moveAllSelectors(atomSels.mouseSels,
            atomSels.selectorShapes,
            xOffset,
            yOffset
        );

        //update debug text if given
        if (this.opts.debug.atoms) {
            const debugSel = atomSels.debugSel;
            const debugInfo = atomSels.debugPosition;
            this.utils.text.moveTextByPlacementInfo(debugSel, debugInfo, xOffset, yOffset);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Signals that an atom is hovered in the draw area by switching the color
     * of its corresponding selection shape to the hover color.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to signal as hovered
     */
    hoverAtom(structureId, atomId) {
        const atomSels = this.atomToSelMap[structureId].atomSels[atomId];
        this.utils.selector.switchTextLabelSelectorStatus(atomSels, SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an atom in the draw area by switching the color of its
     * corresponding selection shape to the selection color.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to select
     */
    selectAtom(structureId, atomId) {
        const atomSels = this.atomToSelMap[structureId].atomSels[atomId];
        this.utils.selector.switchTextLabelSelectorStatus(atomSels, SelectorStatus.select);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously selected/hovered atom, removes color from the atom's
     * corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to unselect
     */
    unselectAtom(structureId, atomId) {
        const atomSels = this.atomToSelMap[structureId].atomSels[atomId];
        this.utils.selector.switchTextLabelSelectorStatus(atomSels, SelectorStatus.unselect);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the color of an atom's corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to select
     * @param color {String} - valid CSS color
     */
    recolorAtomSelector(structureId, atomId, color) {
        const atomSels = this.atomToSelMap[structureId].atomSels[atomId];
        this.utils.selector.switchTextLabelSelectorColor(atomSels, color);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the color of an atom's representation.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to recolor
     * @param color {String} - CSS color to use as new color
     */
    recolorAtom(structureId, atomId, color) {
        const atomGroupDom = this.atomToSelMap[structureId].atomSels[atomId].atomSel.node();
        atomGroupDom.childNodes.forEach(child => {
            child.style.fill = color;
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creation of the representation of an atom within the SVG,
     * places hydrogen text to a specified side of the main text
     *
     * @param structureId {Number} - id of structure the atom belongs to
     * @param atom {Atom} - the Atom object to represent, containing
     * information on orientation of attached hydrogen
     * @param byTemp {Boolean} - whether to use temporary values for
     * hydrogen orientation
     */
    placeHByOrientation(structureId, atom, byTemp) {
        const placementInfo = this.getPlacementInfo(structureId, atom.id);
        if (!placementInfo) {
            return;
        }
        const orientationParam = byTemp ? 'tempHydrogenOrientation' : 'hydrogenOrientation';
        switch (atom[orientationParam]) {
            case 'left':
                this.placeHLeft(placementInfo);
                break;
            case 'right':
                this.placeHRight(placementInfo);
                break;
            case 'up':
                this.placeHUpDown(placementInfo, true);
                break;
            case 'down':
                this.placeHUpDown(placementInfo, false);
                break;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of hydrogen placement. Places hydrogen text to the left of the main
     * atom text.
     *
     * @param atomText {Object} - bbox information for the main atom text
     * @param hText {Object} - bbox information for the hydrogen text
     * @param hNumberText {Object} - bbox information for the small number
     * text as subscript of hydrogen text
     */
    placeHLeft({atomText, hText, hNumberText}) {
        let hNrX = atomText.x;
        if (hNumberText.exists) {
            const hNumberWidth = hNumberText.width;
            hNrX -= hNumberWidth;
            hNumberText.sel.attr('x', hNrX)
                .attr('dy', this.opts.hNumberOffset);
            hNumberText.x = hNrX;
        }
        const hX = hNrX - hText.width;
        hText.sel.attr('x', hX).attr('dy', 0);
        hText.x = hX;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of hydrogen placement. Places hydrogen text to the right of the main
     * atom text.
     *
     * @param atomText {Object} - bbox information for the main atom text
     * @param chargeText {Object} - bbox information for the charge text
     * @param hText {Object} - bbox information for the hydrogen text
     * @param hNumberText {Object} - bbox information for the small number
     * text as subscript of hydrogen text
     */
    placeHRight({atomText, chargeText, hText, hNumberText}) {
        let hX = atomText.x + atomText.width;
        if (chargeText.exists) {
            const chargeRight = chargeText.x + chargeText.width;
            if (chargeRight > hX) {
                hX = chargeRight;
            }
        }
        hText.sel.attr('x', hX).attr('dy', 0);
        hText.x = hX;
        if (hNumberText.exists) {
            const hNrX = hX + hText.width;
            hNumberText.sel.attr('x', hNrX)
                .attr('dy', this.opts.hNumberOffset);
            hNumberText.x = hNrX;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of hydrogen placement. Places hydrogen text above or below the main atom
     * text.
     *
     * @param atomText {Object} - bbox information for the main atom text
     * @param hText {Object} - bbox information for the hydrogen text
     * @param hNumberText {Object} - bbox information for the small number
     * text as subscript of hydrogen text
     * @param up {Boolean} - set to true if H shall be placed above the atom
     */
    placeHUpDown({atomText, hText, hNumberText}, up) {
        const xSizeOffset = (atomText.width - hText.width) / 2;
        let hDy = this.opts.textSize - this.opts.textCrop + this.opts.hOffset;
        if (up) {
            hDy = hDy * -1;
        }
        const hX = atomText.x + xSizeOffset;
        hText.sel.attr('x', hX)
            .attr('dy', hDy);
        hText.x = hX;

        if (hNumberText.exists) {
            const hNrX = hText.x + hText.width;
            hNumberText.sel.attr('x', hNrX)
                .attr('dy', this.opts.hNumberOffset + hDy);
            hNumberText.x = hNrX;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * (Re-)Anchors the draw elements of an Atom object representing an amino
     * acid label. This is done by moving the anchored side on top of the
     * labels current (temporary) position. If the label has been anchored
     * before, the prevOrientation parameter is used to specify the previous
     * anchoring and tells the drawer to undo that first.
     *
     * @param structureId {Number} - unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - unique id of the Atom
     * @param coords {Object} - x- and y-coordinates of the atom
     * @param labelOrientation {String} - 'left', 'right', 'up', or 'down'
     * @param prevOrientation {String} - 'left', 'right', 'up', or 'down'
     */
    anchorAtomLabel(structureId, {
        id: atomId, tempCoordinates: coords, tempLabelOrientation: labelOrientation
    }, prevOrientation) {
        const selMap = this.atomToSelMap[structureId].atomSels[atomId];
        const offsets = {
            x: 0, y: 0
        };
        let width, height;
        selMap.selectorShapes.forEach(selShape => {
            if (selShape.type !== 'line') return;
            //line sel shape better approximation for text than bbox, but only
            //works properly if only one line sel shape exists
            ({height, width} = selShape);
        });
        const horizontalAnchor = width / 2 + this.opts.atomRadius - this.opts.labelSideCorrection;
        const verticalAnchor = height / 2;
        const anchorOffsets = {
            'left': {x: horizontalAnchor},
            'right': {x: -horizontalAnchor},
            'up': {y: verticalAnchor},
            'down': {y: -verticalAnchor}
        };
        const addOffset = (orientation, reverse) => {
            let {x, y} = anchorOffsets[orientation];
            if (x) {
                if (reverse) x = -x;
                offsets.x += x;
            }
            if (y) {
                if (reverse) y = -y;
                offsets.y += y;
            }
        };
        if (prevOrientation) addOffset(prevOrientation, true);
        addOffset(labelOrientation, false);
        this.moveAtom(structureId, atomId, offsets);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves the saved bbox draw limits of all text elements making up the
     * representation of an atom.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atom {Atom} - Atom object to request limits for
     * @returns {Array} - array of objects detailing draw limits
     */
    getAtomDrawLimits(structureId, atom) {
        const placementInfo = this.getPlacementInfo(structureId, atom.id);

        //if no atom text then there is no other text either
        if (!placementInfo.atomText.exists) {
            const coords = atom.tempCoordinates;
            return [
                {
                    type: 'atomPoint', limits: {
                        xMin: coords.x, xMax: coords.x, yMin: coords.y, yMax: coords.y
                    }
                }
            ];
        }
        const structureSel = this.atomToSelMap[structureId].structureSel;
        const display = structureSel.style('display') !== 'none';
        if (!display) {
            structureSel.style('display', null);
        }
        const drawLimits = [];
        for (const textType in placementInfo) {
            const textElement = placementInfo[textType];
            if (!textElement.exists) {
                continue;
            }
            drawLimits.push({
                type: textType, limits: BaseUtils.convertBBoxToMaxes(textElement.sel.node()
                    .getBBox())
            });
        }
        if (!display) {
            structureSel.style('display', 'none');
        }
        return drawLimits;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves information on the selector shapes (currently just the one
     * circle) created for an atom.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom
     * @returns {Array} - array of objects describing the selector shapes
     */
    getAtomSelShapes(structureId, atomId) {
        return this.atomToSelMap[structureId].atomSels[atomId].selectorShapes;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves placement information for an atom (bbox information of the
     * different text elements created for this atom).
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom
     * @returns {Object} - placement information
     */
    getPlacementInfo(structureId, atomId) {
        return this.atomToSelMap[structureId].atomSels[atomId].placementInfo;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides atoms by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all atoms
     * @param atoms {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide atoms from
     * @param visibilityClass {String} - CSS class for show/hide
     */
    setVisibility(full, atoms, structureId, visibilityClass) {
        if ((full || atoms) && this.atomToSelMap.hasOwnProperty(structureId)) {
            const atomToSelMap = this.atomToSelMap[structureId];
            atomToSelMap.structureSel.classed(visibilityClass, true);
            atomToSelMap.selectorSel.classed(visibilityClass, true);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a (new) structure, adds new container groups to the svg for atoms.
     * Creates a new wrapper in the atom group. Further
     * prepares the mapping of selectors for later access. In the selector
     * map, the created groups are mapped also, so they may be hidden later.
     *
     * @param structure {Structure} - Structure object
     * @param structureId {structureId} - id of Structure object
     * @param debug {Boolean} - true if debug information shall be visualized
     */
    addAtomsToTrack(structure, structureId, debug) {
        //create fitting ids for newly created SVG elements
        const movementGroupIDs = {
            idGroup: this.svgId + '_s_' + structureId + '_a',
            idSelGroup: this.svgId + '_s_' + structureId + '_aS',
            idDbgGroup: this.svgId + '_s_' + structureId + '_dbgAtoms'
        };
        const movementGroupsDom = GroupUtils.addGroupsForMovement(this.atomGroupDom,
            this.atomSelGroupDom,
            this.atomDbgGroupDom,
            movementGroupIDs,
            debug
        );
        //creation of more complicated atom maps
        const atomToSelMap = {
            structureSel: movementGroupsDom.movGroupDom, //to quickly access/remove all atoms
            selectorSel: movementGroupsDom.movSelGroupDom, atomSels: {}, //individual cts for one
                                                                         // atom
            debugSel: movementGroupsDom.movDbgGroupDom //dbg group selector
        };
        //add move groups for rings to optimize movement in ring move mode
        const atomRingMap = {};
        for (const bccId in structure.ringsData.ringSystems) {
            const ringMovementGroupIDs = {
                idGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_a',
                idSelGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_aS',
                idDbgGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_dbg'
            };
            const ringMovementGroupsDom = GroupUtils.addGroupsForMovement(movementGroupsDom.movGroupDom,
                movementGroupsDom.movSelGroupDom,
                movementGroupsDom.movDbgGroupDom,
                ringMovementGroupIDs,
                debug
            );
            atomRingMap[bccId] = {
                structureSel: ringMovementGroupsDom.movGroupDom,
                selectorSel: ringMovementGroupsDom.movSelGroupDom,
                debugSel: ringMovementGroupsDom.movDbgGroupDom
            };
        }
        atomToSelMap.ringSysSels = atomRingMap;
        this.atomToSelMap[structureId] = atomToSelMap;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides all text representations of debug labels. Otherwise, display all
     * text representations of debug labels, provided parameters
     * to ever show specific debug elements are set in the configuration.
     *
     * @param visible {Boolean} - true if debug labels shall be visible
     */
    toggleDebugLabelsVisibility(visible) {
        let display = 'none';
        if (visible) {
            display = null;
        }
        if (this.opts.debug.atoms && !this.opts.debug.showAtoms) {
            for (const structureSel of Object.values(this.atomToSelMap)) {
                for (const atomSel of Object.values(structureSel.atomSels)) {
                    atomSel.debugSel.style('display', display);
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached atom DOM elements back
     * into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructureAtoms(structureId) {
        this.atomGroupDom.node().appendChild(this.atomToSelMap[structureId].structureSel.node());
        this.atomSelGroupDom.node().appendChild(this.atomToSelMap[structureId].selectorSel.node());
        if (this.atomToSelMap[structureId].debugSel) {
            this.atomDbgGroupDom.node().appendChild(this.atomToSelMap[structureId].debugSel.node());
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all atoms of a structure from the DOM.
     *
     * @param structureId {Number} - the unique id of the structure to remove
     * its atoms from the DOM
     */
    removeStructureAtomsFromDOM(structureId) {
        this.atomToSelMap[structureId].structureSel.remove();
        this.atomToSelMap[structureId].selectorSel.remove();
        if (this.atomToSelMap[structureId].debugSel) {
            this.atomToSelMap[structureId].debugSel.remove();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Remove all cached information for a given structure (by its id).
     *
     * @param structureId {Number} - id of structure to remove atom information
     * from.
     */
    purgeStructureAtomsFromCache(structureId) {
        delete this.atomToSelMap[structureId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for atoms of a certain ring system.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to reset translations
     * for
     */
    resetRingAtomSkeletonTranslation(structureId, ringSysId) {
        const atomSels = this.atomToSelMap[structureId].ringSysSels[ringSysId];
        SelectorUtils.resetTransformOnSelectors(atomSels);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for atoms of a certain structure.
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetAtomSkeletonTranslation(structureId) {
        SelectorUtils.resetTransformOnSelectors(this.atomToSelMap[structureId]);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (atoms as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveAtomSkeleton(structureId, xOffset, yOffset) {
        const atomSels = this.atomToSelMap[structureId];
        this.utils.selector.moveSelectorsOfSkeleton(atomSels, xOffset, yOffset, 'atom');
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (atoms as groups) of a ring system by specified
     * offsets.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to move skeleton of
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     */
    moveRingAtomSkeleton(structureId, ringSysId, xOffset, yOffset) {
        const atomSels = this.atomToSelMap[structureId].ringSysSels[ringSysId];
        this.utils.selector.moveSelectorsOfSkeleton(atomSels, xOffset, yOffset, 'atom');
    }
}

/* src/Components/Structure/EdgeGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of edges.
 */
class EdgeGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param edgeGroupDom {Object} - D3 selector of the edges group
     * @param edgeSelGroupDom {Object} - D3 selector of the selection shape group
     * @param edgeDbgGroupDom {Object} - D3 selector of the debug label group
     * @param defsComponent {Object} - D3 selector of the defs element (for gradients)
     * @param svgId {String} - DOM id of the SVG
     */
    constructor(opts, utils, edgeGroupDom, edgeSelGroupDom, edgeDbgGroupDom, defsComponent, svgId) {
        this.opts = opts;
        this.utils = utils;
        this.edgeGroupDom = edgeGroupDom;
        this.edgeSelGroupDom = edgeSelGroupDom;
        this.edgeDbgGroupDom = edgeDbgGroupDom;
        this.defsComponent = defsComponent;
        this.svgId = svgId;

        //Structure object id -> (structureSel/debugSel/selectorSel) -> selectors /edgeSels
        //-> Edge object id -> selectors
        this.edgeToSelMap = {};
        //Structure object id -> Edge object id -> gradient
        this.edgeGradientMap = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the representation of a bond within the SVG. Each bond has its
     * own wrapper within the wrapper for all the bonds of this structure.
     * D3 selectors for DOM elements (for the group wrapper, the selection
     * shape, debug text, and ring wrapper) are cached within the
     * edgeToSelMap, gradient information within the edgeGradientMap.
     *
     * @param structure {Structure} - the Structure object containing the bond
     * @param edge {Edge} - the edge object to draw
     * @param from {Atom} - Atom object of the first atom of the bond
     * @param to {Atom} - Atom object of the second atom of the bond (defines
     * direction of the bond)
     * @param byTemp {Boolean} - whether to use temporary draw information to
     * create the bond drawing
     */
    drawEdge(structure, edge, from, to, byTemp = false) {
        //prepare internal / HTML objects to write information to
        const structureId = structure.id;
        const {id: edgeId, ringSystem} = edge;
        const structureSels = this.edgeToSelMap[structureId];
        const {midpoints, drawPoints, selWidth} = byTemp ? edge.tempDrawInfo : edge.drawInfo;

        //prepare container to put elements into and base for id strings
        const wrapperContainer = ringSystem ? structureSels.ringSysSels[ringSystem] : structureSels;
        const structEdgeString = `${this.svgId}_s_${structureId}_e_${edgeId}`;

        //create map entries (will be updated in individual drawing functions)
        const edgeSels = {
            edgeDrawn: true, groupSel: null, //to delete/hide entire group
            //to iterate drawn elements and change coordinates
            mouseSel: null, //to change coordinates
            debugSel: null, //to change position of debug information
            ringSels: {}, //gets filled later if part of aromatic ring
            aromaticSel: null  //gets filled later if its a non ring aromatic edge
        };
        structureSels.edgeSels[edgeId] = edgeSels;

        //create the visualization step by step
        const usedColor = this.createGradientForEdge(structureId,
            edge,
            from.color,
            to.color,
            midpoints
        );
        this.drawEdgeRepresentation(edge,
            wrapperContainer.structureSel,
            structEdgeString,
            usedColor,
            drawPoints,
            edgeSels,
            midpoints
        );
        this.drawEdgeSelector(wrapperContainer.selectorSel,
            structEdgeString,
            selWidth,
            midpoints,
            edgeSels
        );
        if (this.opts.debug.edges) {
            this.drawEdgeDebugText(structure, edge, wrapperContainer.debugSel, edgeSels);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For the construction of bonds within aromatic rings, adds the inner
     * (dashed) line to the SVG.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the outer bond
     * @param ringId {Number} - the unique id of the ring the inner bond
     * should be drawn in
     * @param fromCoords {Object} - x- and y-coordinates of the first endpoint
     * of the inner line
     * @param toCoords {Object} - x- and y-coordinates of the second endpoint
     * of the inner line
     */
    drawAromaticRingEdge(structureId, edgeId, ringId, fromCoords, toCoords) {
        //find SVG group to attach aromatic edge to
        const edgeSels = this.edgeToSelMap[structureId].edgeSels[edgeId];
        const groupSel = edgeSels.groupSel;
        //find the edge's gradient to apply here as well
        const usedColor = this.edgeGradientMap[structureId][edgeId].htmlColor;
        const dashOff = this.utils.base.getBaseDashOffsetByMidpoints([
            fromCoords, toCoords
        ]);
        const styles = {
            'stroke-dasharray': this.utils.line.dashArrString(), 'stroke-dashoffset': dashOff
        };
        if (usedColor !== this.opts.colors.DEFAULT) {
            styles.stroke = usedColor;
        }
        const selId = `structure_${structureId}_edge_${edgeId}_ring_${ringId}`;
        edgeSels.ringSels[ringId] =
            this.utils.line.addLineToSvg(groupSel, selId, fromCoords, toCoords, styles);
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creating the representation for a bond, creates its main
     * representation (lines etc., not the selector or debug info).
     *
     * @param edge {Edge} - the edge object to draw
     * @param wrapper {Object} - D3 selector of group to put elements in
     * @param structEdgeString {String} - base string for element ids
     * @param usedColor {String} - URL of gradient or current color of the
     * bond if the bond has only one color
     * @param drawPoints {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @param edgeSels {Object} - object caching relevant D3 selectors
     */
    drawEdgeRepresentation(edge,
        wrapper,
        structEdgeString,
        usedColor,
        drawPoints,
        edgeSels,
        midpoints
    ) {
        const group = GroupUtils.addGroupToSvg(wrapper, structEdgeString + '_w');
        group.style('stroke', usedColor) //for lines
            .style('fill', usedColor)
            .style('stroke-linejoin', 'round') //for paths
            .style('stroke-width', this.opts.lineWidth + 'px');
        //create lines / path
        if (edge.isAromaticNoRing()) {
            this.utils.line.addElementsByDrawPoints(group, [drawPoints[0]], {edgeType: edge.type});
            edgeSels.groupSel = group;
            const dashOff = this.utils.base.getDashOffsetByMidpoints([
                drawPoints[1][0], drawPoints[1][1]
            ]);
            const styles = {
                'stroke-dasharray': this.utils.line.dashArrString(), 'stroke-dashoffset': dashOff
            };
            edgeSels.aromaticSel = this.utils.line.addLineToSvg(edgeSels.groupSel,
                '',
                drawPoints[1][1],
                drawPoints[1][0],
                styles
            );
        } else {
            this.utils.line.addElementsByDrawPoints(group, drawPoints, {edgeType: edge.type});
            edgeSels.groupSel = group;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the selector around an edge in form of a line of a given selector
     * width. At first, this selector will be made invisible by setting its
     * opacity to 0.
     *
     * @param wrapper {Object} - container to add selector into
     * @param structEdgeString {String} - base string for structure to create
     * id from
     * @param selWidth {Number} - width of created line
     * @param midpoints {Array} - array of two objects holding the coordinates
     * of the endpoints of the bond on both sides ([from, to])
     * @param edgeSels {Object} - selector object used within the drawer to
     * cache selectors
     */
    drawEdgeSelector(wrapper, structEdgeString, selWidth, midpoints, edgeSels) {
        const selId = structEdgeString + '_selector';
        edgeSels.mouseSel =
            this.utils.selector.drawLineSelectionShape(wrapper, selId, midpoints, selWidth).sel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creating the representation for a bond, creates a text element
     * referencing the internal id in the center of the bond representation.
     *
     * @param structure {Structure} - Structure object containing the bond
     * @param edgeId {Number} - id of the bond to draw debug text for
     * @param from {Number} - id of first atom the bond is connected to
     * @param to {Number} - id of second atom the bond is connected to
     * @param wrapper {Object} - D3 selector for group element to append drawn
     * lines/paths to
     * @param edgeSels {Object} - selector object used within the drawer to
     * cache selectors
     */
    drawEdgeDebugText(structure, {id: edgeId, from, to}, wrapper, edgeSels) {
        const fromCoords = structure.atomsData.getAtom(from).coordinates;
        const toCoords = structure.atomsData.getAtom(to).coordinates;
        const midEdge = {
            x: (fromCoords.x + toCoords.x) / 2, y: (fromCoords.y + toCoords.y) / 2
        };
        const styles = {
            'dominant-baseline': 'central', 'font-size': this.opts.debug.textSize
        };
        if (!this.opts.debug.showEdges) {
            styles['display'] = 'none';
        }
        edgeSels.debugSel = this.utils.text.addTextToSvg(wrapper, '', edgeId, midEdge, styles);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches all DOM elements which are part of a bond's drawn representation.
     * These remain cached and can be reattached by use of the redrawEdge()
     * function.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to remove related
     * DOM elements for
     * @param unselect {Boolean} - whether to unselect the bond's selector
     * element prior to detaching it (if you plan to reattach it later)
     */
    removeEdge(structureId, edgeId, unselect = true) {
        const structureSels = this.edgeToSelMap[structureId];
        const edgeSels = structureSels.edgeSels[edgeId];
        if (unselect) {
            this.utils.selector.switchSelector(edgeSels.mouseSel, 'line', SelectorStatus.unselect);
        }
        edgeSels.groupSel.remove();
        if (edgeSels.aromaticSel) {
            edgeSels.aromaticSel.remove();
        }
        edgeSels.mouseSel.remove();
        if (this.opts.debug.edges) {
            edgeSels.debugSel.remove();
        }
        this.edgeGradientMap[structureId][edgeId].domSel.remove();
    }

    /*----------------------------------------------------------------------*/
    /**
     * Detaches the DOM element of the inner line of an aromatic edge.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the outer bond
     * @param ringId {Number} - the unique id of the ring the inner bond
     * is drawn in
     */
    removeAromaticRingEdge(structureId, edgeId, ringId) {
        this.edgeToSelMap[structureId].edgeSels[edgeId].ringSels[ringId].remove();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches cached detached DOM elements which are part of a bond's
     * drawn representation (after application of removeEdge()).
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edge {Edge} - Edge object representing the bond
     */
    redrawEdge(structureId, edge) {
        const edgeId = edge.id;
        const structureSels = this.edgeToSelMap[structureId];
        const edgeSels = structureSels.edgeSels[edgeId];
        //add back edge group to structure group
        let wrapper = structureSels;
        //append ring systems
        if (edge.ringSystem) {
            wrapper = structureSels.ringSysSels[edge.ringSystem];
        }
        //append edge groups
        const structNode = wrapper.structureSel.node();
        structNode.appendChild(edgeSels.groupSel.node());
        if (edgeSels.aromaticSel) {
            structNode.appendChild(edgeSels.aromaticSel.node());
        }
        if (this.opts.debug.edges) {
            structureSels.debugSel.node().appendChild(edgeSels.debugSel.node());
        }
        wrapper.selectorSel.node().appendChild(edgeSels.mouseSel.node());
        //add back gradient
        this.defsComponent.defsDom.node().appendChild(this.edgeGradientMap[structureId]
            [edgeId].domSel.node());
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reattaches the cached line of an aromatic bond to the DOM.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the outer bond
     * @param ringId {Number} - the unique id of the ring the inner bond
     * is drawn in
     */
    redrawAromaticRingEdge(structureId, edgeId, ringId) {
        const structureSels = this.edgeToSelMap[structureId];
        structureSels.structureSel.node()
            .appendChild(structureSels.edgeSels[edgeId].ringSels[ringId].node());
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the SVG representation of an edge by updating the corresponding
     * lines (both of the actual edge and the selector) / paths and also the
     * edge's gradient.
     *
     * @param structure {Structure} - the object holding the edge
     * @param edge {Edge} - Edge object with all the necessary coordinate
     * information
     * @param byTemp {Boolean} - whether to move edge using temporary draw
     * info
     * @param typeChanged {Boolean} - flag to denote if type of edge has
     * changed since it was last drawn
     */
    moveEdge(structure, edge, byTemp = false, typeChanged = false) {
        const structureId = structure.id;
        const {id: edgeId, type} = edge;
        const edgeSels = this.edgeToSelMap[structureId].edgeSels[edgeId];
        const drawElements = edgeSels.groupSel;
        const drawElementsNode = drawElements.node();
        const mouseSel = edgeSels.mouseSel;
        const gradientInfo = this.edgeGradientMap[structureId][edgeId];
        const {midpoints, drawPoints} = byTemp ? edge.tempDrawInfo : edge.drawInfo;

        //EDGE: change position / create new path
        if (typeChanged) { //recreate edges
            GroupUtils.clearWrapper(drawElements);
            this.utils.line.addElementsByDrawPoints(drawElements, drawPoints, {edgeType: type});
        } else { //move edges based on new information
            const movableEdges = [
                'single',
                'double',
                'triple',
                'stereoBack',
                'stereoBackReverse',
                'stereoFront',
                'stereoFrontReverse'
            ];
            if (movableEdges.includes(type)) {
                if (edgeSels.aromaticSel) {
                    const path = this.utils.line.createPathFromPoints([drawPoints[0]]);
                    const pathNode = drawElementsNode.firstChild;
                    pathNode.setAttribute('d', path);
                    const aromaticNode = edgeSels.aromaticSel.node();
                    this.utils.line.updateLineByDrawpoints(aromaticNode, drawPoints[1]);
                } else {
                    const path = this.utils.line.createPathFromPoints(drawPoints);
                    const pathNode = drawElementsNode.firstChild;
                    pathNode.setAttribute('d', path);
                }
            }
        }

        //SELECTOR
        const mouseSelNode = mouseSel.node();
        this.utils.line.updateLineByDrawpoints(mouseSelNode, midpoints);

        //GRADIENT
        if (gradientInfo.isOnDom) {
            const gradientNode = gradientInfo.domSel.node();
            this.utils.line.updateLineByDrawpoints(gradientNode, midpoints);
        }

        //DEBUG-INFO
        if (this.opts.debug.edges) {
            const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
            const fromCoords = structure.atomsData.getAtom(edge.from)[coordParam];
            const toCoords = structure.atomsData.getAtom(edge.to)[coordParam];
            this.moveEdgeDebugText(structureId, edgeId, fromCoords, toCoords);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of bond movement, updates position of debug text.
     *
     * @param structureId {Number} - unique id of structure containing the
     * bond
     * @param edgeId {Number} - unique id of the bond to move
     * @param firstCoords {Object} - new coordinates for first endpoint
     * @param secondCoords {Object} - new coordinates for second endpoint
     */
    moveEdgeDebugText(structureId, edgeId, firstCoords, secondCoords) {
        if (!this.opts.debug.edges) {
            return;
        }
        const dbgNode = this.edgeToSelMap[structureId].edgeSels[edgeId]
            .debugSel.node();
        this.utils.base.setAttributeRounded(dbgNode, 'x', (firstCoords.x + secondCoords.x) / 2);
        this.utils.base.setAttributeRounded(dbgNode, 'y', (firstCoords.y + secondCoords.y) / 2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a bond in the draw area by switching the color of its
     * corresponding selection shape to the selection color.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to select
     */
    selectEdge(structureId, edgeId) {
        const selector = this.edgeToSelMap[structureId].edgeSels[edgeId].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.select);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Signals that a bond is hovered in the draw area by switching the color
     * of its corresponding selection shape to the hover color.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to hover
     */
    hoverEdge(structureId, edgeId) {
        const selector = this.edgeToSelMap[structureId].edgeSels[edgeId].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously selected/hovered bond, removes color from the bond's
     * corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to unselect
     */
    unselectEdge(structureId, edgeId) {
        const selector = this.edgeToSelMap[structureId].edgeSels[edgeId].mouseSel;
        this.utils.selector.switchSelector(selector, 'line', SelectorStatus.unselect);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the color of a bond's representation by giving end colors for a
     * gradient along the bond (colors can be the same).
     *
     *@param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to recolor
     * @param fromColor {String} - valid CSS color for the first end of the
     * gradient which colors the bond
     * @param toColor {String} - valid CSS color for the second end of the
     * gradient which colors the bond
     */
    recolorEdge(structureId, edgeId, fromColor, toColor) {
        const setGroupColor = (color) => {
            const group = this.edgeToSelMap[structureId].edgeSels[edgeId].groupSel;
            group.style('stroke', color)
                .style('fill', color);
        };

        const gradientInfo = this.edgeGradientMap[structureId][edgeId];
        if (fromColor === toColor) { //no gradient needed
            if (gradientInfo.isOnDom) {
                gradientInfo.domSel.remove();
                gradientInfo.isOnDom = false;
            }
            if (gradientInfo.htmlColor !== fromColor) {
                gradientInfo.htmlColor = fromColor;
                setGroupColor(fromColor);
            }
        } else { //gradient needed
            if (!gradientInfo.isOnDom) {
                this.defsComponent.defsDom.node().appendChild(gradientInfo.domSel.node());
                gradientInfo.isOnDom = true;
                const url = gradientInfo.url;
                gradientInfo.htmlColor = url;
                setGroupColor(url);
            }
            if (fromColor) {
                gradientInfo.fromColorSel.attr('stop-color', fromColor);
            }
            if (toColor) {
                gradientInfo.toColorSel.attr('stop-color', toColor);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the color of an inner line of an aromatic bond.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the outer bond
     * @param ringId {Number} - the unique id of the ring the inner bond
     * is drawn in
     */
    recolorAromaticRingEdge(structureId, edgeId, ringId) {
        const ringEl = this.edgeToSelMap[structureId].edgeSels[edgeId].ringSels[ringId];
        const curColor = this.edgeGradientMap[structureId][edgeId].htmlColor;
        ringEl.style('stroke', curColor);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Change the color of a bond's corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to select
     * @param color {String} - valid CSS color
     */
    recolorEdgeSelector(structureId, edgeId, color) {
        const selector = this.edgeToSelMap[structureId].edgeSels[edgeId].mouseSel;
        SelectorUtils.changeSelectorColor(selector, 'line', color);
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of creating the SVG representation of a bond, creates the
     * gradient (in the SVG defs) to color it.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the bond to draw
     * @param type {String} - type of the bond, e.g., 'single', 'double'
     * @param fromColor {String} - CSS color of the first side of the bond
     * @param toColor {String} - CSS color of the second side of the bond
     * @param midpoints {Array} - array of two objects holding the coordinates
     * of the endpoints of the bond on both sides ([from, to])
     * @returns {String} - URL of gradient or current color of the bond if the
     * bond has only one color
     */
    createGradientForEdge(structureId, {id: edgeId, type}, fromColor, toColor, midpoints) {
        const gradientId = `${this.svgId}_s_${structureId}_e_${edgeId}_g`;
        let firstColor, secondColor;
        //be careful with order of colors
        if (type === 'stereoFrontReverse' || type === 'stereoBackReverse') {
            firstColor = toColor;
            secondColor = fromColor;
        } else {
            firstColor = fromColor;
            secondColor = toColor;
        }

        const gradient = this.defsComponent.addGradientToSvg(gradientId,
            firstColor,
            secondColor,
            midpoints[0],
            midpoints[1]
        );
        if (firstColor === secondColor) {
            gradient.domSel.remove();
            gradient.isOnDom = false;
            gradient.htmlColor = firstColor;
        }
        //set map entry, return the used color (url or RBG code)
        this.edgeGradientMap[structureId][edgeId] = gradient;
        return gradient.htmlColor;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if a representation has already been created for a bond (by use
     * of the drawEdge() function).
     *
     * @param structureId {Number} - the unique id of the structure containing
     * the bond
     * @param edgeId {Number} - the unique id of the bond to check for
     * @returns {Boolean} - whether a representation exists
     */
    wasEdgeDrawnBefore(structureId, edgeId) {
        return this.edgeToSelMap[structureId].edgeSels[edgeId].edgeDrawn;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the inner line of an aromatic bond. Assumes that moveEdge() is
     * always called as these inner lines use the same gradients.
     *
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param edgeId {Number} - the unique id of the outer bond
     * @param ringId {Number} - the unique id of the ring the inner bond
     * should be drawn in
     * @param fromCoords {Object} - x- and y-coordinates of the new first
     * endpoint of the inner line
     * @param toCoords {Object} - x- and y-coordinates of the new second
     * endpoint of the inner line
     */
    moveAromaticRingEdge(structureId, edgeId, ringId, fromCoords, toCoords) {
        const ringSel = this.edgeToSelMap[structureId].edgeSels[edgeId].ringSels[ringId];
        const dashOff = this.utils.base.getBaseDashOffsetByMidpoints([
            fromCoords, toCoords
        ]);
        ringSel.style('stroke-dashoffset', dashOff);
        const ringNode = ringSel.node();
        this.utils.line.updateLineByDrawpoints(ringNode, [fromCoords, toCoords]);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides edges by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all edges
     * @param bonds {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide edges from
     * @param visibilityClass {String} - CSS class for show/hide
     */
    setVisibility(full, bonds, structureId, visibilityClass) {
        if ((full || bonds) && this.edgeToSelMap.hasOwnProperty(structureId)) {
            const edgeToSelMap = this.edgeToSelMap[structureId];
            edgeToSelMap.structureSel.classed(visibilityClass, true);
            edgeToSelMap.selectorSel.classed(visibilityClass, true);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates the EDGE skeleton of a structure (new atom positions to be set
     * separately).
     *
     * @param structureId {Number} - id of structure to move edge skeleton for
     * @param angle {Number} - angle to rotate by
     * @param origin {Object} - point to rotate around
     * @param isDeg {Boolean} - whether the provided angle is given in degrees
     * or radians
     */
    setRotationEdgeSkeleton(structureId, angle, origin, isDeg = true) {
        const structureSels = this.edgeToSelMap[structureId];
        const deg = isDeg ? angle : AngleCalculation.radianToDegree(angle);
        structureSels.structureSel
            .attr('transform', `rotate(${deg} ${origin.x} ${origin.y})`);
        structureSels.selectorSel
            .attr('transform', `rotate(${deg} ${origin.x} ${origin.y})`);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the rotation of an edge skeleton.
     *
     * @param structureId {Number} - id of structure to reset rotation for
     */
    resetEdgeSkeletonRotation(structureId) {
        const structureSels = this.edgeToSelMap[structureId];
        SelectorUtils.resetTransformOnSelectors(structureSels);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a (new) structure, adds new container groups to the svg for edges.
     * Creates a new wrapper in the edge group. Further
     * prepares the mapping of selectors for later access. In the selector
     * map, the created groups are mapped also, so they may be hidden later.
     *
     * @param structure {Structure} - Structure object
     * @param structureId {structureId} - id of Structure object
     * @param debug {Boolean} - true if debug information shall be visualized
     */
    addEdgesToTrack(structure, structureId, debug) {
        const movementGroupIDs = {
            idGroup: this.svgId + '_s_' + structureId + '_e',
            idSelGroup: this.svgId + '_s_' + structureId + '_eS',
            idDbgGroup: this.svgId + '_s_' + structureId + '_dbgEdges'
        };
        const movementGroupsDom = GroupUtils.addGroupsForMovement(this.edgeGroupDom,
            this.edgeSelGroupDom,
            this.edgeDbgGroupDom,
            movementGroupIDs,
            debug
        );
        const edgeSels = {};
        structure.edgesData.edges.forEach(({id: edgeId}) => {
            edgeSels[edgeId] = {
                edgeDrawn: false
            };
        });
        //creation of more complicated edge maps
        const edgeToSelMap = {
            structureSel: movementGroupsDom.movGroupDom,
            selectorSel: movementGroupsDom.movSelGroupDom,
            edgeSels: edgeSels,
            debugSel: movementGroupsDom.movDbgGroupDom
        };

        const edgeRingMap = {};
        for (const bccId in structure.ringsData.ringSystems) {
            const ringMovementGroupIDs = {
                idGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_e',
                idSelGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_eS',
                idDbgGroup: this.svgId + '_s_' + structureId + '_rs_' + bccId + '_dbg'
            };
            const ringMovementGroupsDom = GroupUtils.addGroupsForMovement(movementGroupsDom.movGroupDom,
                movementGroupsDom.movSelGroupDom,
                movementGroupsDom.movDbgGroupDom,
                ringMovementGroupIDs,
                debug
            );
            edgeRingMap[bccId] = {
                structureSel: ringMovementGroupsDom.movGroupDom,
                selectorSel: ringMovementGroupsDom.movSelGroupDom,
                debugSel: ringMovementGroupsDom.movDbgGroupDom
            };
        }
        edgeToSelMap.ringSysSels = edgeRingMap;
        this.edgeToSelMap[structureId] = edgeToSelMap;
        this.edgeGradientMap[structureId] = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides all text representations of debug labels. Otherwise, display all
     * text representations of debug labels, provided parameters
     * to ever show specific debug elements are set in the configuration
     *
     * @param visible {Boolean} - true if debug labels shall be visible
     */
    toggleDebugLabelsVisibility(visible) {
        let display = 'none';
        if (visible) {
            display = null;
        }
        if (this.opts.debug.edges && this.opts.debug.showEdges) {
            for (const structureSel of Object.values(this.edgeToSelMap)) {
                for (const edgeSel of Object.values(structureSel.edgeSels)) {
                    edgeSel.debugSel.style('display', visible);
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached edge DOM elements back
     * into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructureEdges(structureId) {
        this.edgeGroupDom.node().appendChild(this.edgeToSelMap[structureId].structureSel.node());
        this.edgeSelGroupDom.node().appendChild(this.edgeToSelMap[structureId].selectorSel.node());
        for (const edgeId in this.edgeGradientMap[structureId]) {
            const gradient = this.edgeGradientMap[structureId][edgeId].domSel;
            gradient && this.defsComponent.defsDom.node().appendChild(gradient.node());
        }
        if (this.edgeToSelMap[structureId].debugSel) {
            this.edgeDbgGroupDom.node().appendChild(this.edgeToSelMap[structureId].debugSel.node());
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes edges of a structure from the DOM.
     *
     * @param structureId {Number} - the unique id of the structure to remove its
     * edges from DOM
     */
    removeStructureEdgesFromDOM(structureId) {
        this.edgeToSelMap[structureId].structureSel.remove();
        this.edgeToSelMap[structureId].selectorSel.remove();
        if (this.edgeToSelMap[structureId].debugSel) {
            this.edgeToSelMap[structureId].debugSel.remove();
        }
        for (const edgeId in this.edgeGradientMap[structureId]) {
            const gradient = this.edgeGradientMap[structureId][edgeId].domSel;
            gradient && gradient.remove();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached edge information for a given structure (by its id).
     *
     * @param structureId {Number} - id of structure to remove information
     * about.
     */
    purgeStructureEdgesFromCache(structureId) {
        delete this.edgeToSelMap[structureId];
        delete this.edgeGradientMap[structureId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for edges of a certain ring system.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to reset translations
     * for
     */
    resetRingEdgeSkeletonTranslation(structureId, ringSysId) {
        const edgeSels = this.edgeToSelMap[structureId].ringSysSels[ringSysId];
        SelectorUtils.resetTransformOnSelectors(edgeSels);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for edges of a certain structure.
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetEdgeSkeletonTranslation(structureId) {
        SelectorUtils.resetTransformOnSelectors(this.edgeToSelMap[structureId]);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (edges as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveEdgeSkeleton(structureId, xOffset, yOffset) {
        const edgeSels = this.edgeToSelMap[structureId];
        this.utils.selector.moveSelectorsOfSkeleton(edgeSels, xOffset, yOffset, 'edge');
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (edges as groups) of a ring system by specified
     * offsets.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to move skeleton of
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     */
    moveRingEdgeSkeleton(structureId, ringSysId, xOffset, yOffset) {
        const edgeSels = this.edgeToSelMap[structureId].ringSysSels[ringSysId];
        this.utils.selector.moveSelectorsOfSkeleton(edgeSels, xOffset, yOffset, 'edge');
    }
}

/* src/Components/Structure/StructureCircleGroupsComponent.js */
/**
 * Component that manages SVG groups for the drawing of structure circles.
 */
class StructureCircleGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the caching of draw element selectors.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param structureCircleGroupDom {Object} - D3 selector of the structure circle group
     * @param structureCircleSelGroupDom {Object} - D3 selector of the selection shape group
     * @param svgId {String} - DOM id of the SVG
     */
    constructor(opts, utils, structureCircleGroupDom, structureCircleSelGroupDom, svgId) {
        this.opts = opts;
        this.utils = utils;
        this.structureCircleGroupDom = structureCircleGroupDom;
        this.structureCircleSelGroupDom = structureCircleSelGroupDom;
        this.svgId = svgId;

        //Structure object id -> structureSel/selectorShapes -> selectors
        this.structureCircleToSelMap = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the circle representation as alternative representation
     * of a structure within the SVG. Each circle contains the name of the
     * structure if present.
     *
     * @param structure {Object} - the Structure object
     */
    drawStructureCircle(structure) {
        const structureId = structure.id;
        const structureMid = structure.boundaries.mid;
        const structureCircleGroupDom = this.structureCircleGroupDom;

        //extract styles
        const {
            rad, textColor, circleCss
        } = this.opts.structureCircleOpts[structure.structureType] ||
        this.opts.structureCircleOpts["default"];

        //add structure wrapper for circle
        const circleWrapperId = this.svgId + '_s_' + structureId + '_sc';
        const circleWrapper = GroupUtils.addGroupToSvg(structureCircleGroupDom, circleWrapperId);

        //add svg circle element
        const circle = this.utils.circle.addCircleToSvg(circleWrapper,
            '',
            structureMid,
            rad,
            circleCss
        );

        //add text wrapper
        const textWrapperId = circleWrapperId + '_text';
        const textWrapper = GroupUtils.addGroupToSvg(circleWrapper, textWrapperId);

        //split label to show multiple lines in the circle
        const labels = this.determineStructureCircleTextSplits(structure);

        //add text
        const labelSels = [];
        for (const label of labels) {
            labelSels.push(this.utils.text.placeText(textWrapper, label, structureMid, textColor));
        }
        //position text
        const finalizedLabels = this.finalizeStructureCircleLabelPosition(structure, labelSels);

        //add structure wrapper for selection
        const selectionWrapperId = this.svgId + '_s_' + structureId + '_scS';
        const selectionWrapper = GroupUtils.addGroupToSvg(this.structureCircleSelGroupDom,
            selectionWrapperId
        );

        //add selectors for selection
        const {
            sel: mouseSel, selectorShape: selectorShape
        } = this.utils.selector.drawCircleSelectionShape(selectionWrapper,
            undefined,
            structureMid,
            rad * 1.15
        );

        //add the d3 selectors to the drawer
        this.structureCircleToSelMap[structureId] = {
            circleSel: circle,
            circlePlacementInfo: {
                x: structureMid.x, y: structureMid.y
            },
            labelSel: textWrapper,
            textSels: finalizedLabels.map(value => value.sel),
            textPlacementInfos: finalizedLabels.map(value => ({x: value.x, y: value.y})),
            selectorShapes: [selectorShape],
            mouseSels: [mouseSel],
            structureSel: circleWrapper,
            selectorSel: selectionWrapper
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Splits the label of the structure to show rows in the structure circle.
     * Splits either automatically by generating equal sized chunks (note that
     * this may be not the best decision since some letters are wider than
     * others) or splits at the first occurrences of a value in a array.
     * Parameters can be set for each specific structure type in the config.
     *
     * @param structure {Object} - the Structure object which label to split
     * @returns {Array} - array containing the split label
     */
    determineStructureCircleTextSplits(structure) {
        const label = structure.structureLabel;
        if (!label) {
            return [];
        }
        const circleStyles = this.opts.structureCircleOpts[structure.structureType] ||
            this.opts.structureCircleOpts['default'];
        const maxLines = circleStyles.labelMaxLines;
        if (maxLines > 3) { //max 3 are implemented
            throw "labelMaxLines in config/opts is " + maxLines + " but is limited to 3."
        }
        const lines = [];

        if (circleStyles.labelAutoSplit) { //automatically split to equal size chunks
            const minLineChars = circleStyles.labelAutoSplitMinCharsPerLine;
            const labelLength = label.length;
            let lineLength = labelLength;
            let lineCount = 1;
            //determine number of lines
            while (lineCount < maxLines && lineLength > minLineChars) {
                lineCount++;
                lineLength = Math.ceil(labelLength / lineCount);
            }
            //split label into lines
            for (let i = 0, offset = 0; i < lineCount; i++, offset += lineLength) {
                lines.push(label.substr(offset, lineLength));
            }
        } else { //split at defined chars
            const splitChars = circleStyles.labelManualLineBreakChars;
            const includeSplitChars = circleStyles.labelManualIncludeSplitChar;
            let line = "";
            for (let i = 0; i < label.length; i++) {
                if (lines.length === maxLines - 1) {
                    lines.push(label.slice(i));
                    line = "";
                    break;
                }

                const currChar = label[i];
                if (splitChars.includes(currChar)) {
                    if (includeSplitChars[lines.length]) {
                        line += currChar
                    }
                    lines.push(line);
                    line = "";
                } else {
                    line += currChar;
                }
            }
            if (line !== "") {
                lines.push(line);
            }
        }

        return lines;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Splits the label of the structure to show rows in the structure circle.
     * Splits either automatically by generating equal sized chunks (note that
     * this may be not the best decision since some letters are wider than
     * others) or splits at the first occurrences of a value in a array.
     * Parameters can be set for each specific structure type in the config.
     *
     * @param structure {Object} - the Structure object which label to split
     * @param labelSels {Object} - the Structure object which label to split
     * @returns {Array} - array containing the split label
     */
    finalizeStructureCircleLabelPosition(structure, labelSels) {
        const circleStyles = this.opts.structureCircleOpts[structure.structureType] ||
            this.opts.structureCircleOpts['default'];
        const sameFontSize = circleStyles.labelSameFontSize;
        //make the rad a little bit smaller so the text does not collide with
        //the circle border
        const circleRad = circleStyles.rad * 0.95;
        const circleMid = structure.boundaries.mid;
        const movedLabels = [];
        if (labelSels.length === 1) {
            //Only one row. Just scale the text. No movement

            const sel = labelSels[0];
            //set the font-size to 1 so we can use the return value directly as
            //the new font-size
            sel.attr('font-size', 1 + 'px');
            const scale = this.calcScaleStructureCircleLabel(sel,
                circleMid,
                circleRad,
                circleRad,
                true
            );
            sel.attr('font-size', scale + 'px');
            movedLabels.push({sel: sel})
        } else if (labelSels.length === 2) {
            //scale both texts and move one text up and one text down

            //we want to add some space in the middle of the texts
            const midSpace = circleRad * .1;

            const selTop = labelSels[0];
            const selBot = labelSels[1];

            //calculate scaling and set font-size
            selTop.attr('font-size', 1 + 'px');
            const scaleTop = this.calcScaleStructureCircleLabel(selTop,
                circleMid,
                circleRad,
                circleRad - midSpace
            );
            selBot.attr('font-size', 1 + 'px');
            const scaleBot = this.calcScaleStructureCircleLabel(selBot,
                circleMid,
                circleRad,
                circleRad - midSpace
            );

            let scale;
            if (sameFontSize) {
                scale = Math.min(scaleTop, scaleBot);
            }
            selTop.attr('font-size', (scale || scaleTop) + 'px');
            selBot.attr('font-size', (scale || scaleBot) + 'px');

            //translate on y axis
            const oldTopY = parseFloat(selTop.attr('y'));
            selTop.attr('y', function () {
                const bbox = this.getBBox();
                return oldTopY - bbox.height / 2 - midSpace / 2;
            });
            const oldBotY = parseFloat(selBot.attr('y'));
            selBot.attr('y', function () {
                const bbox = this.getBBox();
                return oldBotY + bbox.height / 2 + midSpace / 2;
            });

            movedLabels.push({sel: selTop});
            movedLabels.push({sel: selBot});
        } else if (labelSels.length === 3) {
            //scale both texts and move one text up and one text down

            //we want to add some space in between the texts
            const spaceBetween = circleRad * .025;

            const selTop = labelSels[0];
            const selMid = labelSels[1];
            const selBot = labelSels[2];

            //set the font-size to 1 so we can use the return value directly as
            //the new font-size
            selTop.attr('font-size', 1 + 'px');
            selMid.attr('font-size', 1 + 'px');
            selBot.attr('font-size', 1 + 'px');

            //first calculate the size of the mid text because the space of the
            //other two may depend on this. Also give it a max height, so the
            //top and bottom texts may have the same min vertical space.
            //This is done by slicing of 10% (by radius) of the circles top and
            //bot, subtracting the spaceBetween and dividing by 3 (for the
            //3 texts we have). Although it might not be optimal for every case,
            //this heuristic works well in testing.
            const maxMidHeight = (circleRad * .8 - 2 * spaceBetween) / 3;
            const scaleMid = this.calcScaleStructureCircleLabel(selMid,
                circleMid,
                circleRad,
                circleRad,
                true,
                maxMidHeight
            );
            //set font-size of mid and calculate available space for top and bottom
            selMid.attr('font-size', scaleMid + 'px');
            let midHeight = selMid.node().getBBox().height;
            //available height for top and bottom
            const availableHeight = circleRad - midHeight / 2 - spaceBetween;

            const scaleTop = this.calcScaleStructureCircleLabel(selTop,
                circleMid,
                circleRad,
                availableHeight
            );
            const scaleBot = this.calcScaleStructureCircleLabel(selBot,
                circleMid,
                circleRad,
                availableHeight
            );

            let scale;
            if (sameFontSize) {
                scale = Math.min(scaleTop, scaleBot, scaleMid);
                selMid.attr('font-size', scale + 'px');
                midHeight = selMid.node().getBBox().height;
            }
            selTop.attr('font-size', (scale || scaleTop) + 'px');
            selBot.attr('font-size', (scale || scaleBot) + 'px');

            //translate on y axis
            const oldTopY = parseFloat(selTop.attr('y'));
            selTop.attr('y', function () {
                const bbox = this.getBBox();
                return oldTopY - bbox.height / 2 - midHeight / 2 - spaceBetween;
            });
            const oldBotY = parseFloat(selBot.attr('y'));
            selBot.attr('y', function () {
                const bbox = this.getBBox();
                return oldBotY + bbox.height / 2 + midHeight / 2 + spaceBetween;
            });

            movedLabels.push({sel: selTop});
            movedLabels.push({sel: selMid});
            movedLabels.push({sel: selBot});
        }
        for (let i = 0; i < movedLabels.length; i++) {
            const sel = movedLabels[i].sel;
            movedLabels[i] = TextUtils.centerText(sel, {
                x: parseFloat(sel.attr('x')), y: parseFloat(sel.attr('y'))
            });
        }
        return movedLabels;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates a scale parameter to scale (part of) a label of a structure
     * circle to fit inside the circle.
     * This works by define a triangle within the structure circle where the
     * the final height of the text is the opposite (a) and half the final width
     * is the adjacent (b). We know the ratio of this two because it is the same
     * as the current aspect ration of the text. We can derive tha angle alpha
     * from that. We also know the Point A of the triangle (see code). To
     * get the length of the hypotenuse we just need to calculate the intersections
     * of the structure circle with the line defined by A and alpha. From that
     * intersections we take the left-most point (because that is how the
     * triangle is defined inside the circle) and its distance to A.
     * Now we got enough information to calculate a and b.
     *
     * @param sel {Object} - the D3 element which holds the label
     * @param circleMid {Object} - the midpoints of the circle.
     * @param circleRad {Number} - the radius of the structure circle. If you
     * you prefer some space to the edge of the circle consider taking only
     * a percentage of the radius
     * @param availableYspace {Number} - the space to top or bottom that is
     * available (e.g. with 2 label and free space between this should be
     * "circle radius - freeSpace / 2")
     * @param isYcentered {Boolean} - true if the text is in the center of the
     * circle because then we must define a as half the text height
     * @param maxHeight {Number} - define a max height of the text
     * @returns {Number} - array containing the split label
     */
    calcScaleStructureCircleLabel(sel,
        circleMid,
        circleRad,
        availableYspace,
        isYcentered = false,
        maxHeight = undefined
    ) {
        const node = sel.node();
        const bbox = node.getBBox();
        const b = bbox.width / 2;
        const a = isYcentered ? bbox.height / 2 : bbox.height;
        if (b === 0) { //abort if there is not label
            return 1;
        }

        //angle alpha in triangle;
        const alpha = Math.atan(a / b);
        //point A in the triangle
        const pointA = {
            x: circleMid.x, y: circleMid.y + circleRad - availableYspace
        };
        const intersections = LineCalculation.findCircleLineIntersectionsFromPointAngle(circleRad,
            circleMid.x,
            circleMid.y,
            pointA.x,
            pointA.y,
            alpha
        );
        //only take the intersection on the left side since that is
        //how the triangle is defined
        intersections.sort(function (a, b) {
            return a.x - b.x;
        });
        const hypotenuseLength = VectorCalculation.getDist2d(intersections[0], pointA);
        let newHeight = hypotenuseLength * Math.sin(alpha);
        if (maxHeight) {
            newHeight = Math.min(newHeight, maxHeight);
        }
        //Do not produce larger texts than defined in config
        return this.utils.base.round(Math.min(newHeight / a, this.opts.textSize));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies movement to a structureCircle following given offsets.
     *
     * @param structureId {Number} - the unique id of the label
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveStructureCircle(structureId, {
        x: xOffset, y: yOffset
    }) {
        const {
            circleSel, textSels, mouseSels, circlePlacementInfo, textPlacementInfos, selectorShapes
        } = this.structureCircleToSelMap[structureId];
        for (let i = 0; i < textSels.length; i++) {
            this.utils.text.moveTextByPlacementInfo(textSels[i],
                textPlacementInfos[i],
                xOffset,
                yOffset
            );
        }
        this.utils.selector.moveCircleSelectorByPlacementInfo(circleSel,
            circlePlacementInfo,
            xOffset,
            yOffset
        );
        this.utils.selector.moveAllSelectors(mouseSels, selectorShapes, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Signals that a structure circle is hovered in the draw area by switching the
     * color of its corresponding selection shape to the hover color.
     *
     * @param structureId {Number} - the unique id of the structure the structure
     * circle belongs to
     */
    hoverStructureCircle(structureId) {
        const structureCircleSel = this.structureCircleToSelMap[structureId];
        this.utils.selector.switchTextLabelSelectorStatus(structureCircleSel, SelectorStatus.hover);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a structure circle in the draw area by switching the color of its
     * corresponding selection shape to the selection color.
     *
     * @param structureId {Number} - the unique id of the structure the structure
     * circle belongs to
     */
    selectStructureCircle(structureId) {
        const structureCircleSel = this.structureCircleToSelMap[structureId];
        this.utils.selector.switchTextLabelSelectorStatus(structureCircleSel,
            SelectorStatus.select
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously selected/hovered structure circle, removes color from the
     * corresponding selection shape.
     *
     * @param structureId {Number} - the unique id of the structure the structure
     * circle belongs to
     */
    unselectStructureCircle(structureId) {
        const structureCircleSel = this.structureCircleToSelMap[structureId];
        this.utils.selector.switchTextLabelSelectorStatus(structureCircleSel,
            SelectorStatus.unselect
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves the saved bbox draw limits of the drawn element of
     * a structure circle.
     *
     * @param structureId {Number} - the unique id of the structure the circle
     * belongs to
     * @returns {Object} - object detailing draw limits
     */
    getStructureCircleDrawLimits(structureId) {
        return BaseUtils.convertBBoxToMaxes(BaseUtils.getSelBBox(this.structureCircleToSelMap[structureId].structureSel));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves information on the selector shape around a structure circle.
     *
     * @param structureId {Number} - the unique id of the structure the circle
     * belongs to
     * @returns {Array} - array containing an object describing the shape
     */
    getStructureCircleSelShapes(structureId) {
        return this.structureCircleToSelMap[structureId].selectorShapes;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows/hides structure circles by changing the corresponding display
     * properties of the svg elements. Also hides the selectors.
     *
     * @param full {Boolean} - set visibility of all structure circles
     * @param structureCircle {Boolean} - toggles the visibility if set true
     * @param structureId {Number} - id of structure to show/hide structure circles from
     * @param visibilityClass {String} - CSS class for show/hide
     */
    setVisibility(full, structureCircle, structureId, visibilityClass) {
        if ((full || structureCircle) && this.structureCircleToSelMap.hasOwnProperty(structureId)) {
            const structureCircleToSelMap = this.structureCircleToSelMap[structureId];
            structureCircleToSelMap.structureSel
                .classed(visibilityClass, true);
            structureCircleToSelMap.selectorSel
                .classed(visibilityClass, true);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached structure circles
     * DOM elements back into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redraw(structureId) {
        if (this.structureCircleToSelMap.hasOwnProperty(structureId)) {
            this.structureCircleGroupDom.node()
                .appendChild(this.structureCircleToSelMap[structureId].structureSel.node());
            this.structureCircleSelGroupDom.node()
                .appendChild(this.structureCircleToSelMap[structureId].selectorSel.node());
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes structure circle only from the DOM
     *
     * @param structureId {Number} - the unique Id of the structure to remove
     * its structure circles from DOM
     */
    removeFromDOM(structureId) {
        if (this.structureCircleToSelMap.hasOwnProperty(structureId)) {
            this.structureCircleToSelMap[structureId].structureSel.remove();
            this.structureCircleToSelMap[structureId].selectorSel.remove();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached structure circle information for a given structure (by its Id).
     *
     * @param structureId {Number} - id of structure to remove structure circle information
     * from
     */
    purgeFromCache(structureId) {
        if (this.structureCircleToSelMap.hasOwnProperty(structureId)) {
            delete this.structureCircleToSelMap[structureId];
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for structure circles of a certain structure
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetStructureCircleSkeletonTranslation(structureId) {
        if (this.structureCircleToSelMap.hasOwnProperty(structureId)) {
            SelectorUtils.resetTransformOnSelectors(this.structureCircleToSelMap[structureId]);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (structure circles as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveStructureCircleSkeleton(structureId, xOffset, yOffset) {
        const structureCircleSels = this.structureCircleToSelMap[structureId];
        this.utils.selector.moveSelectorsOfSkeleton(structureCircleSels,
            xOffset,
            yOffset,
            'structureCircle'
        );
    }
}

/* src/Components/SvgComponent.js */
/**
 * Draw layer of the InteractionDrawer. Creates and manipulates the required DOM elements
 * in the DOM's inline SVG via inner components.
 */
class SvgComponent {
    /**
     * Contains D3 selector of the SVG and sets up the different draw layer(s) creating inner
     * components with outer SVG groups in the SVG draw area for different structural elements.
     *
     * @param opts {Object} - configuration parameters
     * @param svgDom {Object} - D3 selector of the SVG
     * @param svgId {String} - DOM id of the SVG
     */
    constructor(opts, svgDom, svgId) {
        this.opts = opts;
        //main element to draw in / add elements to
        this.svgDom = svgDom;
        this.svgId = svgId; //unique id necessary if multiple drawers on one page

        this.utils = new SvgUtils(this.opts);

        const backgroundDom = this.appendBackgroundRect();
        this.backgroundComponent = new BackgroundComponent(this.utils, backgroundDom);

        //gradients go in defs element
        const defsDom = this.svgDom.append('defs');
        this.defsComponent = new DefsComponent(this.utils, defsDom);

        const selectionLineDom = this.appendSelectionLine();
        this.selectionLineComponent = new SelectionLineComponent(selectionLineDom);

        const transformGroupsDom = this.appendTransformGroup();
        this.transformGroupsComponent = new TransformGroupsComponent(this.opts,
            this.utils,
            transformGroupsDom,
            this.defsComponent,
            this.svgId
        );

        //create svg groups for draw elements in order defined in configuration
        const svgElementOrder = this.opts.svgElementOrder;
        this.transformGroupsComponent.noteElementOrderInformation(svgElementOrder);
        this.transformGroupsComponent.appendPermanentGroups(svgElementOrder);
        this.transformGroupsComponent.appendTemporaryGroups();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws a background rectangle before everything else.
     */
    appendBackgroundRect() {
        return this.svgDom.append('rect')
            .attr('id', this.svgId + '_background')
            .style('width', '100%')
            .style('height', '100%')
            .style('fill', this.opts.colors.BACKGROUND);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws selector before the atoms/edges and outside transform group.
     */
    appendSelectionLine() {
        return this.svgDom.append('path')
            .attr('id', this.svgId + '_selector')
            .style('fill', this.opts.colors.multiSelectionToolFill)
            .style('stroke', this.opts.colors.multiSelectionToolBorder)
            .style('stroke-dasharray', this.opts.selectorDashArray + 'px')
            .style('stroke-width', this.opts.selectorDashWidth + 'px');
    }

    /*----------------------------------------------------------------------*/

    /**
     * Appends groups to svg for the different visualization elements. Order
     * of adding determines draw order.
     */
    appendTransformGroup() {
        return this.svgDom.append('g')
            .attr('id', this.svgId + '_view')
            .style('user-select', 'none')
            .style('-ms-user-select', 'none');
    }

    /*----------------------------------------------------------------------*/

    /**
     * Infers the necessary information about the draw area to base Drawer and
     * SvgDrawer functionality on.
     *
     * @returns {Object} - key information about the draw area
     */
    getDrawAreaInfo() {
        const drawArea = document.getElementById(this.svgId);
        const boundingRect = drawArea.getBoundingClientRect();
        return {
            type: drawArea.tagName,
            id: this.svgId,
            width: boundingRect.width,
            height: boundingRect.height,
            border: parseInt(getComputedStyle(drawArea)
                .getPropertyValue('border-width')),
            start: {
                x: boundingRect.x, y: boundingRect.y
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the inline browser SVG of the draw area, trim unnecessary
     * parts, then returns the resulting string.
     *
     * @returns {String} - serialized string in XML format containing inline
     * browser SVG information
     */
    getSvgData() {
        //remove all selectors that are not selected (or hovered) + cursor info
        return new XMLSerializer().serializeToString(this.svgDom.node())
            .replace(/<(?:line|circle).*?_selector.*?opacity: 0;/ + /.*?\/(?:line|circle)?>/g, '')
            .replace(/cursor: .*?;/, '');
    }
}

/* src/Components/TransformGroupsComponent.js */
/**
 * This component manages the SVG transform group, which contains and layers in a certain order
 * most of the other components(with SVG groups), e.g. components for atoms or the mirror line
 * visualization. Debug layers are available. Debug labels (e.g. atom ids) are drawn on these layers
 * if the respective config option is set.
 */
class TransformGroupsComponent {
    /**
     * Contains all relevant D3 selectors and instances for configuration options and drawing utils.
     * Creates containers for the order of SVG groups based on the drawer's configuration.
     *
     * @param opts {Object} - configuration parameters
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param transformGroupDom {Object} - D3 selector of the transform group
     * @param defsComponent {Object} - D3 selector of the defs element (for gradients)
     * @param svgId {String} - DOM id of the SVG
     */
    constructor(opts, utils, transformGroupDom, defsComponent, svgId) {
        this.opts = opts;
        this.utils = utils;
        this.transformGroupDom = transformGroupDom;
        this.defsComponent = defsComponent;
        this.svgId = svgId;
        this.firstElementAfterSceneGroups = this.svgId + '_interactionElements';
        if (this.opts.allowInteraction) {
            this.transformGroupDom.style('cursor', 'pointer');
        }
        //denote the order of draw element groups in the SVG transform group
        //type of the SVG group -> index
        this.svgElementPositions = {};
        //index -> {exists: ..., id: ...}
        this.svgPositionsToElements = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Appends all always present SVG groups to the SVG transform group based
     * on a given group order.
     *
     * @param svgElementOrder {Array} - order of SVG group elements based on
     * associated identifiers
     */
    appendPermanentGroups(svgElementOrder) {
        let atomGroupDom = '';
        let atomSelGroupDom = '';
        let atomDbgGroupDom = '';
        let edgeGroupDom = '';
        let edgeSelGroupDom = '';
        let edgeDbgGroupDom = '';
        let structureCircleGroupDom = '';
        let structureCircleSelGroupDom = '';
        let annotationGroupDom = '';
        let annotationSelGroupDom = '';
        svgElementOrder.forEach(identifier => {
            switch (identifier) {
                case 'bondSelectors':
                    edgeSelGroupDom = this.appendBasicGroup(identifier);
                    edgeSelGroupDom.style('stroke-linecap', 'round')
                        .style('stroke-linejoin', 'round');
                    break;
                case 'atomSelectors':
                    atomSelGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'annotationSelectors':
                    annotationSelGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'structureCirclesSelectors':
                    structureCircleSelGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'bonds':
                    edgeGroupDom = this.appendBasicGroup(identifier);
                    const color = this.opts.colors.DEFAULT;
                    edgeGroupDom.style('stroke', color)
                        .style('fill', color)
                        .style('stroke-linecap', 'round')
                        .style('stroke-linejoin', 'round');
                    break;
                case 'atoms':
                    atomGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'annotations':
                    annotationGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'structureCircles':
                    structureCircleGroupDom = this.appendBasicGroup(identifier);
                    break;
                case 'bondDebugTexts':
                    if (this.opts.debug.edges) {
                        edgeDbgGroupDom = this.appendBasicGroup(identifier);
                        edgeDbgGroupDom.style('fill', 'red')
                            .style('font-size', this.opts.debug.textSize + 'px')
                            .style('text-anchor', 'middle');
                    }
                    break;
                case 'atomDebugTexts':
                    if (this.opts.debug.atoms) {
                        atomDbgGroupDom = this.appendBasicGroup(identifier);
                        atomDbgGroupDom.style('fill', 'darkmagenta')
                            .style('font-size', this.opts.debug.textSize + 'px')
                            .style('font-family', this.opts.fontFamily)
                            .style('text-anchor', 'middle');
                    }
                    break;
            }
        });
        const hydrophobicGroupDom = this.insertHydrophobicGroupAtCorrectPosition();
        const hydrophobicSelGroupDom = this.insertHydrophobicSelectorGroupAtCorrectPosition();
        const distanceGroupDom = this.insertIntermolecularGroupAtCorrectPosition('distances');
        const interactionGroupDom = this.insertIntermolecularGroupAtCorrectPosition('interactions');
        const cationpiGroupDom = this.insertIntermolecularGroupAtCorrectPosition('cationPiStackings');
        const pipiGroupDom = this.insertIntermolecularGroupAtCorrectPosition('piStackings');
        const atomPairInteractionGroupDom = this.insertIntermolecularGroupAtCorrectPosition(
            'atomPairInteractions');
        const distanceSelGroupDom = this.insertIntermolecularGroupAtCorrectPosition(
            'distancesSelectors');
        const interactionSelGroupDom = this.insertIntermolecularGroupAtCorrectPosition(
            'interactionsSelectors');
        const cationpiSelGroupDom = this.insertIntermolecularSelectorsGroupAtCorrectPosition(
            'cationPiStackingsSelectors');
        const pipiSelGroupDom = this.insertIntermolecularSelectorsGroupAtCorrectPosition(
            'piStackingsSelectors');
        const atomPairInteractionSelGroupDom = this.insertIntermolecularSelectorsGroupAtCorrectPosition(
            'atomPairInteractionsSelectors');
        this.atomGroupsComponent = new AtomGroupsComponent(this.opts,
            this.utils,
            atomGroupDom,
            atomSelGroupDom,
            atomDbgGroupDom,
            this.svgId
        );
        this.edgeGroupsComponent = new EdgeGroupsComponent(this.opts,
            this.utils,
            edgeGroupDom,
            edgeSelGroupDom,
            edgeDbgGroupDom,
            this.defsComponent,
            this.svgId
        );
        this.structureCircleGroupsComponent = new StructureCircleGroupsComponent(this.opts,
            this.utils,
            structureCircleGroupDom,
            structureCircleSelGroupDom,
            this.svgId
        );
        this.annotationGroupsComponent = new AnnotationGroupsComponent(this.opts,
            this.utils,
            annotationGroupDom,
            annotationSelGroupDom
        );
        this.hydrophobicGroupsComponent = new HydrophobicGroupsComponent(this.opts,
            this.utils,
            hydrophobicGroupDom,
            hydrophobicSelGroupDom
        );
        this.intermolecularGroupsComponent = new IntermolecularGroupsComponent(this.opts,
            this.utils,
            distanceGroupDom,
            interactionGroupDom,
            cationpiGroupDom,
            pipiGroupDom,
            atomPairInteractionGroupDom,
            distanceSelGroupDom,
            interactionSelGroupDom,
            cationpiSelGroupDom,
            pipiSelGroupDom,
            atomPairInteractionSelGroupDom
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Appends a SVG group to contain certain elements to the SVG transform
     * group.
     *
     * @param identifier {String} - type of the added SVG group
     */
    appendBasicGroup(identifier) {
        const id = this.svgId + '_' + identifier;
        const groupDom = this.transformGroupDom.append('g').attr('id', id);
        this.addSVGPositionEntry(identifier, id);
        return groupDom;
    }

    /*----------------------------------------------------------------------*/

    /**
     * When first adding hydrophobic contacts, inserts the SVG group to contain
     * all elements representing such interactions into the ring position
     * inside the SVG transform group based on the defined group order in the
     * configuration and apply intended styling.
     */
    insertHydrophobicGroupAtCorrectPosition() {
        const identifier = 'hydrophobicContacts';
        const id = this.svgId + '_hydrophobicContacts';
        const hydrophobicGroupDom = this.insertGroupAtCorrectPosition(identifier);
        hydrophobicGroupDom.attr('id', id)
            .style('fill', 'none')
            .style('stroke-linecap', 'round');
        this.addSVGPositionEntry(identifier, id);
        return hydrophobicGroupDom;
    }

    /*----------------------------------------------------------------------*/

    /**
     * When first adding hydrophobic contacts, inserts the SVG group to contain
     * all elements representing selection shapes used for these contacts
     * inside the SVG transform group based on the defined group order in the
     * configuration.
     */
    insertHydrophobicSelectorGroupAtCorrectPosition() {
        const identifier = 'hydrophobicContactSelectors';
        const id = this.svgId + '_hydrophobicSels';
        const hydrophobicSelGroupDom = this.insertGroupAtCorrectPosition(identifier);
        hydrophobicSelGroupDom.attr('id', id);
        this.addSVGPositionEntry(identifier, id);
        return hydrophobicSelGroupDom;
    }

    /*----------------------------------------------------------------------*/

    /**
     * When first adding intermolecular interactions, inserts the SVG group
     * to contain all elements representing such interactions into the right
     * position inside the SVG transform group based on the defined group order
     * in the configuration and apply intended styling.
     *
     * @param identifier {String} - type of the added SVG group
     */
    insertIntermolecularGroupAtCorrectPosition(identifier) {
        const id = this.svgId + '_' + identifier;
        const intermolecularGroup = this.insertGroupAtCorrectPosition(identifier);
        intermolecularGroup.attr('id', id);
        this.addSVGPositionEntry(identifier, id);
        return intermolecularGroup;
    }

    /*----------------------------------------------------------------------*/

    /**
     * When first adding intermolecular interactions, inserts the SVG group
     * to contain all elements representing the selection elements of such
     * interactions into the right position inside the SVG transform group
     * based on the defined group order in the configuration and apply
     * intended styling.
     *
     * @param identifier {String} - type of the added SVG group
     */
    insertIntermolecularSelectorsGroupAtCorrectPosition(identifier) {
        const id = this.svgId + '_' + identifier;
        const intermolecularSelGroup = this.insertGroupAtCorrectPosition(identifier);
        intermolecularSelGroup.attr('id', id)
            .style('stroke-linecap', 'round')
            .style('stroke-linejoin', 'round');
        this.addSVGPositionEntry(identifier, id);
        return intermolecularSelGroup;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Appends container for interaction elements, e.g. mirror line
     */
    appendTemporaryGroups() {
        const interactionElementsGroupDom = GroupUtils.addGroupToSvg(this.transformGroupDom,
            this.firstElementAfterSceneGroups
        );
        this.interactionElementsGroupComponent = new InteractionElementsGroupComponent(this.opts,
            this.utils,
            interactionElementsGroupDom,
            this.svgId
        );
        this.interactionElementsGroupComponent.appendInteractionElements();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks that an SVG group given by identifier and DOM id has been added
     * inside the SVG transform group in this.svgPositionsToElements.
     *
     * @param identifier {String} - type of the added SVG group
     * @param idString {String} - DOM id of the added SVG group
     */
    addSVGPositionEntry(identifier, idString) {
        const position = this.svgElementPositions[identifier];
        this.svgPositionsToElements[position] = {
            exists: true, id: idString
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the 'cursor' style on the group containing all relevant draw
     * elements of the scene.
     *
     * @param val {String} - the 'cursor' style to use
     */
    setTransformGroupPointer(val) {
        this.transformGroupDom.style('cursor', val);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates container elements to denote the order of draw element groups in
     * the SVG transform group based on the drawer's configuration.
     *
     * @param svgElementOrder {Array} - string identifiers denoting the order
     * of draw elements (earlier ones to appear behind later ones)
     */
    noteElementOrderInformation(svgElementOrder) {
        svgElementOrder.forEach((identifier, i) => {
            this.svgElementPositions[identifier] = i;
            this.svgPositionsToElements[i] = {
                exists: false, id: undefined
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies transformation to the entire scene by applying transform attribute
     * to the transform group.
     *
     * @param scale {Number} - scale to use for transform
     * @param xOffset {Number} - x-parameter for translation part of transform
     * attribute
     * @param yOffset {Number} - y-parameter for translation part of transform
     * attribute
     */
    applyTransform({scale, translate: {x: xOffset, y: yOffset}}) {
        this.transformGroupDom.attr('transform',
            `scale(${this.utils.base.round(scale)}) ` +
            `translate(${this.utils.base.round(xOffset)} ${this.utils.base.round(yOffset)})`
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Dynamically insert a blank SVG group element inside the SVG transform
     * group based on the position of a given identifier in the SVG group order
     * in the configuration.
     *
     * @param identifier {String} - type of the added SVG group
     * @returns {Object} - D3 selector of the added blank SVG group
     */
    insertGroupAtCorrectPosition(identifier) {
        const transformGroupDom = this.transformGroupDom;
        const nextGroupId = this.findSVGGroupToInsertBefore(identifier);
        return transformGroupDom.insert('g', '#' + nextGroupId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the DOM id of the first existing SVG group that is higher in the
     * order of positions defined in the configuration compared to a group to
     * insert given by its identifier. If none is found, returns the id of the
     * SVG element after all element SVG groups.
     *
     * @param identifier {String} - type of the SVG group to add
     * @return {String} - DOM id of the SVG group with higher position
     */
    findSVGGroupToInsertBefore(identifier) {
        let nextGroupId;
        const svgPosInfo = this.svgPositionsToElements;
        const position = this.svgElementPositions[identifier];
        let nextPos = position + 1;
        while (svgPosInfo.hasOwnProperty(nextPos)) {
            const {exists, id} = svgPosInfo[nextPos];
            if (exists) {
                nextGroupId = id;
                break;
            }
            nextPos++;
        }
        if (!nextGroupId) {
            nextGroupId = this.firstElementAfterSceneGroups;
        }
        return nextGroupId;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates display and cursor css property based on html classes
     * ia-drawer-hide-elem and ia-drawer-show-elem. Note that those classes
     * will be removed from the html element.
     */
    updateVisibility() {
        this.transformGroupDom.selectAll(".ia-drawer-hide-elem")
            .classed("ia-drawer-hide-elem", false)
            .style('cursor', "auto")
            .style('display', "none");
        this.transformGroupDom.selectAll(".ia-drawer-show-elem")
            .classed("ia-drawer-show-elem", false)
            .style('cursor', null)
            .style('display', null);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates the height and width (by BBox) of a svg text element.
     *
     * @param text {String} - text of the text element. Can be omitted if only
     * the height is of interest
     * @return {Object} - key "height" and "width" with values taken from
     * getBBox()
     */
    getTextDimensions(text = "Test") {
        const test = this.transformGroupDom.append('text')
            .attr('font-size', this.opts.textSize)
            .style('font-family', this.opts.fontFamily)
            .text(text);
        const {width, height} = test.node().getBBox();
        test.remove();
        return {
            width: width, height: height
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Different layout algorithms produce output in differently scaled
     * coordinate systems. For coordinate systems with very small distances
     * between atoms, text sizes have to be chosen to also be just as small.
     * The SVG drawing layer can of course render this, but getting bounding
     * boxes gets heavily rounded / inaccurate results, leading to incorrect
     * placements. As such, apply a heuristic: scale to a size that is known
     * to yield good drawings, draw, then scale back. This function gives the
     * scale to at least apply to draw well, given by drawing the slimmest
     * possible label ('I' for Iodine). The value for this 'smallest bbox
     * width' was tried out to be sufficient, but may also be scaled back if
     * ever performance gets negatively influenced by this approach.
     */
    suggestDrawScaling() {
        const suggestion = {
            rescale: false, scale: undefined
        };
        const test = this.transformGroupDom.append('text')
            .attr('font-size', this.opts.textSize)
            .style('font-family', this.opts.fontFamily)
            .text('I');
        const width = test.node().getBoundingClientRect().width;
        if (width === 0) {
            test.remove();
            return suggestion;
        } //sanity check
        //heuristic parameter to guess good draw environment (such that atom
        //labels are placed correctly)
        const smallestAllowedWidth = this.opts.smallestBboxWidth;
        if (width < smallestAllowedWidth) {
            suggestion.rescale = true;
            suggestion.scale = smallestAllowedWidth / width;
        }
        test.remove();
        return suggestion;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows parts of a structure or the full structure by changing the
     * corresponding display properties of the svg elements. Also hides the
     * selectors. If you hide this structure completely make sure to mark
     * the structure as hidden.
     *
     * @param structureId {Number} - id of structure to show
     * @param parts {Object} - which parts of the structure to show/hide. Parts can
     * contain "full, atoms, bonds, structureCircle, hydrophobic, atomPairInteractions,
     * piStackings, cationPiStackings, label" as keys and true (show) or false
     * (do not change visibility) as values.
     * @param hiddenStructures {Array} - ids of structures which are currently
     * completely hidden in the draw area. Those are used to identify whether to
     * show/hide interactions to other structures. Can be omitted if parts only
     * containing atoms, bonds, structureCircle, labels and/or hydrophobic.
     * @param show {Boolean} - set true if structure parts shall be shown otherwise false
     */
    showHideStructureParts(structureId, {
        full,
        atoms,
        bonds,
        structureCircle,
        hydrophobic,
        atomPairInteractions,
        piStackings,
        cationPiStackings,
        label
    }, hiddenStructures = [], show) {
        let visibilityClass = 'ia-drawer-hide-elem';
        if (show) {
            hiddenStructures = hiddenStructures.filter(id => {
                return id !== structureId;
            });
            visibilityClass = 'ia-drawer-show-elem';
        }
        this.atomGroupsComponent.setVisibility(full, atoms, structureId, visibilityClass);
        this.edgeGroupsComponent.setVisibility(full, bonds, structureId, visibilityClass);
        this.structureCircleGroupsComponent.setVisibility(full,
            structureCircle,
            structureId,
            visibilityClass
        );
        this.hydrophobicGroupsComponent.setVisibility(full,
            hydrophobic,
            structureId,
            visibilityClass
        );
        this.intermolecularGroupsComponent.setVisibility(full,
            atomPairInteractions,
            structureId,
            visibilityClass,
            hiddenStructures,
            'atomPairInteractions'
        );
        this.intermolecularGroupsComponent.setVisibility(full,
            piStackings,
            structureId,
            visibilityClass,
            hiddenStructures,
            'cationPiStackings'
        );
        this.intermolecularGroupsComponent.setVisibility(full,
            cationPiStackings,
            structureId,
            visibilityClass,
            hiddenStructures,
            'piStackings'
        );
        this.annotationGroupsComponent.setVisibility(full, label, structureId, visibilityClass);
        this.updateVisibility();
    }
}


/* src/Components/Utils/BaseUtils.js */
/**
 * Contains by components commonly used generic functions for the drawing purposes.
 */
class BaseUtils {
    /**
     * Contains an instance for configuration options.
     *
     * @param opts {Object} - configuration parameters
     */
    constructor(opts) {
        this.opts = opts;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rounds given value to user-specified precision (in this.opts.decimalPrecision).
     *
     * @param val {Number} - value to round
     * @returns {Number} - rounded value
     */
    round(val) {
        return Helpers.round(val, this.opts.decimalPrecision);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Trade-off between accuracy and file size. Rounds attribute (coordinates)
     * to precision specified by user (in this.opts.decimalPrecision).
     *
     * @param node {Element} - node to set attribute for
     * @param attr {String} - attribute to set
     * @param val {Number} - value to set attribute to
     */
    setAttributeRounded(node, attr, val) {
        node.setAttribute(attr, this.round(val));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates x- and y-coordinates of an element to a new position.
     *
     * @param node {Element} - the browser element to move
     * @param x {Number} - x-coordinate of the new position
     * @param y {Number} - y-coordinate of the new position
     */
    moveGenericElement(node, x, y) {
        this.setAttributeRounded(node, 'x', x);
        this.setAttributeRounded(node, 'y', y);
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of atom movement, updates internal placement info for a text
     * element.
     *
     * @param info {Object} - internal placement information object
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    static updatePlacementInfo(info, xOffset, yOffset) {
        const newX = info.x + xOffset;
        const newY = info.y + yOffset;
        info.x = newX;
        info.y = newY;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to determine necessary offsets on the ends of dashed
     * basic lines such that only full dashes are used within the line.
     *
     * @param midpoints {Array} - coordinates of line endpoints
     * @returns {Number} - required offsets
     */
    getBaseDashOffsetByMidpoints(midpoints) {
        return this.getDashOffsetByMidpoints(midpoints,
            this.opts.lineDashDrawn,
            this.opts.lineDashGap
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to determine necessary offsets on the ends of dashed
     * point to point constraints such that only full dashes are used within
     * the line.
     *
     * @param midpoints {Array} - coordinates of point to point constraint endpoints
     * @returns {Number} - required offsets
     */
    getPtoPdashOffsetByMidpoints(midpoints) {
        return this.getDashOffsetByMidpoints(midpoints,
            this.opts.geomine.interactionQueryDashDrawn,
            this.opts.geomine.interactionQueryDashGap
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to determine necessary offsets on the ends of dashed
     * lines such that only full dashes are used within the line.
     *
     * @param midpoints {Array} - coordinates of line endpoints
     * @param drawn {Number} - length of a dash segment
     * @param gap {Number} - gap between dash segments
     * @returns {Number} - required offsets
     */
    getDashOffsetByMidpoints(midpoints, length, gap) {
        const dist = VectorCalculation.getDist2d(midpoints[0], midpoints[1]);
        return LineCalculation.calcDashOffset(dist, length, gap);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to convert structure of bbox object to object of minima
     * and maxima.
     *
     * @param x {Number} - x-coordinate of the bbox (upper left corner)
     * @param y {Number} - y-coordinate of the bbox (upper left corner)
     * @param width {Number} - width of the bbox
     * @param height {Number} - height of the bbox
     * @returns {Object} - minima and maxima of the bbox
     */
    static convertBBoxToMaxes({x, y, width, height}) {
        return {
            xMin: x, yMin: y, xMax: x + width, yMax: y + height
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the bbox of a d3 selector. If the selector node is hidden
     * (display:none) this will display the node, calculate the bbox and
     * hide the node afterwards.
     *
     * @param sel {Object} - D3 selector
     * @returns {Object} - BBox of node
     */
    static getSelBBox(sel) {
        let bbox;
        const display = sel.style("display") !== "none";

        if (!display) {
            sel.style("display", null);
        }

        bbox = sel.node().getBBox();

        if (!display) {
            sel.style("display", "none");
        }

        return bbox;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to determine y-coordinate of text element to align its
     * center with a given y-coordinate, given the text elements bbox (which
     * y-coordinate does not align with provided y-coordinate usually)
     *
     * @param bbox {Object} - bbox of the text element
     * @param centerY {Number} - coordinate that the text's center should
     * align with
     * @returns {Number} - y-coordinate of text element which centers the text
     */
    static centerBBoxY(bbox, {y: centerY}) { //atom
        const curYmid = bbox.y + bbox.height / 2;
        const yOffset = centerY - curYmid;
        return centerY + yOffset;
    }
}

/* src/Components/Utils/CircleUtils.js */
/**
 * Contains by components commonly used functions for the drawing of circles.
 */
class CircleUtils {
    /**
     * Contains instances for configuration options and generic drawing functions.
     *
     * @param opts {Object} - configuration parameters
     * @param baseHelpers {BaseUtils} - util instance with by components commonly
     * used generic functions
     */
    constructor(opts, baseHelpers) {
        this.opts = opts;
        this.base = baseHelpers;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Attaches a circle element to the SVG as child of a given parent element
     *
     * @param domParent {Object} - D3 selector for the parent element
     * @param id {number|string} - unique id to be used in the browser
     * @param x {Number} - x-coordinate to place the element at
     * @param y {Number} - y-coordinate to place the element at
     * @param rad {Number} - radius of the circle
     * @param styles {Object} - properties matched to style values
     * @returns {Object} - D3 selector for the circle
     */
    addCircleToSvg(domParent, id, {x, y}, rad, styles = {}) {
        const circleSel = domParent.append('circle');
        const circleNode = circleSel.node();
        this.base.setAttributeRounded(circleNode, 'cx', x);
        this.base.setAttributeRounded(circleNode, 'cy', y);
        this.base.setAttributeRounded(circleNode, 'r', rad);
        if (id) {
            circleSel.attr('id', id);
        }
        for (const style in styles) {
            circleSel.style(style, styles[style]);
        }
        return circleSel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the position of a circle by moving its center to new x- and y-
     * coordinates.
     *
     * @param circleNode {Element} - the browser element to move
     * @param x {Number} - x-coordinate of the new center
     * @param y {Number} - y-coordinate of the new center
     */
    moveCircleElement(circleNode, x, y) {
        this.base.setAttributeRounded(circleNode, 'cx', x);
        this.base.setAttributeRounded(circleNode, 'cy', y);
    }
}

/* src/Components/Utils/GroupUtils.js */
/**
 * By components commonly used functions for the drawing of SVG groups.
 */
class GroupUtils {
    /**
     * Contains an instance for configuration options.
     *
     * @param opts {Object} - configuration parameters
     */
    constructor(opts) {
        this.opts = opts;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all children from a given SVG group element.
     *
     * @param wrapper {Object} - D3 selector for the group to clean
     */
    static clearWrapper(wrapper) {
        const wrapperNode = wrapper.node();
        while (wrapperNode.firstChild) {
            wrapperNode.removeChild(wrapperNode.firstChild);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Attaches a group element to the SVG as a child of a given parent element.
     *
     * @param domParent {Object} - D3 selector for the parent element
     * @param id {String} - unique id to be used in the browser
     * @param styles {Object} - properties matched to style values
     * @returns {Object} - D3 selector for the group
     */
    static addGroupToSvg(domParent, id, styles = {}) {
        const g = domParent.append('g');
        if (id) {
            g.attr('id', id);
        }
        for (const style in styles) {
            g.style(style, styles[style]);
        }
        return g;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks a group as likely to transform, which can bring a performance boost
     * during interaction.
     *
     * @param groupSel {Object} - D3 selector for the group element
     */
    static markGroupAsTransform(groupSel) {
        groupSel.classed('transform', true);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates new SVG groups using fitting ids for newly created SVG elements
     * for movement via composite layers, optimize movement by marking them as
     * ready to transform
     */
    static addGroupsForMovement(group, selGroup, dbgGroup, movementGroupIDs, debug) {
        const movGroupDom = GroupUtils.addGroupToSvg(group, movementGroupIDs.idGroup);
        GroupUtils.markGroupAsTransform(movGroupDom);
        const movSelGroupDom = GroupUtils.addGroupToSvg(selGroup, movementGroupIDs.idSelGroup);
        GroupUtils.markGroupAsTransform(movSelGroupDom);

        let movDbgGroupDom;

        if (debug) {
            movDbgGroupDom = GroupUtils.addGroupToSvg(dbgGroup, movementGroupIDs.idDbgGroup);
            GroupUtils.markGroupAsTransform(movDbgGroupDom);
        }
        return {
            movGroupDom: movGroupDom, movSelGroupDom: movSelGroupDom, movDbgGroupDom: movDbgGroupDom
        };
    }
}

/* src/Components/Utils/LineUtils.js */
/**
 * By components commonly used functions for thr drawing of lines.
 */
class LineUtils {
    /**
     * Contains instances for configuration options and generic drawing functions.
     *
     * @param opts {Object} - configuration parameters
     * @param baseHelpers {BaseUtils} - util instance with by components commonly
     * used generic functions
     */
    constructor(opts, baseHelpers) {
        this.opts = opts;
        this.base = baseHelpers;
        this.dashArrStringPtoP =
            `${this.opts.geomine.interactionQueryDashDrawn} ${this.opts.geomine.interactionQueryDashGap}`;
    }

    /*----------------------------------------------------------------------*/

    dashArrString() {
        return `${this.opts.lineDashDrawn} ${this.opts.lineDashGap}`;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Attaches a line element to the SVG as child of a given parent element.
     *
     * @param domParent {Object} - D3 selector for the parent element
     * @param id {number|string} - unique id to be used in the browser
     * @param fromCoords {Object} - x- and y-coordinates of first line end
     * @param toCoords {Object} - x- and y-coordinates of the second line end
     * @param styles {Object} - properties matched to style values
     * @returns {Object} - D3 selector for the line element
     */
    addLineToSvg(domParent, id, fromCoords, toCoords, styles = {}) {
        const lineSel = domParent.append('line');
        const lineNode = lineSel.node();
        this.base.setAttributeRounded(lineNode, 'x1', fromCoords.x);
        this.base.setAttributeRounded(lineNode, 'y1', fromCoords.y);
        this.base.setAttributeRounded(lineNode, 'x2', toCoords.x);
        this.base.setAttributeRounded(lineNode, 'y2', toCoords.y);
        if (id) {
            lineSel.attr('id', id);
        }
        for (const style in styles) {
            lineSel.style(style, styles[style]);
        }
        return lineSel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * From given draw points, creates the line and path elements represent
     * bonds of all types.
     *
     * @param wrapper {Object} - D3 selector for group element to append drawn
     * lines/paths to
     * @param drawPoints {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @param edgeType {String} - (optional) parameter to specify type of
     * edge. If not specified, bond is treated like single bond
     * @param styles {Object} - mapping of CSS styles to properties
     * @returns {Array} - D3 selectors for the added edges
     */
    addElementsByDrawPoints(wrapper,
        drawPoints,
        {edgeType, styles} = {edgeType: undefined, styles: {}}
    ) {
        const atomPairInteractionTypes = [
            'up',
            'stereoFront',
            'stereoFrontReverse',
            'stereoBack',
            'stereoBackReverse',
            'single',
            'double',
            'triple',
            'down'
        ];
        if (drawPoints.length === 0) {
            return [];
        }
        let sels;
        if (atomPairInteractionTypes.includes(edgeType)) {
            sels = this.addPathFromDrawPoints(wrapper, drawPoints, styles);
        } else { //no type for atomPairInteraction (treated as single)
            sels = this.addLinesForDrawPoints(wrapper, drawPoints, styles);
        }
        return sels;
    }

    /*----------------------------------------------------------------------*/

    /**
     * From given draw points, construct line elements for the individual lines
     * within the SVG.
     *
     * @param wrapper {Object} - D3 selector for group element to append drawn
     * lines/paths to
     * @param drawPoints {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @param styles {Object} - mapping of CSS styles to properties
     * @returns {Array} - D3 selectors for the added edges
     */
    addLinesForDrawPoints(wrapper, drawPoints, styles) {
        const sels = [];
        drawPoints.forEach(drawPoint => {
            sels.push(this.addLineToSvg(wrapper, '', drawPoint[0], drawPoint[1], styles));
        });
        return sels;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Attaches a path element to the SVG as child of a given parent element.
     *
     * @param domParent {Object} - D3 selector for the parent element
     * @param id {number|string} - unique id to be used in the browser
     * @param path {String} - path to put into the elements 'd' attribute
     * @param styles {Object} - properties matched to style values
     * @returns {Object} - D3 selector for the path element
     */
    static addPathToSvg(domParent, id, path, styles = {}) {
        const pathSel = domParent.append('path')
            .attr('d', path);
        if (id) {
            pathSel.attr('id', id);
        }
        for (const style in styles) {
            pathSel.style(style, styles[style]);
        }
        return pathSel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * From given draw points, constructs lines within a single path element
     * within the SVG.
     *
     * @param wrapper {Object} - D3 selector for group element to append drawn
     * lines/paths to
     * @param drawPoints {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @param styles {Object} - mapping of CSS styles to properties
     * @returns {Object} - D3 selector for the constructed path
     */
    addPathFromDrawPoints(wrapper, drawPoints, styles) {
        return LineUtils.addPathToSvg(wrapper, '', this.createPathFromPoints(drawPoints), styles);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Translates an array of line endpoints into a path usable in SVG path
     * elements.
     *
     * @param pointArrs {Array} - array of arrays that defines the
     * endpoints of lines to draw
     * @returns {String} - the path
     */
    createPathFromPoints(pointArrs) {
        let path = '';
        pointArrs.forEach(points => {
            const first = points[0];
            path += ` M ${this.base.round(first.x)} ${this.base.round(first.y)}`;
            for (let i = 1, len = points.length; i < len; ++i) {
                const cur = points[i];
                path += ` L ${this.base.round(cur.x)} ${this.base.round(cur.y)}`;
            }
            path += ` L ${this.base.round(first.x)} ${this.base.round(first.y)}`;
        });
        return path;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates x- and y-coordinates of a line to a new position.
     *
     * @param lineNode {Element} - line node to set attribute for
     * @param drawPoints {Array} - x- and y-coordinates of line start/end points of a new position.
     */
    updateLineByDrawpoints(lineNode, drawPoints) {
        this.base.setAttributeRounded(lineNode, 'x1', drawPoints[0].x);
        this.base.setAttributeRounded(lineNode, 'y1', drawPoints[0].y);
        this.base.setAttributeRounded(lineNode, 'x2', drawPoints[1].x);
        this.base.setAttributeRounded(lineNode, 'y2', drawPoints[1].y);
    }
}

/* src/Components/Utils/SelectorUtils.js */
/**
 * By components commonly used functions for drawing of selector shapes.
 */
class SelectorUtils {
    /**
     * Contains instances for configuration options, generic, line and circle drawing.
     *
     * @param opts {Object} - configuration parameters
     * @param baseHelpers {BaseUtils} - util instance with by components commonly
     * used generic functions
     * @param circleHelpers {CircleUtils} - util instance with by components commonly
     * used functions for circle drawing
     * @param lineHelpers {LineUtils} - util instance with by components commonly
     * used functions for line drawing
     */
    constructor(opts, baseHelpers, circleHelpers, lineHelpers) {
        this.opts = opts;
        this.base = baseHelpers;
        this.circle = circleHelpers;
        this.line = lineHelpers;
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of atom movement, updates atom selector shapes (currently just
     * the one circle selector).
     *
     * @param selectors {Array} - array of D3 selector of atom selector shapes
     * @param selectorShapes {Array} - array of objects which internally
     * describe the shape of selectors
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveAllSelectors(selectors, selectorShapes, xOffset, yOffset) {
        for (let i = 0; i < selectors.length; ++i) {
            this.moveSelectorShape(selectors[i], selectorShapes[i], xOffset, yOffset);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of atom movement, updates a single atom selector shape.
     *
     * @param selector {Object} - D3 selector of atom selector shape
     * @param selectorShape {Object} - internal description of the shape
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveSelectorShape(selector, selectorShape, xOffset, yOffset) {
        const type = selectorShape.type;
        if (type === 'circle') {
            this.moveCircleSelectorByPlacementInfo(selector,
                selectorShape.coordinates,
                xOffset,
                yOffset
            );
        } else if (type === 'line') {
            this.moveLineSelectorByPlacementInfo(selector, selectorShape, xOffset, yOffset);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out the style to set to a new color for different types of
     * selection shapes.
     *
     * @param type {String} - type of selection shape
     * @returns {String} - CSS style property to change to new color
     */
    static inferSelectorStyleToChange(type) {
        if (type === 'circle') {
            return 'fill'
        } else if (type === 'line') {
            return 'stroke';
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Switches the color of a selection shape based on the status it should
     * convey (unselected, hovered, selected).
     *
     * @param selector {Object} - D3 selector for the selection shape
     * @param type {String} - type of selection shape ('circle' or 'line')
     * @param status {SelectorStatus} - the selection status
     */
    switchSelector(selector, type, status) {
        const style = SelectorUtils.inferSelectorStyleToChange(type);
        switch (status) {
            case SelectorStatus.select:
                selector.style(style, this.opts.colors.SELECTION)
                    .style('opacity', this.opts.selectorOpacity);
                break;
            case SelectorStatus.unselect:
                selector.style('opacity', 0);
                break;
            case SelectorStatus.hover:
                selector.style(style, this.opts.colors.HOVER)
                    .style('opacity', this.opts.selectorOpacity);
                break;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Generic function to mark all selector shapes associated with a text
     * label according to a given status.
     *
     * @param sels {Object} - the container object holding selector information
     * for the text label
     * @param status {SelectorStatus} - the selection status to convey
     */
    switchTextLabelSelectorStatus(sels, status) {
        const selectors = sels.mouseSels;
        const selShapes = sels.selectorShapes;
        selectors.forEach((selector, i) => {
            const type = selShapes[i].type;
            this.switchSelector(selector, type, status);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Generic function to switch the color of all selector shapes associated
     * with a text label to a given color.
     *
     * @param sels {Object} - the container object holding selector information
     * for the text label
     * @param color {String} - valid CSS color
     */
    switchTextLabelSelectorColor(sels, color) {
        const selectors = sels.mouseSels;
        const selShapes = sels.selectorShapes;
        selectors.forEach((selector, i) => {
            const type = selShapes[i].type;
            SelectorUtils.changeSelectorColor(selector, type, color);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Switches the color of a selection shape based on a given CSS color.
     *
     * @param selector {Object} - D3 selector for the selection shape
     * @param type {String} - type of selection shape ('circle' or 'line')
     * @param color {String} - valid CSS color
     */
    static changeSelectorColor(selector, type, color) {
        const style = SelectorUtils.inferSelectorStyleToChange(type);
        selector.style(style, color)
            .style('opacity', this.opts.selectorOpacity);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to create circular selection shapes.
     *
     * @param domParent {Object} - D3 selector for group to place selector in
     * @param id {String} - id for the created DOM element (can be '')
     * @param coordinates {Object} - x- and y-coordinates of the circle's
     * center
     * @param rad {Number} - optional custom radius of selector
     * @returns {Object} - description of created element, contains reference
     * to selector and description of the shape of the selector
     */
    drawCircleSelectionShape(domParent, id, coordinates, rad = this.opts.atomSelectorRadius) {
        const sel = this.circle.addCircleToSvg(domParent, id, coordinates, rad, {
            'fill': this.opts.colors.BACKGROUND, 'opacity': 0
        });
        const selectorShape = {
            type: 'circle', coordinates: {
                x: coordinates.x, y: coordinates.y
            }, rad: rad
        };
        return {
            sel: sel, selectorShape: selectorShape
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to create rectangular selection shapes by creation of a
     * line between two points of a certain width.
     *
     * @param domParent {Object} - D3 selector for group to place selector in
     * @param id {String} - id for the created DOM element (can be '')
     * @param midpoints {Array} - the two endpoints of the line
     * @param strokeWidth {Number} - width of the line
     * @returns {Object} - description of created element, contains reference
     * to selector and description of the shape of the selector
     */
    drawLineSelectionShape(domParent, id, midpoints, strokeWidth) {
        const sel = this.line.addLineToSvg(domParent, id, midpoints[0], midpoints[1], {
            'stroke': this.opts.colors.BACKGROUND, 'opacity': 0, 'stroke-width': strokeWidth
        });
        const normals = LineCalculation.findUnitNormals(midpoints[0], midpoints[1]);
        const poly = PolygonCalculation.createRectFromLine(midpoints[0],
            midpoints[1],
            normals,
            strokeWidth / 2
        );
        const selectorShape = {
            type: 'line',
            midpoints: midpoints,
            corners: poly,
            width: VectorCalculation.getDist2d(midpoints[0], midpoints[1]),
            height: strokeWidth //might sound weird but is correct
        };
        return {
            sel: sel, selectorShape: selectorShape
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the different circle and line shapes constituting the full
     * selection shape engulfing a text label.
     *
     * @param label {String} - the text of the text label
     * @param coordinates {Object} - x- and y-coordinates at the center of the
     * text label
     * @param width {Number} - width of the text label's bounding box
     * @param domParent {Object} - D3 selector of SVG group to insert
     * selector elements into
     * @param selId {String} - id of the selector to use as DOM Id base
     * @returns {Object} - arrays of D3 selector objects and selector shapes
     */
    drawTextLabelSelectors(label, coordinates, width, domParent, selId) {
        const mouseSels = [];
        const selectorShapes = [];
        let sel, selectorShape;
        const addSelector = (type, args, i) => {
            const idSuffix = (i !== undefined) ? '_' + i : '';
            const domId = selId + idSuffix;
            if (type === 'circle') {
                const selDesc = this.drawCircleSelectionShape(domParent, domId, args[0]);
                sel = selDesc.sel;
                selectorShape = selDesc.selectorShape;
            } else if (type === 'rect') {
                const selDesc = this.drawLineSelectionShape(domParent,
                    domId,
                    args,
                    this.opts.atomSelectorRadius * 2
                );
                sel = selDesc.sel;
                selectorShape = selDesc.selectorShape;
            }
            mouseSels.push(sel);
            selectorShapes.push(selectorShape);
        };
        //what shapes to use for selection shape around text
        const textSelector = this.opts.textSelector;
        if (textSelector === 'circle') {
            addSelector('circle', [coordinates]);
        } else if (textSelector === 'full') {
            if (!label || label.length <= 1) {
                addSelector('circle', [coordinates]);
            } else {
                //estimate excess space on border boxes of larger text elements
                const offset = width / 2 - this.opts.textBorderCorrection;
                const leftCoords = {
                    x: coordinates.x - offset, y: coordinates.y
                };
                addSelector('circle', [leftCoords], 0);
                const rightCoords = {
                    x: coordinates.x + offset, y: coordinates.y
                };
                addSelector('circle', [rightCoords], 1);
                addSelector('rect', [leftCoords, rightCoords], 2);
            }
        }

        return {
            mouseSels: mouseSels, selectorShapes: selectorShapes
        }
    };

    /*----------------------------------------------------------------------*/

    /**
     * Updates the position of a line selection shape based on given offsets.
     *
     * @param sel {Object} - D3 selector of line selection shape
     * @param selShape {Object} - object representing the selection shape
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveLineSelectorByPlacementInfo(sel, selShape, xOffset, yOffset) {
        const newMidpoints = selShape.midpoints.map(midpoint => {
            return {
                x: midpoint.x + xOffset, y: midpoint.y + yOffset
            };
        });
        selShape.midpoints = newMidpoints;
        selShape.corners = selShape.corners.map(point => {
            return {
                x: point.x + xOffset, y: point.y + yOffset
            };
        });
        this.line.updateLineByDrawpoints(sel.node(), newMidpoints);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the position of a circle selection shape based on given offsets.
     *
     * @param sel {Object} - D3 selector of circle selection shape
     * @param info {Object} - new x- and y-coordinates of selection shape
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveCircleSelectorByPlacementInfo(sel, info, xOffset, yOffset) {
        BaseUtils.updatePlacementInfo(info, xOffset, yOffset);
        this.circle.moveCircleElement(sel.node(), info.x, info.y);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the 'transform' attribute on given D3 selectors.
     *
     * @param selector {Object} - selectors to reset
     */
    static resetTransformOnSelectors(selector) {
        selector.structureSel.node().removeAttribute('transform');
        selector.selectorSel.node().removeAttribute('transform');
        if (selector.debugSel) {
            selector.debugSel.node().removeAttribute('transform');
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies transformations to groups for atoms, edges, and their respective
     * surrounding selector shapes (making up a structural skeleton)
     *
     * @param sels {Object} - object holding D3 selectors for atom, edge and
     * structure circle related draw elements
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     * @param type {String} - structural type identifier
     */
    moveSelectorsOfSkeleton(sels, xOffset, yOffset, type) {
        xOffset = this.base.round(xOffset);
        yOffset = this.base.round(yOffset);
        const transformStr = `translate(${xOffset} ${yOffset})`;
        if (type === "atom" || type === "edge") {
            sels.structureSel.attr('transform', transformStr);
            sels.selectorSel.attr('transform', transformStr);
            if (sels.debugSel) {
                sels.debugSel.attr('transform', transformStr);
            }
        }
        if (sels && type === "structureCircle") {
            sels.structureSel.attr('transform', transformStr);
            sels.selectorSel.attr('transform', transformStr);
        }
    }
}

/* src/Components/Utils/SvgUtils.js */
/**
 * Contains several by components commonly used generic and specialized util instances
 * for drawing purposes.
 */
class SvgUtils {
    /**
     * Contains an instance for configuration options and sets up all types of util instances.
     *
     * @param opts {Object} - configuration parameters
     */
    constructor(opts) {
        this.opts = opts;
        this.base = new BaseUtils(this.opts);
        this.group = new GroupUtils(this.opts);
        this.circle = new CircleUtils(this.opts, this.base);
        this.line = new LineUtils(this.opts, this.base);
        this.selector = new SelectorUtils(this.opts, this.base, this.circle, this.line);
        this.text = new TextUtils(this.opts, this.base);
    }
}

/* src/Components/Utils/TextUtils.js */
/**
 * By components commonly used functions for drawing of text.
 */
class TextUtils {
    /**
     * Contains instances for configuration options and generic drawing.
     *
     * @param opts {Object} - configuration parameters
     * @param baseHelpers {BaseUtils} - util instance with by components commonly
     * used generic functions
     */
    constructor(opts, baseHelpers) {
        this.opts = opts;
        this.base = baseHelpers;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Attaches a text element to the SVG as child of a given parent element.
     *
     * @param domParent {Object} - D3 selector for the parent element
     * @param id {number|string} - unique Id to be used in the browser
     * @param text {String}- the text to be displayed
     * @param x {Number} - x-coordinate to place the element at
     * @param y {Number} - y-coordinate to place the element at
     * @param styles {Object} - properties matched to style values
     * @returns {Object} - D3 selector for the text element
     */
    addTextToSvg(domParent, id, text, {x, y}, styles = {}) {
        //place main text
        const textSel = domParent.append('text')
            .text(text);
        const textNode = textSel.node();
        this.base.setAttributeRounded(textNode, 'x', x);
        this.base.setAttributeRounded(textNode, 'y', y);
        if (id) {
            textSel.attr('id', id);
        }
        for (const style in styles) {
            textSel.style(style, styles[style]);
        }
        return textSel;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to align coordinates with center of text representation
     * (which normally is drawn with coordinates at top left corner).
     *
     * @param sel {Object} - D3 selector of text to center
     * @param coordinates {Object} - x- and y-coordinates to center text in
     * @param forceBotLeft {Boolean} - set to true to force the coordinates
     * to be set to the lower left corner instead of using css features. Used
     * for the atoms labels.
     * @returns {Object} - description of text element and its bounding box
     */
    static centerText(sel, coordinates, forceBotLeft = false) {
        //by svg itself text is placed with lower left corner at coordinates,
        //reposition s.t. middle of text is at coordinates.
        //'text-anchor: middle' aligns the text on mid with x-axis
        //and 'dominant-baseline: middle' with y-axis.
        //Because some browsers (at least firefox) change the BBox of elements
        //with 'transform:scale()' set and that leads to incorrect placement
        //if the coordinates are set to bottom left it is best to use the
        //css features instead. Unfortunately those are not supported by
        //all browsers yet.
        const labelBbox = sel.node().getBBox();
        let labelX, labelY;

        if (forceBotLeft || !CSS.supports("text-anchor", "middle")) {
            labelX = coordinates.x - labelBbox.width / 2;
        } else {
            labelX = coordinates.x;
            sel.style("text-anchor", "middle")
        }

        if (forceBotLeft || !CSS.supports("dominant-baseline", "middle")) {
            labelY = BaseUtils.centerBBoxY(labelBbox, coordinates);
        } else {
            labelY = coordinates.y;
            sel.style("dominant-baseline", "middle")
        }

        sel.attr('x', labelX)
            .attr('y', labelY);

        return {
            sel: sel, width: labelBbox.width, height: labelBbox.height, x: labelX, y: labelY
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to create a d3 text selector with its svg element.
     *
     * @param textG {Object} - D3 selector for group to place text in
     * @param label {String} - text label to create
     * @param coordinates {Object} - x- and y-coordinates to center text in
     * @param color {String} - valid CSS color string for text color
     * @returns {Object} - d3 selector of the text
     */
    placeText(textG, label, coordinates, color) {
        return textG.append('text')
            .attr('x', coordinates.x)
            .attr('y', coordinates.y)
            .style('font-family', this.opts.fontFamily)
            .attr('font-size', this.opts.textSize + 'px')
            .style('fill', color)
            .text(label);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Helper function to align coordinates with center of text representation
     * (which normally is drawn with coordinates at top left corner).
     *
     * @param textG {Object} - D3 selector for group to place text in
     * @param label {String} - text label to create
     * @param coordinates {Object} - x- and y-coordinates to center text in
     * @param color {String} - valid CSS color string for text color     *
     * @param forceBotLeft {Boolean} - set to true to force the coordinates
     * to be set to the lower left corner instead of using css features to
     * center the text. Used for the atoms labels.
     * @returns {Object} - description of text element and its bounding box
     */
    placeCenteredText(textG, label, coordinates, color, forceBotLeft = false) {
        return TextUtils.centerText(this.placeText(textG, label, coordinates, color),
            coordinates,
            forceBotLeft
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * As part of atom movement, update internal placement information of one
     * of the different text elements drawn to represent a certain atom.
     *
     * @param sel {Object} - D3 selector of the text element
     * @param info {Object} - placement info object
     * @param xOffset {Number} - offset to move in x-direction
     * @param yOffset {Number} - offset to move in y-direction
     */
    moveTextByPlacementInfo(sel, info, xOffset, yOffset) {
        BaseUtils.updatePlacementInfo(info, xOffset, yOffset);
        this.base.moveGenericElement(sel.node(), info.x, info.y);
    }
}

/* src/Components/Viewer/AnnotationFormComponent.js */
/**
 * Component that manages SVG group for the drawing of the add annotation form.
 */
class AnnotationFormComponent {
    /**
     * Contains all relevant D3 selectors.
     *
     * @param addAnnotationFormDom {Object} - D3 selector of the add annotation form
     */
    constructor(addAnnotationFormDom) {
        this.addAnnotationFormDom = addAnnotationFormDom;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the color for new annotations.
     *
     * @param color {String} - rpg color for new annotation.
     */
    setInputColor(color) {
        this.addAnnotationFormDom.colorInput.value = Helpers.rgbToHex(color);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the form that allows adding of new annotations.
     */
    hideAnnotationAddForm() {
        const formElements = this.addAnnotationFormDom;
        formElements.shown = false;
        formElements.foreignObject.style('display', 'none');
        formElements.textInput.value = '';
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns user defined info from the annotation form.
     *
     * @return {Object} - info of the add annotation form
     */
    getData() {
        const formData = {};
        const formElements = this.addAnnotationFormDom;
        formData.text = formElements.textInput.value;
        if (formData.text) {
            formData.snap = formElements.snapCbox.checked;
            formData.color = formElements.colorInput.value;
        }
        return formData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Opens the form that allows the adding of new annotations. Set x and y so that the
     * form is completely in visible (in draw area). This will fail if the form is to large
     * to fit at all. In this case the user has to zoom. Note that is is impossible for the form
     * to be out of view area on top or left because the 'cursorCoords' define the top left corner
     * of the form.
     *
     * @param x {Number} - x coordinate of cursor
     * @param y {Number} - y coordinate of cursor
     * @param globalLimits {Object} - fixed values for known boundaries (xMin, xMax, yMin, yMax)
     */
    open(x, y, globalLimits) {
        const formElements = this.addAnnotationFormDom;
        const foreignObj = formElements.foreignObject;
        formElements.shown = true;

        const {xMax, yMax} = globalLimits;
        const foreignWidth = parseFloat(foreignObj.style('width'));
        const foreignHeight = parseFloat(foreignObj.style('height'));

        if (x + foreignWidth > xMax) {
            x = xMax - foreignWidth;
        }
        if (y + foreignHeight > yMax) {
            y = yMax - foreignHeight;
        }

        foreignObj
            .style('display', null)
            .attr('x', x)
            .attr('y', y);
        formElements.textInput.focus();
    }
}

