/* src/Components/Viewer/IntermolecularLineComponent.js */
/**
 * Component that manages the drawing of the intermolecular line used for the adding
 * of new intermolecular edges.
 */
class IntermolecularLineComponent {
    /**
     * Contains all relevant D3 selectors and an instance for drawing utils.
     *
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param addIntermolecularLineDom {Object} - D3 selector of the intermolecular line
     */
    constructor(utils, addIntermolecularLineDom) {
        this.utils = utils;
        this.addIntermolecularLineDom = addIntermolecularLineDom;
        this.addIntermolecularLineShown = false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the line to signal the intermolecular edge to add.
     *
     * @param first {Object} - first new coordinates of the line
     * @param second {Object} - second new coordinates of the line
     * @param color {String} - color of the line as valid css
     * @param dashed {Boolean} - draw a dashed line
     */
    moveAddIntermolecularLine(first, second, color = undefined, dashed = true ) {
        if (!this.addIntermolecularLineShown) {
            this.addIntermolecularLineDom.style('display', null);
            this.addIntermolecularLineShown = true;
        }
        if (dashed) {
            this.addIntermolecularLineDom.style('stroke-dasharray', this.utils.line.dashArrString());
            this.addIntermolecularLineDom.style('stroke-dashoffset',
                this.utils.base.getBaseDashOffsetByMidpoints([first, second])
            );
        } else {
            this.addIntermolecularLineDom.style('stroke-dasharray', '');
            this.addIntermolecularLineDom.style('stroke-dashoffset', '');
        }
        if (color) {
            this.addIntermolecularLineDom.style('stroke', color)
        }
        this.utils.line.updateLineByDrawpoints(this.addIntermolecularLineDom.node(),
            [first, second]
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides element representing the add intermolecular line.
     */
    hideAddIntermolecularLine() {
        this.addIntermolecularLineDom.style('display', 'none');
        this.addIntermolecularLineShown = false;
    }
}

/* src/Components/Viewer/MirrorLineComponent.js */
/**
 * Component that manages the drawing of the mirror line used for structure mirroring.
 */
class MirrorLineComponent {
    /**
     * Contains all relevant D3 selectors and an instance for drawing utils.
     *
     * @param utils {Object} - by components commonly used generic functions for drawing
     * @param mirrorLineDom {Object} - D3 selector of the mirror line
     */
    constructor(utils, mirrorLineDom) {
        this.utils = utils;
        this.mirrorLineDom = mirrorLineDom;
        this.mirrorLineShown = false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the line on which structures are mirrored.
     *
     * @param first {Object} - first new coordinates of mirror line
     * @param second {Object} - second new coordinates of mirror line
     */
    moveMirrorLine(first, second) {
        if (!this.mirrorLineShown) {
            this.mirrorLineDom.style('display', null);
            this.mirrorLineShown = true;
        }
        this.utils.line.updateLineByDrawpoints(this.mirrorLineDom.node(), [first, second]);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides element representing the mirror line.
     */
    hideMirrorLine() {
        this.mirrorLineDom.style('display', 'none');
        this.mirrorLineShown = false;
    }
}


/* src/Components/Viewer/SelectionLineComponent.js */
/**
 * Component that manages the drawing of the selection line used for selection of scene elements.
 */
class SelectionLineComponent {
    /**
     * Contains all relevant D3 selectors.
     *
     * @param selectionLineDom {Object} - D3 selector of the selection line
     */
    constructor(selectionLineDom) {
        this.selectionLineDom = selectionLineDom;
        //INTERACTION - for selection
        this.selectionPath = '';
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the path for the selection helper element into a rectangular
     * selector through given polygon point.
     *
     * @param selectorPoints {Array} - corner points of the rectangle
     */
    drawRectSelector(selectorPoints) {
        const path = Helpers.addFormToPath(selectorPoints, '');
        this.selectionLineDom.attr('d', path);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a point to the current path of the selection helper element.
     *
     * @param x {Number} - x-coordinate of point to add
     * @param y {Number} - y-coordinate of point to add
     */
    addToFreeSelector({x, y}) {
        if (this.selectionPath === '') {
            this.selectionPath += `M${x} ${y}`;
        } else {
            this.selectionPath += ` L${x} ${y}`;
        }
        this.selectionLineDom.attr('d', this.selectionPath);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the selection helper element.
     */
    hideSelector() {
        this.selectionLineDom.attr('d', '');
        this.selectionPath = '';
    }
}

/* src/Components/Viewer/StructureFormComponent.js */
/**
 * Component that manages SVG group for the drawing of the add structure form.
 */
class StructureFormComponent {
    /**
     * Contains all relevant D3 selectors.
     *
     * @param addStructureFormDom {Object} - D3 selector of the add structure form
     */
    constructor(addStructureFormDom) {
        this.addStructureFormDom = addStructureFormDom;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the form that allows adding of new structures.
     */
    hideStructureAddForm() {
        const formElements = this.addStructureFormDom;
        formElements.shown = false;
        formElements.foreignObject.style('display', 'none');
        formElements.select.value = 'WATER';
        formElements.tagInput.value = '';
        formElements.select.disabled = false;
        formElements.input.value = '';
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns user defined info from the structure form.
     *
     * @return {Object} - info of the add structure form
     */
    getData() {
        const formData = {};
        const formElements = this.addStructureFormDom;
        formData.structure = formElements.select.value
        if (formData.structure) {
            formData.tag = formElements.tagInput.value;
        }
        formData.input = formElements.input.value;
        return formData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Opens the form that allows the adding of new structures. Set x and y so that the
     * form is completely in visible (in draw area). This will fail if the form is to large
     * to fit at all. In this case the user has to zoom. Note that is is impossible for the form
     * to be out of view area on top or left because the 'cursorCoords' define the top left corner
     * of the form.
     *
     * @param x {Number} - x coordinate of cursor
     * @param y {Number} - y coordinate of cursor
     * @param globalLimits {Object} - fixed values for known boundaries (xMin, xMax, yMin, yMax)
     */
    open(x, y, globalLimits) {
        const formElements = this.addStructureFormDom;
        const foreignObj = formElements.foreignObject;
        formElements.shown = true;

        const {xMax, yMax} = globalLimits;
        const foreignWidth = parseFloat(foreignObj.style('width'));
        const foreignHeight = parseFloat(foreignObj.style('height'));

        if (x + foreignWidth > xMax) {
            x = xMax - foreignWidth;
        }
        if (y + foreignHeight > yMax) {
            y = yMax - foreignHeight;
        }

        foreignObj
            .style('display', null)
            .attr('x', x)
            .attr('y', y);
        formElements.select.focus();
    }
}

