/**
 * Class representing a simple line in the form f(x) = m*x+b.
 */
class Line {
    /**
     * Creates a new Line object.
     *
     * @param m - slope of the line
     * @param b - y-intercept of the line
     */
    constructor(m, b) {
        this.m = m;
        this.b = b;
        this.function = (x) => {
            return m * x + b;
        }
    }
}

/* src/Data/Objects/Ring.js */
/**
 * Class containing information on rings of larger structures (structure
 * objects), holding its atoms and bonds.
 */
class Ring {
    /**
     * Creates a new Ring object.
     *
     * @param id {Number} - internal id of ring inside structure
     * @param aromatic {Boolean} - whether the ring is aromatic or not
     * @param spaceToRing {Number} - space between first bond of a bond and
     * the inner bond of a double bond for this ring
     */
    constructor(id, aromatic, spaceToRing) {
        this.id = id;
        this.aromatic = aromatic;
        this.spaceToRing = spaceToRing;
        this.length = 0;

        this.edges = [];
        this.edgeIdToPos = {};
        this.atoms = []; //listed in order they appear in
        this.atomIdToPos = {};

        //updated parameters
        this.edgeNormals = {};
        this.edgePositions = {};

        //for correct assignment of double bonds to rings (load one up)
        this.doublePotential = 0;

        //used temporary variables on ring construction, moved to edge / atom
        //parameters on call of finalize()
        this._firstAddedEdge = null;
        this._atomIdsToEdges = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds an edge (Edge object) to this ring.
     *
     * @param edge {Object} - Edge object to add
     */
    addEdge(edge) {
        if (!this._firstAddedEdge) {
            this._firstAddedEdge = edge;
        }
        const {from, to} = edge;
        if (!this._atomIdsToEdges.hasOwnProperty(from)) {
            this._atomIdsToEdges[from] = [];
        }
        this._atomIdsToEdges[from].push(edge);
        if (!this._atomIdsToEdges.hasOwnProperty(to)) {
            this._atomIdsToEdges[to] = [];
        }
        this._atomIdsToEdges[to].push(edge);
    }

    /*----------------------------------------------------------------------*/

    /**
     * From all added edges, infer the edge and atom order of the ring.
     */
    finalize(ringsData) {
        let count = 0;
        const atoms = this.atoms;
        const edges = this.edges;
        const atomIdToPos = this.atomIdToPos;
        const edgeIdToPos = this.edgeIdToPos;
        const addEdge = (edge) => {
            edges.push(edge);
            edgeIdToPos[edge.id] = count;
        };
        const addAtom = (atom) => {
            atoms.push(atom);
            atomIdToPos[atom.id] = count;
        };
        const addPair = (atom, edge) => {
            addEdge(edge);
            addAtom(atom);
            count++;
        };
        const firstAdded = this._firstAddedEdge;
        const firstId = firstAdded.from;
        addPair(ringsData.atomsData.getAtom(firstId), firstAdded);
        let curEdgeId = firstAdded.id;
        let nextId = firstAdded.to;
        //iterate edges in order (while finding such order)
        while (nextId !== firstId) {
            const possibleEdges = this._atomIdsToEdges[nextId];
            let nextEdge = possibleEdges[0];
            if (nextEdge.id === curEdgeId) {
                nextEdge = possibleEdges[1];
            }
            addPair(ringsData.atomsData.getAtom(nextId), nextEdge);
            curEdgeId = nextEdge.id;
            nextId = nextEdge.from === nextId ? nextEdge.to : nextEdge.from;
        }
        this.ringSystem = ringsData.getRingSystemMembership(atoms);
        this.length = edges.length;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates this ring based on new coordinates of its atoms.
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates of contained atoms for the update
     */
    update(byTemp = false) {
        this.findCentroid(byTemp);
        this.findEdgeNormals(byTemp);
        this.setAllAromaticPositions(byTemp);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on the order of edges within this ring, gets the edge appearing
     * next after a given edge (by its id) in this order.
     *
     * @param edgeId {Number} - id of edge for which to find the next edge
     * @returns {Edge} - the next edge
     */
    getNextEdge(edgeId) {
        const edgePos = this.edgeIdToPos[edgeId];
        const nextPos = (edgePos === this.edges.length - 1) ? 0 : edgePos + 1;
        return this.edges[nextPos];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on the order of edges within this ring, gets the edge appearing
     * before a given edge (by its id) in this order.
     *
     * @param edgeId {Number} - id of edge for which to find the previous edge
     * @returns {Edge} - the previous edge
     */
    getPreviousEdge(edgeId) {
        const edgePos = this.edgeIdToPos[edgeId];
        const prevPos = (edgePos === 0) ? this.edges.length - 1 : edgePos - 1;
        return this.edges[prevPos];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks this ring as aromatic or non-aromatic.
     *
     * @param aromatic {Boolean} - whether this ring is to be marked as
     * aromatic or not
     */
    setAromatic(aromatic) {
        this.aromatic = aromatic;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the centroid of this ring and store its information to
     * this.centroidInfo
     *
     * @param byTemp {Boolean} - whether to calculate this centroid from
     * temporary or non-temporary coordinates of atoms contained within this
     * ring
     */
    findCentroid(byTemp) {
        const poly = byTemp ? this.atoms.map(atom => {
            return atom.tempCoordinates;
        }) : this.atoms.map(atom => {
            return atom.coordinates;
        });

        this.centroidInfo = PolygonCalculation.findCenterOfConvexPolygon(poly);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For all edges of this ring, finds the edge normals that point inside the
     * ring.
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates of atoms contained in edges for this calculation
     */
    findEdgeNormals(byTemp) {
        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
        this.edges.forEach(edge => {
            //relevant info for from atom
            const fromId = edge.from;
            const fromAtom = this.atoms[this.atomIdToPos[fromId]];
            const fromCoords = fromAtom[coordParam];
            //relevant info for to atom
            const toId = edge.to;
            const toAtom = this.atoms[this.atomIdToPos[toId]];
            const toCoords = toAtom[coordParam];

            //find normals and project first normal (as guess to point inside)
            const mid = PointCalculation.findEdgeMidpoint(fromCoords, toCoords);
            const normals = LineCalculation.findUnitNormals(fromCoords, toCoords);
            let normal = normals[0];
            const projMid = {
                x: mid.x + normal.x, y: mid.y + normal.y
            };

            //choose projected normal point that is inside of the circle
            const coords = this.atoms.map(atom => {
                return atom[coordParam];
            });
            if (!PolygonCalculation.checkCollisionPolygonPoint(projMid, coords)) {
                normal = normals[1];
            }

            Helpers.makeOrderedObjEntry(this.edgeNormals, fromId, toId, normal);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the endpoints for all inner edges of edges of an aromatic ring.
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates of atoms of this ring for this calculation
     */
    setAllAromaticPositions(byTemp) {
        for (let i = 0, len = this.atoms.length; i < len; ++i) {
            const atomId = this.atoms[i].id;
            this.findInnerPosition(i, byTemp);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the points of the inner edge for a specific edge by traversing the
     * rings atoms in order.
     *
     * @param atomIdx {Number} - current atom id to define current edge to
     * calculate positions for
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates of atoms of this ring for this calculation
     */
    findInnerPosition(atomIdx, byTemp) {
        const curAtom = this.atoms[atomIdx];
        const curId = curAtom.id;
        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';

        const nextIdx = (atomIdx === this.atoms.length - 1) ? 0 : atomIdx + 1;
        const nextAtom = this.atoms[nextIdx];
        const nextId = nextAtom.id;
        const edgeNormal = this.getEdgeNormal(curId, nextId);

        const cur = curAtom[coordParam];
        const next = nextAtom[coordParam];
        const innerLineInfo = LineCalculation.createInnerLine(cur,
            next,
            edgeNormal,
            this.spaceToRing,
            60
        );
        Helpers.makeOrderedObjEntry(this.edgePositions, curId, nextId, innerLineInfo.points);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the edge normal for an edge defined by its contained atoms (by
     * their ids) which points inside the ring.
     *
     * @param atomId_1 {Number} - first atom id
     * @param atomId_2 {Number} - second atom id
     * @returns {Object} - edge normal which points inside the ring
     */
    getEdgeNormal(atomId_1, atomId_2) {
        return Helpers.getOrderedObjEntry(this.edgeNormals, atomId_1, atomId_2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the positions by which to place the inner edge of an aromatic
     * edge inside this ring by an edge defined by its atoms (by atom ids).
     *
     * @param atomId_1 {Number} - first atom id
     * @param atomId_2 {Number} - second atom id
     * @returns {Array} - the two endpoints of the inner edge
     */
    getEdgePositions(atomId_1, atomId_2) {
        return Helpers.getOrderedObjEntry(this.edgePositions, atomId_1, atomId_2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the endpoints for the inner edge of a given edge
     * (by Edge object).
     *
     * @param edge {Edge} - the edge to find the inner edge points for
     * @returns {Object} - the positions of the inner edge, defined as 'from'
     * and 'to' in the same way as in the original edge to preserve direction
     */
    findInnerPositionsForEdge(edge) {
        const from = edge.from;
        const to = edge.to;
        const [fromInnerPos, toInnerPos] = this.getEdgePositions(from, to);
        return {
            from: fromInnerPos, to: toInnerPos
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Deep clone this Ring object.
     *
     * @returns {Ring} - the new Ring object
     */
    clone() {
        const clone = new Ring(this.id, this.aromatic, this.spaceToRing);
        //does forgo cloning creation parameters as they are never needed after
        clone.atomIdToPos = Object.assign({}, this.atomIdToPos);
        clone.atoms = [];
        this.atoms.forEach(atom => {
            clone.atoms.push(atom.clone());
        });
        const centroidInfo = this.centroidInfo;
        clone.centroidInfo = {
            centroid: Object.assign({}, centroidInfo.centroid), signedArea: centroidInfo.signedArea
        };
        clone.edgeIdToPos = Object.assign({}, this.edgeIdToPos);
        clone.edgeNormals = {};
        for (const edgeNormalId_1 in this.edgeNormals) {
            const edgeNormalsOfId_1 = this.edgeNormals[edgeNormalId_1];
            const edgeNormalObj = {};
            for (const edgeNormalId_2 in edgeNormalsOfId_1) {
                edgeNormalObj[edgeNormalId_2] =
                    Object.assign({}, edgeNormalsOfId_1[edgeNormalId_2]);
            }
            clone.edgeNormals[edgeNormalId_1] = edgeNormalObj;
        }
        clone.edges = [];
        this.edges.forEach(edge => {
            clone.edges.push(edge.clone());
        });
        clone.nrDoubles = this.nrDoubles;
        clone.length = this.length;
        return clone;
    }
}


/* src/Data/Objects/Spline.js */
/**
 * Class to manage the representation of splines (for hydrophobic contacts).
 */
class Spline {
    /**
     * Creates new Spline object.
     *
     * @param structureLink {Number} - the structure the spline belongs to
     * @param controlPoints {Array} - control points defining the spline
     * (optional, can be set later from data, need to have radius as rad)
     */
    constructor(structureLink, controlPoints = null) {
        this.structureLink = structureLink;
        this.hidden = false;
        this.enabled = true;
        if (controlPoints) {
            this.controlPoints = JSON.parse(JSON.stringify(controlPoints));
            this.tempControlPoints = JSON.parse(JSON.stringify(controlPoints));
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds control points from data as expected in JSON input format.
     *
     * @param dataPoints {Array} - array of objects containing x- and
     * y-coordinates of control points + atomLinks to remember for data
     * retrieval
     * @param rad {Number} - radius of control points
     * @param addId {Number} - where to insert the given control points in the
     * control points array. Add to end if undefined
     */
    addControlPointsFromData(dataPoints, rad, addId = undefined) {
        let startPoints = [];
        let midPoints = [];
        let endPoints = [];
        if (this.hasOwnProperty("controlPoints")) {
            if (addId === undefined || addId >= this.controlPoints.length) {
                addId = this.controlPoints.length;
            }
            startPoints = this.controlPoints.slice(0, addId);
            endPoints = this.controlPoints.slice(addId)
        }
        midPoints = dataPoints.map(({x, y, atomLinks}) => {
            return {
                x: x, y: y, atomLinks: atomLinks ? atomLinks.slice() : [], rad: rad, enabled: true
            };
        });
        const controlPoints = [...startPoints, ...midPoints, ...endPoints];
        this.controlPoints = JSON.parse(JSON.stringify(controlPoints));
        this.tempControlPoints = JSON.parse(JSON.stringify(controlPoints));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the path representing the spline for use in SVG elements.
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates for control points
     * @returns {String} - the path representing the spline
     */
    createSplinePath(byTemp = false) {
        const ctrlArr = this.makeCtrlPointArr(byTemp);
        const curvePoints = SplineInterpolation.getCurvePoints(ctrlArr);
        const coords = SplineInterpolation.curvePointsToCoords(curvePoints);
        this.tempCurveCoords = coords;
        if (!byTemp) {
            this.curveCoords = Object.assign([], coords);
        }
        return SplineInterpolation.createSplinePath(curvePoints);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates input for spline interpolation from control points.
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates for control points
     * @returns {Array} - array of alternating x- and y-coordinates of control
     * points
     */
    makeCtrlPointArr(byTemp = false) {
        const arr = [];
        const controlPoints = this.getControlPoints(byTemp)
            .filter((cp => cp.enabled));
        controlPoints.forEach(({x, y}) => {
            arr.push(x);
            arr.push(y);
        });
        return arr;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds offset to a specified (by index) control point.
     *
     * @param idx {Number} - index of control point in internal control point
     * Array
     * @param offset {Object} - x- and y-offset to move control point by
     * @param byTemp {Boolean} - whether to update temporary or non-temporary
     * coordinates of the control point
     */
    updateControlPoint(idx, offset, byTemp = false) {
        const controlPoints = this.getControlPoints(byTemp);
        const oldPointInfo = controlPoints[idx];
        const newPoint = {
            x: oldPointInfo.x + offset.x,
            y: oldPointInfo.y + offset.y,
            rad: oldPointInfo.rad,
            enabled: oldPointInfo.enabled
        };
        controlPoints[idx] = newPoint;
        if (!byTemp) {
            this.getControlPoints(true)[idx] = Object.assign({}, newPoint);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates control points specified by id of the spline around a given
     * center point.
     *
     * @param controlPointIds {Array} - ids of control points to rotate
     * @param angle {Number} - angle of rotation
     * @param isDeg {Boolean} - whether given angle is in degrees or radians
     * @param center {Object} - point to rotate around
     * @param byTemp {Boolean} - whether to update temporary or non-temporary
     * coordinates of the control points
     */
    rotateControlPoints(controlPointIds, angle, isDeg, center, byTemp = false) {
        const radian = isDeg ? AngleCalculation.degreeToRadian(angle) : angle;
        const sin = Math.sin(radian);
        const cos = Math.cos(radian);
        controlPointIds.forEach(cpId => {
            const controlPoint = this.getControlPoint(cpId, byTemp);
            const rotaPoint = PointCalculation.rotatePointAroundAnotherSinCosKnown(controlPoint,
                center,
                sin,
                cos
            );
            this.setControlPoint(cpId, rotaPoint, byTemp);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets a control point (by index) to a certain value.
     *
     * @param idx {Number} - index of control point in internal control point
     * Array
     * @param newPoint {Object} - new control point (coordinates and radius)
     * @param byTemp {Boolean} - whether to set only temporary or also non-
     * temporary coordinates of this control point
     */
    setControlPoint(idx, newPoint, byTemp = false) {
        const cps = [];
        cps.push(this.getControlPoints(byTemp)[idx]);
        if (!byTemp) {
            cps.push(this.getControlPoints(true)[idx]);
        }
        cps.forEach(cp => {
            cp.x = newPoint.x || cp.x;
            cp.y = newPoint.y || cp.y;
            cp.rad = newPoint.rad || cp.rad;
        })
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the internal array of control points.
     *
     * @param byTemp {Boolean} - whether to return temporary or non-temporary
     * coordinates of the control points
     * @returns {Array} - control points of this spline
     */
    getControlPoints(byTemp = false) {
        return byTemp ? this.tempControlPoints : this.controlPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns a single control point based on a given index position.
     *
     * @param idx {Number} - index position of the control point
     * @param byTemp {Boolean} - whether to return the point's temporary or
     * non-temporary coordinates
     * @returns {Object} - the control point
     */
    getControlPoint(idx, byTemp = false) {
        return this.getControlPoints(byTemp)[idx];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the index positions of control points of this spline.
     *
     * @returns {Set} - the ids of control points
     */
    getControlPointIds() {
        return new Set(Object.keys(this.controlPoints));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns all coordinates on the curve of the spline.
     *
     * @param byTemp {Boolean} - whether to return temporary or non-temporary
     * coordinates
     * @returns {Array} - curve coordinates of this spline
     */
    getCurveCoords(byTemp = false) {
        return byTemp ? this.tempCurveCoords : this.curveCoords;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns whether the given control point defines the start or end
     * of the currently enabled control points of this spline.
     *
     * @param controlPointId {Number} - id of the control point
     * @returns {Number} - 0: neither, 1: at start, 2: at end, 3: both
     */
    determineCPEnd(controlPointId) {
        let first = undefined;
        let last = undefined;
        this.controlPoints.forEach((cp, idx) => {
            if (cp.enabled) {
                if (first === undefined) {
                    first = idx;
                }
                last = idx;
            }
        });

        let ret = 0;
        if (first === controlPointId) {
            ret += 1;
        }
        if (last === controlPointId) {
            ret += 2;
        }
        return ret;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Create a deep copy of this Spline object.
     *
     * @returns {Spline} - cloned Spline object
     */

    clone() {
        return new Spline(this.structureLink, this.controlPoints);
    }
}


/* src/Data/Objects/Structure.js */
/**
 * Class containing information on an entire structure, holding its
 * atoms, bonds and information on which intermolecular forces affect which
 * parts of the structure.
 */
class Structure {
    /**
     * Creates a new Structure object.
     *
     * @param id {Number} - internal id of structure
     * @param structureName {String} - optional name of structure
     * @param structureType {String} - optional type of structure
     * @param structureLabel {String} - label of the structure. This might
     * differ (e.g. be shorter) than the name and is displayed in the structure
     * circle representation.
     * @param spaceToRings {Number} - space between first bond of a bond and
     * the inner bond of a double bond for all rings of this structure
     * @param additionalInformation {Object} - custom additional information
     * that is saved but does not belong to the drawer itself
     */
    constructor(id,
        structureName,
        structureType,
        structureLabel,
        spaceToRings,
        additionalInformation
    ) {
        this.id = id; //may be assigned by drawer if not given directly
        this.hidden = false;
        this.enabled = true;
        this.structureName = structureName;
        this.structureType = structureType || 'default';
        this.structureLabel = structureLabel;
        this.additionalInformation = additionalInformation;
        this.spaceToRings = spaceToRings;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Extends the Structure object by actual draw information. Missing
     * information has to be calculated.
     *
     * @param atomInfos {Array} - objects defining atoms of the structure
     * @param edgeInfos {Array} - objects defining bonds of the structure
     * @param ringInfos {Array} - objects defining rings of the structure
     * @param stereoCenterInfos {Array} - objects defining which atoms of
     * the structure are stereo centers (optional, otherwise inferred from
     * bond types)
     * @param ringSystemInfos {Array} - objects defining the ring system of
     * the structure (optional, otherwise found by DFS)
     */
    addStructureInfo(atomInfos, edgeInfos, {
        ringInfos, stereoCenterInfos, ringSystemInfos
    }) {
        //global properties of structure
        this.curOffset = {x: 0, y: 0}; //given in px
        this.boundaries = undefined;
        //large elements containing multiple atoms / edges
        this.atomsData = new AtomsData();
        this.atomsData.addAtomInfo(atomInfos, stereoCenterInfos);
        this.edgesData = new EdgesData(this.atomsData);
        this.edgesData.addEdgeInfo(edgeInfos);
        this.edgesData.postProcessEdges();
        this.edgesData.postProcessAtomsByEdges(stereoCenterInfos);
        this.atomsData.postProcessAtoms();
        this.ringsData = new RingsData(this.atomsData, this.edgesData, this.spaceToRings);
        this.ringsData.addRingInfo(ringInfos, ringSystemInfos);
        this.representationsData = new RepresentationsData(this.structureType);
        //related objects, noted for movement
        this.annotationConnectionData = new AnnotationConnectionData();
        this.hydrophobicConnectionData = new HydrophobicConnectionData();
        this.intermolecularConnectionData =
            new IntermolecularConnectionData(this.ringsData);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Splits structure into two parts on acyclic bond by DFS.
     *
     * @param edgeId {Number} - id of edge to split structure on
     * @returns {Array|undefined} - atom ids of the two parts of the structure,
     * or undefined for bad input (including cyclic edges)
     */
    splitStructureOnBond(edgeId) {
        const edge = this.edgesData.getEdge(edgeId);
        if (edge.cyclic) {
            return;
        }
        const {from, to} = edge;
        const firstSubset = [];
        const secondSubset = [];
        const fillFirst = (atom) => {
            firstSubset.push(atom.id);
        };
        const fillSecond = (atom) => {
            secondSubset.push(atom.id);
        };
        const structureVisitor = new StructureVisitor(this.atomsData, this.edgesData);
        structureVisitor.dfs({
            atomCallback: fillFirst, startIds: [from], excludedAtoms: new Set([to])
        });
        structureVisitor.dfs({
            atomCallback: fillSecond, startIds: [to], excludedAtoms: new Set([from])
        });

        return [firstSubset, secondSubset];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets ids of atoms to move based on a given atom (by id) which is
     * currently affected by some form of interaction. This decision is based
     * on the defined move freedom level.
     *
     * @param atomId {Number} - id of atom affected by interaction
     * @param moveFreedomLevel {String} - freedom level defining the size of
     * units of the structure which can be moved at one. Either 'free',
     * 'rings', or 'structures'
     * @returns {Array} - ids of atoms to move
     */
    getMoveUnitForAtom(atomId, moveFreedomLevel) {
        switch (moveFreedomLevel) {
            case 'free':
                return [atomId];
            case 'rings':
                const ringSystem = this.atomsData.getAtom(atomId).ringSystem;
                if (!ringSystem) return [atomId];
                return this.ringsData.ringSystems[ringSystem].atoms;
            case 'structures':
                return this.atomsData.atomIds.slice();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Get ids of atoms to move based on a given edge (by id) which is
     * currently affected by some form of interaction. This decision is based
     * on the defined move freedom level.
     *
     * @param edgeId {Number} - id of edge affected by interaction
     * @param moveFreedomLevel {String} - freedom level defining the size of
     * units of the structure which can be moved at one. Either 'free',
     * 'rings', or 'structures'
     * @returns {Array} - ids of atoms to move
     */
    getMoveUnitForEdge(edgeId, moveFreedomLevel) {
        const edge = this.edgesData.getEdge(edgeId);
        const moveUnit = new Set(this.getMoveUnitForAtom(edge.from, moveFreedomLevel)
            .concat(this.getMoveUnitForAtom(edge.to, moveFreedomLevel)));
        return Array.from(moveUnit);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds all non-molecular elements which are in some connected to this
     * structure (either as bonds or elements that belong to the structure).
     *
     * @returns {Object} - the connected elements by type
     */
    getConnectedElements() {
        return {
            annotations: this.annotationConnectionData.annotations,
            distances: this.intermolecularConnectionData.ids.distances,
            interactions: this.intermolecularConnectionData.ids.interactions,
            atomPairInteractions: this.intermolecularConnectionData.ids.atomPairInteractions,
            piStackings: this.intermolecularConnectionData.ids.piStackings,
            cationPiStackings: this.intermolecularConnectionData.ids.cationPiStackings,
            splineControlPoints: this.hydrophobicConnectionData.getSplineControlPointIds()
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds all non-molecular (bond) elements which are connected to given
     * atoms of this structure.
     *
     * @param atomArr {Array} - atoms ids to look up connections for
     * @param moveFreedomLevel {String} - freedom level defining the size of
     * units of the structure which can be moved at one. Either 'free',
     * 'rings', or 'structures'
     * @returns {Object} - the connected elements by type
     */
    getConnectedElementsForAtoms(atomArr, moveFreedomLevel) {
        if (atomArr.length === this.atomsData.atoms.length) {
            return this.getConnectedElements();
        }
        const atomPairInteractions = this.intermolecularConnectionData.getAtomPairInteractionsAffectedByAtoms(
            atomArr, moveFreedomLevel);
        const affectedRingSystems = this.ringsData.getRingSystemsAffectedByAtoms(atomArr);
        const piStackings = this.intermolecularConnectionData.getPiStackingsAffectedByAtoms(atomArr,
            affectedRingSystems
        );
        const cationPiStackings = this.intermolecularConnectionData.getCationPiStackingsAffectedByAtoms(atomArr,
            affectedRingSystems
        );
        const annotations = this.annotationConnectionData.getAnnotationsForAtoms(atomArr);
        const splineControlPoints = this.hydrophobicConnectionData.getSplineControlPointIdsForAtoms(
            atomArr);
        return {
            atomPairInteractions: atomPairInteractions,
            piStackings: piStackings,
            cationPiStackings: cationPiStackings,
            annotations: annotations,
            splineControlPoints: splineControlPoints
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns true if at least one atom, bond or structure circle is selected,
     * either by normal selection, temp selection or both.
     *
     * @param type {Number} - whether to just check normal selection (0),
     * temp selection (1) or both (2)
     */
    isSelected(type = 2) {
        return ((type === 1 || type === 2) && (this.atomsData.tempSelectedAtoms.size !== 0 ||
            this.edgesData.tempSelectedEdges.size !== 0 ||
            this.representationsData.tempSelectedStructureCircle)) || ((type === 0 || type === 2) &&
            (this.atomsData.selectedAtoms.size !== 0 || this.edgesData.selectedEdges.size !== 0 ||
                this.representationsData.selectedStructureCircle))
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked offsets applied to this structure.
     */
    resetCurOffset() {
        this.curOffset = {
            x: 0, y: 0
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates given boundaries for given draw limits.
     *
     * @param drawLimits {Object} - bounding box limits of a certain object.
     * Must contain 'xMin', 'xMax', 'yMin', and 'yMax'
     * @param boundaries {Object} - current boundaries which should be updated
     * with parameters from drawLimits. Must contain 'xMin', 'xMax',
     * 'yMin', and 'yMax'
     * @returns {Boolean} - whether the boundaries have changed
     */
    static calcBoundariesStep(drawLimits, boundaries) {
        const {xMin, xMax, yMin, yMax} = drawLimits;
        let changed = false;
        if (xMin < boundaries.xMin) {
            boundaries.xMin = xMin;
            changed = true;
        }
        if (xMax > boundaries.xMax) {
            boundaries.xMax = xMax;
            changed = true;
        }
        if (yMin < boundaries.yMin) {
            boundaries.yMin = yMin;
            changed = true;
        }
        if (yMax > boundaries.yMax) {
            boundaries.yMax = yMax;
            changed = true;
        }
        return changed;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given certain bounding box limits of the structure, finds remaining such
     * limits for this structure.
     *
     * @param forcedLimits {Object} - bounding box limits of the structure
     * which are already known for sure. Can specify 'xMin', 'xMax',
     * 'yMin', and 'yMax'
     */
    calcBoundaries(forcedLimits = undefined) {
        const newBoundaries = {
            xMin: Infinity, xMax: -Infinity, yMin: Infinity, yMax: -Infinity
        };

        if (this.enabled) {
            this.atomsData.atoms.forEach(atom => {
                if (!atom.enabled) {
                    return
                }
                Structure.calcBoundariesStep(atom.globalDrawLimits, newBoundaries);
            });
        }

        this.setLimits({...newBoundaries, ...forcedLimits});
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets bounding box boundaries for this structure.
     *
     * @param boundingBox {Object} - bounding box limits of the structure.
     * Contains specify 'xMin', 'xMax', 'yMin', and 'yMax'
     */
    setLimits(boundingBox) {
        const {xMin, xMax, yMin, yMax} = boundingBox;
        const mid = PointCalculation.findGeometricCenter(this.atomsData.atoms.map(atom => {
            return atom.coordinates;
        }));
        const maxDist = Math.max(...this.atomsData.atoms.map(atom => {
            return VectorCalculation.getDist2d(atom.coordinates, mid)
        }));
        this.boundaries = {
            xMin: xMin,
            xMax: xMax,
            yMin: yMin,
            yMax: yMax,
            mid: mid,
            maxDist: maxDist,
            width: xMax - xMin,
            height: yMax - yMin
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns bounding box limits of this structure.
     *
     * @returns {Object} - bounding box limits, containing fields 'xMin',
     * 'xMax', 'yMin', and 'yMax'
     */
    getLimits() {
        return this.boundaries;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For the structure circle of the structure, calculates the necessary
     * offset to move it such that it rotates some angle around a rotation point.
     *
     * @param angle {Number} - angle to rotate
     * @param isDeg {Boolean} - is angle given in degree (false -> angle is
     * radian)
     * @param rotationPoint {Object} - point to rotate around - if none is
     * given, rotate around own midpoint
     * @param byTemp {Boolean} - if temporary coordinates should be used for
     * calculation
     * @returns {Object} - x and y values of offset
     */
    calcStructureCircleRotationOffset(angle, isDeg, rotationPoint, byTemp = true) {
        const mid = rotationPoint ? rotationPoint : this.boundaries.mid;
        const circleMid = byTemp ? this.representationsData.structureCircle.tempCoordinates :
            this.representationsData.structureCircle.coordinates;

        const rotatedCoords = PointCalculation.rotatePointAroundAnother(circleMid,
            mid,
            angle,
            !isDeg
        );
        return {
            x: rotatedCoords.x - circleMid.x, y: rotatedCoords.y - circleMid.y
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the boundaries of the structure circle to the structure boundaries.
     * This is needed because it might be possible that the circle is larger than the
     * drawn structure.
     *
     * @returns {Boolean} - true if that changed the boundaries, else false
     */
    addStructureCircleToBoundaries() {
        if (!this.enabled) {
            return false;
        }

        const newBoundaries = Object.assign({}, this.boundaries);

        const changed = Structure.calcBoundariesStep(this.representationsData.structureCircle.drawLimits,
            newBoundaries
        );

        if (changed) {
            this.setLimits(newBoundaries);
            return true;
        } else {
            return false;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For each atom of the structure, calculates the necessary offsets to move
     * the atom such that it rotates some angle around a rotation point.
     *
     * @param angle {Number} - angle to rotate
     * @param isDeg {Boolean} - is angle given in degree (false -> angle is
     * radian)
     * @param rotationPoint {Object} - point to rotate around - if none is
     * given, rotate around own midpoint
     * @param filter - callback to filter out atoms if only subset of atoms
     * should be rotated
     * @returns {Object} - map of atom ids to offsets
     */
    calcAtomRotationOffsets(angle, isDeg, rotationPoint, filter) {
        const mid = rotationPoint ? rotationPoint : this.boundaries.mid;

        const atomsToRotate = filter ? this.atomsData.atoms.filter(atom => {
            return filter(atom)
        }) : this.atomsData.atoms;
        const atomCoords = atomsToRotate.map(atom => {
            return atom.tempCoordinates;
        });

        const rotatedCoords = PointCalculation.rotatePointsAroundMid(atomCoords, angle, mid, isDeg);

        const offsetMap = {};
        atomsToRotate.forEach(({id: atomId, tempCoordinates}, idx) => {
            const rotatedCoord = rotatedCoords[idx];
            offsetMap[atomId] = {
                x: rotatedCoord.x - tempCoordinates.x, y: rotatedCoord.y - tempCoordinates.y
            }
        });
        return offsetMap;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Deep clone this Structure object.
     *
     * @returns {Structure} - the new Structure object
     */
    clone() {
        const clone = new Structure(this.id,
            this.structureName,
            this.structureType,
            this.structureLabel,
            this.spaceToRings,
            Object.assign({}, this.additionalInformation)
        );
        clone.atomsData = new AtomsData();
        clone.edgesData = new EdgesData(this.atomsData);
        clone.ringsData = new RingsData(this.atomsData, this.edgesData, this.spaceToRings);
        clone.representationsData = new RepresentationsData(this.structureType);
        clone.annotationConnectionData = new AnnotationConnectionData();
        clone.hydrophobicConnectionData = new HydrophobicConnectionData();
        clone.intermolecularConnectionData =
            new IntermolecularConnectionData(clone.ringsData);
        clone.edgesData.angles = Object.assign({}, this.edgesData.angles);
        clone.atomsData.atoms = [];
        clone.atomsData.atomById = {};
        this.atomsData.atoms.forEach(atom => {
            const atomClone = atom.clone();
            clone.atomsData.atoms.push(atomClone);
            clone.atomsData.atomById[atomClone.id] = atomClone;
        });
        clone.ringsData.bccs = JSON.parse(JSON.stringify(this.ringsData.bccs));
        clone.ringsData.ringSystems = JSON.parse(JSON.stringify(this.ringsData.ringSystems));
        clone.boundaries = Object.assign({}, this.boundaries);
        clone.curOffset = Object.assign({}, this.curOffset);
        clone.edgesData.edges = [];
        clone.edgesData.edgeById = {};
        clone.edgesData.edgeByAtoms = {};
        this.edgesData.edges.forEach(edge => {
            const edgeClone = edge.clone();
            clone.edgesData.edges.push(edgeClone);
            const {id: edgeId, to, from} = edgeClone;
            clone.edgesData.edgeById[edgeId] = edgeClone;
            const toIsSmaller = (to < from);
            const smaller = toIsSmaller ? to : from;
            const larger = toIsSmaller ? from : to;
            if (!clone.edgesData.edgeByAtoms.hasOwnProperty(smaller)) {
                clone.edgesData.edgeByAtoms[smaller] = {};
            }
            clone.edgesData.edgeByAtoms[smaller][larger] = edgeClone;
        });
        clone.atomsData.neighbors = Object.assign({}, this.atomsData.neighbors);
        clone.ringsData.rings = {};
        clone.ringsData.aromaticRings = {};
        for (const ringId in this.ringsData.rings) {
            const ring = this.ringsData.getRing(ringId);
            const ringClone = ring.clone();
            clone.ringsData.rings[ringId] = ringClone;
            if (ringClone.aromatic) {
                clone.ringsData.aromaticRings[ringId] = ringClone;
            }
        }
        clone.atomsData.selectedAtoms = new Set(this.atomsData.selectedAtoms);
        clone.edgesData.selectedEdges = new Set(this.edgesData.selectedEdges);
        clone.atomsData.tempSelectedAtoms = new Set(this.atomsData.tempSelectedAtoms);
        clone.edgesData.tempSelectedEdges = new Set(this.edgesData.tempSelectedEdges);
        clone.hydrophobicConnectionData.hydrophobicConts = {};
        for (const hId in this.hydrophobicConnectionData.hydrophobicConts) {
            clone.hydrophobicConnectionData.hydrophobicConts[hId] =
                this.hydrophobicConnectionData.hydrophobicConts[hId].clone();
        }
        return clone;
    }
}


/* src/Data/Objects/TextLabelBased.js */
/**
 * Base class for representation of text label information in the drawer's memory. Used for
 * annotations.
 */
class TextLabel {
    /**
     * Creates a new TextLabel object.
     *
     * @param id {Number} - internal id of text label
     * @param label {String} - text of the label
     * @param coordinates {Object} - placement of the label, object with x- and
     * y-coordinates
     * @param color {String} - color text should appear in
     * @param additionalInformation {Object} - custom additional information
     * that is saved but does not belong to the drawer itself
     */
    constructor(id, label, coordinates, color, additionalInformation) {
        this.id = id;
        this.label = label;
        this.additionalInformation = additionalInformation;
        this.coordinates = Object.assign({}, coordinates);
        this.tempCoordinates = Object.assign({}, coordinates);
        this.color = color; //may be undefined
        this.enabled = true;

        //to check actual space taken by text (e.g. used to center the view)
        this.drawLimits = null;
        this.globalDrawLimits = null;
        this.surroundingRect = null;

        //to check collisions of elements with the selector
        this.selectorShapes = [];
        this.tempSelectorShapes = [];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Represents movement of a text label by a certain offset.
     *
     * @param offset {Object} - object to represent x- and y-movement
     * @param byTemp {Boolean}- whether movement is temporary (not logged to
     * history) or not
     */
    addOffsetToCoords(offset, byTemp = false) {
        const coords = byTemp ? this.tempCoordinates : this.coordinates;
        coords.x = coords.x + offset.x;
        coords.y = coords.y + offset.y;
        if (!byTemp) {
            this.tempCoordinates = Object.assign({}, coords);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds representation of draw limits after creating draw element for the
     * label (for placement concerns).
     *
     * @param drawLimits {Array} - object containing draw limits as minima
     * and maxima of the text label's bounding box
     * (as xMin, xMax, yMin, yMax)
     * @param rectBoundaries {Array} - object containing boundaries as minima
     * and maxima of the text label's bounding box (as xMin, xMax, yMin,
     * yMax). If present those will be taken to calculate the surrounding rect
     */
    setDrawLimits(drawLimits, rectBoundaries = undefined) {
        this.drawLimits = JSON.parse(JSON.stringify(drawLimits));
        const globalDrawLimits = {
            xMin: Infinity, xMax: -Infinity, yMin: Infinity, yMax: -Infinity
        };
        drawLimits.forEach(({limits: curDrawLimits}) => {
            if (curDrawLimits.xMin < globalDrawLimits.xMin) {
                globalDrawLimits.xMin = curDrawLimits.xMin;
            }
            if (curDrawLimits.xMax > globalDrawLimits.xMax) {
                globalDrawLimits.xMax = curDrawLimits.xMax;
            }
            if (curDrawLimits.yMin < globalDrawLimits.yMin) {
                globalDrawLimits.yMin = curDrawLimits.yMin;
            }
            if (curDrawLimits.yMax > globalDrawLimits.yMax) {
                globalDrawLimits.yMax = curDrawLimits.yMax;
            }
        });
        this.globalDrawLimits = globalDrawLimits;
        const {xMin, xMax, yMin, yMax} = (rectBoundaries && rectBoundaries[0].limits) || drawLimits;
        this.surroundingRect = PolygonCalculation.createRectByBoundaries(xMin, xMax, yMin, yMax);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds representation of the surrounding selector shape of the text label
     * after creating its draw element.
     *
     * @param selectorShapes {Array} - different selector shapes, objects
     * holding both 'type' and 'coordinates' field
     * @param byTemp {Boolean}- whether movement is temporary (not logged to
     * history) or not
     */
    setSelectorShapes(selectorShapes, byTemp = false) {
        this.tempSelectorShapes = selectorShapes;
        if (!byTemp) {
            this.selectorShapes = JSON.parse(JSON.stringify(selectorShapes));
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given different hit functions, checks whether the text label is hit by
     * certain other draw elements. The provided callbacks must define which
     * elements to check for, as none are passed into this function. Hit tests
     * selector shapes and the text label itself by approximation over its
     * bounding box.
     *
     * @param circleHitFunction {Function} - function to hit test circle
     * elements
     * @param rectHitFunction {Function} - function to hit test rectangular
     * elements
     * @returns {Boolean} - whether the label is hit by provided functions
     */
    testHitFunctionsForSelection({circleHitFunction, rectHitFunction}) {
        const selShapes = this.selectorShapes;
        //test hits with overall text (appropriated by text box)
        if (rectHitFunction(this.surroundingRect)) {
            return true;
        }
        //test hits with individual selectors (currently just circles)
        for (let i = 0, len = selShapes.length; i < len; ++i) {
            const selShape = selShapes[i];
            if (selShape.type === 'circle') {
                if (circleHitFunction) {
                    //convert shape to circle format used in Geometry
                    const {coordinates: {x, y}, rad} = selShape;
                    const circle = {
                        x: x, y: y, rad: rad
                    };
                    if (circleHitFunction(circle)) {
                        return true;
                    }
                }
            } else if (selShape.type === 'line') {
                if (rectHitFunction && rectHitFunction(selShape.corners)) {
                    return true;
                }
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a deep copy of this TextLabel object.
     *
     * @returns {TextLabel} cloned TextLabel object
     */
    clone() {
        const clone = new TextLabel(this.id,
            this.label,
            this.coordinates,
            this.color,
            this.additionalInformation
        );
        this.transferParameters(clone);
        return clone;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Transfers important parameters of this object to a new object during the
     * cloning process.
     *
     * @param clone {TextLabel} - text label to refer parameters to
     */
    transferParameters(clone) {
        clone.drawLimits = JSON.parse(JSON.stringify(this.drawLimits));
        clone.globalDrawLimits = JSON.parse(JSON.stringify(this.globalDrawLimits));
        clone.surroundingRect = JSON.parse(JSON.stringify(this.surroundingRect));
        clone.selectorShapes = JSON.parse(JSON.stringify(this.selectorShapes));
        clone.tempSelectorShapes = JSON.parse(JSON.stringify(this.tempSelectorShapes));
    }
}

/**
 * Class for representation of annotation text labels. Extends base TextLabel
 * class by memorization of related structures and atoms.
 */
class Annotation extends TextLabel {
    /**
     * Creates a new Annotation object.
     *
     * @param id {Number} - internal id of the annotation
     * @param label {String} - text of the label
     * @param coordinates {Object} - placement of the label, object with x- and
     * y-coordinates
     * @param color {String} - color text should appear in
     * @param structureLink {Number} - structure the annotation belongs to
     * @param atomLinks {Array} - ids of atoms the annotations should mimic
     * interaction for (e.g., follow the same movement)
     * @param type {String} - type of the annotation ('structure', 'structureSpline')
     * @param belongsToStructure {Boolean} - true if Annotation is connected to a structure
     * @param isStructureLabel {Boolean} - if the annotation is (a part of) the
     * structure label or name. Those annotations will be hidden when the the
     * linked structure is shown as structure circle
     * @param additionalInformation {Object} - custom additional information
     * that is saved but does not belong to the drawer itself
     */
    constructor({
        id,
        label,
        coordinates,
        color,
        structureLink,
        atomLinks,
        type,
        belongsToStructure,
        isStructureLabel,
        additionalInformation
    }) {
        super(id, label, coordinates, color, additionalInformation);
        this.structureLink = structureLink;
        this.atomLinks = atomLinks;
        this.type = type;
        this.belongsToStructure = belongsToStructure;
        this.isStructureLabel = isStructureLabel;
        this.structureRepresentationInfo = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a deep copy of this Annotation object.
     *
     * @returns {Annotation} - cloned Annotation object
     */
    clone() {
        const createParams = {
            id: this.id,
            label: this.label,
            coordinates: Object.assign({}, this.coordinates),
            color: this.color,
            structureLink: this.structureLink,
            atomLinks: this.atomLinks.slice(),
            type: this.type,
            belongsToStructure: this.belongsToStructure,
            isStructureLabel: this.isStructureLabel,
            structureRepresentationInfo: JSON.parse(JSON.stringify(this.structureRepresentationInfo)),
            additionalInformation: Object.assign({}, this.additionalInformation)
        };
        const clone = new Annotation(createParams);
        this.transferParameters(clone);
        return clone;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates alternative coordinates of the annotation.
     *
     * @param structureRep {StructureRepresentation} - the current
     * representation of the Structure object the annotation belongs to
     * @param structureMoved {Boolean} - whether the complete structure moved
     * or just the (atom and) annotation
     * @param offsets {Object} - x- and y-values of vector to move coordinates
     * @param interactionMode {InteractionMode} - the applied interaction mode
     * @param altRotCoords {Object} - rotation coordinates for the not
     * StructureRepresentation currently not in use
     * @param newStructureMid {Object} - x- and y-values of the structure mid
     * after coordination changes
     * @param oldStructureMid {Object} - x- and y-values of the structure mid
     * before coordination changes
     * @param dimensions {Object} - object containing width and height of the
     * annotation (bbox)
     */
    updateAlternativeRepresentationCoords(structureRep,
        structureMoved,
        offsets,
        interactionMode,
        altRotCoords,
        newStructureMid,
        oldStructureMid,
        dimensions
    ) {
        for (const [rep, info] of Object.entries(this.structureRepresentationInfo)) {
            const repInfoObj = this.structureRepresentationInfo[rep];
            switch (interactionMode) {
                case InteractionMode.movement:
                    if (structureMoved || rep == structureRep) {
                        repInfoObj.coordinates =
                            VectorCalculation.vectorAdd(info.coordinates, offsets);
                    }
                    if (!structureMoved && rep == StructureRepresentation.circle && structureRep ==
                        StructureRepresentation.circle) {

                        const {
                            dist, relativePosition
                        } = PolygonCalculation.getClosestPointOnRectangle(newStructureMid, {
                            xMin: repInfoObj.coordinates.x - dimensions.width / 2,
                            xMax: repInfoObj.coordinates.x + dimensions.width / 2,
                            yMin: repInfoObj.coordinates.y - dimensions.height / 2,
                            yMax: repInfoObj.coordinates.y + dimensions.height / 2
                        });
                        repInfoObj.distToCircleMid = dist;
                        repInfoObj.circleMidIsInside = relativePosition === RelativePosition.inside;
                    }
                    break;
                case InteractionMode.rotation:
                    if (rep != structureRep && altRotCoords) {
                        repInfoObj.coordinates = Object.assign({}, altRotCoords);
                    } else if (rep == structureRep) {
                        repInfoObj.coordinates =
                            VectorCalculation.vectorAdd(info.coordinates, offsets);
                    }
                    break;
                case InteractionMode.lineMirror:
                case InteractionMode.bondMirror:
                    if (rep == structureRep && offsets) {
                        repInfoObj.coordinates =
                            VectorCalculation.vectorAdd(info.coordinates, offsets);
                    } else if (rep == StructureRepresentation.circle) {
                        const offs = VectorCalculation.vectorSubstract(newStructureMid,
                            oldStructureMid
                        );
                        repInfoObj.coordinates =
                            VectorCalculation.vectorAdd(info.coordinates, offs);
                    }
                    break;
            }
        }
    }
}

/**
 * Class for representation of atom text labels. Extends functionality of
 * base TextLabel class for atom specific (chemically motivated) functions.
 */
class Atom extends TextLabel {
    /**
     * Creates a new Atom object.
     *
     * @param id {Number}- internal id (within structure) of atom
     * @param element {String} - one/two letter code for atom's element
     * @param label {String} - text of the label
     * @param charge {Number} - charge of the atom, to draw as separate text
     * element
     * @param hydrogenCount {Number} - hydrogen count of atom, to draw as
     * separate text
     * element {String} - one/two letter code of atom's element
     * @param coordinates {Object} - placement of the label, object with x- and
     * y-coordinates
     * @param color {String} - color text should appear in
     * @param aromatic {Boolean} - whether atom is part of aromatic ring system
     * @param stereoCenter {Boolean} - whether atom is stereo center
     * @param additionalInformation {Object} - custom additional information
     * that is saved but does not belong to the drawer itself
     */
    constructor({
        id,
        element,
        label,
        charge,
        hydrogenCount,
        coordinates,
        color,
        aromatic,
        stereoCenter,
        additionalInformation
    }) {
        super(id, label, coordinates, color, additionalInformation);

        this.element = element;
        this.charge = charge;

        //keep track of aromatic rings (if there are any and which this atom is
        //part of)
        this.aromatic = aromatic;
        this.rings = new Set();
        this.aromaticRings = new Set();
        this.isInRing = false;

        this.stereoCenter = stereoCenter ? stereoCenter : false;
        this.connectedComponent = undefined;
        this.ringSystem = undefined;

        this.hydrogenCount = hydrogenCount;
        this.hydrogenOrientation = undefined;
        this.tempHydrogenOrientation = undefined;

        //if atom should be treated as (amino acid) label
        this.isLabel = (!!this.label && this.label.length > 2 && !this.hydrogenCount);
        this.labelOrientation = undefined;
        this.tempLabelOrientation = undefined;

        this.wn = 0; //winding number for free selector
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks atom as part of ring with given id.
     *
     * @param ringId {Number} - ring the atom is part of
     */
    addRing(ringId) {
        this.rings.add(ringId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks atom as part of aromatic ring with given id.
     *
     * @param ringId {Number} - aromatic ring the atom is part of
     */
    addAromaticRing(ringId) {
        this.aromaticRings.add(ringId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the hydrogen count of this atom, based on its element and given
     * number of outgoing bonds.
     *
     * @param nrEdges {Number} - number of bonds from this atom
     */
    calcHydrogenCount(nrEdges) {
        this.hydrogenCount = this.calcExpectedHCount(nrEdges);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates the hydrogen count of this atom, based on its element and
     * given number of outgoing bonds.
     *
     * @param nrEdges {Number} - number of bonds from this atom
     * @returns {Number} - atom's hydrogen count
     */
    calcExpectedHCount(nrEdges) {
        const maxPossibleBonds = AtomInfo.maxPossibleBonds(this.element);
        if (maxPossibleBonds === -1) {
            return 0;
        }
        const aromaticBonds = this.aromatic ? 1 : 0;
        return Math.max(maxPossibleBonds - nrEdges - aromaticBonds + this.charge, 0);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets current hydrogen orientation of atom text, to be committed to the
     * drawer's history.
     *
     * @param orientation {String} - 'left', 'right', 'down', or 'up'
     */
    setHydrogenOrientation(orientation) {
        this.hydrogenOrientation = orientation;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets current hydrogen orientation of atom text, NOT to be committed to
     * the drawer's history.
     *
     * @param orientation {String} - 'left', 'right', 'down', or 'up'
     */
    setTempHydrogenOrientation(orientation) {
        this.tempHydrogenOrientation = orientation;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets current label orientation of atom representing amino acid label.
     *
     * @param orientation {String} - 'left', 'right', 'up', or 'down'
     * @param byTemp {Boolean} - whether to apply orientation only to
     * temporary data
     */
    setLabelSide(orientation, byTemp) {
        this.tempLabelOrientation = orientation;
        if (!byTemp) {
            this.labelOrientation = orientation;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out in which direction, based of the main atom (element) text the
     * text for hydrogen representation should be drawn.
     *
     * @param neighbors {Array} - neighboring Atom objects of this atom
     * @param byTemp {Boolean} - if temporary coordinates should be used for
     * calculation
     * @returns {String} - the atom's hydrogen orientation -> 'left', 'right',
     * 'up' or 'down'
     */
    calcHydrogenOrientation(neighbors, byTemp) {
        const permitUpDown = neighbors.length !== 1;
        return this.findAtomSideMostSpace(neighbors, byTemp, permitUpDown);
    }

    /*----------------------------------------------------------------------*/

    /**
     * If this Atom object represents an amino acid label, finds the side its
     * neighboring bond should dock on.
     *
     * @param neighbors {Array} - neighboring Atom objects of this atom
     * @param byTemp {Boolean} - if temporary coordinates should be used for
     * calculation
     * @returns {String} - the side the neighboring bond should dock on ->
     * 'left', 'right', 'up' or 'down'
     */
    calcLabelSide(neighbors, byTemp) {
        switch (this.findAtomSideMostSpace(neighbors, byTemp, true)) {
            case 'left':
                return 'right';
            case 'right':
                return 'left';
            case 'up':
                return 'down';
            case 'down':
                return 'up';
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out which side of the atom offers the most free space based on the
     * positions of its neighbors.
     *
     * @param neighbors {Array} - neighboring Atom objects of this atom
     * @param byTemp {Boolean} - if temporary coordinates should be used for
     * calculation
     * @param permitUpDown {Boolean} - whether direction can be 'up' or
     * 'down' (sometimes this should be suppressed for cleaner drawing)
     * @returns {String} - the side with most free space -> 'left', 'right',
     * 'up' or 'down'
     */
    findAtomSideMostSpace(neighbors, byTemp, permitUpDown) {
        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
        const center = this[coordParam];
        const nbCoords = neighbors.map(nb => nb[coordParam]);
        return PointCalculation.findSideMostSpace(center, nbCoords, permitUpDown);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if the atom is a hydrogen.
     *
     * @returns {Boolean} - true if the atom is a hydrogen, else false
     */
    isHydrogen() {
        return this.element === 'H';
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if the atom is a metal.
     *
     * @returns {Boolean} - true if the atom is a metal, else false
     */
    isMetal() {
        return AtomInfo.metalElements.includes(this.element)
    }

    /*----------------------------------------------------------------------*/

    /**
     * Create a deep copy of this Atom object.
     *
     * @returns {Atom} - cloned Atom object
     */
    clone() {
        const createParams = {
            id: this.id,
            element: this.element,
            label: this.label,
            charge: this.charge,
            hydrogenCount: this.hydrogenCount,
            coordinates: Object.assign({}, this.coordinates),
            color: this.color,
            aromatic: this.aromatic,
            stereoCenter: this.stereoCenter,
            rings: new Set(this.rings),
            aromaticRings: new Set(this.aromaticRings),
            additionalInformation: Object.assign({}, this.additionalInformation)
        };
        const clone = new Atom(createParams);
        this.transferParameters(clone);
        clone.connectedComponent = this.connectedComponent;
        clone.ringSystem = this.ringSystem;
        clone.hydrogenOrientation = this.hydrogenOrientation;
        clone.tempHydrogenOrientation = this.tempHydrogenOrientation;
        return clone;
    }
}

