/* src/Data/SceneData.js */
/**
 * Contains the data of the current scene (i.e. the input JSONs and the data extracted out of
 * those).
 */
class SceneData {
    /**
     * Contains an instance for the configuration options and sets the object to default state.
     */
    constructor(opts) {
        this.opts = opts;
        this.reset();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets many important containers for structural information to their
     * default (often empty) state. Useful when resetting the scene.
     */
    reset() {
        //with graph structures that track relevant coordinates etc
        this.structuresData = new StructuresData();
        this.intermolecularData = new IntermolecularData();
        this.annotationsData = new AnnotationsData();
        this.hydrophobicData = new HydrophobicData();

        //global limits of structures, used to center the view
        this.globalLimits = {
            xMin: Infinity,
            xMax: -Infinity,
            yMin: Infinity,
            yMax: -Infinity,
            width: Infinity,
            height: Infinity,
            mid: {
                x: undefined, y: undefined
            }
        };

        //all previously added json. Used for a reset of the scene
        this.loadedJsonStrings = [];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the global boundaries of the scene to new values.
     *
     * @param xMin {Number} - new minimum x-coordinate of the bounding box of
     * the scene
     * @param xMax {Number} - new maximum x-coordinate of the bounding box of
     * the scene
     * @param yMin {Number} - new minimum y-coordinate of the bounding box of
     * the scene
     * @param yMax {Number} - new maximum y-coordinate of the bounding box of
     * the scene
     */
    setGlobalLimits(xMin, xMax, yMin, yMax) {
        this.globalLimits = {
            xMin: xMin, xMax: xMax, yMin: yMin, yMax: yMax, mid: {
                x: (xMin + xMax) / 2, y: (yMin + yMax) / 2
            }, width: xMax - xMin, height: yMax - yMin
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the global boundaries of the scene based on structure boundaries,
     * splines, and annotations. To optimize performance, allows the setting
     * of fixed values for boundaries which do not have to be looked at
     * during further comparisons.
     *
     * @param limits {Object} - fixed values for known boundaries (xMin,
     * xMax, yMin, yMax)
     */
    calcBoundaries(limits = undefined) {
        const xMinSet = limits && limits.xMin;
        const xMaxSet = limits && limits.xMax;
        const yMinSet = limits && limits.yMin;
        const yMaxSet = limits && limits.yMax;
        let newXmin = xMinSet ? limits.xMin : Infinity;
        let newXmax = xMaxSet ? limits.xMax : -Infinity;
        let newYmin = yMinSet ? limits.yMin : Infinity;
        let newYmax = yMaxSet ? limits.yMax : -Infinity;

        const updateLimits = (xMin, xMax, yMin, yMax) => {
            if (!xMinSet && xMin < newXmin) {
                newXmin = xMin;
            }
            if (!xMaxSet && xMax > newXmax) {
                newXmax = xMax;
            }
            if (!yMinSet && yMin < newYmin) {
                newYmin = yMin;
            }
            if (!yMaxSet && yMax > newYmax) {
                newYmax = yMax;
            }
        };

        for (const structureId in this.structuresData.structures) {
            const structure = this.structuresData.structures[structureId];
            //setting by structure boundaries
            const {boundaries: {xMin, xMax, yMin, yMax}} = structure;
            updateLimits(xMin, xMax, yMin, yMax);

            //setting by spline boundaries
            Object.values(structure.hydrophobicConnectionData.hydrophobicConts).forEach(spline => {
                const rad = this.opts.lineWidth;
                spline.getCurveCoords(false).forEach(({x, y}) => {
                    updateLimits(x - rad, x + rad, y - rad, y + rad);
                });
            });
        }

        for (const labelId in this.annotationsData.annotations) {
            const annotation = this.annotationsData.annotations[labelId];
            const {globalDrawLimits: {xMin, xMax, yMin, yMax}} = annotation;
            updateLimits(xMin, xMax, yMin, yMax);
        }

        this.setGlobalLimits(newXmin, newXmax, newYmin, newYmax);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on width and height of the draw area provided to the drawer to
     * build its scenes in, eludes vital information to produce nicely centered
     * drawings.
     *
     * @param width {Number} - new width of the draw area
     * @param height {Number} - new height of the draw area
     */
    setInfoForDrawing(width, height) {
        this.drawAreaDim = {
            width: width, height: height
        };
        this.midCoords = {
            x: width / 2, y: height / 2
        };
        this.idealMaxWidth = width - 2 * this.opts.drawAreaPadding;
        this.idealMaxHeight = height - 2 * this.opts.drawAreaPadding;
        this.drawAreaMid = {
            x: this.drawAreaDim.width / 2, y: this.drawAreaDim.height / 2
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns a sub selection of jsons based on type parameter.
     *
     * @param type {Number} - defines which previously added jsons to return
     * 0: load all,
     * 1: only load the first added json,
     * 2: only load jsons containing at least one structure
     */
    getJsonByType(type) {
        let jsonStrings;
        if (type === 0) {
            jsonStrings = this.loadedJsonStrings.slice();
        } else if (type === 1) {
            jsonStrings = this.loadedJsonStrings.slice(0, 1);
        } else if (type === 2) {
            jsonStrings = this.loadedJsonStrings.slice()
                .filter(jString => {
                    const scene = JSON.parse(jString).scene;
                    return scene.structures && scene.structures[0];
                });
        }
        return jsonStrings;
    }
}

/* src/Data/Structure/AnnotationConnectionData.js */
/**
 * Stores data about all annotations of one structure present in the scene.
 */
class AnnotationConnectionData {
    /**
     * Contains instances with data about Annotation objects connected to this structure.
     */
    constructor() {
        //Annotation object ids
        this.annotations = new Set();
        //Atom object id -> Annotation objects ids
        this.atomAnnotationConnections = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the annotations linked to given atom ids.
     *
     * @param atomArr {Array} - atom ids to find linked annotations for
     */
    getAnnotationsForAtoms(atomArr) {
        const annotations = new Set();
        for (const atomId of atomArr) {
            if (!this.atomAnnotationConnections.hasOwnProperty(atomId)) {
                continue;
            }
            Helpers.mergeIntoSet(annotations, this.atomAnnotationConnections[atomId]);
        }
        return annotations;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes that an annotation (by id) belongs to this structure.
     *
     * @param annotationId {Number} - id of annotation
     */
    addAnnotation(annotationId) {
        this.annotations.add(annotationId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes that an annotation is linked to an atom of the structure
     * (consequently, interaction that affects the atom must also affect this
     * annotation).
     *
     * @param atomId {Number} - unique id of the atom to link to
     * @param annotationId {Number} - unique id of the linked annotation
     */
    linkAtomToAnnotation(atomId, annotationId) {
        if (!this.atomAnnotationConnections.hasOwnProperty(atomId)) {
            this.atomAnnotationConnections[atomId] = new Set();
        }
        this.atomAnnotationConnections[atomId].add(annotationId);
    }
}

/* src/Data/Structure/AtomsData.js */
/**
 * Stores data about all atoms of one structure present in the scene.
 */
class AtomsData {

    /*----------------------------------------------------------------------*/

    /**
     * Adds atoms data to a structure setting up further data containers.
     *
     * @param atomInfos {Array} - objects defining atoms of the structure
     * @param stereoCenterInfos {Array} - objects defining which atoms of
     * the structure are stereo centers (optional, otherwise inferred from
     * bond types)
     */
    addAtomInfo(atomInfos, stereoCenterInfos) {
        //Atom objects
        this.atoms = [];
        //Atom object id -> Edge and Atom object id pairs
        this.neighbors = {};
        //Atom object ids
        this.atomIds = [];
        //Atom object id -> index in atomInfos
        this.atomIdxById = {}; //to map back from e.g. adjacency matrix
        //index in atomInfos -> Atom object id
        this.atomIdByIdx = {};
        //Atom object id -> Atom object
        this.atomById = {};
        //Atom object ids
        this.selectedAtoms = new Set();
        //Atom object ids
        this.tempSelectedAtoms = new Set();
        //Atom object id -> direction and order
        this.stereoSubstituentOrders = {};

        //if stereo center information given, add it to atom information
        if (stereoCenterInfos) {
            stereoCenterInfos.forEach((atomId, idx) => {
                atomInfos[idx].stereoCenter = true;
            });
        }

        atomInfos.forEach((atomInfo, idx) => {
            const atom = new Atom(atomInfo);
            const atomId = atom.id;
            this.atoms.push(atom);
            this.atomIds.push(atomId);
            this.atomIdxById[atomId] = idx;
            this.atomIdByIdx[idx] = atomId;
            this.atomById[atomId] = atom;
            this.neighbors[atomId] = [];
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Does some postprocessing of atom data after adding it, e.g. the side of a label.
     */
    postProcessAtoms() {
        this.atoms.forEach(atom => {
            const neighbors = this.neighbors[atom.id];
            const neighborAtoms = [];
            neighbors.forEach(({neighbor: nbId, edgeId}) => {
                neighborAtoms.push(this.getAtom(nbId));
            });
            //setting of required atom orientations
            if (atom.element !== 'C' && atom.hydrogenCount !== 0) {
                atom.setHydrogenOrientation(atom.calcHydrogenOrientation(neighborAtoms, false));
            }
            if (atom.isLabel) {
                atom.setLabelSide(atom.calcLabelSide(neighborAtoms, false), false);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns an Atom object belonging to this structure by its id.
     *
     * @param atomId {Number} - id of Atom object to find
     * @returns {Atom} - Atom object of specified id
     */
    getAtom(atomId) {
        return this.atomById[atomId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds atom objects of atoms which are neighbors of given atom (by id).
     *
     * @param atomId {Number} - id of atom to find neighbors for
     * @returns {Array} - atom objects of neighboring atoms
     */
    getNonHNeighbors(atomId) {
        return this.neighbors[atomId].filter(({neighbor: nbId}) => {
            return this.getAtom(nbId).element !== 'H';
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds ids of all atoms for which currently (non-hidden) representations
     * exist in the draw area.
     *
     * @returns {Array} - drawn atoms by their ids
     */
    getAllDrawnAtoms() {
        return this.atoms.filter(atom => {
            return atom.enabled;
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds ids of all atoms for which currently representations exist in the
     * draw area (INCLUDING hidden representations).
     *
     * @returns {Array} - drawn atoms by their ids
     */
    getAllEnabledAtoms() {
        return this.atoms.filter(atom => {
            return atom.enabled;
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether an interaction on a given subset of atoms affects all
     * atoms of the structure.
     *
     * @param atomArr {Array} - atoms (by id) affected by interactions
     * @returns {Boolean} - whether all atoms of the structure are affected
     */
    isFullStructureAffected(atomArr) {
        return atomArr.length === this.atoms.length;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks atom as selected in internal selection set.
     *
     * @param atomId {Number} - id of atom to mark
     */
    selectAtom(atomId) {
        this.selectedAtoms.add(atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks atom as selected in internal selection Set, but only for temporary
     * means not to be committed into the drawer's history.
     *
     * @param atomId {Number} - id of atom to mark
     */
    tempSelectAtom(atomId) {
        this.tempSelectedAtoms.add(atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on its current position, finds out whether the placement of atom
     * text for this structure's atoms must be altered (and how).
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * atom parameters for this calculation
     * @returns {Object} - map between atom ids and new hydrogen text
     * orientations
     */
    findAtomsWithChangedHPlacement(byTemp) {
        const orientationParam = byTemp ? 'tempHydrogenOrientation' : 'hydrogenOrientation';
        const changedAtoms = {};
        this.atoms.forEach(atom => {
            if (atom.element === 'C' || atom.hydrogenCount <= 0) {
                return;
            }
            const neighbors = this.neighbors[atom.id].map(nb => {
                return this.getAtom(nb.neighbor);
            });
            const newHorientation = atom.calcHydrogenOrientation(neighbors, byTemp);
            if (newHorientation !== atom[orientationParam]) {
                changedAtoms[atom.id] = newHorientation;
            }
        });
        return changedAtoms;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on its current position, finds out whether the placement of amino
     * acid labels must be altered (and how).
     *
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * atom parameters for this calculation
     * @returns {Object} - map between atom ids and new label orientations
     */
    findAtomsWithChangedAnchors(byTemp) {
        const orientationParam = byTemp ? 'tempLabelOrientation' : 'labelOrientation';
        const changedLabels = {};
        this.atoms.forEach(atom => {
            if (!atom.isLabel) return;
            const neighbors = this.neighbors[atom.id].map(nb => {
                return this.getAtom(nb.neighbor);
            });
            const newOrientation = atom.calcLabelSide(neighbors, byTemp);
            if (newOrientation !== atom[orientationParam]) {
                changedLabels[atom.id] = newOrientation;
            }
        });
        return changedLabels;
    }
}

/* src/Data/Structure/EdgesData.js */
/**
 * Stores data about all edges of one structure present in the scene.
 */
class EdgesData {
    /**
     * Contains instances with data about atoms.
     */
    constructor(atomsData) {
        this.atomsData = atomsData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds edges data to a structure setting up further data containers.
     *
     * @param edgeInfos {Array} - objects defining bonds of the structure
     */
    addEdgeInfo(edgeInfos) {
        //Edge objects
        this.edges = [];
        //Atom object ids -> Atom object id -> Edge object
        this.edgeByAtoms = {};
        //Edge object id -> index in edgeInfos
        this.edgeIdxById = {}; //for e.g. XOR
        //index in edgeInfos -> Edge object id
        this.edgeIdByIdx = {};
        //Edge object id -> Edge object
        this.edgeById = {};
        //Edge object id -> Edge object ids
        this.edgeNeighbors = {}; //Sets to memorize if edges are next to each other
        //Edge object id -> Edge object id -> angle
        this.angles = {}; //angles between neighboring edges
        //Edge object ids
        this.selectedEdges = new Set();
        //Edge object ids
        this.tempSelectedEdges = new Set();

        this.avgEdgeLength = 0;
        let accEdgeLength = 0;
        edgeInfos && edgeInfos.forEach((edgeInfo, idx) => {
            const edge = new Edge(edgeInfo);
            this.edges.push(edge);
            const {id: edgeId, to, from} = edge;
            this.edgeById[edgeId] = edge;
            this.edgeIdxById[edgeId] = idx;
            this.edgeIdByIdx[idx] = edgeId;
            this.atomsData.neighbors[to].push({
                neighbor: from, edgeId: edgeId
            });
            this.atomsData.neighbors[from].push({
                neighbor: to, edgeId: edgeId
            });
            const toIsSmaller = (to < from);
            const smaller = toIsSmaller ? to : from;
            const larger = toIsSmaller ? from : to;
            if (!this.edgeByAtoms.hasOwnProperty(smaller)) {
                this.edgeByAtoms[smaller] = {};
            }
            this.edgeByAtoms[smaller][larger] = edge;
            this.edgeNeighbors[edgeId] = new Set();
            this.angles[edgeId] = {};
            accEdgeLength += this.getEdgeLength(edgeId);
        });
        this.avgEdgeLength = accEdgeLength / this.edges.length;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Does some postprocessing of edge data after adding it.
     */
    postProcessEdges() {
        this.edges.forEach(({id: edgeId}) => {
            this.calcEdgeNeighborInfo(edgeId);
        });
        //needs neighbors
        this.edges.forEach(({id: edgeId}) => {
            this.calcRelevantAnglesForEdge(edgeId);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Does some postprocessing of edge data after adding it, e.g. with respect to
     * stereo centers.
     *
     * @param stereoCenterInfos {Array} - objects defining which atoms of
     * the structure are stereo centers (optional, otherwise inferred from
     * bond types)
     */
    postProcessAtomsByEdges(stereoCenterInfos) {
        this.atomsData.atoms.forEach(atom => {
            const atomId = atom.id;
            const neighbors = this.atomsData.neighbors[atomId];
            if (atom.hydrogenCount === 'missing') {
                atom.calcHydrogenCount(this.getNrBondsFromAtom(atomId, true));
            }
            const neighborEdges = [];
            neighbors.forEach(({neighbor: nbId, edgeId}) => {
                neighborEdges.push(this.getEdge(edgeId));
            });
            //if stereo centers not given by user, deduce them here
            if (!stereoCenterInfos) {
                EdgesData.deduceAtomStereoByEdges(atom, atomId, neighborEdges)
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Deduces the stereo center property based on neighbour edge types.
     *
     * @param atom {Array} - Atom object
     * @param atomId {Array} - id of this Atom object
     * @param neighborEdges {Array} - neighbour edges of this atom
     */
    static deduceAtomStereoByEdges(atom, atomId, neighborEdges) {
        for (const edge of neighborEdges) {
            const type = edge.type;
            if (type === 'stereoBack' || type === 'stereoFront') {
                if (edge.from === atomId) {
                    atom.stereoCenter = true;
                    break;
                }
            } else if (type === 'stereoBackReverse' || type === 'stereoFrontReverse') {
                if (edge.to === atomId) {
                    atom.stereoCenter = true;
                    break;
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns an Edge object belonging to this structure by its id.
     *
     * @param edgeId {Number}- id of Edge object to find
     * @returns {Edge} - Edge object of specified id
     */
    getEdge(edgeId) {
        return this.edgeById[edgeId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Extends info on which atoms are neighbors of each other in the
     * this.neighbors object based on an edge (by id).
     *
     * @param edgeId {Number} - id of edge to extend neighbor information by
     */
    calcEdgeNeighborInfo(edgeId) {
        const {from, to} = this.getEdge(edgeId);
        let edgeNeighborIds = this.atomsData.neighbors[from].map(nb => {
            return nb.edgeId;
        });
        edgeNeighborIds = edgeNeighborIds.concat(this.atomsData.neighbors[to].map(nb => {
            return nb.edgeId;
        }));
        const edgeNeighborSet = new Set(edgeNeighborIds);
        edgeNeighborSet.delete(edgeId);
        this.edgeNeighbors[edgeId] = edgeNeighborSet;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates angles from an edge (given by its id) towards neighboring
     * edges if not calculated before (or force calculation via override
     * parameter) and write these into the this.angles object
     *
     * @param edgeId {Number} - id of edge to calculate angles for
     * @param override {Boolean} - whether angles should still be calculated
     * for which an entry in this.angles already exists
     * @param byTemp {Boolean} - whether angle changes are only temporary or
     * to be committed to the drawer's history
     */
    calcRelevantAnglesForEdge(edgeId, override = false, byTemp = false) {
        const {from, to} = this.getEdge(edgeId);
        const angles = this.angles[edgeId];

        this.edgeNeighbors[edgeId].forEach(secondEdgeId => {
            if (angles.hasOwnProperty(secondEdgeId) && !override) {
                return;
            }
            //get all necessary coordinates
            const {from: from2, to: to2} = this.getEdge(secondEdgeId);

            //firstOtherId belongs to edge by edgeId
            let sharedAtomId, firstOtherId, secondOtherId;
            if (from === from2) {
                sharedAtomId = from;
                firstOtherId = to;
                secondOtherId = to2;
            } else if (from === to2) {
                sharedAtomId = from;
                firstOtherId = to;
                secondOtherId = from2;
            } else if (to === from2) {
                sharedAtomId = to;
                firstOtherId = from;
                secondOtherId = to2;
            } else { //to === to2
                sharedAtomId = to;
                firstOtherId = from;
                secondOtherId = from2;
            }

            const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
            const sharedCoords = this.atomsData.getAtom(sharedAtomId)[coordParam];
            const firstOtherCoords = this.atomsData.getAtom(firstOtherId)[coordParam];
            const secondOtherCoords = this.atomsData.getAtom(secondOtherId)[coordParam];

            //calc angle based on coordinates (define as two lines)
            const edgeAngle = AngleCalculation.radianToDegree(VectorCalculation.findAngleBetweenLines(sharedCoords,
                firstOtherCoords,
                sharedCoords,
                secondOtherCoords
            ));
            //set angles, other direction via shortcut
            if (LineCalculation.isLeft(sharedCoords, firstOtherCoords, secondOtherCoords)) {
                angles[secondEdgeId] = 360 - edgeAngle;
                this.angles[secondEdgeId][edgeId] = edgeAngle;
            } else {
                angles[secondEdgeId] = edgeAngle;
                this.angles[secondEdgeId][edgeId] = 360 - edgeAngle;
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets length of Edge with given id.
     *
     * @param edgeId {Number}- id of Edge object to find length for
     * @returns {Number} - length of edge
     */
    getEdgeLength(edgeId) {
        const {from, to} = this.getEdge(edgeId);
        const fromCoords = this.atomsData.getAtom(from).coordinates;
        const toCoords = this.atomsData.getAtom(to).coordinates;
        return VectorCalculation.getDist2d(fromCoords, toCoords);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For an atom specified by its id, finds the number of bonds outgoing from
     * this atom (can include atom pair interactions, based on bond types and the
     * atom's element).
     *
     * @param atomId {Number} - id of atom to find number of outgoing bonds for
     * @param includeExplHs {Boolean} - whether hydrogen bonds to atoms
     * without explicit representation should be counted
     * @returns {Number} - number of outgoing bonds from the queried atom
     */
    getNrBondsFromAtom(atomId, includeExplHs = true) {
        const nbs = includeExplHs ? this.atomsData.neighbors[atomId] :
            this.atomsData.getNonHNeighbors(atomId);
        return nbs.reduce((bondCount, nb) => {
            const edge = this.getEdge(nb.edgeId);
            let bondVal;
            switch (edge.type) {
                case 'double':
                    bondVal = 2;
                    break;
                case 'triple':
                    bondVal = 3;
                    break;
                default:
                    bondVal = 1;
                    break;
            }
            return bondCount + bondVal;
        }, 0);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets (unique!) atom ids references by 'from' and 'to' parameters in edge
     * objects belonging to this structure referenced by their (edge) ids.
     *
     * @param edgeIds {Array} - ids of edge objects to query
     * @param asSet {Boolean} - whether to return atom ids as set (or, if set
     * to false, as an Array)
     * @returns {Set|Array} - unique atom ids belonging to queried Edge objects
     */
    getAtomsByEdges(edgeIds, asSet = false) {
        const atomSet = edgeIds.reduce((atomSet, edgeId) => {
            const {from, to} = this.getEdge(edgeId);
            return [from, to].reduce((atomSet, atomId) => {
                return atomSet.add(atomId);
            }, atomSet)
        }, new Set());
        if (asSet) {
            return atomSet;
        } else {
            return [...atomSet];
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds ids of all edges for which currently representations exist in the
     * draw area (INCLUDING hidden representations).
     *
     * @returns {Array} - drawn edges by their ids
     */
    getAllEnabledEdges() {
        return this.edges.filter(edge => {
            return edge.enabled;
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks edge as selected in internal selection Set.
     *
     * @param edgeId {Number} - id of edge to mark
     */
    selectEdge(edgeId) {
        this.selectedEdges.add(edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks edge as selected in internal selection Set, but only for temporary
     * means not to be committed into the drawer's history.
     *
     * @param edgeId {Number} - id of edge to mark
     */
    tempSelectEdge(edgeId) {
        this.tempSelectedEdges.add(edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds Edge object which contains given atom ids in its 'from' and 'to'
     * fields.
     *
     * @param atom1Id {Number} - first atom id
     * @param atom2Id {Number} - second atom id
     * @returns {Edge} - Edge object containing atom ids
     */
    getEdgeByAtomIds(atom1Id, atom2Id) {
        const firstIsSmaller = atom1Id < atom2Id;
        const smaller = firstIsSmaller ? atom1Id : atom2Id;
        const larger = firstIsSmaller ? atom2Id : atom1Id;
        return this.edgeByAtoms[smaller][larger];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Double bonds might have to be drawn with offset or straight, finds out
     * which is the case here.
     *
     * @param edge {Edge} - Edge object representing the double bond
     * @returns {Boolean} - whether the second bond has to be drawn with offset
     * (or straight)
     */
    decideDrawWithOffset(edge) {
        const edgeId = edge.id;

        if (edge.cyclic) {
            return true;
        }
        const {from, to} = edge;
        const fromAtom = this.atomsData.getAtom(from);
        const toAtom = this.atomsData.getAtom(to);
        const nbsFrom = this.atomsData.neighbors[from];
        const nbsTo = this.atomsData.neighbors[to];
        const nrNbsFrom = nbsFrom.length;
        const nrNbsTo = nbsTo.length;

        //criterion to decide if edge can be straight
        const canDrawStraight = (ptAtom, nrNbsPt, nbsPt, nrNbsOther) => {
            //case 1: double bond to terminal atom
            if (nrNbsPt === 1) {
                if (ptAtom.element !== 'C') {
                    return true;
                }
                if (nrNbsOther === 1 || nrNbsOther > 2) {
                    return true;
                }
                //case 2: double bond after other double bond (must be directly on
                //line)
            } else if (nrNbsPt === 2) {
                let remNeighbor = nbsPt[0];
                if (remNeighbor.edgeId === edgeId) {
                    remNeighbor = nbsPt[1];
                }
                const remEdge = this.getEdge(remNeighbor.edgeId);
                //TODO: works well in practice, but maybe not precise enough
                if (edge.type === 'double' && remEdge.type === 'double') {
                    return true;
                }
            }
            return false;
        };

        //check criterion from both edge sides
        return !canDrawStraight(fromAtom, nrNbsFrom, nbsFrom, nrNbsTo) &&
            !canDrawStraight(toAtom, nrNbsTo, nbsTo, nrNbsFrom)
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given an array of atoms affected by an interaction (by their ids), finds
     * out which bonds must then be updated.
     *
     * @param atomArr {Array} - ids of atom affected by interaction
     * @returns {Set} - ids of bonds that must be updated
     */
    getEdgesAffectedByAtoms(atomArr) {
        const affectedEdges = new Set();
        atomArr.forEach(atomId => {
            this.atomsData.neighbors[atomId].forEach(({edgeId}) => {
                affectedEdges.add(edgeId);
            });
        });
        return affectedEdges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Some values (like for now only correct edge labeling) may be unknown
     * until all user specified functions are run on adding structures. This
     * function finishes the structure based on such user input.
     */
    finishEdgeLabeling() {
        this.atomsData.atoms.forEach(atom => {
            if (atom.stereoCenter) {
                this.atomsData.stereoSubstituentOrders[atom.id] = {};
                this.decideSubstituentOrder(atom);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Decides the order of substituents around a stereo center.
     *
     * @param atomID {Number} - atom id of stereo center
     * @param atomCoords {Number} - coordinates of stereo center
     * @returns {Object} - orders of substituents as seen from the direction of
     * each such substituent, given a direction as either 'clockwise' or
     * 'counterclockwise'
     */
    decideSubstituentOrder({id: atomID, coordinates: atomCoords}) {
        const neighbors = this.atomsData.neighbors[atomID];
        const {down: neighborDown, up: neighborUp} = this.getStereoBondsInfoOfNeighbors(neighbors);
        if (neighborDown === undefined && neighborUp === undefined) {
            console.log('No stereo bonds given for atom:', atomID);
            return;
        }
        //when neighborUp exists always take this, SD might have special case
        const {neighborID: a, edgeID: aEdgeID} = neighborUp !== undefined ? neighborUp :
            neighborDown;
        const dir = neighborDown === undefined ? 'counterclockwise' : 'clockwise';
        const otherNeighbors = this.getPositionInfoOfOtherNeighbors(neighbors,
            atomCoords,
            a,
            aEdgeID
        );
        this.setSubstituentOrderForAtom(atomID, a, dir, otherNeighbors);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks how stereo-centers are represented by the drawer
     */
    getStereoBondsInfoOfNeighbors(neighbors) {
        const nrOfNeighbors = neighbors.length;
        let neighborDown, neighborUp;
        for (let i = 0; i < nrOfNeighbors; ++i) {
            const {neighbor: neighborID, edgeId: edgeID} = neighbors[i];
            const type = this.getEdge(edgeID).type;
            if (type === 'stereoFront' || type === 'stereoFrontReverse') {
                neighborUp = {
                    neighborID: neighborID, edgeID: edgeID
                }
            } else if (type === 'stereoBack' || type === 'stereoBackReverse') {
                neighborDown = {
                    neighborID: neighborID, edgeID: edgeID
                };

            }
            if (neighborDown && neighborUp) {
                break;
            }
        }
        return {down: neighborDown, up: neighborUp};
    }

    getPositionInfoOfOtherNeighbors(neighbors, atomCoords, a, aEdgeID) {
        const aCoords = this.atomsData.getAtom(a).coordinates;
        const otherNeighbors = [];
        neighbors.forEach(({neighbor: nextNeighborID, edgeId: nextEdgeID}) => {
            if (nextNeighborID === a) {
                return;
            }
            const nextCoords = this.atomsData.getAtom(nextNeighborID).coordinates;
            //side: -1 -> is on left side of line, 1 -> is on right side of line
            otherNeighbors.push({
                id: nextNeighborID,
                angle: this.angles[aEdgeID][nextEdgeID],
                side: LineCalculation.getSideOfLine(atomCoords, aCoords, nextCoords)
            });
        });
        return otherNeighbors;
    }

    setSubstituentOrderForAtom(atomID, a, dir, otherNeighbors) {
        const order = otherNeighbors.sort((a, b) => {
            if (a.side === -1) {
                if (b.side === 1) {
                    return -1;
                }
                return a.angle - b.angle;
            }
            if (b.side === -1) {
                return 1;
            }
            return b.angle - a.angle;
        }).map(obj => {
            return obj.id;
        });
        const b = order[0];
        const c = order[1];
        const d = order[2];
        if (d) {
            this.atomsData.stereoSubstituentOrders[atomID] = {
                direction: dir, orders: {
                    [a]: [b, c, d], [b]: [d, c, a], [c]: [b, d, a], [d]: [a, c, b]
                }
            };
        } else {
            this.atomsData.stereoSubstituentOrders[atomID] = {
                direction: dir, orders: {
                    [a]: [b, c], [b]: [c, a], [c]: [b, a]
                }
            };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * When selecting an edge, finds out whether neighboring edges are also
     * selected. Return ids of unselected atoms between given edge (by its id)
     * and such neighboring edges.
     *
     * @param edgeId {Number} - id of edge to be selected
     * @returns {Array} - ids of atoms to subsequently select
     */
    findAtomsToSelectOnEdgeSelect(edgeId) {
        const {from, to} = this.getEdge(edgeId);
        const selAtoms = this.atomsData.selectedAtoms;
        const selEdges = this.selectedEdges;
        const atomsToSelect = [];
        const checkForSelection = (atomId => {
            if (selAtoms.has(atomId)) {
                return;
            }
            const nbs = this.atomsData.neighbors[atomId];
            for (let i = 0, len = nbs.length; i < len; ++i) {
                const nbEdgeId = nbs[i].edgeId;
                if (nbEdgeId === edgeId) {
                    continue;
                }
                if (selEdges.has(nbEdgeId)) {
                    atomsToSelect.push(atomId);
                    return;
                }
            }
        });
        checkForSelection(from);
        checkForSelection(to);
        return atomsToSelect;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds ids of all atoms which are currently selected or part if selected
     * edges.
     *
     * @returns {Array} - affected atoms by their ids
     */
    getAtomsAffectedBySelection() {
        if (this.atomsData.selectedAtoms.size === this.atomsData.atoms.length) {
            return this.atomsData.atomIds.slice();
        }
        const edgeAffected = this.getAtomsByEdges([...this.selectedEdges], true);
        return [...new Set([...edgeAffected, ...this.atomsData.selectedAtoms])];
    }
}

/* src/Data/Structure/HydrophobicConnectionData.js */
/**
 * Stores data about all hydrophobic contacts (Spline objects) of one structure present in the
 * scene.
 */
class HydrophobicConnectionData {
    /**
     * Contains instances with data about hydrophobic contacts (Spline objects)
     * belonging to this structure.
     */
    constructor() {
        //Spline object ids
        this.hydrophobicConts = {};
        //links Atom object id -> hydrophobic contact ids -> control point ids
        this.atomControlPointConnections = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes that a hydrophobic contact (by id) belongs to this structure
     * and store the related Spline object.
     *
     * @param hydrophobicId {Number} - unique id of the spline
     * @param spline {Spline} - representation of the hydrophobic contact
     */
    addHydrophobicContact(hydrophobicId, spline) {
        this.hydrophobicConts[hydrophobicId] = spline;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes that a control point of a spline representing a hydrophobic
     * contact is linked to an atom of the structure (consequently, interaction
     * that affects the atom must also affect this control point).
     *
     * @param atomId {Number} - unique id of the atom to link to
     * @param hydrophobicId {Number} - unique id of the hydrophobic contact
     * @param controlPointId {Number} - unique id of the linked control point
     */
    linkAtomToSplineControlPoint(atomId, hydrophobicId, controlPointId) {
        if (!this.atomControlPointConnections.hasOwnProperty(atomId)) {
            this.atomControlPointConnections[atomId] = {};
        }
        const hLinks = this.atomControlPointConnections[atomId];
        if (!hLinks.hasOwnProperty(hydrophobicId)) {
            hLinks[hydrophobicId] = new Set();
        }
        hLinks[hydrophobicId].add(controlPointId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes linking of a control point of a spline representing a hydrophobic
     * contact to an atom of the structure.
     *
     * @param hydrophobicId {Number} - unique id of the hydrophobic contact
     */
    removeAtomToSplineControlPointLink(hydrophobicId) {
        for (const atomId of Object.keys(this.atomControlPointConnections)) {
            if (this.atomControlPointConnections[atomId]
                .hasOwnProperty(hydrophobicId)) {
                this.atomControlPointConnections[atomId][hydrophobicId] = new Set();
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the control point ids of all splines associated with this structure.
     *
     * @returns {Object} - control points for each spline
     */
    getSplineControlPointIds() {
        const controlPoints = {};
        for (const hydrophobicId in this.hydrophobicConts) {
            const spline = this.hydrophobicConts[hydrophobicId];
            controlPoints[hydrophobicId] = spline.getControlPointIds();
        }
        return controlPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the control point ids of all splines linked to given atom ids.
     *
     * @param atomArr {Array} - atom ids to find linked spline control points
     * for
     */
    getSplineControlPointIdsForAtoms(atomArr) {
        const controlPoints = {};
        for (const atomId of atomArr) {
            if (!this.atomControlPointConnections.hasOwnProperty(atomId)) {
                continue;
            }
            const hLinks = this.atomControlPointConnections[atomId];
            for (const hId in hLinks) {
                if (!controlPoints.hasOwnProperty(hId)) {
                    controlPoints[hId] = new Set();
                }
                Helpers.mergeIntoSet(controlPoints[hId], hLinks[hId]);
            }
        }
        return controlPoints;
    }
}

/* src/Data/Structure/IntermolecularConnectionData.js */
/**
 * Stores data about all intermolecular connections of one structure present in the scene.
 */
class IntermolecularConnectionData {
    /**
     * Contains instances with data rings and about intermolecular connections of this structure.
     *
     * @param ringsData {RingsData} - data about structure rings
     */
    constructor(ringsData) {
        this.ringsData = ringsData;
        // IntermolecularEdge object ids
        this.ids = {
            atomPairInteractions: new Set(),
            piStackings: new Set(),
            cationPiStackings: new Set(),
            distances: new Set(),
            interactions: new Set()
        };
        //Atom/Ring object id -> IntermolecularEdge object ids
        this.connections = {
            atomPairInteractions: {atom: {}},
            piStackings: {ring: {}},
            cationPiStackings: {atom: {}, ring: {}},
            distances: {annotation: {}},
            interactions: {annotation: {}}
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes that an intermolecular edge (by id and type) belongs to this
     * structure and note the start point such edge is connected to.
     *
     * @param fromID {Number} - start point (atom or ring) the intermolecular
     * edge is connected to
     * @param intermolecularID {Number} - id of intermolecular edge which is
     * connected to this structure
     * @param intermolecularType {String} - identifier of the intermolecular edge
     * @param fromType {String} - optional identifier of the connected object
     */
    addIntermolecularConnection(fromID, intermolecularID, intermolecularType, fromType) {
        this.ids[intermolecularType].add(intermolecularID);
        const connectionsOfType = this.connections[intermolecularType][fromType];
        if (!connectionsOfType.hasOwnProperty(fromID)) {
            connectionsOfType[fromID] = [];
        }
        connectionsOfType[fromID].push(intermolecularID);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given an array of atoms affected by an interaction (by their ids), finds
     * out which atom pair interactions must then be updated.
     *
     * @param atomArr {Array} - ids of atom affected by interaction
     * @param moveFreedomLevel {String} - freedom level defining the size of
     * units of the structure which can be moved at one. Either 'free',
     * 'rings', or 'structures'
     * @returns {Set} - ids of atom pair interactions that must be updated
     */
    getAtomPairInteractionsAffectedByAtoms(atomArr, moveFreedomLevel) {
        const affectedAtomPairInteractions = new Set();
        if (moveFreedomLevel === 'structures') {
            Object.values(this.connections.atomPairInteractions.atom)
                .forEach(atomPairInteractionArr => {
                    atomPairInteractionArr.forEach(atomPairInteractionId => {
                        affectedAtomPairInteractions.add(atomPairInteractionId);
                    });
                });
        } else {
            this.getAffectedIntermolecularForAtoms(affectedAtomPairInteractions,
                atomArr,
                'atomPairInteractions'
            );
        }
        return affectedAtomPairInteractions;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given information of which atoms of this structure are to be interacted
     * with and the ring systems these are contained in, finds out which pi-pi
     * stacking interactions must be updated.
     *
     * @param atomIds {Array} - ids of atom affected by interaction
     * @param affectedRingSystems {Array|Set} - ids of ring systems affected
     * by interaction (optional, can be given to speed up the process)
     * @returns {Set} - ids of pi-pi interactions that must be updated
     */
    getPiStackingsAffectedByAtoms(atomIds, affectedRingSystems) {
        const affectedPipi = new Set();
        this.getAffectedIntermolecularforRings(affectedPipi,
            atomIds,
            affectedRingSystems,
            'piStackings'
        );
        return affectedPipi;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given information of which atoms of this structure are to be interacted
     * with and the ring systems these are contained in, finds out which cation-
     * pi stacking interactions must be updated.
     *
     * @param atomIds {Array} - ids of atom affected by interaction
     * @param affectedRingSystems {Array|Set} - ids of ring systems affected
     * by interaction (optional, can be given to speed up the process)
     * @returns {Set} - ids of cation-pi interactions that must be updated
     */
    getCationPiStackingsAffectedByAtoms(atomIds, affectedRingSystems) {
        const affectedCationPi = new Set();
        this.getAffectedIntermolecularforRings(affectedCationPi,
            atomIds,
            affectedRingSystems,
            'cationPiStackings'
        );
        this.getAffectedIntermolecularForAtoms(affectedCationPi, atomIds, 'cationPiStackings');
        return affectedCationPi;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given information of which rings of this structure are to be interacted
     * with, finds out which intermolecular edges of a certain type must be updated.
     *
     * @param affectedIntermolecular {Array} - collects affected intermolecular edges of a certain
     *     type
     * @param atomIds {Array} - ids of atoms affected by interaction
     * @param affectedRingSystems {Array|Set} - ids of ring systems affected
     * by intermolecular edge (optional, can be given to speed up the process)
     * @param type {String} - type of intermolecular edge to check
     */
    getAffectedIntermolecularforRings(affectedIntermolecular, atomIds, affectedRingSystems, type) {
        if (!affectedRingSystems) {
            affectedRingSystems = this.ringsData.getRingSystemsAffectedByAtoms(atomIds);
        }
        const affectedRingIds = this.ringsData.getRingsInRingsystem(affectedRingSystems);
        const connectedRingsOfType = this.connections[type].ring;
        for (const ringId of affectedRingIds) {
            if (connectedRingsOfType.hasOwnProperty(ringId)) {
                connectedRingsOfType[ringId].forEach(stackingId => {
                    affectedIntermolecular.add(stackingId);
                });
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given information of which atoms of this structure are to be interacted
     * with, finds out which intermolecular edges of a certain type must be updated.
     *
     * @param affectedIntermolecular {Array} - collects affected intermolecular edges of a certain
     *     type
     * @param atomIds {Array} - ids of atoms affected by interaction
     * @param type {String} - type of intermolecular edge to check
     */
    getAffectedIntermolecularForAtoms(affectedIntermolecular, atomIds, type) {
        const connectedAtomsOfType = this.connections[type].atom;
        atomIds.forEach(atomId => {
            if (connectedAtomsOfType.hasOwnProperty(atomId)) {
                connectedAtomsOfType[atomId].forEach(id => {
                    affectedIntermolecular.add(id);
                });
            }
        });
    }
}


/* src/Data/Structure/RepresentationsData.js */
/**
 * Stores data about structure representations of one structure in the scene.
 */
class RepresentationsData {
    /**
     * Contains instances with data about structure representation data.
     */
    constructor(structureType) {
        this.representations = new Set([StructureRepresentation.default]);
        this.currentRepresentation = undefined;
        this.structureType = structureType;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes what representation belong to this structure.
     *
     * @param representations {Object} - allowed representations for this
     * drawer. It has the form of "structureType: [StructureRepresentation]"
     */
    addAlternativeRepresentations(representations) {
        const allowedRepresentations = representations[this.structureType] ||
            representations.default;
        for (const rep of allowedRepresentations) {
            this.representations.add(rep);
            if (rep === StructureRepresentation.circle) {
                this.structureCircle = {};
                this.selectedStructureCircle = false;
                this.tempSelectedStructureCircle = false;
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns whether the structure has a given representation.
     *
     * @param rep {StructureRepresentation} - name of representation
     */
    hasRepresentation(rep) {
        return this.representations.has(rep);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the current shown structure representation.
     */
    curRepresentation() {
        return this.currentRepresentation;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns whether the structures current representation is the
     * given representation.
     *
     * @param rep {StructureRepresentation} - name of representation
     */
    isCurRepresentation(rep) {
        return this.currentRepresentation === rep;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Change the representation of this structure to a given representation.
     * If a unknown representation is given change to default.
     *
     * @param representation {StructureRepresentation} - the representation
     * to display
     */
    changeInternalRepresentation(representation = StructureRepresentation.default) {
        if (representation === this.curRepresentation() ||
            !this.hasRepresentation(representation)) {
            return;
        }
        this.currentRepresentation = representation
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks structure circle as selected in internal selection set.
     */
    selectStructureCircle() {
        this.selectedStructureCircle = true;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks structure circle as selected in internal selection set, but only
     * for temporary means not to be committed into the drawer's history.
     */
    tempSelectStructureCircle() {
        this.tempSelectedStructureCircle = true;
    }
}

/* src/Data/Structure/RingsData.js */
/**
 * Stores data about all rings of one specific structure present in the scene.
 */
class RingsData {
    /**
     * Contains instances with data about atoms and edges of the structure.
     *
     * @param atomsData {AtomsData} - data about atoms of one structure in the scene
     * @param edgesData {EdgesData} - data about edges of one structure in the scene
     * @param spaceToRings {Number} - space between first bond of a bond and
     * the inner bond of a double bond for the created rings
     */
    constructor(atomsData, edgesData, spaceToRings) {
        this.atomsData = atomsData;
        this.edgesData = edgesData;
        this.spaceToRings = spaceToRings;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds rings data to a structure setting up further data containers.
     *
     * @param ringInfos {Array} - objects defining rings of the structure
     * @param ringSystemInfos {Array} - objects defining the ring system of
     * the structure (optional, otherwise found by DFS)
     */
    addRingInfo(ringInfos, ringSystemInfos) {
        //id of Ring object -> Ring object
        this.rings = {};
        this.aromaticRings = {};
        this.bccs = {};
        this.connectedComponents = [];

        //find connected and bi-connected components
        this.classifyBasedOnEdges();
        //get rings systems for rings movement, pi-stacking
        if (ringSystemInfos) {
            this.deduceRingSystemsFromInfo(ringSystemInfos);
        } else {
            this.deduceRingSystemsFromBCCs();
        }
        Object.keys(this.ringSystems).forEach(ringSystemId => {
            this.updateRingSystem(ringSystemId, false);
        });
        Object.values(this.ringSystems).forEach(({atoms: atomIds}) => {
            atomIds.forEach(atomId => {
                this.atomsData.getAtom(atomId).isInRing = true;
            });
        });
        //needs connected components from previous step + isInRing from atoms
        if (ringInfos) {
            this.createRings(ringInfos);
            this.setAromaticRings();
            this.decideRingsForDoubleBonds();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds a Ring object belonging to the structure by its id.
     *
     * @param ringId {Number} - id of Ring object to find
     * @returns {Ring} - Ring object with specified id
     */
    getRing(ringId) {
        return this.rings[ringId];
    }

    /*----------------------------------------------------------------------*/

    /**
     * From given ring system info, finds out which atoms and edges are part of
     * this ring systems and further which edges leaves this ring system to
     * other parts of the structure.
     *
     * @param ringSystemInfo {Object} - info on the ring systems of this
     * structure (ids and contained atoms)
     */
    deduceRingSystemsFromInfo(ringSystemInfo) {
        const ringSystems = {};
        const seenEdges = new Set();
        ringSystemInfo.forEach(({id: ringSysId, atoms: atomIds}) => {
            const edges = [];
            const outgoingEdges = [];
            const atomSet = new Set(atomIds);
            atomIds.forEach(atomId => {
                this.atomsData.getAtom(atomId).ringSystem = ringSysId;
                this.atomsData.neighbors[atomId].forEach(({edgeId}) => {
                    if (seenEdges.has(edgeId)) {
                        return;
                    }
                    const {from, to} = this.edgesData.getEdge(edgeId);
                    if (atomSet.has(from) && atomSet.has(to)) {
                        this.edgesData.getEdge(edgeId).ringSystem = ringSysId;
                        edges.push(edgeId);
                    } else {
                        outgoingEdges.push(edgeId);
                    }
                    seenEdges.add(edgeId);
                });
            });
            ringSystems[ringSysId] = {
                atoms: atomIds, edges: edges, outgoingEdges: outgoingEdges
            };
        });
        this.ringSystems = ringSystems;
    }

    /*----------------------------------------------------------------------*/

    /**
     * From calculated bccs, derives which atoms/edges are part of ring systems
     * and which edges leave such ring systems to other parts of the structure.
     */
    deduceRingSystemsFromBCCs() {
        const ringSystems = {};
        let ringSystemId = 1;
        for (const bccStr in this.bccs) {
            const bccId = parseInt(bccStr);
            const bcc = this.bccs[bccId];
            if (bcc.length <= 1) continue;
            const atoms = new Set();
            const edges = new Set();
            const outgoingEdges = new Set();
            const findOutgoing = (atomId) => {
                this.atomsData.neighbors[atomId].forEach(({edgeId}) => {
                    if (this.edgesData.getEdge(edgeId).bcc !== bccId) {
                        outgoingEdges.add(edgeId);
                    }
                });
            };
            bcc.forEach(edgeId => {
                const edge = this.edgesData.getEdge(edgeId);
                edge.ringSystem = ringSystemId;
                const {from, to} = edge;
                if (!atoms.has(from)) {
                    this.atomsData.getAtom(from).ringSystem = ringSystemId;
                    atoms.add(from);
                    findOutgoing(from)
                }
                if (!atoms.has(to)) {
                    this.atomsData.getAtom(to).ringSystem = ringSystemId;
                    atoms.add(to);
                    findOutgoing(to);
                }
                edges.add(edgeId);
            });
            ringSystems[ringSystemId] = {
                atoms: [...atoms], edges: [...edges], outgoingEdges: [...outgoingEdges]
            };
            ringSystemId++;
        }
        this.ringSystems = ringSystems;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates Ring objects for required ring information of this structure,
     * based on given ring info.
     *
     * @param ringInfos {Object} - object containing information on this
     * structure's rings (id, edges, and atoms), can be undefined
     */
    createRings(ringInfos) {
        const ringEdgesUnknown = new Set();
        //add ring information to atoms and edges
        ringInfos.forEach(({
            id: ringId, edges: ringEdges, atoms: ringAtoms
        }) => {
            if (ringEdges) {
                this.getRingFromInfo(ringId, ringEdges, ringAtoms);
            } else {
                if (ringAtoms) {
                    ringAtoms.forEach(atomId => {
                        this.atomsData.getAtom(atomId).addRing(ringId);
                    });
                }
                ringEdgesUnknown.add(ringId);
            }
        });
        if (ringEdgesUnknown.size) {
            this.findEdgesByDfs(ringEdgesUnknown)
        }
        for (const ringId in this.rings) {
            const ring = this.rings[ringId];
            ring.finalize(this); //immutable changes
            ring.update(); //mutable changes, gets called to fix representation
            if (ring.aromatic) {
                ring.atoms.forEach(atom => {
                    atom.addAromaticRing(ringId);
                });
                ring.edges.forEach(edge => {
                    edge.addAromaticRing(ringId);
                });
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a Ring object and adds ring information to atoms and edges.
     *
     * @param ringId {Number} - id of the ring
     * @param ringEdges {Array} - edge ids of edges of this ring
     * @param ringAtoms {Array} - atom ids of atoms of this ring
     */
    getRingFromInfo(ringId, ringEdges, ringAtoms) {
        const ring = new Ring(ringId, true, this.spaceToRings);
        ringEdges.forEach(edgeId => {
            const edge = this.edgesData.getEdge(edgeId);
            ring.addEdge(edge);
            edge.addRing(ringId);
        });
        if (!ringAtoms) {
            ringAtoms = this.edgesData.getAtomsByEdges(ringEdges);
        }
        ringAtoms.forEach(atomId => {
            const atom = this.atomsData.getAtom(atomId);
            atom.addRing(ringId);
            ring.aromatic = ring.aromatic && atom.aromatic;
        });
        this.rings[ringId] = ring;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For rings with only known atoms, finds edges by dfs.
     *
     * @param ringEdgesUnknown {Array} - ring ids of rings with unknown edges
     */
    findEdgesByDfs(ringEdgesUnknown) {
        const addEdgeToRings = (fromId, toId, edge) => {
            const fromAtom = this.atomsData.getAtom(fromId);
            const toAtom = this.atomsData.getAtom(toId);
            const sharedRings = [...fromAtom.rings].filter(ringId => {
                return toAtom.rings.has(ringId);
            });

            const aromatic = edge.aromatic;
            sharedRings.forEach(ringId => {
                if (!ringEdgesUnknown.has(ringId)) {
                    return;
                }
                let ring;
                if (!this.rings.hasOwnProperty(ringId)) {
                    ring = new Ring(ringId, aromatic, this.spaceToRings);
                    this.rings[ringId] = ring;
                } else {
                    ring = this.rings[ringId];
                    if (!aromatic) {
                        ring.setAromatic(false);
                    }
                }
                ring.addEdge(edge);
                edge.addRing(ringId);
            });
        };
        const structureVisitor = new StructureVisitor(this.atomsData, this.edgesData);
        //make sure to actually see all the edges
        structureVisitor.dfs({
            edgeCallback: addEdgeToRings, backEdgeCallback: addEdgeToRings
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * From created rings, transfers all aromatic rings into their own
     * container.
     */
    setAromaticRings() {
        for (const ringId in this.rings) {
            const ring = this.getRing(ringId);
            if (ring.aromatic) {
                this.aromaticRings[ringId] = ring;
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For all double bonds contained in this structure which are part of
     * rings, decides inside which ring the inner bond should be drawn, trying
     * to fill the same rings as much as possible.
     */
    decideRingsForDoubleBonds() {
        const offsetDoubles = [];
        this.edgesData.edges.forEach(edge => {
            if (edge.type === 'double') {
                const drawWithOffset = this.edgesData.decideDrawWithOffset(edge);
                edge.drawWithOffset = drawWithOffset;
                if (drawWithOffset) {
                    offsetDoubles.push(edge);
                }
            }
        });
        if (offsetDoubles.length) {
            const left = [];
            offsetDoubles.forEach(edge => {
                if (!edge.cyclic) { //decided by neighbor positions only
                    return;
                }
                const ringIds = edge.rings;
                if (ringIds.size === 1) {
                    const ringId = ringIds.values().next().value;
                    this.rings[ringId].doublePotential++;
                    edge.drawnInRing = ringId;
                } else {
                    left.push(edge);
                    edge.rings.forEach(ringId => {
                        this.rings[ringId].doublePotential++;
                    });
                }
            });
            left.forEach(edge => { //cyclic edges with undecided ring
                let best = -Infinity, inRing = undefined, bestRingLen = Infinity;
                edge.rings.forEach(ringId => {
                    const ring = this.rings[ringId];
                    if (ring.length > 6 && bestRingLen <= 6) {
                        return;
                    }
                    const nrDoubles = ring.doublePotential;
                    if (nrDoubles > best) {
                        best = nrDoubles;
                        inRing = ringId;
                        bestRingLen = ring.length;
                    }
                });
                edge.drawnInRing = inRing;
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * By DFS, finds bccs and connected components of this structure and marks
     * bonds as cyclic or not.
     */
    classifyBasedOnEdges() {
        const d = {}, low = {};
        this.atomsData.atoms.forEach(({id: atomId}) => {
            d[atomId] = 0;
            low[atomId] = 0;
        });
        const bccs = this.bccs;
        const connectedComponents = this.connectedComponents;

        let curBcc = 1, time = 0, curEdges = [], connectedComponent, curCc = 0;
        const dfsVisit = (atomId, parentId) => {
            time++;
            d[atomId] = time;
            low[atomId] = time;
            const atom = this.atomsData.getAtom(atomId);
            connectedComponent.atoms.push(atomId);
            atom.connectedComponent = curCc;
            this.atomsData.neighbors[atomId].forEach(({neighbor: nbId, edgeId}) => {
                if (d[nbId] === 0) {
                    connectedComponent.edges.push(edgeId);
                    curEdges.push(edgeId);
                    dfsVisit(nbId, atomId);
                    low[atomId] = Math.min(low[atomId], low[nbId]);
                    if (low[nbId] >= d[atomId]) {
                        let addEdgeId, bcc = [];
                        do {
                            addEdgeId = curEdges.pop();
                            this.edgesData.getEdge(addEdgeId).bcc = curBcc;
                            bcc.push(addEdgeId);
                        } while (addEdgeId !== edgeId);
                        bccs[curBcc] = bcc;
                        curBcc++;
                        //stricter criterion for finding acyclic edges
                        if (low[nbId] > d[atomId]) {
                            this.edgesData.getEdgeByAtomIds(atomId, nbId).cyclic = false;
                        }
                    }
                } else if (parentId && parentId !== nbId && d[nbId] < d[atomId]) {
                    connectedComponent.edges.push(edgeId);
                    curEdges.push(edgeId);
                    low[atomId] = Math.min(low[atomId], d[nbId]);
                }
            });
        };
        this.atomsData.atoms.forEach(({id: atomId}) => {
            if (connectedComponent && connectedComponent.atoms.length > 0) {
                connectedComponents.push(connectedComponent);
                curCc++;
            }
            connectedComponent = {
                atoms: [], edges: []
            };
            if (d[atomId] === 0) {
                dfsVisit(atomId);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates ring systems (i.e., their centers) based on new coordinates of
     * atoms within such systems. Also update all rings which are part
     * of the ring systems.
     *
     * @param ringSystemId {Number} - ring system to update
     * @param byTemp {Boolean} - whether to use temporary or non-temporary
     * coordinates of contained atoms for the update
     */
    updateRingSystem(ringSystemId, byTemp = false) {
        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
        const ringSystem = this.ringSystems[ringSystemId];
        const convexHull = PointCalculation.findConvexHull(ringSystem.atoms.map(atomId => {
            return this.atomsData.getAtom(atomId)[coordParam];
        }));
        const newCenter = PolygonCalculation.findCenterOfConvexPolygon(convexHull).centroid;
        this.setRingSystemCenter(ringSystemId, newCenter, byTemp);
        for (const ring of Object.values(this.rings)) {
            if (ring.ringSystem == ringSystemId) {
                ring.update(byTemp);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Directly sets the center information of a ring system to new coordinates.
     *
     * @param ringSystemId {Number} - ring system to update
     * @param newCenter {Object} - x- and y-coordinates of the new center
     * @param byTemp {Boolean} - whether to update only temporary center
     * information
     */
    setRingSystemCenter(ringSystemId, newCenter, byTemp = false) {
        const ringSystem = this.ringSystems[ringSystemId];
        ringSystem.tempCenter = newCenter;
        if (!byTemp) {
            ringSystem.center = newCenter;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds all rings which are in a given set of ring systems.
     *
     * @param ringSystemsIds {Array|Set} - ids of ring systems
     * @returns {Array} - ids of rings in given ring systems
     */
    getRingsInRingsystem(ringSystemsIds) {
        const ringIds = [];
        for (const [ringId, ring] of Object.entries(this.rings)) {
            ringSystemsIds.forEach(ringSysId => {
                if (ring.ringSystem === parseInt(ringSysId)) {
                    ringIds.push(ringId)
                }
            });
        }
        return ringIds;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns the id of the ring system containing all of the given atoms.
     *
     * @param atoms {Array} - array of Atom objects
     * @return {Number} - id of found ring system or undefined
     */
    getRingSystemMembership(atoms) {
        let ringSysId = undefined;
        for (const [sysId, sys] of Object.entries(this.ringSystems)) {
            if (Object.values(atoms).every(atom => sys.atoms.includes(atom.id))) {
                ringSysId = parseInt(sysId);
                break;
            }
        }
        return ringSysId;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given any number of atoms by their ids, finds ids of all the rings these
     * atoms are a part of.
     *
     * @param atomIds {Set|Array} - atom ids of which to get shared rings
     * @param aromatic {Boolean} - if this flag is set, only return shared
     * aromatic rings
     * @returns {Array} - shared ring ids
     */
    getRingsAffectedByAtoms(atomIds, aromatic) {
        if (Array.isArray(atomIds)) {
            atomIds = new Set(atomIds);
        }
        const ringsToCheck = aromatic ? this.aromaticRings : this.rings;
        const affectedRings = [];

        for (const ringId in ringsToCheck) {
            const ringAtoms = ringsToCheck[ringId].atoms;
            if (ringAtoms.some(ringAtom => {
                return atomIds.has(ringAtom.id);
            })) {
                affectedRings.push(ringId);
            }
        }

        return affectedRings;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given any number of atoms by their ids, finds ids of all the ring
     * systems these atoms are a part of.
     *
     * @param atomIds {Array} - atom ids of which to get shared rings
     * @returns {Set} - shared ring system ids
     */
    getRingSystemsAffectedByAtoms(atomIds) {
        return new Set(Object.keys(this.ringSystems)
            .filter(ringSysId => {
                const ringSysAtoms = new Set(this.ringSystems[ringSysId].atoms);
                return atomIds.some(atomId => {
                    return ringSysAtoms.has(atomId);
                });
            }));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Given any number of edges by their ids, finds ids of all the ring
     * systems these edges are a part of.
     *
     * @param edges {Array} - edge of which to get shared rings
     * @returns {Set} - shared ring system ids
     */
    getRingSystemsAffectedByEdges(edges) {
        return new Set(Object.keys(this.ringSystems)
            .filter(ringSysId => {
                const ringSysEdges = new Set(this.ringSystems[ringSysId].edges);
                return edges.some(edge => {
                    return ringSysEdges.has(edge.edgeId);
                });
            }));
    }
}

/* src/Data/Structure/StructuresData.js */
/**
 * Stores structural data about all structures present in the scene.
 */
class StructuresData {
    /**
     * Contains objects to store Structure objects and to set/query data of those.
     */
    constructor() {
        //id of Structure object -> Structure object
        this.structures = {};
        this.originalStructures = {};
        //id of Atom object -> Structure object id
        this.atomIdsToStructure = {};
        this.structureLoaded = false;
        //Structure object ids
        this.structuresInUse = new Set();
        //History step nr. -> added Structure ids
        this.addTimesToStructure = {}; //to clear memory appropriately
        //Structure object id -> Structure object id -> intermolecular ids
        this.intermolecularConnections = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves ids of atoms and bonds of the structure with a specified id.
     *
     * @param structureId {Number} - the unique id of a structure currently
     * present in the scene
     * @returns {Object} - ids of atoms (field 'atoms') and bonds (field
     * 'edges') of the structure in form of Arrays | null for bad requests
     */
    getIdsForStructure(structureId) {
        const structure = this.structures[structureId];
        if (!structure) {
            return null;
        }
        return {
            atoms: structure.atomsData.atoms.map(atom => atom.id),
            edges: structure.edgesData.edges.map(edge => edge.id)
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns all ids of currently hidden structures.
     *
     * @return {Array} - hidden structure ids
     */
    getHiddenStructures() {
        const ids = [];
        for (const structure of Object.values(this.structures)) {
            if (structure.hidden) ids.push(structure.id);
        }
        return ids;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if structure with given id contains edges and atoms by ids.
     *
     * @param atoms {Array} - ids of atoms
     * @param edges {Array} - ids of edges
     * @param structureId {Number} - id of structure
     * @returns {Boolean} - true if all atom/edge ids belong to the given structure
     */
    structureHasElements(atoms, edges, structureId) {
        const elementsIDs = this.getIdsForStructure(structureId);
        let hasElements = true;
        atoms && atoms.forEach((atomSelection) => {
            if (!atomSelection || !elementsIDs["atoms"].includes(atomSelection.id)) {
                hasElements = false;
            }
        });
        edges && edges.forEach((edgeSelection) => {
            if (!edgeSelection || !elementsIDs["edges"].includes(edgeSelection.id)) {
                hasElements = false;
            }
        });
        return hasElements;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns all structure ids and their names that are currently loaded.
     *
     * @returns {Array} - array of objects with key "id" and key "name"
     */
    getStructures() {
        return Object.values(this.structures).map((structure) => {
            return {
                id: structure.id,
                name: structure.structureName,
                enabled: structure.enabled,
                hidden: structure.hidden
            }
        })
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns all additional information of atoms and structures
     *
     * @param onlySelected {Boolean} - if true returns only information of
     * currently selected elements. If the current representation of a structure
     * is circle then all atoms are considered selected
     * @returns {Object} - contains keys "structures", and "atoms" which
     * hold an array containing objects which hold all "additionalInformation",
     * the "structureId", and, for atoms, the "atomId".
     */
    getAdditionalInformation(onlySelected = false) {
        const info = {
            structures: [], atoms: [], edges: []
        };
        for (const structure of Object.values(this.structures)) {
            const atomInfo = structure.atomsData.atoms
                .filter(atom => atom.additionalInformation &&
                       (!onlySelected || structure.atomsData.selectedAtoms.has(atom.id) ||
                        structure.representationsData.selectedStructureCircle))
                .map(atom => {
                    return {
                        additionalInformation: atom.additionalInformation,
                        atomId: atom.id,
                        structureId: structure.id
                    }
                });
            info.atoms.push(...atomInfo);
            const edgeInfo = structure.edgesData.edges
                .filter(edge =>
                    (!onlySelected || structure.edgesData.selectedEdges.has(edge.id) ||
                        structure.representationsData.selectedStructureCircle))
                .map(edge => {
                    return {
                        edgeId: edge.id,
                        fromId: edge.from,
                        toId: edge.to,
                        structureId: structure.id
                    }
                });
            info.edges.push(...edgeInfo);
            if ((!onlySelected || structure.representationsData.selectedStructureCircle ||
                structure.edgesData.selectedEdges.size > 0 ||
                structure.atomsData.selectedAtoms.size > 0) && structure.additionalInformation) {
                info.structures.push({
                    additionalInformation: structure.additionalInformation,
                    structureId: structure.id
                });
            }
        }
        return info;
    }
}

/* src/DataProcessing/ChangeMapCreater.js */
/**
 * Collects from structural data new positions of draw objects based on movement operations.
 */
class ChangeMapCreater {
    /**
     * Contains instances for the data storage/access and user interaction tracking.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param interactionState {Object} - tracks user interactions
     */
    constructor(opts, sceneData, interactionState) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.interactionState = interactionState;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulates new positions of annotations of given Ids based on a mirror
     * operation on a given line (defined by two points).
     *
     * @param annotationIds {Array} - array of annotation ids
     * @param first {Object} - x- and y-coordinates of the first point on the
     * mirror line
     * @param second {Object} - x- and y-coordinates of the second point on the
     * mirror line
     * @param map {Object} - map of all changes to apply to next history step
     * @param interactionMode {InteractionMode} - interaction mode that was
     * performed
     * @param onlyUpdateStrucInfo {Boolean} - whether only the information
     * to update the structureRepresentationInfo should be included
     */
    createAnnotationMirrorMap(annotationIds,
        first,
        second,
        map,
        interactionMode,
        onlyUpdateStrucInfo = false
    ) {
        if (!map.hasOwnProperty('annotationCoordinateChanges')) {
            map.annotationCoordinateChanges = {};
        }
        const updateMap = map.annotationCoordinateChanges;
        const annotationCoords = annotationIds.map(annotationId => {
            return this.sceneData.annotationsData.annotations[annotationId].coordinates;
        });
        const newCoords = onlyUpdateStrucInfo ? undefined :
            LineCalculation.mirrorPointsOnLine(annotationCoords, first, second);
        annotationIds.forEach((annotationId, i) => {
            updateMap[annotationId] = {
                newCoords: newCoords && newCoords[i], interactionMode: interactionMode
            };
            const annotation = this.sceneData.annotationsData.annotations[annotationId];
            if (annotation &&
                this.sceneData.structuresData.structures.hasOwnProperty(annotation.structureLink)) {
                updateMap[annotationId].oldStructureMid = Object.assign({},
                    this.sceneData.structuresData.structures[annotation.structureLink].boundaries.mid
                );
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Performs a mirror operation on given atoms based on a mirror line defined
     * by two given points. Afterwards, apply new coordinates to history.
     *
     * @param atomsToMirror {Object} - map from structure Ids to Arrays of
     * atom signalling the atoms to mirror
     * @param first {Object} - x- and y-coordinates of the first line point
     * @param second {Object} - x- and y-coordinates of the second line point
     * @param map {Object} - collects coordinate changes
     */
    createAtomMirrorMap(atomsToMirror, first, second, map) {
        if (!map.hasOwnProperty('coordinateChanges')) {
            map.coordinateChanges = {};
        }
        const coordChanges = map.coordinateChanges;
        for (const structureId in atomsToMirror) {
            const atoms = atomsToMirror[structureId];
            //mirror atoms and build map for changes
            const mirroredAtoms = LineCalculation.mirrorPointsOnLine(atoms.map(atom => atom.coordinates),
                first,
                second
            );
            const atomChanges = {};
            atoms.forEach(({id: atomId}, idx) => {
                atomChanges[atomId] = mirroredAtoms[idx];
            });
            coordChanges[structureId] = {
                newCoordinates: atomChanges, isFlip: true
            };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulates new positions of specified spline control points based on a
     * mirror operation on a given line (defined by two points).
     *
     * @param controlPoints {Object} - the control points (by structure Id and
     * spline Id) to mirror
     * @param first {Object} - x- and y-coordinates of the first point on the
     * mirror line
     * @param second {Object} - x- and y-coordinates of the second point on the
     * mirror line
     * @param map {Object} - map of all changes to apply to next history step
     */
    createSplineControlPointMirrorMap(controlPoints, first, second, map) {
        if (!map.hasOwnProperty('splineCoordinateChanges')) {
            map.splineCoordinateChanges = {};
        }
        const splineChanges = map.splineCoordinateChanges;
        for (const splineId in controlPoints) {
            const cpChanges = {};
            const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
            const cpIds = [...controlPoints[splineId]];
            const cpCoords = cpIds.sort().map(cpId => {
                return spline.getControlPoint(cpId, false);
            });
            const newCpCoords = LineCalculation.mirrorPointsOnLine(cpCoords, first, second);
            cpIds.forEach((cpId, i) => {
                cpChanges[cpId] = newCpCoords[i];
            });
            splineChanges[splineId] = cpChanges;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulates new positions of specified spline control points into a
     * change map which can be fed into this.applySceneChanges().
     *
     * @param controlPoints {Object} - the control points (by structure Id and
     * spline Id) to update
     * @param changeMap {Object} - map of all changes to apply to next history
     * step
     */
    createSplineControlPointUpdateMap(controlPoints, changeMap) {
        const splineChanges = {};
        for (const splineId in controlPoints) {
            const cpChanges = {};
            const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
            controlPoints[splineId].forEach(cpId => {
                cpChanges[cpId] = spline.getControlPoint(cpId, true);
            });
            splineChanges[splineId] = cpChanges;
        }
        changeMap.splineCoordinateChanges = splineChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulates new positions of annotations of given Ids into a change map
     * which can be fed into this.applySceneChanges().
     *
     * @param annotationIds {Set} - ids of annotations to update
     * @param structureIds {Array} - ids of all structures that were updated
     * in this step
     * @param changeMap {Object} - map of all changes to apply to next history
     * step
     * @param interactionMode {InteractionMode} - mode of the corresponding
     * interaction
     */
    createAnnotationUpdateMap(annotationIds, structureIds, changeMap, interactionMode) {
        const annotationChanges = {};
        annotationIds.forEach(annotationId => {
            const annotation = this.sceneData.annotationsData.annotations[annotationId];
            const structureLink = annotation.structureLink;
            annotationChanges[annotationId] = {
                newCoords: annotation.tempCoordinates,
                structureMoved: structureIds.includes(structureLink),
                interactionMode: interactionMode
            };
            if (!this.sceneData.structuresData.structures.hasOwnProperty(structureLink)) {
                return;
            }
            const structure = this.sceneData.structuresData.structures[structureLink];
            annotationChanges[annotationId].oldStructureMid =
                Object.assign({}, structure.boundaries.mid);
            if (interactionMode !== InteractionMode.rotation ||
                Object.keys(annotation.structureRepresentationInfo).length <= 1) {
                return;
            }
            const repInfo = annotation.structureRepresentationInfo;
            const fullAngle = this.interactionState.interaction.rotation.curRotation;
            const sceneRotation = this.interactionState.interaction.rotation.type === 'fullScene';
            if (structure.representationsData.isCurRepresentation(StructureRepresentation.default) &&
                sceneRotation) {
                const offset = structure.calcStructureCircleRotationOffset(fullAngle,
                    true,
                    this.interactionState.getRealCoordinates(this.sceneData.midCoords),
                    false
                );
                annotationChanges[annotationId].oldAltRotCoords =
                    Object.assign({}, repInfo[StructureRepresentation.circle].coordinates);
                annotationChanges[annotationId].newAltRotCoords = VectorCalculation.vectorAdd(
                    repInfo[StructureRepresentation.circle].coordinates,
                    offset
                );
            } else if (structure
                .representationsData.isCurRepresentation(StructureRepresentation.circle)) {
                const mid = sceneRotation ?
                    this.interactionState.getRealCoordinates(this.sceneData.midCoords) :
                    structure.boundaries.mid;
                annotationChanges[annotationId].oldAltRotCoords =
                    Object.assign({}, repInfo[StructureRepresentation.default].coordinates);
                annotationChanges[annotationId].newAltRotCoords =
                    PointCalculation.rotatePointAroundAnother(repInfo[StructureRepresentation.default].coordinates,
                        mid,
                        fullAngle,
                        false
                    );
            }
        });
        changeMap.annotationCoordinateChanges = annotationChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a map to be used in this.applySceneChanges() to set (real) coordinates
     * of all atoms of structures specified by Id to previously updated
     * temporary coordinates. These changes are then written into a provided
     * map to be used in the larger update.
     *
     * @param structureIds {Array} - ids of structures to update all atoms for
     * @param map {Object} - map to write changes to apply into
     */
    createTempCoordinateUpdateMapForFullStructures(structureIds, map) {
        const atomsToUpdate = {};
        structureIds.forEach(structureId => {
            const structure = this.sceneData.structuresData.structures[structureId];
            atomsToUpdate[structureId] = structure.atomsData.atomIds;
        });
        this.createTempCoordinateUpdateMap(atomsToUpdate, map);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a map to be used in this.applySceneChanges() to set (real) coordinates
     * of given atoms to previously updated temporary coordinates. These
     * changes are then written into a provided map to be used in the larger
     * update.
     *
     * @param atomsToUpdate {Object} - which atoms to update (structure Ids
     * to Arrays)
     * @param map {Object} - map to write changes to apply into
     */
    createTempCoordinateUpdateMap(atomsToUpdate, map) {
        if (!map.hasOwnProperty('coordinateChanges')) {
            map.coordinateChanges = {};
        }
        const coordChanges = map.coordinateChanges;
        for (const structureId in atomsToUpdate) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const structChanges = {};
            atomsToUpdate[structureId].forEach(atomId => {
                const atom = structure.atomsData.getAtom(atomId);
                structChanges[atomId] = atom.tempCoordinates;
            });
            coordChanges[structureId] = {
                newCoordinates: structChanges, isFlip: false
            };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Undoes translations applied to SVG groups representing structures which
     * were moved in full and apply offsets to temporary atom coordinates.
     */
    createFullStructureUpdateMap(map) {
        if (!map.hasOwnProperty('coordinateChanges')) {
            map.coordinateChanges = {};
        }
        const coordChanges = map.coordinateChanges;
        for (const structureId of this.interactionState.interaction.movement.fullStructures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const curOffset = structure.curOffset;
            structure.resetCurOffset();
            const structChanges = {};
            structure.atomsData.atoms.forEach(atom => {
                structChanges[atom.id] = {
                    x: atom.tempCoordinates.x + curOffset.x,
                    y: atom.tempCoordinates.y + curOffset.y
                }
            });
            coordChanges[structureId] = {
                newCoordinates: structChanges, isFlip: false
            };
        }
    }
}

/* src/DataProcessing/ClosestObjectFinder.js */
/**
 * Searches structural data for the closest draw object of a certain type to a given point.
 */
class ClosestObjectFinder {
    /**
     * Contains instance for the data storage/access and configuration options.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     */
    constructor(opts, sceneData) {
        this.opts = opts;
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the closest structure (by its geometric center) that is enabled and
     * is not hidden to a given point.
     *
     * @param coords {Object} - contains x- and y-coordinates of point
     * @param structureIds {Array} - optional. Limit the search to structures
     * with this ids only
     * @param structureCircleHandling {Boolean} - how to determine the nearest
     * structure. If a structure is represented as structure circle and this is
     * set to true, then the closest point of the edge of the circle will be
     * taken as coords of that structure instead of the geometric center
     * @return {Object} - contains the Structure object or undefined as value of
     * key 'structure' and the x- and y-coordinates of the closest structure
     * (either geometric center or point on edge of structure circle) as
     * key 'closestCoords'
     */
    getClosestEnabledStructure(coords, structureIds = undefined, structureCircleHandling = false) {
        structureIds =
            (structureIds || Object.keys(this.sceneData.structuresData.structures)).map(Number);
        const structures = Object.values(this.sceneData.structuresData.structures)
            .filter(structure => structure.enabled && !structure.hidden &&
                structureIds.includes(structure.id) &&
                (!structureCircleHandling || structure.representationsData.curRepresentation() !==
                    StructureRepresentation.circle));
        const closestNonCircle = structures[PointCalculation.getClosestPoint(coords,
            structures.map(structure => structure.boundaries.mid)
        ).id];
        const closestNonCircleObj = {
            structure: closestNonCircle,
            closestCoords: closestNonCircle ? closestNonCircle.boundaries.mid : undefined
        };

        if (!structureCircleHandling) {
            return closestNonCircleObj;
        } else {
            const circleStructures = Object.values(this.sceneData.structuresData.structures)
                .filter(structure => structure.enabled && !structure.hidden &&
                    structureIds.includes(structure.id) &&
                    structure.representationsData.isCurRepresentation(StructureRepresentation.circle))
                .map(structure => {
                    return {
                        structure: structure,
                        closestCoords: PointCalculation.movePointTowardsAnother(structure.boundaries.mid,
                            coords,
                            structure.representationsData.structureCircle.rad
                        )
                    }
                });
            const closestCircleObj = circleStructures[PointCalculation.getClosestPoint(coords,
                circleStructures.map(val => val.closestCoords)
            ).id];

            if (!closestCircleObj) {
                return closestNonCircleObj;
            } else if (!closestNonCircleObj.structure) {
                return closestCircleObj;
            } else if (0 === PointCalculation.getClosestPoint(coords, [
                closestNonCircleObj.closestCoords, closestCircleObj.closestCoords
            ]).id) {
                return closestNonCircleObj;
            } else {
                return closestCircleObj;
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the closest atom that is enabled and which structure is not hidden
     * to a given point.
     *
     * @param coords {Object} - contains x- and y-coordinates of point
     * @param structureIds {Array} - optional. Limit the search to structures
     * with this ids only
     * @param structureCircleHandling {Number} - how to determine the nearest
     * atom. If a structure is represented as structure circle and this is set to
     * 1, then the mid of the circle will be taken as atom coords of that
     * structure. If this is set to 2 then the actual coordinates of all atoms are
     * taken. If this is set to 3 atoms of structures which are currently
     * represented as circles will not be included in the search
     * @return {Object} - Atom object or undefined
     */
    getClosestEnabledAtom(coords, structureIds = undefined, structureCircleHandling = 2) {
        structureIds =
            (structureIds || Object.keys(this.sceneData.structuresData.structures)).map(Number);
        const atoms = [];
        Object.values(this.sceneData.structuresData.structures)
            .filter(structure => structure.enabled && !structure.hidden &&
                structureIds.includes(structure.id) && (structureCircleHandling === 2 ||
                    structure.representationsData.curRepresentation() !==
                    StructureRepresentation.circle))
            .map(structure => Object.values(structure.atomsData.atoms))
            .forEach(structureAtoms => {
                atoms.push(...structureAtoms);
            });
        atoms.filter(atom => atom.enabled);
        const closestAtom = atoms[PointCalculation
            .getClosestPoint(coords, atoms.map(atom => atom.coordinates)).id];

        if (structureCircleHandling === 2 || structureCircleHandling === 3) {
            return closestAtom;
        } else {
            const closestStructureObj = this.getClosestEnabledStructure(coords,
                Object.values(this.sceneData.structuresData.structures)
                    .filter(structure => structure.enabled && !structure.hidden &&
                        structureIds.includes(structure.id) &&
                        structure.representationsData.isCurRepresentation(StructureRepresentation.circle))
                    .map(structure => structure.id),
                true
            );

            if (!closestStructureObj.structure) {
                return closestAtom;
            } else if (!closestAtom) {
                return this.getClosestEnabledAtom(coords, [closestStructureObj.structure.id]);
            } else if (0 === PointCalculation.getClosestPoint(coords,
                [closestAtom.coordinates, closestStructureObj.closestCoords]
            ).id) {
                return closestAtom;
            } else {
                return this.getClosestEnabledAtom(coords, [closestStructureObj.structure.id]);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the ring that is enabled and which structure is not hidden,
     * which center is closest to a given point.
     *
     * @param coords {Object} - contains x- and y-coordinates of point
     * @param structureIds {Array} - optional. Limit the search to structures
     * with this ids only
     * @param structureCircleHandling {Boolean} - how to determine the nearest
     * ring. If a structure is represented as structure circle and this is set to
     * true, then the mid of the circle will be taken as ring coords of that
     * structure if the structure has at least one ring
     * @return {Object} - Ring object or undefined
     */
    getClosestEnabledRing(coords, structureIds = undefined, structureCircleHandling = false) {
        structureIds =
            (structureIds || Object.keys(this.sceneData.structuresData.structures)).map(Number);
        const rings = [];
        Object.values(this.sceneData.structuresData.structures)
            .filter(structure => structure.enabled && !structure.hidden &&
                structureIds.includes(structure.id) &&
                (!structureCircleHandling || structure.representationsData.curRepresentation() !==
                    StructureRepresentation.circle))
            .map(structure => Object.values(structure.ringsData.rings))
            .forEach(structureRings => {
                rings.push(...structureRings);
            });
        rings.filter(ring => {
            return Object.values(ring.atoms)
                .filter(atom => atom.enabled).length !== 0;
        });

        const closestRing = rings[PointCalculation.getClosestPoint(coords,
            rings.map(ring => ring.centroidInfo.centroid)
        ).id];

        if (!structureCircleHandling) {
            return closestRing;
        } else {
            const closestStructureObj = this.getClosestEnabledStructure(coords,
                Object.values(this.sceneData.structuresData.structures)
                    .filter(structure => structure.enabled && !structure.hidden &&
                        structureIds.includes(structure.id) &&
                        structure.representationsData.isCurRepresentation(StructureRepresentation.circle) &&
                        Object.keys(structure.ringsData.rings).length !== 0)
                    .map(structure => structure.id),
                true
            );

            if (!closestStructureObj.structure) {
                return closestRing;
            } else if (!closestRing) {
                return this.getClosestEnabledRing(coords, [closestStructureObj.structure.id]);
            } else if (0 === PointCalculation.getClosestPoint(coords, [
                closestRing.centroidInfo.centroid, closestStructureObj.closestCoords
            ]).id) {
                return closestRing;
            } else {
                return this.getClosestEnabledRing(coords, [closestStructureObj.structure.id]);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the control point that is enabled and not hidden of hydrophobic
     * contact which is closest to a given point and which linked structures
     * current representation is not circle.
     *
     * @param coords {Object} - contains x- and y-coordinates of point
     * @param endpointsOnly {Boolean} - limits the search to the endpoints of
     * the splines only
     * @param structureIds {Array} - optional. Limit the search to structures
     * with this ids only
     * @return {Object} - undefined or object containing 'hydrophobicContactId',
     * 'controlPointId' and the 'controlPoint'
     */
    getClosestEnabledSplineControlPoint(coords, endpointsOnly = false, structureIds = undefined) {
        structureIds =
            (structureIds || Object.keys(this.sceneData.structuresData.structures)).map(Number);
        const controlPoints = [];
        for (const [hydroId, hydroContact] of
            Object.entries(this.sceneData.hydrophobicData.hydrophobicContacts)) {
            const structureLink = hydroContact.structureLink;
            if (!hydroContact.enabled || hydroContact.hidden ||
                !structureIds.includes(structureLink) ||
                this.sceneData.structuresData.structures[structureLink]
                    .representationsData.isCurRepresentation(StructureRepresentation.circle)) {
                continue;
            }

            const points = [];
            hydroContact.controlPoints.forEach((cp, idx) => {
                if (!cp.enabled) {
                    return;
                }

                points.push({
                    hydrophobicContactId: hydroId, controlPointId: idx, controlPoint: cp
                });
            });
            if (endpointsOnly) {
                const pointsLength = points.length;
                switch (pointsLength) {
                    case 0:
                        break;
                    case 1:
                        controlPoints.push(points[0]);
                        break;
                    default:
                        controlPoints.push(points[0]);
                        controlPoints.push(points[pointsLength - 1]);
                }
            } else {
                controlPoints.push(...points);
            }
        }
        return controlPoints[PointCalculation.getClosestPoint(coords,
            controlPoints.map(points => points.controlPoint)
        ).id];
    }
}

/* src/DataProcessing/CollisionFinder.js */
/**
 * Searches structural data for the colliding draw object of a certain type to a given point or
 * polygon.
 */
class CollisionFinder {
    /**
     * Contains instance for the data storage/access and configuration options.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     */
    constructor(opts, sceneData) {
        this.opts = opts;
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a given polygon or point, checks annotations for collision and report
     * the such found collision (if any is found). The lastly added annotation is
     * always returned based on Id for the case that different annotations are
     * located on top of each other.
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {null|Object} - null if no collision is found, else the lastly added
     * hit (logging Id of annotation as field "label")
     */
    findLastCollisionAnnotation(polyVertices) {
        if (polyVertices.length === 0) {
            return null;
        }
        const {circleTest, polyTest} = this.createCollisionChecksForPoints(polyVertices);
        const annotations = this.sceneData.annotationsData.annotations;
        const labelIds = Object.keys(annotations).reverse();
        for (const labelId of labelIds) {
            const annotation = this.sceneData.annotationsData.annotations[labelId];
            const displayed = !annotation.isStructureLabel ||
                !this.sceneData.structuresData.structures.hasOwnProperty(annotation.structureLink) ||
                !this.sceneData.structuresData.structures[annotation.structureLink].representationsData.isCurRepresentation(
                    StructureRepresentation.circle);
            if (!annotation.hidden && annotation.enabled && displayed) {
                if (annotation.testHitFunctionsForSelection({
                    circleHitFunction: circleTest, rectHitFunction: polyTest
                })) {
                    if (this.opts.geomineMode && (!annotation.additionalInformation ||
                        !annotation.additionalInformation.nglFeatureType ||
                        annotation.additionalInformation.nglFeatureType === 'surface')) {
                        return null;
                    }
                    return {
                        type: 'annotation',
                        id: parseInt(labelId),
                        structureLink: parseInt(annotation.structureLink),
                        additionalInformation: annotation.additionalInformation
                    };
                }
            }
        }
        return null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a given polygon or point, checks spline control points for collision
     * and report the first such found collision (if any is found).
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {null|Object} - null if no collision is found, else the first
     * hit (logging structureId, id of spline, and control point id)
     */
    findFirstCollisionSplines(polyVertices) {
        if (this.opts.geomineMode || polyVertices.length === 0) {
            return null;
        }
        const {circleTest} = this.createCollisionChecksForPoints(polyVertices);

        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            for (const hIdx in structure.hydrophobicConnectionData.hydrophobicConts) {
                const spline = structure.hydrophobicConnectionData.hydrophobicConts[hIdx];
                if (!spline.hidden && spline.enabled) {
                    const cPs = spline.getControlPoints(true);
                    for (let cIdx = 0, cLen = cPs.length; cIdx < cLen; ++cIdx) {
                        if (!cPs[cIdx].enabled) {
                            continue;
                        }
                        const circle = cPs[cIdx];
                        if (circleTest(circle)) {
                            return {
                                type: 'splineControlPoint',
                                structureId: parseInt(structureId),
                                hydrophobicId: parseInt(hIdx),
                                controlPointId: cIdx
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a given point, checks the paths of splines (through the coordinates
     * of points along this path) for collision and report the first such
     * collision (if any is found).
     *
     * @param interactionPoint {Object} - point to check for collisions
     * @returns {null|Object} - null if no collision is found, else the first
     * hit (logging structureId, id of spline and all control points of this
     * spline)
     */
    findFirstCollisionSplinePath(interactionPoint) {
        let hit = null;
        if (this.opts.geomineMode) {
            return hit;
        }
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            for (const hIdx in structure.hydrophobicConnectionData.hydrophobicConts) {
                const spline = structure.hydrophobicConnectionData.hydrophobicConts[hIdx];
                if (!spline.hidden && spline.enabled) {
                    if (PolygonCalculation.checkCollisionPointPath(spline
                        .getCurveCoords(true), this.opts.lineWidth, interactionPoint)) {
                        const cpIds = Object.keys(spline.getControlPoints(true));
                        hit = {
                            type: 'splinePath',
                            structureId: parseInt(structureId),
                            hydrophobicId: hIdx,
                            controlPointIds: cpIds
                        }
                    }
                }
            }
        }
        return hit;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a given polygon or point, check atoms bonds and alternative structure
     * representations for collision and report the first such found collision
     * (if any is found).
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {null|Object} - null if no collision is found, else the first
     * hit (logging type of hit, structureId of Structure which contains the
     * hit element and id of hit element)
     */
    findFirstStructureCollision(polyVertices) {
        if (polyVertices.length === 0) {
            return null;
        }

        const {circleTest, polyTest} = this.createCollisionChecksForPoints(polyVertices);

        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            if (!structure.hidden && structure.enabled) {
                if (!this.opts.geomineMode &&
                    structure.representationsData.isCurRepresentation(StructureRepresentation.circle) &&
                    this.testForStructureCircleCollision(structureId, circleTest)) {
                    return {
                        type: 'structureCircle',
                        structureId: parseInt(structureId),
                        id: parseInt(structureId)
                    };
                }
                if (structure.representationsData.isCurRepresentation(StructureRepresentation.default)) {
                    for (const atom of structure.atomsData.getAllEnabledAtoms()) {
                        if (atom.testHitFunctionsForSelection({
                            circleHitFunction: circleTest, rectHitFunction: polyTest
                        })) {
                            const element = atom.element;
                            if (this.opts.geomineMode && (element === 'R' || atom.isHydrogen())) {
                                return null;
                            }
                            return {
                                type: 'atom',
                                structureId: parseInt(structureId),
                                structureName: structure.structureName,
                                structureType: structure.structureType,
                                id: atom.id,
                                additionalInformation: atom.additionalInformation
                            };
                        }
                    }
                }
                if (!this.opts.geomineMode &&
                    structure.representationsData.isCurRepresentation(StructureRepresentation.default)) {
                    for (const edge of structure.edgesData.getAllEnabledEdges()) {
                        //careful with hidden edges
                        const selectorPoints = edge.hidden ? [
                            PointCalculation.findEdgeMidpoint(
                                structure.atomsData.getAtom(edge.from).coordinates,
                                structure.atomsData.getAtom(edge.to).coordinates
                            )
                        ] : edge.getCollisionPointsByMode(this.opts.handleCollisionWith);
                        if (edge.enabled && polyTest(selectorPoints)) {
                            return {
                                type: 'edge',
                                structureId: parseInt(structureId),
                                id: edge.id,
                                from: edge.from,
                                to: edge.to
                            };
                        }
                    }
                }
            }
        }
        return null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a given polygon or point, checks intermolecular (atom pair interaction,
     * pi stackings, pi cation stackings) representations for collision
     * and report the last such found collision (if any is found).
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {null|Object} - null if no collision is found, else the last
     * hit (logging type of hit, and id of hit element)
     */
    findLastIntermolecularCollision(polyVertices) {
        if (polyVertices.length === 0) {
            return null;
        }

        const {polyTest} = this.createCollisionChecksForPoints(polyVertices);

        for (const type of this.sceneData.intermolecularData.intermolecularTypes) {
            for (const [id, interaction] of
                Object.entries(this.sceneData.intermolecularData[type]).reverse()) {
                if (!interaction.hidden && interaction.enabled) {
                    //careful with hidden edges
                    const selectorPoints = interaction
                        .getCollisionPointsByMode(this.opts.handleCollisionWith);
                    if (polyTest(selectorPoints)) {
                        return {
                            id: parseInt(id),
                            type: type,
                            additionalInformation: interaction.additionalInformation
                        };
                    }
                }
            }
        }

        return null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates necessary test functions for collision detection for a given
     * array of polygon points. Most notably fills in different geometrical
     * check functions if only a single point is given.
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {Object} - collision test functions to check whether the given
     * points collide with an input circle (field "circleTest") or with an
     * input polygon (field "polyTest")
     */
    createCollisionChecksForPoints(polyVertices) {
        let circleTestFn, polyTestFn;
        if (polyVertices.length === 1) { //hits with single point
            const singlePoint = polyVertices[0];
            circleTestFn = (circle) => {
                return PointCalculation.checkPointInCircle(singlePoint, circle, circle.rad);
            };
            polyTestFn = (poly) => {
                return PolygonCalculation.checkCollisionPolygonPoint(singlePoint, poly);
            };
        } else { //hits with multiple points
            circleTestFn = (circle) => {
                return PolygonCalculation.checkCollisionPolygonCircle(circle, polyVertices);
            };
            polyTestFn = (otherPoly) => {
                return PolygonCalculation.checkCollisionTwoPolygons(polyVertices, otherPoly);
            };
        }

        return {
            circleTest: circleTestFn, polyTest: polyTestFn
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Tests whether a selector shape of a structure circle passes a circle
     * collision check function.
     *
     * @param structureId {Object} - the Structure the structure circle
     * belongs to
     * @param circleHitFunction {Function} - function to hit test circle
     * elements
     */
    testForStructureCircleCollision(structureId, circleHitFunction) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const selShapes = structure.representationsData.structureCircle.selectorShapes;
        for (const selShape of selShapes) {
            const {coordinates: {x, y}, rad} = selShape;
            const circle = {
                x: x, y: y, rad: rad
            };
            if (circleHitFunction(circle)) {
                return true;
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks which atoms, bonds and structure circles a given polygon or point
     * collides with.
     *
     * @param polyVertices {Array} - points of the polygon to check for
     * collisions. Can just contain a single point
     * @returns {Object} - log which atoms edges and structure circles
     * are hit in which structures
     */
    findCollisions(polyVertices) {
        if (polyVertices.length === 0) {
            return {
                hitAtoms: {}, hitEdges: {}, hitStructureCircles: []
            }
        }

        const {circleTest, polyTest} = this.createCollisionChecksForPoints(polyVertices);

        const hitAtoms = {};
        const hitEdges = {};
        const hitStructureCircles = [];
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            if (!structure.hidden && structure.enabled) {
                structure.atomsData.getAllEnabledAtoms().forEach(atom => {
                    if (atom.testHitFunctionsForSelection({
                        circleHitFunction: circleTest, rectHitFunction: polyTest
                    })) {
                        if (!hitAtoms.hasOwnProperty(structureId)) {
                            hitAtoms[structureId] = [];
                        }
                        hitAtoms[structureId].push(atom.id);
                    }
                });

                structure.edgesData.getAllEnabledEdges().forEach(edge => {
                    //careful with hidden edges
                    const selectorPoints = edge.hidden ? [
                        PointCalculation.findEdgeMidpoint(
                            structure.atomsData.getAtom(edge.from).coordinates,
                            structure.atomsData.getAtom(edge.to).coordinates
                        )
                    ] : edge.getCollisionPointsByMode(this.opts.handleCollisionWith);
                    if (polyTest(selectorPoints)) {
                        if (!hitEdges.hasOwnProperty(structureId)) {
                            hitEdges[structureId] = [];
                        }
                        hitEdges[structureId].push(edge.id);
                    }
                });

                if (structure.representationsData.hasRepresentation(StructureRepresentation.circle) &&
                    this.testForStructureCircleCollision(structureId, circleTest)) {
                    hitStructureCircles.push(structureId);
                }
            }
        }

        return {
            hitAtoms: hitAtoms, hitEdges: hitEdges, hitStructureCircles: hitStructureCircles
        }
    }
}


/* src/DataProcessing/EdgeBuilder.js */
/**
 * Creates data for different edge types for drawing.
 */
class EdgeBuilder {
    /**
     * Contains instance for the data storage/access and configuration options.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     */
    constructor(opts, sceneData) {
        this.opts = opts;
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates an object that holds all the relevant information to draw a
     * bond (i.e. "drawPoints": array of endpoints of lines, "midpoints": the
     * points in the middle of either end of the bond, "edgeCollisionPoints":
     * corners of a rectangle representing only (!) the drawn bond,
     * "selCollisionPoints": corners of a rectangle representing the bond's
     * surrounding selection shape, and "selWidth": the width of the bond's
     * surrounding selection shape). As a fail-safe, this function is allowed
     * to return null whenever an edge cannot be drawn (or should not be drawn
     * for aesthetic reasons). Such null return must then be caught (here that
     * is handled usually by letting the createEdgeUpdateFunction decide how to
     * proceed with such a draw information).
     *
     * @param from {Number} - atom id of the first atom involved in the bond
     * @param to {Number} - atom id of the second atom involved in the bond
     * @param structure {Structure} - Structure object which holds the bond
     * @param edge {Edge} - Edge object representing the bond
     * @param byTemp {Boolean} - whether to base bond creation on temporary
     * coordinates of involved atoms
     * @returns {null|Object} - draw information for the bond
     */
    createBondByType(from, to, structure, edge, byTemp) {
        const fromAtom = structure.atomsData.getAtom(from);
        const toAtom = structure.atomsData.getAtom(to);
        //directionCheck set to false. 1DFG has a strange ligand bond but looks ok otherwise. The
        //original PoseView draws that PDB despite that
        const midpoints = this.getEdgeMidPoints(fromAtom, toAtom, byTemp, false);
        if (!midpoints) {
            return null;
        }
        const [midFrom, midTo] = midpoints;
        switch (edge.type) {
            case 'single':
                if (edge.aromatic) {
                    if (edge.isAromaticNoRing()) {
                        return this.createOffsetDoubleBond(edge,
                            structure,
                            midFrom,
                            midTo,
                            byTemp,
                            true
                        );
                    } else {
                        return this.createSingleBondWithAromaticOffsets(midFrom,
                            midTo,
                            structure,
                            edge.aromaticRings,
                            byTemp
                        );
                    }
                } else {
                    return this.createSingleEdge(midFrom, midTo);
                }
            case 'double':
                if (edge.drawWithOffset) {
                    return this.createOffsetDoubleBond(edge,
                        structure,
                        midFrom,
                        midTo,
                        byTemp,
                        false
                    );
                }
                return this.createDoubleBond(midFrom, midTo);
            case 'triple':
                return this.createTripleBond(midFrom, midTo);
            case 'stereoFront':
                return this.createStereoFront(midFrom, midTo);
            case 'stereoFrontReverse':
                return this.createStereoFront(midTo, midFrom);
            case 'stereoBack':
                return this.createStereoBack(midFrom, midTo);
            case 'stereoBackReverse':
                return this.createStereoBack(midTo, midFrom);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw an edge, e.g. single bond.
     *
     * @param from {Object} - x- and y-coordinates of first involved object
     * @param to {Object} - x- and y-coordinates of second involved object
     * @returns {Object} - draw information for the bond
     */
    createSingleEdge(from, to) {
        const normals = LineCalculation.findUnitNormals(from, to);

        const bondWidth = this.opts.lineWidth;
        const selWidth = 2 * this.opts.edgeSelectorOffset + bondWidth;

        return {
            drawPoints: [[from, to]],
            midpoints: [from, to],
            edgeCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                bondWidth / 2
            ),
            selCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Bonds connecting atoms represented by text labels are not allowed to
     * reach into a clear zone around such text (defined by this.opts.atomRadius).
     * Bonds (in this case interactions between structures) connected to
     * a structure circle should be shortened to end at the edge of the circle.
     * This function shortens such bonds accordingly and returns the new
     * midpoints to be used for drawing the bond.
     *
     * @param from {Object} - first atom or structure circle to connect
     * @param to {Object} - second atom or structure circle to connect
     * @param byTemp {Boolean} - whether temporary or real coordinates
     * shall be used
     * @param directionCheck {Boolean} - if true, return null if shortening
     * leads to a invalid line in the opposite direction.
     * @param forcedMinDist {Number} - a forced minimal distance to be kept
     * from the atom
     * @returns {Array} - the two new midpoints of the bond
     */
    getEdgeMidPoints(from, to, byTemp = false, directionCheck = false, forcedMinDist = 0) {
        const fromCoords = byTemp ? from.tempCoordinates : from.coordinates;
        const toCoords = byTemp ? to.tempCoordinates : to.coordinates;

        //check which label the edge has to keep a distance from or
        //if from/to is a structureCircle
        const mustKeepDistFrom = (from.label && !from.isLabel) || from.isStructureCircle;
        const mustKeepDistTo = (to.label && !to.isLabel) || to.isStructureCircle;

        //if no distances must be kept, just return original coordinates
        if (forcedMinDist <= 0 && !mustKeepDistFrom && !mustKeepDistTo) {
            return [fromCoords, toCoords];
        }

        //calculate new positions
        const fromRad = from.isStructureCircle ? from.rad : this.opts.atomRadius;
        const toRad = to.isStructureCircle ? to.rad : this.opts.atomRadius;
        const fromDist = mustKeepDistFrom ? Math.max(forcedMinDist, fromRad) : forcedMinDist;
        const toDist = mustKeepDistTo ? Math.max(forcedMinDist, toRad) : forcedMinDist;

        return LineCalculation.shortenLine(fromCoords, toCoords, fromDist, toDist, directionCheck);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw the first bond to be used for the
     * representation of an aromatic bond (the non-dashed one).
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @param structure {Structure} - the Structure object which holds the bond
     * @param aromRings {Array} - which aromatic rings the bond is included in
     * @param byTemp {Boolean} - whether to base bond creation on temporary
     * coordinates of involved atoms
     * @returns {Object} - draw information for the bond
     */
    createSingleBondWithAromaticOffsets(from, to, structure, aromRings, byTemp) {
        const normals = LineCalculation.findUnitNormals(from, to);

        let bondWidth = 2 * this.opts.lineWidth + this.opts.spaceToRing;
        let selWidth = 2 * this.opts.edgeSelectorOffset + bondWidth;

        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';
        let newFrom = from, newTo = to;
        if (aromRings.size === 1) {
            //find correct normal (the one that points inside the ring)
            const midPoint = PointCalculation.findEdgeMidpoint(from, to);
            let normal = normals[0];
            const proj = {
                x: midPoint.x + normal.x, y: midPoint.y + normal.y
            };
            const ring = structure.ringsData.getRing(aromRings.values().next().value);
            const ringCoords = ring.atoms.map(atom => {
                return atom[coordParam];
            });
            if (!PolygonCalculation.checkCollisionPolygonPoint(proj, ringCoords)) {
                normal = normals[1];
            }
            //move to real midpoint, add lineWidth for real distance
            const halfDist = (this.opts.spaceToRing + this.opts.lineWidth) / 2;
            newFrom = {
                x: from.x + halfDist * normal.x, y: from.y + halfDist * normal.y
            };
            newTo = {
                x: to.x + halfDist * normal.x, y: to.y + halfDist * normal.y
            };
        } else {
            const addedWidth = this.opts.lineWidth + this.opts.spaceToRing;
            bondWidth += addedWidth;
            selWidth += addedWidth;
        }

        return {
            drawPoints: [[from, to]],
            midpoints: [newFrom, newTo],
            edgeCollisionPoints: PolygonCalculation.createRectFromLine(newFrom,
                newTo,
                normals,
                bondWidth / 2
            ),
            selCollisionPoints: PolygonCalculation.createRectFromLine(newFrom,
                newTo,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw a double bond in a special way, s.t the
     * first bond is drawn like a single bond and the other bond is drawn on
     * the "less full" side of the bond (i.e., the side on which fewer
     * substituents lie) or preferable inside a ring as a shortened line.
     *
     * @param edge {Edge} - the Wdge object representing the bond
     * @param structure {Structure} - the Structure object holding the bond
     * @param fromCoords {Object} - x- and y-coordinates of first involved
     * atom
     * @param toCoords {Object} - x- and y-coordinates of second involved atom
     * @param byTemp {Boolean} - whether to base bond creation on temporary
     * coordinates of involved atoms
     * @returns {Object} - draw information for the bond
     */
    createOffsetDoubleBond(edge, structure, fromCoords, toCoords, byTemp, aromaticNoRing) {
        const {from, to, cyclic} = edge;

        const normals = LineCalculation.findUnitNormals(fromCoords, toCoords);
        const coordParam = byTemp ? 'tempCoordinates' : 'coordinates';

        //find the normal on previously determined side and get dist vector
        let normal = normals[0];
        const mid = PointCalculation.findEdgeMidpoint(fromCoords, toCoords);
        const proj = {
            x: mid.x + normal.x, y: mid.y + normal.y
        };
        const projSide = LineCalculation.getSideOfLine(fromCoords, toCoords, proj);
        //for cyclic edges, make sure that projected side is within ring
        if (cyclic) {
            const ring = structure.ringsData.getRing(edge.drawnInRing);
            const ringCoords = ring.atoms.map(atom => {
                return atom[coordParam];
            });
            if (!PolygonCalculation.checkCollisionPolygonPoint(proj, ringCoords)) {
                normal = normals[1];
            }
        } else {
            if (projSide !== this.fullerSize(structure,
                coordParam,
                edge,
                fromCoords,
                toCoords,
                aromaticNoRing
            )) {
                normal = normals[1];
            }
        }

        //add lineWidth bc to reach mid of other line, go through half of both
        const offset = this.opts.spaceBetweenDouble + this.opts.lineWidth;
        const innerLineInfo = LineCalculation.createInnerLine(fromCoords,
            toCoords,
            normal,
            offset,
            this.opts.cutoffAngleDouble
        );

        const [secondFrom, secondTo] = innerLineInfo.points;

        //midpoint is point between
        const midpointFrom = {
            x: (secondFrom.x + fromCoords.x) / 2, y: (secondFrom.y + fromCoords.y) / 2
        };
        const midpointTo = {
            x: (secondTo.x + toCoords.x) / 2, y: (secondTo.y + toCoords.y) / 2
        };

        //finalize return values
        const drawPoints = [[fromCoords, toCoords]];
        if (innerLineInfo.secondMakesSense) {
            drawPoints.push([secondFrom, secondTo]);
        }
        const bondWidth = this.opts.spaceBetweenDouble + this.opts.lineWidth * 2;
        const selWidth = 2 * this.opts.edgeSelectorOffset + bondWidth;

        return {
            drawPoints: drawPoints,
            midpoints: [midpointFrom, midpointTo],
            edgeCollisionPoints: PolygonCalculation.createRectFromLine(midpointFrom,
                midpointTo,
                normals,
                bondWidth / 2
            ),
            selCollisionPoints: PolygonCalculation.createRectFromLine(midpointFrom,
                midpointTo,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For non cyclic edges, puts them on the fuller side.
     *
     * @param structure {Structure} - the Structure object holding the bond
     * @param coordParam {String} - 'tempCoordinates' or 'coordinates'
     * @param edge {Edge} - the Edge object representing the bond
     * @param fromCoords {Object} - x- and y-coordinates of first involved
     * atom
     * @param toCoords {Object} - x- and y-coordinates of second involved atom
     */
    fullerSize(structure, coordParam, edge, fromCoords, toCoords, aromaticNoRing) {
        const {from, to, cyclic} = edge;
        //fetch representation for neighbors on both side of edge
        const fromNbs = structure.atomsData.neighbors[from]
            .filter(({neighbor}) => {
                if (aromaticNoRing) {
                    const edge = structure.edgesData.getEdgeByAtomIds(from, neighbor);
                    return neighbor !== to && edge.isAromaticNoRing()
                }
                return neighbor !== to
            });
        const toNbs = structure.atomsData.neighbors[to].filter(({neighbor}) => {
            if (aromaticNoRing) {
                const edge = structure.edgesData.getEdgeByAtomIds(to, neighbor);
                return neighbor !== from && edge.isAromaticNoRing()
            }
            return neighbor !== from
        });
        const allNbCoordinates = [fromNbs, toNbs].flat()
            .map(nbInfo => {
                const atom = structure.atomsData.getAtom(nbInfo.neighbor);
                return {
                    coordinates: atom[coordParam], inRing: atom.isInRing
                };
            });

        //check for fuller side
        let nrSide_1 = 0, nrSide_2 = 0, side_1 = -1, side_2 = 1;
        allNbCoordinates.forEach(({coordinates: nbCoords}) => {
            const side = LineCalculation.getSideOfLine(fromCoords, toCoords, nbCoords);
            if (side === side_1) {
                nrSide_1++;
            } else if (side === side_2) {
                nrSide_2++;
            }
        });
        //place on fuller side
        return (nrSide_1 > nrSide_2) ? side_1 : side_2;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw a double bond.
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @returns {Object} - draw information for the bond
     */
    createDoubleBond(from, to) {
        const normals = LineCalculation.findUnitNormals(from, to);

        //add half line width bc go through half of other line to reach its mid
        const offset = (this.opts.spaceBetweenDouble) / 2 + this.opts.lineWidth / 2;

        const leftFrom = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[0], offset)
        );
        const leftTo = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[0], offset)
        );

        const rightFrom = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[1], offset)
        );
        const rightTo = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[1], offset)
        );

        const bondWidth = this.opts.spaceBetweenDouble + this.opts.lineWidth * 2;
        const selWidth = 2 * (this.opts.edgeSelectorOffset) + bondWidth;

        return {
            drawPoints: [[leftFrom, leftTo], [rightFrom, rightTo]],
            midpoints: [from, to],
            edgeCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                bondWidth / 2
            ),
            selCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw a triple bond.
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @returns {Object} - draw information for the bond
     */
    createTripleBond(from, to) {
        const normals = LineCalculation.findUnitNormals(from, to);

        //two halves between two midpoints
        const offset = this.opts.spaceBetweenTriple + this.opts.lineWidth;

        const leftFrom = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[0], offset)
        );
        const leftTo = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[0], offset)
        );

        const rightFrom = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[1], offset)
        );
        const rightTo = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[1], offset)
        );

        const bondWidth = this.opts.spaceBetweenTriple * 2 + this.opts.lineWidth * 3;
        const selWidth = 2 * this.opts.edgeSelectorOffset + bondWidth;

        return {
            drawPoints: [
                [leftFrom, leftTo], [from, to], [rightFrom, rightTo]
            ],
            midpoints: [from, to],
            edgeCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                bondWidth / 2
            ),
            selCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the draw information to draw a front-facing stereo bond between
     * two points, opening up towards the second point.
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @returns {Object} - draw information for the bond
     */
    createStereoFront(from, to) {
        const normals = LineCalculation.findUnitNormals(from, to);
        const baseSideOffset = this.opts.wedgeBaseWidth / 2;
        const fullSideOffset = this.opts.wedgeFullWidth / 2;

        const A = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[0], baseSideOffset)
        );
        const B = VectorCalculation.vectorAdd(from,
            VectorCalculation.scalarMult(normals[1], baseSideOffset)
        );
        const C = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[0], fullSideOffset)
        );
        const D = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[1], fullSideOffset)
        );

        const bondWidth = this.opts.lineWidth;
        const selWidth = 2 * (this.opts.edgeSelectorOffset) + bondWidth;

        return {
            drawPoints: [[B, A, C, D]],
            midpoints: [from, to],
            edgeCollisionPoints: [B, A, C, D],
            selCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the draw information to draw a back-facing stereo bond between
     * two points, opening up towards the second point. This is done by
     * creating multiple horizontal lines separated by free space of a certain
     * width defined by this.opts.wedgeSpacing.
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @returns {Object} - draw information for the bond
     */
    createStereoBack(from, to) {
        const wedgeWidth = this.opts.lineWidth;
        const wedgeSpacing = this.opts.wedgeSpacing;

        const normals = LineCalculation.findUnitNormals(from, to);
        const triangle = this.createTriangle(from, to);
        const [A, C, D] = triangle.drawPoints[0];
        const mid = {
            x: (C.x + D.x) / 2, y: (C.y + D.y) / 2
        };

        const {x: normalX, y: normalY} = normals[0]; //only need one normal
        const maxDist = Math.sqrt((mid.x - from.x) ** 2 + (mid.y - from.y) ** 2);

        //vector from A to mid between C and D
        const lineMov = PointCalculation.createMovementBetweenTwoPoints(A, mid);
        const ACVec = VectorCalculation.normalize({
            x: A.x - C.x, y: A.y - C.y
        });
        const ACNext = {
            x: A.x + ACVec.x, y: A.y + ACVec.y
        };
        const ACLine = LineCalculation.createLinearFunctionByTwoPoints(A, ACNext);

        let nextAddedDist = wedgeWidth / 2;
        let curDistance = nextAddedDist;
        const drawPoints = [];
        while (curDistance <= maxDist) {
            //move along line to next point
            const nextLinePoint = lineMov.forward(nextAddedDist);
            const proj = {
                x: nextLinePoint.x + normalX, y: nextLinePoint.y + normalY
            };
            const nextLine = LineCalculation.createLinearFunctionByTwoPoints(nextLinePoint, proj);
            //this is intersection point
            const firstLineNext = LineCalculation.findIntersectionTwoLines(ACLine, nextLine);

            //this is equivalent to the inverted offsets from nextLinePoint
            //to firstLineNext
            const offsetsToSecond = {
                x: nextLinePoint.x - firstLineNext.x, y: nextLinePoint.y - firstLineNext.y
            };
            const secondLineNext = {
                x: nextLinePoint.x + offsetsToSecond.x, y: nextLinePoint.y + offsetsToSecond.y
            };

            drawPoints.push([firstLineNext, secondLineNext]);

            nextAddedDist = wedgeWidth + wedgeSpacing;
            curDistance += nextAddedDist;
        }

        return {
            drawPoints: drawPoints,
            midpoints: triangle.midpoints,
            edgeCollisionPoints: triangle.edgeCollisionPoints,
            selCollisionPoints: triangle.selCollisionPoints,
            selWidth: triangle.selWidth
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates draw information to draw a triangle between two points, the
     * triangle opening up towards the second point.
     *
     * @param from {Object} - x- and y-coordinates of first involved atom
     * @param to {Object} - x- and y-coordinates of second involved atom
     * @returns {Object} - draw information for the triangle
     */
    createTriangle(from, to) {
        const normals = LineCalculation.findUnitNormals(from, to);
        const fullSideOffset = this.opts.wedgeFullWidth / 2;

        const C = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[0], fullSideOffset)
        );
        const D = VectorCalculation.vectorAdd(to,
            VectorCalculation.scalarMult(normals[1], fullSideOffset)
        );

        const bondWidth = this.opts.lineWidth;
        const selWidth = 2 * (this.opts.edgeSelectorOffset) + bondWidth;

        return {
            drawPoints: [[from, C, D]],
            midpoints: [from, to],
            edgeCollisionPoints: [from, C, D],
            selCollisionPoints: PolygonCalculation.createRectFromLine(from,
                to,
                normals,
                selWidth / 2
            ),
            selWidth: selWidth
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines on basis of current representation of the involved structures
     * whether to use coordinates of the atom(s) or the structure circle(s) to
     * draw a intermolecular bond. If both involved structures are currently
     * represented as structure circles also offset the coordinates according
     * to their order in intermolecularConnections so they don't overlap.
     *
     * @param id {Number} - id of the intermolecular connection
     * @param type {String} - type of the intermolecular connection
     * @param fromStructure {Object} - structure from where to draw connection
     * @param toStructure {Object} - structure to where to draw the connection
     * @param from {Number} - id of atom/ring from where to draw the connection
     * @param to {Number} - id of atom/ring to where to draw the connection
     * @param byTemp {Boolean} - whether to use temp coordinates
     * @return {Array} - fromCoords and toCoords of the connection
     *
     */
    getNewIntermolecularCoords(id, type, fromStructure, toStructure, from, to, byTemp = false) {
        if (fromStructure.representationsData.isCurRepresentation(StructureRepresentation.circle) &&
            toStructure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
            //add a offset to the connections so they do not overlap
            //reorder the structures so that the one with smaller index always is
            //'from' to have consistent results over multiple connections
            return this.getCoordsBetweenTwoStructureCircles(id,
                type,
                fromStructure,
                toStructure,
                byTemp
            );
        }

        let fromObj, toObj;
        const getRingCenter = (structure, ringId) => {
            const centroid = structure.ringsData.getRing(ringId).centroidInfo.centroid;
            return {
                coordinates: centroid, tempCoordinates: centroid
            }
        };

        if (fromStructure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
            fromObj = fromStructure.representationsData.structureCircle;
        } else {
            switch (type) {
                case 'distances':
                case 'interactions':
                    fromObj = this.sceneData.annotationsData.annotations[from];
                    break;
                case 'atomPairInteractions':
                    fromObj = fromStructure.atomsData.getAtom(from);
                    break;
                case 'cationPiStackings':
                case 'piStackings':
                    fromObj = getRingCenter(fromStructure, from);
            }
        }
        if (toStructure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
            toObj = toStructure.representationsData.structureCircle;
        } else {
            switch (type) {
                case 'distances':
                case 'interactions':
                    toObj = this.sceneData.annotationsData.annotations[to];
                    break;
                case 'atomPairInteractions':
                case 'cationPiStackings':
                    toObj = toStructure.atomsData.getAtom(to);
                    break;
                case 'piStackings':
                    toObj = getRingCenter(toStructure, to);
            }
        }
        //returns [{x,y}, {x,y}]
        return this.getEdgeMidPoints(fromObj, toObj, byTemp);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates coordinates between two structure circles for drawing of
     * intermolecular edges.
     *
     * @param id {Number} - id of the intermolecular connection
     * @param type {String} - type of the intermolecular connection
     * @param fromStructure {Object} - structure from where to draw connection
     * @param toStructure {Object} - structure to where to draw the connection
     * @param byTemp {Boolean} - whether to use temp coordinates
     * @return {Array} - fromCoords and toCoords of the intermolecular connection
     */
    getCoordsBetweenTwoStructureCircles(id, type, fromStructure, toStructure, byTemp = false) {
        const [lowerStructure, higherStructure, swapped] = fromStructure.id < toStructure.id ? [
            fromStructure, toStructure, false
        ] : [toStructure, fromStructure, true];
        //radius defines the max available space to move the connections
        //just take the smaller one to have parallel lines in the end
        const lowerRad = lowerStructure.representationsData.structureCircle.rad;
        const higherRad = higherStructure.representationsData.structureCircle.rad;
        const maxSpace = Math.min(lowerRad, higherRad);
        //set this so that they barely not touch
        const maxDistBetweenConnections = this.opts.piPiRadius * 2.1;
        //since this.sceneData.structuresData.intermolecularConnections is ordered so that the
        // smaller id comes first
        const intermolecularOrder = this.sceneData.structuresData.intermolecularConnections
            [lowerStructure.id][higherStructure.id];
        const connectionCount = intermolecularOrder.length;
        const connectionIdx = intermolecularOrder.findIndex(elem => {
            return elem.type === type && elem.id == id;
        });
        //actual distance between connections and the space taken by all
        //connections (perpendicular to the connections)
        const [distBetween, space] = (maxSpace / (connectionCount - 1) >=
            maxDistBetweenConnections) ? [
            maxDistBetweenConnections, (connectionCount - 1) * maxDistBetweenConnections
        ] : [
            maxSpace / (connectionCount - 1), maxSpace
        ];
        //offset of connection from one end of the available space
        const offset = connectionIdx * distBetween;
        //structure circle midpoints
        const lowerMid = byTemp ?
            lowerStructure.representationsData.structureCircle.tempCoordinates :
            lowerStructure.representationsData.structureCircle.coordinates;
        const higherMid = byTemp ?
            higherStructure.representationsData.structureCircle.tempCoordinates :
            higherStructure.representationsData.structureCircle.coordinates;
        //find a parallel line where the connection is a section of
        const rotatedMid = PointCalculation.rotatePointAroundAnother(higherMid,
            lowerMid,
            90,
            false
        );
        const rotatedNormalizedVector = VectorCalculation.normalize(VectorCalculation.vectorizeLine(lowerMid,
            rotatedMid
        ));
        const distFromMid = space / 2 - offset;
        const directedDist = VectorCalculation.scalarMult(rotatedNormalizedVector, distFromMid);
        const [newFrom, newTo] = VectorCalculation.findParallelLineByDistVec(lowerMid,
            higherMid,
            directedDist
        );
        //endpoints are still inside the circle.
        //move points to the edge of the structure circle
        const distToCircleEdgeFrom = Math.sqrt(lowerRad ** 2 - distFromMid ** 2);
        const lowerCoords = PointCalculation.movePointTowardsAnother(newFrom,
            newTo,
            distToCircleEdgeFrom
        );
        const distToCircleEdgeTo = Math.sqrt(higherRad ** 2 - distFromMid ** 2);
        const higherCoords = PointCalculation.movePointTowardsAnother(newTo,
            newFrom,
            distToCircleEdgeTo
        );
        //swapped is necessary to determine where to draw the pi circle
        //when drawing cation pi connections
        return swapped ? [higherCoords, lowerCoords] : [lowerCoords, higherCoords];
    }
}

/* src/DataProcessing/JsonBuilder.js */
/**
 * Converts currently stored structural data data to JSON that represents the scene.
 */
class JsonBuilder {
    /**
     * Contains instances for data access and configuration options.
     *
     * @param sceneData {Object} - data storage
     * @param opts {Object} - configuration options for the drawer
     */
    constructor(sceneData, opts) {
        this.sceneData = sceneData;
        this.opts = opts;

        const options = {
            explicitHydrogens: true,
            compactDrawing: false,
        };
        this.smilesDrawer = new SmilesDrawer.Drawer(options);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data of the scene into a string in
     * the same JSON format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @param defaultCoords {Boolean} - return circle representation coordinates for annotations
     * @returns {String} - structural data in JSON format
     */
    getJson(enabled = false, defaultCoords = false) {
        const structureInfo = this.getStructureJson(enabled);
        const [atomPairInteractionInfo, piPiInfo, cationPiInfo] =
            this.getIntermolecularJson(enabled);
        const hydrophobicInfo = this.getHydrophobicJson(enabled);
        const annotationInfo = this.getAnnotationJson(enabled, defaultCoords);
        return JSON.stringify({
            scene: {
                structures: structureInfo,
                atomPairInteractions: atomPairInteractionInfo,
                piStackings: piPiInfo,
                cationPiStackings: cationPiInfo,
                hydrophobicContacts: hydrophobicInfo,
                annotations: annotationInfo
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data of the scene and the config
     * into a string in the same JSON format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @param defaultCoords {Boolean} - return circle representation coordinates for annotations
     * @returns {String} - structural data in JSON format
     */
    getJsonWithConfig(enabled = false, defaultCoords = false) {
        const structureInfo = this.getStructureJson(enabled);
        const [atomPairInteractionInfo, piPiInfo, cationPiInfo] =
            this.getIntermolecularJson(enabled);
        const hydrophobicInfo = this.getHydrophobicJson(enabled);
        const annotationInfo = this.getAnnotationJson(enabled, defaultCoords);
        return JSON.stringify({
            opts: this.opts,
            diagram: {
                scene: {
                    structures: structureInfo,
                    atomPairInteractions: atomPairInteractionInfo,
                    piStackings: piPiInfo,
                    cationPiStackings: cationPiInfo,
                    hydrophobicContacts: hydrophobicInfo,
                    annotations: annotationInfo
                }
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data for structures in the same JSON
     * format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @returns {Array} - structural data of structures in JSON format
     */
    getStructureJson(enabled = false) {
        const structureInfo = [];
        Object.values(this.sceneData.structuresData.structures).forEach(structure => {
            if (enabled && !structure.enabled) {
                return;
            }
            const atomInfo = [];
            structure.atomsData.atoms.forEach(atom => {
                if (atom.enabled) {
                    atomInfo.push({
                        id: atom.id,
                        label: atom.label,
                        stereoCenter: atom.stereoCenter,
                        element: atom.element,
                        charge: atom.charge,
                        hydrogenCount: atom.hydrogenCount,
                        coordinates: Object.assign({}, atom.coordinates),
                        aromatic: atom.aromatic,
                        additionalInformation: atom.additionalInformation
                    });
                }
            });
            const edgeInfo = [];
            structure.edgesData.edges.forEach(edge => {
                if (edge.enabled) {
                    edgeInfo.push({
                        id: edge.id,
                        from: edge.from,
                        to: edge.to,
                        type: edge.type,
                        aromatic: edge.aromatic
                    });
                }
            });
            const ringInfo = [];
            //edges could be added for rings
            for (const ringId in structure.ringsData.rings) {
                const ring = structure.ringsData.getRing(ringId);
                ringInfo.push({
                    id: ring.id, atoms: ring.atoms.map(atom => {
                        return atom.id;
                    })
                });
            }
            //ring system info could be added
            structureInfo.push({
                id: structure.id,
                structureName: structure.structureName,
                structureLabel: structure.structureLabel,
                structureType: structure.structureType,
                representation: structure.representationsData.currentRepresentation,
                additionalInformation: structure.additionalInformation,
                atoms: atomInfo,
                bonds: edgeInfo,
                rings: ringInfo,
                selectedAtoms: [...structure.atomsData.selectedAtoms],
                selectedEdges: [...structure.edgesData.selectedEdges]
            });
        });
        return structureInfo;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data for intermolecular forces in
     * the same JSON format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @returns {Array} - structural data of intermolecular forces in JSON format
     */
    getIntermolecularJson(enabled = false) {
        const intermolecularData = this.sceneData.intermolecularData;
        const atomPairInteractionInfo = [];
        Object.entries(intermolecularData.atomPairInteractions)
            .forEach(([atomPairInteractionId, atomPairInteraction]) => {
                if (enabled && !atomPairInteraction.enabled) {
                    return;
                }
                atomPairInteractionInfo.push({
                    id: parseInt(atomPairInteractionId),
                    fromStructure: atomPairInteraction.fromStructure,
                    toStructure: atomPairInteraction.toStructure,
                    from: atomPairInteraction.from,
                    to: atomPairInteraction.to,
                    additionalInformation: atomPairInteraction.additionalInformation
                });
            });
        //get necessary pi stacking data
        const piPiInfo = [];
        Object.entries(intermolecularData.piStackings).forEach(([piStackId, piStacking]) => {
            if (enabled && !piStacking.enabled) {
                return;
            }
            piPiInfo.push({
                id: parseInt(piStackId),
                fromStructure: piStacking.fromStructure,
                toStructure: piStacking.toStructure,
                from: piStacking.from,
                to: piStacking.to,
                additionalInformation: piStacking.additionalInformation
            });
        });
        //get necessary cation-pi stacking data
        const cationPiInfo = [];
        Object.entries(intermolecularData.cationPiStackings).forEach(([catPiId, catPiStacking]) => {
            if (enabled && !catPiStacking.enabled) {
                return;
            }
            cationPiInfo.push({
                id: parseInt(catPiId),
                fromStructure: catPiStacking.fromStructure,
                toStructure: catPiStacking.toStructure,
                from: catPiStacking.from,
                to: catPiStacking.to,
                additionalInformation: catPiStacking.additionalInformation
            });
        });
        return [atomPairInteractionInfo, piPiInfo, cationPiInfo];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data for hydrophobic contacts in
     * the same JSON format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @returns {Array} - structural data of hydrophobic contacts in JSON format
     */
    getHydrophobicJson(enabled = false) {
        const hydrophobicInfo = [];
        Object.entries(this.sceneData.hydrophobicData.hydrophobicContacts)
            .forEach(([hydrophobicId, hydrophobicContact]) => {
                if (enabled && !hydrophobicContact.enabled) {
                    return;
                }
                let controlPoints = hydrophobicContact.controlPoints;
                if (enabled) {
                    controlPoints = hydrophobicContact.controlPoints.filter(cp => cp.enabled);
                }
                controlPoints = controlPoints.map(({
                    x, y, atomLinks
                }) => {
                    return {
                        x: x, y: y, atomLinks: atomLinks
                    }
                });
                hydrophobicInfo.push({
                    id: parseInt(hydrophobicId),
                    belongsTo: hydrophobicContact.structureLink,
                    controlPoints: controlPoints
                });
            });
        return hydrophobicInfo;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Accumulate the internal structural data for annotations in
     * the same JSON format that is used in the drawer's input.
     *
     * @param enabled {Boolean} - return only not removed elements
     * @param defaultCoords {Boolean} - return only default representation coordinates for
     * annotations
     * @returns {Array} - structural data of annotations in JSON format
     */
    getAnnotationJson(enabled = false, defaultCoords = false) {
        const annotationsInfo = [];
        Object.values(this.sceneData.annotationsData.annotations).forEach(annotation => {
            if (enabled && !annotation.enabled) {
                return;
            }
            const annotationInfo = {
                id: annotation.id,
                label: annotation.label,
                isStructureLabel: annotation.isStructureLabel,
                additionalInformation: annotation.additionalInformation
            };

            if (annotation.color !== this.opts.colors.DEFAULT) {
                annotationInfo.color = annotation.color;
            }

            let coordinates = annotation.coordinates;

            if (annotation.belongsToStructure) {
                annotationInfo.belongsTo = {
                    type: annotation.type,
                    id: annotation.structureLink,
                    atomLinks: annotation.atomLinks
                };
                const structureID = annotation.structureLink;
                const structures = this.sceneData.structuresData.structures;
                const structure = structures[structureID.toString()];
                //take non circle representation coordinates if other representations are set
                if (defaultCoords &&
                    !structure.representationsData.isCurRepresentation(
                        StructureRepresentation.default) &&
                    annotation.structureRepresentationInfo[StructureRepresentation.default]) {
                    coordinates =
                        annotation.structureRepresentationInfo[
                            StructureRepresentation.default].coordinates;
                }
            }
            annotationInfo.coordinates = coordinates;
            annotationsInfo.push(annotationInfo);
        });
        return annotationsInfo;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Converts a SMILES expression to a structure JSON readable by the library.
     *
     * @param smilesString {String} - SMILES of the structure
     * @returns {Object} - structure data in JSON format
     */
    getJsonBySmiles(smilesString) {
        const {
            success, atomInfo, edgeInfo, ringInfo, unclearStereoEdges, stereoCenters
        } = this.translateInput(smilesString);
        const unassignedStereoCenters = new Set(stereoCenters);
        if (success) {
            //to resolve SmilesDrawer ambiguities with stereo centers
            while (unclearStereoEdges.size) {
                unclearStereoEdges.forEach(edgeId => {
                    for (const edge of edgeInfo) {
                        if (edge.id === edgeId) {
                            let cleared = false;
                            //from is the stereo center, edge: from -> to
                            if (!unassignedStereoCenters.has(edge.to)) {
                                edge.type = edge.type === 'down' ? 'stereoBack' : 'stereoFront';
                                unassignedStereoCenters.delete(edge.from);
                                cleared = true;
                                //to is the stereo center, edge: to -> from
                            } else if (!unassignedStereoCenters.has(edge.from)) {
                                edge.type = edge.type === 'down' ? 'stereoBackReverse' :
                                    'stereoFrontReverse';
                                unassignedStereoCenters.delete(edge.to);
                                cleared = true;
                            }
                            if (cleared) {
                                unclearStereoEdges.delete(edgeId);
                            }
                        }
                    }
                });
            }
            for (const atomId of stereoCenters) {
                for (const atom of atomInfo) {
                    if (atom.id === atomId) {
                        atom.stereoCenter = true;
                    }
                }
            }
            return {
                scene: {
                    structures: [
                        {
                            structureName: 'Custom',
                            structureLabel: 'Custom',
                            structureType: 'residue',
                            id: 0,
                            atoms: atomInfo,
                            bonds: edgeInfo,
                            rings: ringInfo
                        }
                    ]
                }
            };
        } else {
            console.log('smiles parsing not successful');
            return null;
        }
    }

    translateInput(smilesString){
        let res = {
            success: false,
            atomInfo: null,
            edgeInfo: null,
        };
        const drawnAtomIds = new Set();
        //to resolve SmilesDrawer stereo ambiguity
        const unclearStereoEdges = new Set();
        const stereoCenters = new Set();
        SmilesDrawer.parse(smilesString, tree => {
            //to initiate construction of drawer graph etc
            this.smilesDrawer.draw(tree, null, null, true); //set to info only mode
            const {vertices: graphVertices, edges: graphEdges} =
                this.getSmilesDrawerGraphData();
            let atoms = [];
            let rings = {};
            for (const idx in graphVertices) {
                const {
                    id,
                    position: {x: xPos, y: yPos},
                    neighbours: neighbours,
                    value,
                    positioned
                } = graphVertices[idx];
                if (!positioned) {
                    continue;
                }
                const isAromatic = value.isPartOfAromaticRing;
                const atomRings = value.rings;
                const element = value.element;
                const atom = {
                    id: id,
                    element: element,
                    label: element === 'C' ? null : element,
                    charge: (value.bracket && value.bracket.charge)
                        ? value.bracket.charge
                        : 0,
                    hydrogenCount: (value.bracket && value.bracket.hcount)
                        ? value.bracket.hcount
                        : 'missing',
                    coordinates: {
                        x: xPos,
                        y: yPos,
                    },
                    aromatic: isAromatic,
                }
                if (element === 'H') {
                    const {
                        position: {x: xNeighbourPos, y: yNeighbourPos}
                    } = graphVertices[neighbours[0]];
                    const move = PointCalculation.createMovementBetweenTwoPoints(
                        {x: xNeighbourPos, y: yNeighbourPos},
                        {x: xPos, y: yPos}
                    );
                    const newHCoords = move.forward(VectorCalculation.getDist2d(
                        {x: xNeighbourPos, y: yNeighbourPos},
                        {x: xPos, y: yPos}
                    ) * 0.75);
                    atom.coordinates.x = newHCoords.x;
                    atom.coordinates.y = newHCoords.y;
                }
                atoms.push(atom);
                atomRings.forEach(ringId => {
                    if (!rings.hasOwnProperty(ringId)) {
                        rings[ringId] = {
                            id: ringId,
                            atoms: [id],
                        };
                    } else {
                        const ring = rings[ringId];
                        ring.atoms.push(id);
                    }
                });
                drawnAtomIds.add(id);
                if (value.isStereoCenter) {
                    stereoCenters.add(id);
                }
            }

            let edges = [];
            for (const idx in graphEdges){
                const {id, sourceId, targetId, bondType, wedge,
                    isPartOfAromaticRing} = graphEdges[idx];
                if (!drawnAtomIds.has(sourceId)
                    || !drawnAtomIds.has(targetId)) {
                    continue;
                }
                let type, valid = true;
                if (!wedge) {
                    switch (bondType) {
                        case '-':
                        case '/':
                        case '\\':
                        case ':':
                            type = 'single';
                            break;
                        case '=':
                            type = 'double';
                            break;
                        case '#':
                            type = 'triple';
                            break;
                        default: //includes (or limited to?) case '.'
                            valid = false;
                    }
                } else {
                    unclearStereoEdges.add(id);
                    if (wedge === 'up') {
                        type = 'up';
                    } else { //wedge === 'down'
                        type = 'down';
                    }
                }
                if (!valid){
                    continue;
                }
                edges.push({
                    id: id,
                    from: sourceId,
                    to: targetId,
                    type: type,
                    aromatic: isPartOfAromaticRing,
                });
            }

            res = {
                success: true,
                atomInfo: atoms,
                edgeInfo: edges,
                ringInfo: Object.values(rings),
                stereoCenters: stereoCenters,
                unclearStereoEdges: unclearStereoEdges,
            };
        }, err => {
            console.log('-----------------');
            console.log('smiles drawer error:');
            console.log(err);
            console.log('-----------------');
        });
        return res;
    }

    /*----------------------------------------------------------------------*/

    getSmilesDrawerGraphData(){
        const sd = this.smilesDrawer;
        //next part is what smilesDrawer.draw() only does if infoOnly is set to false
        sd.position(); // Restore the ring information (removes bridged rings and replaces them with the original, multiple, rings)

        sd.restoreRingInformation(); // Atoms bonded to the same ring atom

        sd.resolvePrimaryOverlaps();
        let overlapScore = sd.getOverlapScore();
        sd.totalOverlapScore = sd.getOverlapScore().total;

        for (var o = 0; o < sd.opts.overlapResolutionIterations; o++) {
            for (var i = 0; i < sd.graph.edges.length; i++) {
                let edge = sd.graph.edges[i];

                if (sd.isEdgeRotatable(edge)) {
                    let subTreeDepthA = sd.graph.getTreeDepth(edge.sourceId, edge.targetId);
                    let subTreeDepthB = sd.graph.getTreeDepth(edge.targetId, edge.sourceId); // Only rotate the shorter subtree

                    let a = edge.targetId;
                    let b = edge.sourceId;

                    if (subTreeDepthA > subTreeDepthB) {
                        a = edge.sourceId;
                        b = edge.targetId;
                    }

                    let subTreeOverlap = sd.getSubtreeOverlapScore(b, a, overlapScore.vertexScores);

                    if (subTreeOverlap.value > sd.opts.overlapSensitivity) {
                        let vertexA = sd.graph.vertices[a];
                        let vertexB = sd.graph.vertices[b];
                        let neighboursB = vertexB.getNeighbours(a);

                        if (neighboursB.length === 1) {
                            let neighbour = sd.graph.vertices[neighboursB[0]];
                            let angle = neighbour.position.getRotateAwayFromAngle(vertexA.position, vertexB.position, 2.0944);
                            sd.rotateSubtree(neighbour.id, vertexB.id, angle, vertexB.position); // If the new overlap is bigger, undo change

                            let newTotalOverlapScore = sd.getOverlapScore().total;

                            if (newTotalOverlapScore > sd.totalOverlapScore) {
                                sd.rotateSubtree(neighbour.id, vertexB.id, -angle, vertexB.position);
                            } else {
                                sd.totalOverlapScore = newTotalOverlapScore;
                            }
                        } else if (neighboursB.length === 2) {
                            // Switch places / sides
                            // If vertex a is in a ring, do nothing
                            if (vertexB.value.rings.length !== 0 && vertexA.value.rings.length !== 0) {
                                continue;
                            }

                            let neighbourA = sd.graph.vertices[neighboursB[0]];
                            let neighbourB = sd.graph.vertices[neighboursB[1]];

                            if (neighbourA.value.rings.length === 1 && neighbourB.value.rings.length === 1) {
                                // Both neighbours in same ring. TODO: does this create problems with wedges? (up = down and vice versa?)
                                if (neighbourA.value.rings[0] !== neighbourB.value.rings[0]) {
                                    continue;
                                } // TODO: Rotate circle

                            } else if (neighbourA.value.rings.length !== 0 || neighbourB.value.rings.length !== 0) {
                                continue;
                            } else {
                                let angleA = neighbourA.position.getRotateAwayFromAngle(vertexA.position, vertexB.position, 2.0944);
                                let angleB = neighbourB.position.getRotateAwayFromAngle(vertexA.position, vertexB.position, 2.0944);
                                sd.rotateSubtree(neighbourA.id, vertexB.id, angleA, vertexB.position);
                                sd.rotateSubtree(neighbourB.id, vertexB.id, angleB, vertexB.position);
                                let newTotalOverlapScore = sd.getOverlapScore().total;

                                if (newTotalOverlapScore > sd.totalOverlapScore) {
                                    sd.rotateSubtree(neighbourA.id, vertexB.id, -angleA, vertexB.position);
                                    sd.rotateSubtree(neighbourB.id, vertexB.id, -angleB, vertexB.position);
                                } else {
                                    sd.totalOverlapScore = newTotalOverlapScore;
                                }
                            }
                        }

                        overlapScore = sd.getOverlapScore();
                    }
                }
            }
        }

        sd.resolveSecondaryOverlaps(overlapScore.scores);

        if (sd.opts.isomeric) {
            sd.annotateStereochemistry();
        } // Initialize pseudo elements or shortcuts


        if (sd.opts.compactDrawing && sd.opts.atomVisualization === 'default') {
            sd.initPseudoElements();
        }

        sd.rotateDrawing(); // Set the canvas to the appropriate size

        return sd.graph;
    }
}

/* src/DataProcessing/JsonPreprocessor.js */
/**
 * Preprocesses drawer's input JSONs in various ways.
 */
class JsonPreprocessor {
    /**
     * Contains instance for data access.
     */
    constructor(sceneData) {
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Preprocesses the JSON by altering the ids of added objects (e.g. residue) so
     * that all ids are unique. This usually makes sense if there is already a
     * structure loaded and you want to add another which has no information
     * about the already loaded structure. Note that this is not done automatically
     * when adding something to the drawer.
     *
     * @param diagramString {String} - diagram string
     */
    prepJsonUIds(diagramString) {
        let diagramJson;
        try {
            diagramJson = JSON.parse(diagramString);
            //first get the highest ids of everything already drawn
            const highestDrawnIds = this.getHighestIDs();
            //Change the current ids of the JSON to new ids
            //Map old ids to new ids to change e.g. fromAtom in atomPairInteractions
            const idMaps = {
                structures: {}, atoms: {}, rings: {}, hydrophobicContacts: {}
            };
            this.changeStructureIDs(diagramJson, highestDrawnIds, idMaps);
            this.changeIntermolecularIDs(diagramJson, highestDrawnIds, idMaps);
            this.changeHydrophobicIDs(diagramJson, highestDrawnIds, idMaps);
            this.changeAnnotationIDs(diagramJson, highestDrawnIds, idMaps);
            return JSON.stringify(diagramJson);
        } catch (err) {
            console.log('Could not parse JSON:');
            console.log(err);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines for each draw object type the highest used id.
     *
     * @return {Object} - highest used ids for all draw object types
     */
    getHighestIDs() {
        const highestDrawnIds = {
            structures: -1,
            atoms: -1,
            bonds: -1,
            rings: -1,
            ringsystems: -1,
            distances: -1,
            interactions: -1,
            atomPairInteractions: -1,
            piStackings: -1,
            cationPiStackings: -1,
            hydrophobicContacts: -1,
            annotations: -1
        };
        for (const structure of Object.values(this.sceneData.structuresData.structures)) {
            highestDrawnIds.structures = Math.max(highestDrawnIds.structures, structure.id);
            highestDrawnIds.atoms = Math.max(highestDrawnIds.atoms, ...structure.atomsData.atomIds);
            highestDrawnIds.bonds = Math.max(highestDrawnIds.bonds,
                ...Object.keys(structure.edgesData.edgeById).map(Number)
            );
            highestDrawnIds.rings = Math.max(highestDrawnIds.rings,
                ...Object.keys(structure.ringsData.rings).map(Number)
            );
            highestDrawnIds.ringsystems = Math.max(highestDrawnIds.ringsystems,
                ...Object.keys(structure.ringsData.ringSystems).map(Number)
            );
        }
        highestDrawnIds.atomPairInteractions =
            Math.max(highestDrawnIds.atomPairInteractions
                ,...Object.keys(this.sceneData.intermolecularData.atomPairInteractions)
                .map(Number));
        highestDrawnIds.piStackings =
            Math.max(highestDrawnIds.piStackings,
                ...Object.keys(this.sceneData.intermolecularData.piStackings)
                .map(Number));
        highestDrawnIds.cationPiStackings =
            Math.max(...Object.keys(this.sceneData.intermolecularData.cationPiStackings)
                .map(Number));
        highestDrawnIds.distances =
            Math.max(highestDrawnIds.distances,
                ...Object.keys(this.sceneData.intermolecularData.distances)
                .map(Number));
        highestDrawnIds.interactions =
            Math.max(highestDrawnIds.interactions,
                ...Object.keys(this.sceneData.intermolecularData.interactions)
                .map(Number));
        highestDrawnIds.hydrophobicContacts =
            Math.max(highestDrawnIds.hydrophobicContacts,
                ...Object.keys(this.sceneData.hydrophobicData.hydrophobicContacts)
                .map(Number));
        highestDrawnIds.annotations =
            Math.max(highestDrawnIds.annotations,
                ...Object.keys(this.sceneData.annotationsData.annotations)
                .map(Number));
        return highestDrawnIds;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adapts structure ids to the currently highest used one such that
     * no id is used multiple times.
     */
    changeStructureIDs(diagramJson, highestDrawnIds, idMaps) {
        if (diagramJson.scene.hasOwnProperty('structures')) {
            diagramJson.scene.structures.forEach(function (mol, mIdx) {
                idMaps.structures[mol.id] = ++highestDrawnIds.structures;
                this[mIdx].id = idMaps.structures[mol.id];

                if (this[mIdx].hasOwnProperty('atoms')) {
                    mol.atoms.forEach(function (atom, aIdx) {
                        idMaps.atoms[atom.id] = ++highestDrawnIds.atoms;
                        this[aIdx].id = idMaps.atoms[atom.id];
                    }, diagramJson.scene.structures[mIdx].atoms)
                }

                if (this[mIdx].hasOwnProperty('bonds')) {
                    mol.bonds.forEach(function (bond, bIdx) {
                        this[bIdx].id = ++highestDrawnIds.bonds;
                        this[bIdx].from = idMaps.atoms[bond.from];
                        this[bIdx].to = idMaps.atoms[bond.to];
                    }, diagramJson.scene.structures[mIdx].bonds)
                }

                if (this[mIdx].hasOwnProperty('rings')) {
                    mol.rings.forEach(function (ring, rIdx) {
                        idMaps.rings[ring.id] = ++highestDrawnIds.rings;
                        this[rIdx].id = idMaps.rings[ring.id];
                        this[rIdx].atoms = ring.atoms.map(id => idMaps.atoms[id]);
                    }, diagramJson.scene.structures[mIdx].rings)
                }

                if (this[mIdx].hasOwnProperty('ringsystems')) {
                    mol.ringsystems.forEach(function (sys, sIdx) {
                        this[sIdx].id = ++highestDrawnIds.ringsystems;
                        this[sIdx].atoms = sys.atoms.map(id => idMaps.atoms[id]);
                    }, diagramJson.scene.structures[mIdx].ringsystems)
                }

            }, diagramJson.scene.structures);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adapts ids of a given intermolecular type to the currently highest used one
     * such that no id is used multiple times.
     */
    changeIntermolecularTypeIDs(json, highestDrawnIds, idMaps, type, fromMap, toMap) {
        if (json.scene.hasOwnProperty(type)) {
            json.scene[type].forEach(function (intermolecular, idx) {
                this[idx].id = ++highestDrawnIds[type];
                if (idMaps.structures.hasOwnProperty(intermolecular.fromStructure)) {
                    this[idx].fromStructure = idMaps.structures[intermolecular.fromStructure];
                }
                if (idMaps.structures.hasOwnProperty(intermolecular.toStructure)) {
                    this[idx].toStructure = idMaps.structures[intermolecular.toStructure];
                }
                if (idMaps[fromMap].hasOwnProperty(intermolecular.from)) {
                    this[idx].from = idMaps[fromMap][intermolecular.from];
                }
                if (idMaps[toMap].hasOwnProperty(intermolecular.to)) {
                    this[idx].to = idMaps[toMap][intermolecular.to];
                }
            }, json.scene[type]);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adapts ids of all intermolecular types to the currently highest used ones
     * such that no id is used multiple times.
     */
    changeIntermolecularIDs(diagramJson, highestDrawnIds, idMaps) {
        this.changeIntermolecularTypeIDs(diagramJson,
            highestDrawnIds,
            idMaps,
            'atomPairInteractions',
            'atoms',
            'atoms'
        );
        this.changeIntermolecularTypeIDs(diagramJson,
            highestDrawnIds,
            idMaps,
            'piStackings',
            'rings',
            'rings'
        );
        this.changeIntermolecularTypeIDs(diagramJson,
            highestDrawnIds,
            idMaps,
            'cationPiStackings',
            'rings',
            'atoms'
        );
        this.changeIntermolecularTypeIDs(diagramJson,
            highestDrawnIds,
            idMaps,
            'distances',
            'annotations',
            'annotations'
        );
        this.changeIntermolecularTypeIDs(diagramJson,
            highestDrawnIds,
            idMaps,
            'interactions',
            'annotations',
            'annotations'
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adapts ids of hydrophobic contacts to the currently highest used one
     * such that no id is used multiple times.
     */
    changeHydrophobicIDs(diagramJson, highestDrawnIds, idMaps) {
        if (diagramJson.scene.hasOwnProperty('hydrophobicContacts')) {
            diagramJson.scene.hydrophobicContacts.forEach(function (hydro, hIdx) {
                idMaps.hydrophobicContacts[hydro.id] = ++highestDrawnIds.hydrophobicContacts;
                this[hIdx].id = idMaps.hydrophobicContacts[hydro.id];
                if (idMaps.structures.hasOwnProperty(hydro.belongsTo)) {
                    this[hIdx].belongsTo = idMaps.structures[hydro.belongsTo];

                    hydro.controlPoints.forEach(function (cp, cIdx) {
                        if (cp.hasOwnProperty('atomLinks')) {
                            this[cIdx].atomLinks = cp.atomLinks.map(id => idMaps.atoms[id]);
                        }
                    }, diagramJson.scene.hydrophobicContacts[hIdx].controlPoints)
                }

            }, diagramJson.scene.hydrophobicContacts);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adapts ids of annotations to the currently highest used one
     * such that no id is used multiple times.
     */
    changeAnnotationIDs(diagramJson, highestDrawnIds, idMaps) {
        if (diagramJson.scene.hasOwnProperty('annotations')) {
            diagramJson.scene.annotations.forEach(function (anno, aIdx) {
                this[aIdx].id = ++highestDrawnIds.annotations;
                if (anno.belongsTo && idMaps.structures.hasOwnProperty(anno.belongsTo.id)) {
                    this[aIdx].belongsTo.id = idMaps.structures[anno.belongsTo.id];
                    if (this[aIdx].belongsTo.hasOwnProperty('atomLinks')) {
                        this[aIdx].belongsTo.atomLinks = this[aIdx].belongsTo.atomLinks
                            .map(id => idMaps.atoms[id]);
                    }
                }
            }, diagramJson.scene.annotations);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Preprocesses the JSON by moving all objects to the top left corner or
     * to specified coordinates of the current view area.
     *
     * @param diagramString {String} - diagram as string
     * @param coords {Object|optional} - coordinates to move diagram to
     * @return {String} - the string in JSON format with moved diagram
     */
    prepJsonCoordinates(diagramString, coords = undefined) {
        let diagramJson;
        try {
            diagramJson = JSON.parse(diagramString);
            const [moveX, moveY] = this.getMoveXY(diagramJson, coords);
            this.moveXY(diagramJson, moveX, moveY);
            return JSON.stringify(diagramJson);
        } catch (err) {
            console.log('Could not parse JSON:');
            console.log(err);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Preprocesses the JSON by moving all objects next to the currently loaded diagram(s) and
     * by altering the ids of added objects so that all ids are unique. This is only done, when
     * another diagram is already loaded
     *
     * @param diagramString {String} - diagram as string
     * @return {String} - the string in JSON format with moved diagram
     */
    prepAdditionalJsonCoordinatesUIds(diagramString, coords = undefined) {
        if (!this.sceneData.structuresData.structureLoaded) {
            return diagramString;
        }
        let diagramJson;
        try {
            diagramJson = JSON.parse(diagramString);
            //the center of the new diagram
            const diagramCenter = this.getDiagramCenter(diagramJson);
            //the mid point of the current scene
            const sceneMid = this.sceneData.globalLimits.mid;
            //move the center of the new diagramJson to the center of the current scene
            this.moveXY(
                diagramJson,
                diagramCenter.x - sceneMid.x,
                diagramCenter.y - sceneMid.y
            );
            //move to the left including some excess space in between the two diagrams
            this.moveXY(
                diagramJson,
                this.sceneData.globalLimits.width * 0.55,
                0
            );
            const moveLeftX = this.getDiagramWidthXright(diagramJson);
            this.moveXY(
                diagramJson,
                moveLeftX * 1.05,
                0
            );
            return this.prepJsonUIds(JSON.stringify(diagramJson));
        } catch (err) {
            console.log('Could not parse JSON:');
            console.log(err);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines necessary movement for the top left corner of the current view area or for
     * specific coordinates if given.
     *
     * @param diagramJson {Object} - diagram as object
     * @param coords {Object} - coordinates to move JSON objects to
     * @return {Array} - x and y coordinates
     */
    getMoveXY(diagramJson, coords = undefined) {
        let {xMin: drawerMinX, yMin: drawerMinY} = this.sceneData.globalLimits;
        if (coords) {
            drawerMinX = coords.x;
            drawerMinY = coords.y;
        }
        let minX = Infinity;
        let minY = Infinity;

        if (diagramJson.scene.hasOwnProperty('structures')) {
            diagramJson.scene.structures.forEach(function (mol) {
                if (mol.hasOwnProperty('atoms')) {
                    mol.atoms.forEach(function (atom) {
                        const coords = atom.coordinates;
                        if (minX > coords.x) minX = coords.x;
                        if (minY > coords.y) minY = coords.y;
                    })
                }
            });
        }

        if (diagramJson.scene.hasOwnProperty('hydrophobicContacts')) {
            diagramJson.scene.hydrophobicContacts
                .forEach(function (hydro) {
                    hydro.controlPoints.forEach(function (cp) {
                        if (minX > cp.x) minX = cp.x;
                        if (minY > cp.y) minY = cp.y;
                    })
                });
        }

        if (diagramJson.scene.hasOwnProperty('annotations')) {
            diagramJson.scene.annotations.forEach(function (anno) {
                const coords = anno.coordinates;
                if (minX > coords.x) minX = coords.x;
                if (minY > coords.y) minY = coords.y;
            });
        }

        const moveX = minX - drawerMinX;
        const moveY = minY - drawerMinY;
        return [moveX, moveY];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Executes the movement of a diagram by a specified length in x and y directions.
     *
     * @param diagramJson {Object} - diagram as object
     * @param moveX {Number} - movement length on x axis
     * @param moveY {Number} - movement length on y axis
     */
    moveXY(diagramJson, moveX, moveY) {
        if (diagramJson.scene.hasOwnProperty('structures')) {
            diagramJson.scene.structures.forEach(function (mol, mIdx) {
                if (mol.hasOwnProperty('atoms')) {
                    mol.atoms.forEach(function (atom, aIdx) {
                        this[aIdx].coordinates.x -= moveX;
                        this[aIdx].coordinates.y -= moveY;
                    }, diagramJson.scene.structures[mIdx].atoms)
                }
            });
        }

        if (diagramJson.scene.hasOwnProperty('hydrophobicContacts')) {
            diagramJson.scene.hydrophobicContacts
                .forEach(function (hydro, hIdx) {
                    hydro.controlPoints.forEach(function (cp, cIdx) {
                        this[cIdx].x -= moveX;
                        this[cIdx].y -= moveY;
                    }, diagramJson.scene.hydrophobicContacts[hIdx].controlPoints)
                });
        }

        if (diagramJson.scene.hasOwnProperty('annotations')) {
            diagramJson.scene.annotations.forEach(function (anno, aIdx) {
                this[aIdx].coordinates.x -= moveX;
                this[aIdx].coordinates.y -= moveY;
            }, diagramJson.scene.annotations);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines right extension of a diagram on the x axis with respect to its the midpoint.
     *
     * @param diagramJson {Object} - diagram as object
     * @return {Number} - extension of the diagram on the x axis
     */
    getDiagramWidthXright(diagramJson) {
        let xRight = undefined;
        const coordinates = [];

        if (diagramJson.scene.hasOwnProperty('structures')) {
            diagramJson.scene.structures.forEach(function (mol) {
                if (mol.hasOwnProperty('atoms')) {
                    mol.atoms.forEach(function (atom) {
                        const coords = atom.coordinates;
                        if (!xRight) {
                            xRight = coords.x;
                        } else if (xRight < coords.x) {
                            xRight = coords.x;
                        }
                        coordinates.push(coords);
                    })
                }
            });
        }

        if (diagramJson.scene.hasOwnProperty('hydrophobicContacts')) {
            diagramJson.scene.hydrophobicContacts
                .forEach(function (hydro) {
                    hydro.controlPoints.forEach(function (cp) {
                        if (!xRight) {
                            xRight = cp.x;
                        } else if (xRight < cp.x) {
                            xRight = cp.x;
                        }
                        coordinates.push({x: cp.x, y: cp.y});
                    })
                });
        }

        if (diagramJson.scene.hasOwnProperty('annotations')) {
            diagramJson.scene.annotations.forEach(function (anno) {
                const coords = anno.coordinates;
                if (!xRight) {
                    xRight = coords.x;
                } else if (xRight < coords.x) {
                    xRight = coords.x;
                }
                coordinates.push(coords);
            });
        }
        const geometricCenter = PointCalculation.findGeometricCenter(coordinates);
        //move to the left by this distance
        return (geometricCenter.x - xRight) * -1;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines geometric center of a diagram.
     *
     * @param diagramJson {Object} - diagram as object
     * @return {Object} - center of the diagram with x and y coordinates
     */
    getDiagramCenter(diagramJson) {
        const coordinates = [];

        if (diagramJson.scene.hasOwnProperty('structures')) {
            diagramJson.scene.structures.forEach(function (mol) {
                if (mol.hasOwnProperty('atoms')) {
                    mol.atoms.forEach(function (atom) {
                        const coords = atom.coordinates;
                        coordinates.push(coords);
                    })
                }
            });
        }

        if (diagramJson.scene.hasOwnProperty('hydrophobicContacts')) {
            diagramJson.scene.hydrophobicContacts
                .forEach(function (hydro) {
                    hydro.controlPoints.forEach(function (cp) {
                        coordinates.push({x: cp.x, y: cp.y});
                    })
                });
        }

        if (diagramJson.scene.hasOwnProperty('annotations')) {
            diagramJson.scene.annotations.forEach(function (anno) {
                const coords = anno.coordinates;
                coordinates.push(coords);
            });
        }
        return PointCalculation.findGeometricCenter(coordinates);
    }
}

/* src/DataProcessing/JsonValidator.js */
/**
 * Validates drawer's input JSON and outputs warning/error messages.
 */
class JsonValidator {
    /**
     * Contains instance for data access.
     */
    constructor(sceneData) {
        this.sceneData = sceneData;
        this.errorLogger = [];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks annotation in JSON format.
     *
     * @param labelInfo {Object} - annotation in JSON format
     * @param i {Number} - annotation index in JSON
     * @param jsonKey {String} - name of the field in the input
     * @returns {Boolean} - false if input is not valid
     */
    annotationJSONerror(labelInfo, i, jsonKey) {
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        if (this.checkJSONStructure(labelInfo,
            jsonKey,
            i,
            this.sceneData.annotationsData.annotations,
            errPrefix,
            true
        ).error) {
            return true;
        }

        const belongsTo = labelInfo.belongsTo;

        //further sanity checks
        if (belongsTo) {
            let errMsg = '';
            const belongsPrefix = 'Field "belongsTo": ';
            let validSid = true;
            if (!this.sceneData.structuresData.structures.hasOwnProperty(belongsTo.id)) {
                errMsg += belongsPrefix + '"id" does not match any ' + 'structure!';
                validSid = false;
            }
            if (!['structure', 'structureSpline']
                .includes(belongsTo.type)) {
                if (errMsg) errMsg += ' ';
                errMsg += belongsPrefix + '"type" must match ' +
                    'either "structure" or "structureSpline"!'
            }
            if (validSid && belongsTo.hasOwnProperty('atomLinks')) {
                const badAtomLinks = [];
                const checkStructure = this.sceneData.structuresData.structures[belongsTo.id];
                belongsTo.atomLinks.forEach((atomLink, i) => {
                    if (!checkStructure.atomsData.atomIds.includes(atomLink)) {
                        badAtomLinks.push(i);
                    }
                });
                if (badAtomLinks.length) {
                    if (errMsg) errMsg += ' ';
                    errMsg += belongsPrefix + `"atomLinks" contains ` +
                        `references to non-existing atom` +
                        `${badAtomLinks.length > 1 ? 's' : ''} (` +
                        `position${badAtomLinks.length > 1 ? 's' : ''}` +
                        ` ${badAtomLinks.join(', ')})`;
                }
            }

            if (errMsg) {
                console.log(errPrefix + errMsg);
                this.errorLogger.push(errPrefix + errMsg);
                return true;
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks hydrophobic contact in JSON format.
     *
     * @param hydrophobicInfo {Object} - hydrophobic contact in JSON format
     * @param i {Number} - hydrophobic contact index in JSON
     * @param jsonKey {String} - name of the field in the input
     * @returns {Boolean} - false if input is not valid
     */
    hydrophobicJSONerror(hydrophobicInfo, i, jsonKey) {
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        //set container parameter to false here to prevent the unique id
        //error message because we can add control points to a existing
        //hydrophobic contact
        if (this.checkJSONStructure(hydrophobicInfo, jsonKey, i, false, errPrefix, true).error) {
            return true;
        }
        const {
            belongsTo: belongsTo, controlPoints: controlPoints
        } = hydrophobicInfo;

        //further sanity checks
        if (!this.sceneData.structuresData.structures.hasOwnProperty(belongsTo)) {
            const error = errPrefix + 'Field "belongsTo" does not ' + 'refer to a valid structure!';
            console.log(error);
            this.errorLogger.push(error);
            return true;
        }
        const structure = this.sceneData.structuresData.structures[belongsTo];
        const badAtomLinks = {};
        controlPoints.forEach((cpInfo, cpPos) => {
            if (cpInfo.hasOwnProperty('atomLinks')) {
                cpInfo.atomLinks.forEach((atomLink, linkPos) => {
                    if (!structure.atomsData.atomIds.includes(atomLink)) {
                        if (!badAtomLinks.hasOwnProperty(cpPos)) {
                            badAtomLinks[cpPos] = [];
                        }
                        badAtomLinks[cpPos].push(linkPos);
                    }
                });
            }
        });
        let errMsg = '';
        for (const cpPos in badAtomLinks) {
            if (errMsg) errMsg += ' ';
            errMsg += `Field "control points": "[${cpPos}]": ` +
                `"atomLinks" contains references to non-existing atom` +
                `${badAtomLinks[cpPos].length > 1 ? 's' : ''} ` +
                `(position${badAtomLinks[cpPos].length > 1 ? 's' : ''} ` +
                `${badAtomLinks[cpPos].join(', ')})!`;
        }
        if (errMsg) {
            console.log(errPrefix + errMsg);
            this.errorLogger.push(errPrefix + errMsg);
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks by intermolecular edge connected structures in JSON format.
     *
     * @param interactionInfo {Object} - intermolecular edge in JSON format
     * @param i {Number} - intermolecular edge index in JSON
     * @param jsonKey {String} - name of the field in the input
     * @returns {Boolean} - false if input is not valid
     */
    intermolecularMolJSONerror(interactionInfo, i, jsonKey) {
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        if (this.checkJSONStructure(interactionInfo,
            jsonKey,
            i,
            this.sceneData.intermolecularData[jsonKey],
            errPrefix,
            true
        ).error) {
            return true;
        }

        let errMsg = '';
        if (!interactionInfo.fromStruct) {
            errMsg += `Field "fromStructure" does not refer to a valid ` + `structure!`;
        }
        if (!interactionInfo.toStruct) {
            if (errMsg) errMsg += ' ';
            errMsg += `Field "toStructure" does not refer to a valid ` + `structure!`;
        }
        if (errMsg) {
            console.log(errPrefix + errMsg);
            this.errorLogger.push(errPrefix + errMsg);
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks intermolecular edge end point in JSON format.
     *
     * @param interactionInfo {Object} - intermolecular edge in JSON format
     * @param i {Number} - intermolecular edge index in JSON
     * @param jsonKey {String} - name of the field in the input
     * @returns {Boolean} - false if input is not valid
     */
    intermolecularEndPointJSONerror(interactionInfo, i, jsonKey) {
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        let errMsg = '';
        if (!interactionInfo.fromObj) {
            errMsg = errPrefix + `Structure ${interactionInfo.fromStructure} does not ` +
                `contain an interaction endpoint with ID ${interactionInfo.from}!`;
        }
        if (!interactionInfo.toObj) {
            if (errMsg) errMsg += ' ';
            errMsg +=
                `Structure ${interactionInfo.toStructure} does not contain an interaction endpoint with ` +
                `with ID ${interactionInfo.to}!`;
        }
        if (errMsg) {
            console.log(errPrefix + errMsg);
            this.errorLogger.push(errPrefix + errMsg);
            return true;
        }
        if (jsonKey !== 'distances' && jsonKey !== 'interactions' &&
            interactionInfo.fromStructure === interactionInfo.toStructure &&
            interactionInfo.from === interactionInfo.to) {
            const endpointsErrorMsg = errPrefix + 'The two given endpoint ids are the same!';
            console.log(endpointsErrorMsg);
            this.errorLogger.push(endpointsErrorMsg);
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks structure in JSON format.
     *
     * @param structureInfo {Object} - structure in JSON format
     * @param i {Number} - structure index in JSON
     * @returns {Boolean} - false if input is not valid
     */
    structureJSONerror(structureInfo, i) {
        const jsonKey = 'structures';
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        if (this.checkJSONStructure(structureInfo,
            jsonKey,
            i,
            this.sceneData.structuresData.structures,
            errPrefix,
            true
        ).error) {
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks structure content (atoms, bonds) in JSON format.
     *
     * @param structureInfo {Object} - structure in JSON format
     * @param i {Number} - structure index in JSON
     * @returns {Boolean} - false if input is not valid
     */
    structureNestedJSONerror(structureInfo, i) {
        const jsonKey = 'structures';
        const errPrefix = JsonValidator.createErrorPrefixByIdx(jsonKey, i);
        //sanity checks on all relevant fields
        //assumes that prop name in structure info is same as in JSON base!
        let errOccurred = false;
        let errMsg = '';
        const handleError = (msg) => {
            if (errOccurred) errMsg += ' ';
            errMsg += msg;
            errOccurred = true;
        };
        //structure is only build if no errors in JSON -> use dummy containers
        const atomContainer = {};

        //sanity check atoms
        this.checkStructureContentJSONerror(structureInfo, 'atoms', (i) => {
            return `Field atoms at position ${i}: `
        }, handleError, atomContainer);
        //sanity check bonds
        const createPrefixBonds = (i) => {
            return `Field "bonds" at position ${i}: `;
        };
        if (!this.checkStructureContentJSONerror(structureInfo,
            'bonds',
            createPrefixBonds,
            handleError,
            {}
        )) {
            structureInfo.bonds.forEach(({from, to, type}, i) => {
                let errMsg = '';
                if (from === to) {
                    errMsg += 'Fields "from" and "to" are the same!';
                }
                if (!atomContainer.hasOwnProperty(from)) {
                    if (errMsg) errMsg += ' ';
                    errMsg += 'Field "from" does not match any atom!';
                }
                if (!atomContainer.hasOwnProperty(to)) {
                    if (errMsg) errMsg += ' ';
                    errMsg += 'Field "to" does not match any atom!';
                }
                if (errMsg) {
                    handleError(createPrefixBonds(i) + errMsg);
                }
            });
        }
        //prepare checking of atom ids in arrays (rings)
        const checkAtomArr = (ringObj, createPrefix, idx) => {
            const badIdxs = [];
            ringObj.atoms.forEach((atomId, i) => {
                if (!atomContainer.hasOwnProperty(atomId)) badIdxs.push(i);
            });
            if (badIdxs.length) {
                handleError(createPrefix(idx) + 'Given atoms do not match ' +
                    `any atom (at positions ${badIdxs.join(', ')}).`);
            }
        };
        //sanity check rings
        if (structureInfo.rings) {
            const createPrefixRings = (i) => {
                return `Field rings at position ${i}: `;
            };
            if (!this.checkStructureContentJSONerror(structureInfo,
                'rings',
                createPrefixRings,
                handleError,
                {}
            )) {
                structureInfo.rings.forEach((ringInfo, i) => {
                    checkAtomArr(ringInfo, createPrefixRings, i);
                });
            }
        }
        //sanity check ring systems
        if (structureInfo.ringsystems) {
            const createPrefixRingSys = (i) => {
                return `Field ringsystems at position ${i}: `;
            };
            if (!this.checkStructureContentJSONerror(structureInfo,
                'ringsystems',
                createPrefixRingSys,
                handleError,
                {}
            )) {
                structureInfo.ringsystems.forEach((ringSysInfo, i) => {
                    checkAtomArr(ringSysInfo, createPrefixRingSys, i);
                });
            }
        }
        //log accumulated error message
        if (errOccurred) {
            console.log(errPrefix + errMsg);
            this.errorLogger.push(errPrefix + errMsg);
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks a certain object type of a structure in JSON format.
     *
     * @param structureInfo {Object} - structure in JSON format
     * @param jsonKey {String} - name of the Structure object type field (e.g. "atoms")
     * in the input
     * @param createPrefixFn {Function} - creates the prefix for an error message
     * @param handleError {Function} - tracks error and extends error message
     * @param container {Object} - container object in which the drawer saves
     * new elements based on information from the input object
     * @returns {Boolean} - false if input is not valid
     */
    checkStructureContentJSONerror(structureInfo, jsonKey, createPrefixFn, handleError, container) {
        const jsonArr = structureInfo[jsonKey];
        let {error, msg} = this.checkJSONStructureArray(jsonArr, jsonKey, false);
        if (error) { //ignore original msg
            handleError(`Field ${jsonKey} is not an Array!`);
            return true;
        }
        let errFound = false;
        jsonArr.forEach((jsonObj, i) => {
            ({error, msg} = this.checkJSONStructure(jsonObj, jsonKey, i, container, '', false));
            if (error) {
                errFound = true;
                handleError(createPrefixFn(i) + msg);
                return;
            }
            container[jsonObj.id] = true;
        });
        return errFound;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether one of the fields given in an input object to create a new
     * scene in the draw area is an array. If not, create an error message
     * based on the name of the property.
     *
     * @param jsonArray {*} - variable to check whether it is an array
     * @param jsonKey {String} - name of the field in the input
     * @param logError {Boolean} - whether to immediately log the error when
     * the given input is not an array
     * @returns {Object} - report of the error: whether an error occurred
     * (field "error") and the related error message (field "msg")
     */
    checkJSONStructureArray(jsonArray, jsonKey, logError = true) {
        const report = {
            error: false, msg: ''
        };
        const name = JSONSceneStructure[jsonKey]().ref;
        //check if given JSON array is actually array
        if (!Array.isArray(jsonArray)) {
            report.error = true;
            report.msg = `Skipped drawing of ${name}s: must be given in form ` + `of an Array!`;
        }
        if (logError && report.error) {
            console.log(report.msg);
            this.errorLogger.push(report.msg)
        }
        return report;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether the structure and types of fields of a given object
     * present in the input object to create a new scene matches the expected
     * structure and types of fields as logged in JSON_Base_Structures.js.
     * Return information on possible mismatches.
     *
     * @param jsonToCheck {Object} - object to check
     * @param jsonKey {String} - name of the field in which the object is
     * located
     * @param idx {Number} - position of the checked object in the array the
     * field maps to
     * @param container {Object} - container object in which the drawer saves
     * new elements based on information from the input object
     * @param errPrefix {String} - prefix for an error message
     * @param logError {Boolean} - whether to immediately log the error when
     * the given input does not match the expected structure or types
     * @returns {Object} - report of the error: whether an error occurred
     * (field "error") and the related error message (field "msg")
     */
    checkJSONStructure(jsonToCheck, jsonKey, idx, container, errPrefix = '', logError = true) {
        const report = {
            error: false, msg: '', missing: [], badTypes: []
        };
        //sanity check given parameters
        if (jsonToCheck.constructor.name !== 'Object') {
            report.error = true;
            report.msg = 'Not an Object.';
        }
        //compare given structure with correct structure blueprint
        const correctJson = JSONSceneStructure[jsonKey]();
        if (!report.error) {
            this.recCompareObjectStructures(jsonToCheck, correctJson, report);
        }
        //check uniqueness of id in given container
        if (!report.error && container) {
            if (container.hasOwnProperty(jsonToCheck.id)) {
                report.error = true;
                report.msg = 'ID is not unique!';
            }
        }
        //finalize error message and log to console if requested
        if (report.error) {
            report.msg = errPrefix + report.msg;
            if (logError) {
                console.log(report.msg);
                this.errorLogger.push(report.msg);
            }
        }
        return report;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Recursively compares the structure and types of fields of a given input
     * object with a blueprint of the expected structure.
     *
     * @param jsonToCheck {Object} - the object to check
     * @param correctJson {Object} - the blueprint to check against
     * @param report {Object} - report of the error: whether an error occurred
     * (field "error") and the related error message (field "msg")
     */
    recCompareObjectStructures(jsonToCheck, correctJson, report) {
        //during check, log which properties are missing or of wrong type
        //start of recursion check
        this.recursiveJSONcheck(report, jsonToCheck, correctJson.required, [], false);
        if (correctJson.hasOwnProperty('optional')) {
            this.recursiveJSONcheck(report, jsonToCheck, correctJson.optional, [], true);
        }

        //construct error message after recursion check is done
        const mLen = report.missing.length;
        const btLen = report.badTypes.length;
        if (!mLen && !btLen) { //structure okay, shortcut return
            return;
        }
        let errMsg = '';
        const reducePredArr = (predArr) => {
            const len = predArr.length;
            return predArr.reduce((accStr, prop, i) => {
                return accStr + `\"${prop}\"${i < len - 1 ? ': ' : ''}`;
            }, '');
        };
        if (mLen) {
            errMsg += 'Missing the following fields: ';
            errMsg += Helpers.orderedStringFromArr(report.missing.map(predArr => {
                return reducePredArr(predArr);
            }));
        }
        if (btLen) {
            if (mLen) errMsg += ' ';
            errMsg += 'Fields have wrong type: ';
            errMsg += Helpers.orderedStringFromArr(report.badTypes.map(({props, reqType}) => {
                const propString = reducePredArr(props);
                return `${propString} (should be ${reqType})`;
            }));
        }
        report.error = true;
        report.msg = errMsg;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Recursive step that compares the structure and types of fields of a
     * given input object with a blueprint of the expected structure.
     *
     * @param report {Object} - report of the error: whether an error occurred
     * (field "error") and the related error message (field "msg")
     * @param jsonToCheck {Object} - the object to check
     * @param correctJson {Object} - the blueprint to check against
     * @param predArr {Array} - array of properties to check
     * @param optional {Boolean} - whether the entry is optional
     */
    recursiveJSONcheck(report, jsonToCheck, correctJson, predArr, optional = false) {
        for (const prop in correctJson) {
            //add prop to currently checked chain of properties
            const extArr = predArr.slice();
            extArr.push(prop);
            //check if property exists in provided JSON
            if (!jsonToCheck.hasOwnProperty(prop)) {
                if (!optional && !correctJson[prop].isOptional) {
                    report.missing.push(extArr);
                }
                continue;
            }

            //type checking initialisation
            const curVal = jsonToCheck[prop];
            let corVal = correctJson[prop];
            const curType = (curVal === null) ? null : curVal.constructor.name;
            let corType = (corVal === null) ? null : corVal.constructor.name;
            const compareTypes = () => {
                if (curType !== corType) {
                    report.badTypes.push({
                        props: extArr, reqType: corType
                    });
                    return false;
                }
                return true;
            };

            //special helper types first
            //duck typing for JSONChoice class as uglify strips class name
            if (corVal.isChoice) {
                const {typeMatches, typeChoices} = JsonValidator.checkTypes(corVal,
                    curVal,
                    curType,
                    corType
                );
                if (!typeMatches) {
                    report.badTypes.push({
                        props: extArr, reqType: typeChoices
                    });
                    continue;
                }
                //duck typing for SpecificString class
            } else if (corVal.isSpecificString) {
                if (!corVal.checkString(curVal)) {
                    report.badTypes.push({
                        props: extArr, reqType: corVal.stringsToChoice()
                    });
                    continue;
                }
                //duck typing for JSONOptional class
            } else if (corVal.isOptional) {
                corVal = corVal.value;
                corType = (corVal === null) ? null : corVal.constructor.name;
                if (!compareTypes()) continue;
            } else {
                if (!compareTypes()) continue;
            }
            this.nextRecursiveCheck(report, curVal, corVal, corType, extArr);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks and compares with blueprint structure and types of fields of JSON object.
     *
     * @param report {Object} - report of the error: whether an error occurred
     * (field "error") and the related error message (field "msg")
     * @param curVal {*} - value in the JSON that has to be checked
     * @param corVal {*} - value in the blueprint
     * @param corType {*} - type in the blueprint
     * @param extArr {*} -
     */
    nextRecursiveCheck(report, curVal, corVal, corType, extArr) {
        //recursion for objects
        if (corType === 'Object') {
            this.recursiveJSONcheck(report, curVal, corVal, extArr, false);
        }
        //recursion for arrays
        if (corType === 'Array') {
            const blueprint = corVal[0];
            corType = blueprint.constructor.name;
            curVal.forEach((nextVal, i) => {
                const itArr = extArr.slice();
                itArr.push(`[${i}]`);
                if (corType !== 'Object' && nextVal.constructor.name !== corType) {
                    report.badTypes.push({
                        props: itArr, reqType: corType
                    });
                    return;
                }
                this.recursiveJSONcheck(report, nextVal, blueprint, itArr, false);
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks and compares JSON type of field with type in the blueprint.
     *
     * @param corVal {*} - value in the JSON that has to be checked
     * @param curVal {*} - value in the blueprint
     * @param curType {*} - type in the JSON that has to be checked
     * @param corType {*} - type in the blueprint
     */
    static checkTypes(corVal, curVal, curType, corType) {
        const choices = corVal.choices;
        let typeMatches = false;
        let typeChoices = '';
        for (let i = 0; i < choices.length; ++i) {
            corVal = choices[i];
            //duck typing for SpecificStrings class
            if (corVal && corVal.isSpecificString) {
                if (corVal.checkString(curVal)) {
                    typeMatches = true;
                    break;
                } else {
                    if (i !== 0) typeChoices += '|';
                    typeChoices += corVal.stringsToChoice();
                    continue;
                }
            }
            corType = choices[i] === null ? null : choices[i].constructor.name;
            if (curType === corType) {
                typeMatches = true;
                break;
            } else {
                if (i !== 0) typeChoices += '|';
                typeChoices += corType
            }
        }
        return {typeMatches, typeChoices};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the prefix for an error message when checking the entries of a
     * specific array in the input object to create a new scene in the draw
     * area.
     *
     * @param jsonKey {String} - name of the field in which checked entries
     * are located
     * @param idx {Number} - position of the checked object in the array
     * @returns {String} - the prefix
     */
    static createErrorPrefixByIdx(jsonKey, idx) {
        const name = JSONSceneStructure[jsonKey]().ref;
        return `Skipped drawing of ${name} at Array position ${idx}: `;
    }
}


/* src/DataProcessing/RemoveCollector.js */
/**
 * Collects from the loaded structural data draw objects that are to remove from the draw area.
 */
class RemoveCollector {
    /**
     * Contains instance for the data storage/access and configuration options.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     */
    constructor(opts, sceneData) {
        this.opts = opts;
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which items should be removed from the draw area by user input.
     *
     * @param structures {Array|Set} - ids of structure to completely remove
     * @param atoms {Array|Set} - ids of atoms to remove
     * @param edges {Array|Set} - ids of bonds to remove
     * @param annotations {Array|Set} - ids of annotations to remove
     * @param atomPairInteractions {Array|Set} - ids of atom pair interactions to remove
     * @param piStackings {Array|Set} - ids of pi stackings to remove
     * @param cationPiStackings {Array|Set} - ids of cation pi stackings to remove
     * @param hydrophobicContacts {Array|Set} - ids of hydrophobic contacts to remove
     * Those are objects which have 'id' as key and can optional have specified
     * control points (key 'controlPoints', values as array of ids) to only remove
     * those
     */
    determineRemoveObjects({
        structures,
        atoms,
        edges,
        annotations,
        atomPairInteractions,
        piStackings,
        cationPiStackings,
        hydrophobicContacts
    }) {
        const remStructures = new Set(structures);
        const remAtoms = new Set(atoms);
        const remEdges = new Set(edges);
        const remAnnotations = new Set(annotations);
        const remAtomPairInteractions = new Set(atomPairInteractions);
        const remPiStackings = new Set(piStackings);
        const remCationPiStackings = new Set(cationPiStackings);
        const remHydrophobicContacts = new Set(hydrophobicContacts);
        //will be filled later
        const remRings = new Set();
        //Remove a structure if all of its atoms should be removed
        //key as structure id, value as numbers of atoms to remove from structure
        const atomCountMap = {};
        const structuresData = this.sceneData.structuresData;
        RemoveCollector.getAtomsToRemove(structuresData, remAtoms, atomCountMap);
        RemoveCollector.getStructuresToRemove(structuresData, remStructures, atomCountMap);
        RemoveCollector.getHydrophobicAnnotationsToRemove(structuresData,
            remAnnotations,
            remHydrophobicContacts,
            remStructures,
            remAtoms
        );
        RemoveCollector.getRingsToRemove(structuresData, remRings, remAtoms);
        const intermolecularData = this.sceneData.intermolecularData;
        RemoveCollector.determineIntermolecularToRemove(intermolecularData.atomPairInteractions,
            remAtoms,
            remAtoms,
            remStructures,
            remAtomPairInteractions
        );
        RemoveCollector.determineIntermolecularToRemove(intermolecularData.piStackings,
            remRings,
            remRings,
            remStructures,
            remPiStackings
        );
        RemoveCollector.determineIntermolecularToRemove(intermolecularData.cationPiStackings,
            remRings,
            remAtoms,
            remStructures,
            remCationPiStackings
        );
        //process hydrophobic contacts so that no id is present more than once
        const hContacts = {};
        for (const {id, controlPoints} of remHydrophobicContacts) {
            if (!hContacts.hasOwnProperty(id)) {
                hContacts[id] = {
                    completeRemove: false, controlPoints: new Set()
                }
            }
            if (controlPoints) {
                hContacts[id].completeRemove = false;
                Helpers.mergeIntoSet(hContacts[id].controlPoints, controlPoints);
            } else {
                hContacts[id].completeRemove = true;
            }
        }
        remHydrophobicContacts.clear();
        for (const [id, val] of Object.entries(hContacts)) {
            const remContact = {
                id: id
            };
            if (!val.completeRemove) {
                remContact.controlPoints = [...val.controlPoints];
            }
            remHydrophobicContacts.add(remContact);
        }
        return {
            remStructures,
            remAtoms,
            remEdges,
            remAnnotations,
            remAtomPairInteractions,
            remPiStackings,
            remCationPiStackings,
            remHydrophobicContacts
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which atoms should be removed from the draw area.
     *
     * @param structuresData {Object} - ids of structure to completely remove
     * @param remAtoms {Set} - ids of atoms to remove
     * @param atomCountMap {Object} - counter for nr. of atoms to remove from structure
     */
    static getAtomsToRemove(structuresData, remAtoms, atomCountMap) {
        for (const atomId of remAtoms) {
            if (!structuresData.atomIdsToStructure.hasOwnProperty(atomId)) {
                continue;
            }

            const structureId = structuresData.atomIdsToStructure[atomId];
            if (!atomCountMap.hasOwnProperty(structureId)) {
                atomCountMap[structureId] = 0;
            }
            ++atomCountMap[structureId];
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which structures should be removed from the draw area.
     *
     * @param structuresData {Object} - ids of structure to completely remove
     * @param remStructures {Set} - ids of structures to remove
     * @param atomCountMap {Object} - counter for nr. of atoms to remove from structure
     */
    static getStructuresToRemove(structuresData, remStructures, atomCountMap) {
        for (const [structureId, remAtomCount] of Object.entries(atomCountMap)) {
            if (!structuresData.structures.hasOwnProperty(structureId)) {
                continue;
            }

            if (remAtomCount === structuresData.structures[structureId].atomsData.atomIds.length) {
                remStructures.add(structureId);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which annotations and hydrophobic contacts should be removed from the draw area.
     *
     * @param structuresData {Object} - ids of structure to completely remove
     * @param remAnnotations {Set} - ids of annotations to remove
     * @param remHydrophobicContacts {Set} - ids of hydrophobic contacts to remove
     * @param remStructures {Set} - ids of structures to remove
     * @param remAtoms {Set} - ids of atoms to remove
     */
    static getHydrophobicAnnotationsToRemove(structuresData,
        remAnnotations,
        remHydrophobicContacts,
        remStructures,
        remAtoms
    ) {
        //set annotations and hydrophobic contacts to remove from
        //structures to completely remove
        //also delete atoms and bonds to remove which are part of a structure
        //to delete because structure deletion is handled all at once.
        for (const structureId of remStructures) {
            if (!structuresData.structures.hasOwnProperty(structureId)) {
                continue;
            }
            const structure = structuresData.structures[structureId];
            Helpers.mergeIntoSet(remAnnotations, structure.annotationConnectionData.annotations);
            Helpers.mergeIntoSet(remHydrophobicContacts,
                Object.keys(structure.hydrophobicConnectionData.hydrophobicConts)
                    .map(id => ({id: id}))
            );
            Helpers.deleteFromSet(remAtoms, structure.atomsData.atomIds);
            Helpers.deleteFromSet(remAtoms, Object.values(structure.edgesData.edgeIdByIdx));
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which rings should be removed from the draw area.
     *
     * @param structuresData {Object} - ids of structure to completely remove
     * @param remRings {Set} - ids of rings to remove
     * @param remAtoms {Set} - ids of atoms to remove
     */
    static getRingsToRemove(structuresData, remRings, remAtoms) {
        //determine rings to remove. This is used to determine
        //(cation-)pi-stackings to remove.
        for (const structure of Object.values(structuresData.structures)) {
            for (const ring of Object.values(structure.ringsData.rings)) {
                let removeRing = true;
                for (const atom of Object.values(ring.atoms)) {
                    if (!remAtoms.has(atom.id)) {
                        removeRing = false;
                        break;
                    }
                }
                if (removeRing) {
                    remRings.add(ring.id);
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines which intermolecular edges of a certain type should be removed
     * from the draw area.
     *
     * @param container {Array} - data container of the intermolecular edge type
     * @param remFrom {Set} - ids of start points to remove
     * @param remTo {Set} - ids of end points to remove
     * @param remStruc {Set} - structures to remove
     * @param remInter {Set} - collects ids of intermolecular edges to remove
     */
    static determineIntermolecularToRemove(container, remFrom, remTo, remStruc, remInter) {
        for (const [id, intermolecular] of Object.entries(container)) {
            if (remFrom.has(intermolecular.from) || remTo.has(intermolecular.to) ||
                remStruc.has(intermolecular.fromStructure) ||
                remStruc.has(intermolecular.toStructure)) {
                remInter.add(id);
            }
        }
    }
}

/* src/DataProcessing/StructureVisitor.js */
/**
 * Does DFS over the data of a structure executing callbacks.
 */
class StructureVisitor {
    /**
     * Contains atom and edge data of a structure.
     *
     * @param atomsData {AtomsData} - atom data of a structure
     * @param edgesData {EdgesData} - edge data of a structure
     */
    constructor(atomsData, edgesData) {
        this.atomsData = atomsData;
        this.edgesData = edgesData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Generic function to do DFS over the atoms of this structure. Executes
     * callback on each traversed atom. Optional parameters to define callbacks
     * at many different points of the DFS, to exclude certain atoms, and to
     * determine order of traversal.
     *
     * @param atomCallback {Function} - callback to execute on atom visits
     * @param edgeCallback {Function} - callback to execute on edge visits
     * @param backEdgeCallback {Function} - callback to execute on back edges
     * (unvisited edges back to visited atoms)
     * @param newStartCallback {Function} - callback to execute when DFS
     * starts over (on new connected component)
     * @param finalizeCallback {Function} - callback at the end of DFS
     * @param multiEdgeVisitCallback {Function} - callback on edges which
     * have already been visited
     * @param determineNbSorting {Function} - callback to sort neighbors of
     * atoms
     * @param startIds {Array} - optionally defined DFS start points. Defaults
     * to all atom ids of the structure
     * @param excludedAtoms {Set} - atoms to exclude from DFS visits
     */
    dfs({
        atomCallback,
        edgeCallback,
        backEdgeCallback,
        newStartCallback,
        finalizeCallback,
        multiEdgeVisitCallback,
        determineNbSorting,
        startIds,
        excludedAtoms
    } = {}) {
        const visited = {};
        const edgeVisited = new Set();
        this.atomsData.atoms.forEach(({id: atomId}) => {
            visited[atomId] = (!!excludedAtoms && excludedAtoms.has(atomId));
        });
        const backedges = new Set();

        const dfsVisit = (atomId, parentId) => {
            visited[atomId] = true;
            if (atomCallback) {
                const atom = this.atomsData.getAtom(atomId);
                const parent = this.atomsData.getAtom(parentId);
                if (atomCallback(atom, parent) === false) {
                    return;
                }
            }

            let neighborSorting;
            if (determineNbSorting) {
                const atom = this.atomsData.getAtom(atomId);
                const parent = this.atomsData.getAtom(parentId);
                neighborSorting = determineNbSorting(atom, parent);
            }
            const sortedNeighbors = neighborSorting ?
                this.atomsData.neighbors[atomId].sort(neighborSorting) :
                this.atomsData.neighbors[atomId];
            sortedNeighbors.forEach(({neighbor: nbId, edgeId}) => {
                if (nbId === parentId) { //parent id may be undefined
                    return;
                }
                //mark unseen edges, return to prevent double callbacks
                if (edgeVisited.has(edgeId)) {
                    if (multiEdgeVisitCallback) {
                        multiEdgeVisitCallback(atomId, nbId, this.edgesData.getEdge(edgeId));
                    }
                    return;
                } else {
                    edgeVisited.add(edgeId);
                }

                //proceed on unseen neighbors and/or do callbacks on edges/back edges
                if (!visited[nbId]) {
                    if (edgeCallback) {
                        const edge = this.edgesData.getEdge(edgeId);
                        if (edgeCallback(atomId, nbId, edge) === false) {
                            return;
                        }
                    }
                    dfsVisit(nbId, atomId);
                } else if (backEdgeCallback) {
                    const edge = this.edgesData.getEdge(edgeId);
                    //back edge, so no further recursion and no return value
                    backEdgeCallback(atomId, nbId, edge);
                    backedges.add(edgeId);
                }
            });
        };

        if (!startIds) {
            startIds = [this.atomsData.atoms[0].id];
        }
        let i = 0;
        startIds.forEach(atomId => {
            if (!this.atomsData.atomById.hasOwnProperty(atomId)) {
                console.log(`Can not start from atom: ${atomId} ` +
                    `(no such atom exists in structure).`);
                return;
            }
            if (!visited[atomId]) {
                if (newStartCallback) {
                    const atom = this.atomsData.getAtom(atomId);
                    newStartCallback(atom, i++);
                }
                dfsVisit(atomId, undefined);
            }
        });

        if (finalizeCallback) {
            finalizeCallback(visited, edgeVisited);
        }
    }
}

/* src/DataProcessing/TextBuilder.js */
/**
 * Converts currently stored data to a string representation.
 */
class TextBuilder {
    /**
     * Contains instances for data access and configuration options.
     *
     * @param sceneData {Object} - data storage
     */
    constructor(sceneData) {
        this.sceneData = sceneData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the interaction data of the draw area and then returns it as string.
     *
     * @returns {Object} - blob of serialized interaction data
     */
    getInteractionsText() {
        let text = '';
        text += 'Interactions:\n\n';
        for (const type of ['atomPairInteractions', 'cationPiStackings', 'piStackings']) {
            for (const interactionId in this.sceneData.intermolecularData[type]) {
                const interaction = this.sceneData.intermolecularData[type][interactionId];
                if (!interaction.enabled) {
                    continue;
                }
                const structures = this.sceneData.structuresData.structures;
                const fromStructure = structures[interaction.fromStructure];
                const toStructure = structures[interaction.toStructure];
                let from, to;
                if (type === "atomPairInteractions") {
                    let firstType = "";
                    let secondType = "";
                    from = fromStructure.atomsData.getAtom(interaction.from);
                    to = toStructure.atomsData.getAtom(interaction.to);
                    if (from.isMetal() || to.isMetal()) {
                        if ((!from.additionalInformation || !from.additionalInformation.infileId) ||
                            (!to.additionalInformation || !to.additionalInformation.infileId)) {
                            continue;
                        }
                        text += "Metal interaction";
                        text += ": ";
                    } else if ((from.charge > 0 && to.charge < 0) ||
                        (from.charge < 0 && to.charge > 0)) {
                        if ((!from.additionalInformation || !from.additionalInformation.infileId) ||
                            (!to.additionalInformation || !to.additionalInformation.infileId)) {
                            continue;
                        }
                        if (from.charge > 0 && to.charge < 0) {
                            firstType = "Cation";
                            secondType = "Anion";
                        } else if (from.charge < 0 && to.charge > 0) {
                            firstType = "Anion";
                            secondType = "Cation";
                        }
                        text += "Ionic interaction";
                        text += ": ";
                    } else if (from.isHydrogen()) {
                        from = fromStructure.atomsData.getAtom(
                            fromStructure.atomsData.neighbors[from.id][0].neighbor)
                        if ((!from.additionalInformation || !from.additionalInformation.infileId) ||
                            (!to.additionalInformation || !to.additionalInformation.infileId)) {
                            continue;
                        }
                        text += "Hydrogen bond";
                        text += ": ";
                        firstType = "Donor";
                        secondType = "Acceptor";
                    } else if (to.isHydrogen()) {
                        to = toStructure.atomsData.getAtom(
                            toStructure.atomsData.neighbors[to.id][0].neighbor)
                        if ((!from.additionalInformation || !from.additionalInformation.infileId) ||
                            (!to.additionalInformation || !to.additionalInformation.infileId)) {
                            continue;
                        }
                        text += "Hydrogen bond";
                        text += ": ";
                        secondType = "Donor";
                        firstType = "Acceptor";
                    } else {
                        continue;
                    }
                    text +=
                        firstType + " " +
                        from.additionalInformation.infileId + ":" +
                        from.additionalInformation.atomName + " (" +
                        fromStructure.structureLabel + ") "
                        + "- " +
                        secondType + " " +
                        to.additionalInformation.infileId + ":" +
                        to.additionalInformation.atomName + " (" +
                        toStructure.structureLabel + ")";
                    text += '\n';
                } else if (type === "cationPiStackings") {
                    from = fromStructure.ringsData.rings[interaction.from];
                    to = toStructure.atomsData.getAtom(interaction.to);
                    for (const atom of from.atoms) {
                        if (!atom.additionalInformation || !atom.additionalInformation.infileId) {
                            continue;
                        }
                    }
                    if (!to.additionalInformation || !to.additionalInformation.infileId) {
                        continue;
                    }
                    text += "Cation-pi interaction";
                    text += ": ";
                    const ringAtoms = [];
                    for (const atom of from.atoms) {
                        ringAtoms.push(atom.additionalInformation.infileId +
                            ":" + atom.additionalInformation.atomName);
                    }
                    text += ringAtoms.join(";");
                    text += " (" + fromStructure.structureLabel + ") ";
                    text += "- ";
                    text += to.additionalInformation.infileId + ":" +
                        to.additionalInformation.atomName + " (" + toStructure.structureLabel + ")";
                    text += '\n';
                } else if (type === "piStackings") {
                    from = fromStructure.ringsData.rings[interaction.from];
                    to = toStructure.ringsData.rings[interaction.to];
                    for (const atom of from.atoms) {
                        if (!atom.additionalInformation  || !atom.additionalInformation.infileId) {
                            continue;
                        }
                    }
                    for (const atom of to.atoms) {
                        if (!atom.additionalInformation  || !atom.additionalInformation.infileId) {
                            continue;
                        }
                    }
                    text += "Pi-pi interaction";
                    text += ": ";
                    const ringAtomsFrom = [];
                    for (const atom of from.atoms) {
                        ringAtomsFrom.push(atom.additionalInformation.infileId +
                            ":" + atom.additionalInformation.atomName);
                    }
                    const ringAtomsTo = [];
                    for (const atom of from.atoms) {
                        ringAtomsTo.push(atom.additionalInformation.infileId +
                            ":" + atom.additionalInformation.atomName);
                    }
                    text += ringAtomsFrom.join(";");
                    text += " (" + fromStructure.structureLabel + ") ";
                    text += "- ";
                    text += ringAtomsTo.join(";");
                    text += " (" + toStructure.structureLabel + ") ";
                    text += '\n';
                }
            }
        }
        text += "\nHydrophobic Contacts:\n\n"
        for (const annotationId in this.sceneData.annotationsData.annotations) {
            const annotation = this.sceneData.annotationsData.annotations[annotationId];
            if (annotation.type === 'structureSpline' && annotation.enabled) {
                text += annotation.label;
                text += '\n';
            }
        }
        return text;
    }
}

/* src/Drawers/AnnotationDrawer.js */
/**
 * Drawer that uses its own component for the visualization of annotations.
 */
class AnnotationDrawer {
    /**
     * Contains instances for JSON validation, configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     * A selection callback can be set optionally.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param annotationGroupsComponent {Object} - component for annotations
     * @param textLabelDrawer {Object} - drawer for generic text labels
     * @param jsonValidator {Object} - validates input JSON
     */
    constructor(opts, sceneData, annotationGroupsComponent, textLabelDrawer, jsonValidator) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.annotationGroupsComponent = annotationGroupsComponent;
        this.textLabelDrawer = textLabelDrawer;
        this.jsonValidator = jsonValidator;
        this.closestObjectFinder = new ClosestObjectFinder(opts, sceneData);

        this.selectionCallback = null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the individual components of different annotations based on the
     * "annotations" field of provided scene draw information and link
     * annotations that belong to specific structures to these structures.
     * Returns the necessary Change objects to remove and re-add these
     * components.
     *
     * @param labelInfos {Array} - draw information for the different
     * annotations to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {undefined|Array} - Change objects for the next history step
     */
    applyAddAnnotations(labelInfos, globalMaxes) {
        const jsonKey = 'annotations';
        if (this.jsonValidator.checkJSONStructureArray(labelInfos, jsonKey, true).error) {
            return;
        }
        //apply add for each given info
        const addChanges = [];
        labelInfos.forEach((labelInfo, i) => {
            if (this.jsonValidator.annotationJSONerror(labelInfo, i, jsonKey)) {
                return;
            }
            this.createNewAnnotation(labelInfo, globalMaxes, addChanges);
        });
        return addChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds an annotation to data an draw area.
     *
     * @param labelInfo {Object} - draw information of annotation to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addChanges {Object} - collects Change objects for history
     */
    createNewAnnotation(labelInfo, globalMaxes, addChanges) {
        //create annotation and reference in memory
        const {
            id: labelId,
            label,
            coordinates,
            color: labelColor,
            belongsTo,
            isStructureLabel,
            additionalInformation
        } = labelInfo;
        const color = labelColor ? labelColor : this.opts.colors.DEFAULT;
        let structureLink;
        let atomLinks = [];
        let type;
        let belongsToStructure = false;
        if (belongsTo) {
            structureLink = belongsTo.id;
            atomLinks = belongsTo.atomLinks ? belongsTo.atomLinks : [];
            type = belongsTo.type;
            belongsToStructure = true;
        }
        const annotation = new Annotation({
            id: labelId,
            label: label,
            coordinates: coordinates,
            color: color,
            structureLink: structureLink,
            atomLinks: atomLinks,
            type: type,
            belongsToStructure: belongsToStructure,
            hidden: false,
            isStructureLabel: isStructureLabel,
            additionalInformation: additionalInformation
        });
        this.sceneData.annotationsData.annotations[labelId] = annotation;

        //check context of annotation
        if (belongsTo) {
            let {type, id, atomLinks} = belongsTo;
            switch (type) {
                case 'structureSpline':
                    //special color takes precedence
                    annotation.color = this.opts.colors.hydrophobicContacts;
                //FALLTHROUGH!
                case 'structure':
                    const structure = this.sceneData.structuresData.structures[id];
                    structure.annotationConnectionData.addAnnotation(labelId);
                    if (!atomLinks) {
                        atomLinks = [
                            this.closestObjectFinder.getClosestEnabledAtom(
                                annotation.coordinates,
                                [structure.id]).id
                        ];
                    }
                    if (atomLinks) {
                        new Set(atomLinks).forEach(atomLink => {
                            structure.annotationConnectionData.linkAtomToAnnotation(atomLink,
                                labelId
                            );
                        });
                        annotation.atomLinks = atomLinks;
                    }
                    break;
            }
        }
        if (belongsTo) {
            this.annotationGroupsComponent.drawLabel(annotation, belongsTo.id);
            this.addAltCoordsToAnnotation(annotation);
        } else {
            this.annotationGroupsComponent.drawLabel(annotation);
        }
        annotation.setDrawLimits(this.getAnnotationDrawLimits(annotation),
            this.annotationGroupsComponent.getLabelDrawLimits(annotation.id)
        );
        annotation.setSelectorShapes(this.annotationGroupsComponent.getLabelSelShapes(labelId));
        const {xMin, xMax, yMin, yMax} = annotation.globalDrawLimits;
        globalMaxes.setMaxesAdd(xMin, xMax, yMin, yMax);
        addChanges.push(this.createRemoveChangeAnnotation(labelId));
        //keep track of original to reset later
        this.sceneData.annotationsData.originalAnnotations[labelId] = annotation.clone();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds alternative coordinates to the annotation depending on the
     * allowed representations for the linked structure.
     *
     * @param annotation {Object} - annotation to add the coordinates to
     */
    addAltCoordsToAnnotation(annotation) {
        if (!annotation.hasOwnProperty('structureLink') ||
            !this.sceneData.structuresData.structures.hasOwnProperty(annotation.structureLink) ||
            annotation.isStructureLabel) {
            return;
        }
        const linkedStructureId = annotation.structureLink;
        const linkedStructure = this.sceneData.structuresData.structures[linkedStructureId];
        const representationInfo = {};
        representationInfo[StructureRepresentation.default] = {
            coordinates: Object.assign({}, annotation.coordinates)
        };
        if (linkedStructure.representationsData.hasRepresentation(StructureRepresentation.circle)) {
            const structureCircle = linkedStructure.representationsData.structureCircle;
            if (linkedStructure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
                const maxes = this.annotationGroupsComponent.getAnnotationMinMax(annotation.id);
                const {dist, relativePosition} = PolygonCalculation.getClosestPointOnRectangle(structureCircle.coordinates,
                    maxes
                );
                representationInfo[StructureRepresentation.circle] = {
                    coordinates: Object.assign({}, annotation.coordinates),
                    distToCircleMid: dist,
                    circleMidIsInside: relativePosition === RelativePosition.inside
                }
            } else {
                //radius around the circle where to draw the annotations on
                const rad = structureCircle.rad * 1.1;
                //init one possible position for the annotation as the position
                //right above the structure circle
                const startCoord = {
                    x: structureCircle.coordinates.x, y: structureCircle.coordinates.y - rad
                };
                this.setAnnotationPositionWithoutOverlap(structureCircle,
                    representationInfo,
                    annotation,
                    linkedStructureId,
                    startCoord,
                    rad
                );
                //if no position without overlap could be found take the position
                //above the circle
                if (!representationInfo.hasOwnProperty(StructureRepresentation.circle)) {
                    representationInfo[StructureRepresentation.circle] = {
                        coordinates: Object.assign({}, startCoord),
                        distToCircleMid: rad,
                        circleMidIsInside: false
                    }
                }
            }
        }
        annotation.structureRepresentationInfo = representationInfo;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Greedy algorithm to determine a position where this annotation
     * does not overlap with another annotation linked to this structure.
     *
     * @param structureCircle {Object} - info about the structure circle the annotation belongs to
     * @param representationInfo {Object} - info about the current structure representation
     * @param annotation {Object} - annotation to modify the coordinates
     * @param linkedStructureId {Object} - id of structure the annotation belongs to
     * @param startCoord {Object} - possible position for the annotation right above the
     * structure circle
     * @param rad {Object} - radius around the circle where to draw the annotations on
     */
    setAnnotationPositionWithoutOverlap(structureCircle,
        representationInfo,
        annotation,
        linkedStructureId,
        startCoord,
        rad
    ) {
        //calculate the width and height of this annotation
        const {height, width} = this.textLabelDrawer.getTextDimensions(annotation.label);
        //least amount of space between annotations
        const spaceBetween = height;
        //already present annotations to check against
        const checkAgainstCoords = Object.values(this.sceneData.annotationsData.annotations)
            .filter(anno => anno.enabled && anno.structureLink === linkedStructureId &&
                anno.structureRepresentationInfo.hasOwnProperty(StructureRepresentation.circle))
            .map(anno => {
                return {
                    coords: anno.structureRepresentationInfo[StructureRepresentation.circle].coordinates, //height and width of BBox
                    ...this.textLabelDrawer.getTextDimensions(anno.label)
                }
            });
        //bounding rect. Note that coords are in the middle and
        //not at bottom right like with BBox
        //checks if an overlap exists between the current position to
        //evaluate and one of the existing annotations
        const isOverlapping = (curCoords) => {
            const curRect = PolygonCalculation.boundingRectangle({
                height, width, coords: curCoords
            });
            for (const checkAgainst of checkAgainstCoords) {
                const checkRect = PolygonCalculation.boundingRectangle(checkAgainst);
                if (curRect.xMin - spaceBetween < checkRect.xMax && checkRect.xMin - spaceBetween <
                    curRect.xMax && curRect.yMin - spaceBetween < checkRect.yMax && checkRect.yMin -
                    spaceBetween < curRect.yMax) {
                    return true;
                }
            }
            return false;
        };
        //loop through possible positions until one is found that does not
        //overlap
        //take 10 times the max possible annotations without overlap, this
        //works well in practice
        const maxPositions = 10 * 2 * (rad + 2 * height) / height;
        const angleStep = 360 / maxPositions;
        //angle = 0 means the annotation is drawn just vertically above
        let angle = 0;
        while (angle < 360) {
            const evalCoords = PolygonCalculation.rotateRectangleAroundPoint(startCoord,
                PolygonCalculation.boundingRectangle({
                    height: height, width: width, coords: startCoord
                }),
                structureCircle.coordinates,
                angle,
                rad,
                false
            );

            if (!isOverlapping(evalCoords)) {
                representationInfo[StructureRepresentation.circle] = {
                    coordinates: Object.assign({}, evalCoords),
                    distToCircleMid: rad,
                    circleMidIsInside: false
                };
                break;
            }
            angle += angleStep;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Retrieves the saved bbox draw limits of the text element of a label.
     * If the label has any alternative coordinates includes those in the draw
     * limits.
     *
     * @param annotation {Object} - annotation to get the draw limits for
     */
    getAnnotationDrawLimits(annotation) {
        const extendBoundary = (maxBoundary, minBoundary, includeVal, origVal) => {
            const ret = {
                min: minBoundary, max: maxBoundary
            };

            if (includeVal !== origVal) { //if same boundaries do not change
                const dist = Math.abs(origVal - includeVal);
                if (includeVal < origVal) { //change boundaries min
                    ret.min = minBoundary - dist;
                } else { //change boundaries max
                    ret.max = maxBoundary + dist;
                }
            }

            return ret;
        };

        const {xMin, xMax, yMin, yMax} = this.annotationGroupsComponent.getLabelDrawLimits(
            annotation.id)[0]['limits'];
        const {x: origX, y: origY} = annotation.coordinates;
        const boundaries = {
            xMins: [xMin], xMaxs: [xMax], yMins: [yMin], yMaxs: [yMax]
        };

        for (const info of Object.values(annotation.structureRepresentationInfo)) {
            const {x: repX, y: repY} = info.coordinates;
            const xBoundaries = extendBoundary(xMax, xMin, repX, origX);
            boundaries.xMins.push(xBoundaries.min);
            boundaries.xMaxs.push(xBoundaries.max);

            const yBoundaries = extendBoundary(yMax, yMin, repY, origY);
            boundaries.yMins.push(yBoundaries.min);
            boundaries.yMaxs.push(yBoundaries.max);
        }

        return [
            {
                limits: {
                    xMin: Math.min(...boundaries.xMins),
                    xMax: Math.max(...boundaries.xMaxs),
                    yMin: Math.min(...boundaries.yMins),
                    yMax: Math.max(...boundaries.yMaxs)
                }
            }
        ];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to remove/re-add an annotation.
     *
     * @param labelId {Number} - id of the annotation to remove/re-add
     * @param isAdd {Boolean} - whether the change should add the annotation as its
     * apply() or revert() function
     * @returns {Change} - Change object to apply/revert removal
     */
    createRemoveChangeAnnotation(labelId, isAdd = true) {
        const labelChange = new Change();
        const annotation = this.sceneData.annotationsData.annotations[labelId];
        const selectedAnnotations = this.sceneData.annotationsData.selectedAnnotations;
        const wasSelected = selectedAnnotations.has(labelId);
        const remove = () => {
            annotation.enabled = false;
            this.annotationGroupsComponent.removeLabelFromDOM(labelId);
            selectedAnnotations.delete(labelId);
        };
        const readd = () => {
            annotation.enabled = true;
            this.annotationGroupsComponent.redrawLabel(labelId);
        };
        if (isAdd) {
            labelChange.bindApply(readd);
            labelChange.bindRevert(remove);
        } else {
            labelChange.bindApply(remove);
            labelChange.bindRevert(readd);
        }
        return labelChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves a single annotation specified by id based on given offsets.
     *
     * @param labelId {Number} - unique id of the annotation to move
     * @param offset {Object} - x- and y-offsets to move draw elements by
     * @param byTemp {Boolean}- whether movement is temporary or not
     */
    moveAnnotation(labelId, offset, byTemp = true) {
        const annotation = this.sceneData.annotationsData.annotations[labelId];
        annotation.addOffsetToCoords(offset, byTemp);
        this.annotationGroupsComponent.moveLabel(labelId, offset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the bbox draw limits of the text element of an annotation and its selection shape.
     *
     * @param annotation {Annotation} - Annotation object
     */
    updateAnnotationLimitsSelectors(annotation) {
        annotation.setDrawLimits(this.getAnnotationDrawLimits(annotation),
            this.annotationGroupsComponent.getLabelDrawLimits(annotation.id)
        );
        annotation.setSelectorShapes(this.annotationGroupsComponent.getLabelSelShapes(annotation.id),
            false
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the coordinates of a single annotation to new values.
     *
     * @param labelId {Number} - id of the annotation to move
     * @param annotationChange {Object} - contains x- and y-coordinates of the
     * new position as value of key "coordinates" and at key "structureMoved"
     * true if the linked structure (if any) was moved as well
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {Array} - Change objects for the next history step
     */
    applyCoordinateChangesAnnotation(labelId, annotationChange, globalMaxes) {
        const annotation = this.sceneData.annotationsData.annotations[labelId];
        const oldCoords = annotation.coordinates;
        if (annotationChange.newCoords &&
            PointCalculation.coordsAlmostEqual(oldCoords, annotationChange.newCoords)) {
            return [];
        }

        const labelChanges = [];
        labelChanges.push(this.updateAnnotationCoordinates(annotation, annotationChange));

        //update draw limits and selector shapes
        const oldDrawLimits = Object.assign({}, annotation.globalDrawLimits);
        annotation.setSelectorShapes(this.annotationGroupsComponent.getLabelSelShapes(annotation.id),
            false
        );
        annotation.setDrawLimits(this.getAnnotationDrawLimits(annotation),
            this.annotationGroupsComponent.getLabelDrawLimits(annotation.id)
        );
        const newDrawLimits = annotation.globalDrawLimits;

        //update global boundaries
        globalMaxes.updateMaxesByLimits(oldDrawLimits, newDrawLimits);

        const limitChange = new Change();
        const changeLimits = () => {
            annotation.setSelectorShapes(this.annotationGroupsComponent.getLabelSelShapes(labelId),
                false
            );
            annotation.setDrawLimits(this.getAnnotationDrawLimits(annotation),
                this.annotationGroupsComponent.getLabelDrawLimits(annotation.id)
            );
        };
        limitChange.bindApplyRevert(changeLimits);
        labelChanges.push(limitChange);

        return labelChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Function to move a annotation to new coordinates. Returns the change
     * object to apply/revert this coordinate change. If no new coordinates
     * are available, apply changes to the structureRepresentationInfo
     * so that no actual coordination changes happen.
     * This is (and should) only be used for mirror interaction mode.
     * Returns the Change object to apply/revert the change.
     *
     * @param annotation {Object} - the annotation's container object
     * @param annotationChange {Object} - information about the coordination change
     * @returns {Change} - Change object to apply/revert movement
     */
    updateAnnotationCoordinates(annotation, annotationChange) {
        const {id: annotationId, coordinates: oldCoords, structureLink} = annotation;
        const {
            newCoords,
            structureMoved,
            interactionMode,
            newAltRotCoords,
            oldAltRotCoords,
            oldStructureMid
        } = annotationChange;
        const structure = this.sceneData.structuresData.structures.hasOwnProperty(structureLink) ?
            this.sceneData.structuresData.structures[structureLink] : undefined;
        const structureRep = structure ? structure.representationsData.curRepresentation() :
            undefined;
        const structureMid = structure ? structure.boundaries.mid : undefined;
        let dimensions = undefined;
        let fullOffsets = undefined;
        let invertedOffsets = undefined;
        if (newCoords) {
            dimensions = this.annotationGroupsComponent.getLabelBBox(annotationId);
            const curOffsets = {
                x: newCoords.x - annotation.tempCoordinates.x,
                y: newCoords.y - annotation.tempCoordinates.y
            };
            fullOffsets = {
                x: newCoords.x - oldCoords.x, y: newCoords.y - oldCoords.y
            };
            invertedOffsets = {
                x: -fullOffsets.x, y: -fullOffsets.y
            };
            this.updateContainerAndMoveAnnotation(annotation, newCoords, curOffsets);
        }
        //for NOW: update coordinates in relation to previous temp movement
        annotation.updateAlternativeRepresentationCoords(structureRep,
            structureMoved,
            fullOffsets,
            interactionMode,
            newAltRotCoords,
            structureMid,
            oldStructureMid,
            dimensions
        );
        //for HISTORY: add change based on full movements since last step
        const coordChange = new Change();
        const moveFunction = (moveBack) => {
            const curStructureRep = this.sceneData.structuresData.structures.hasOwnProperty(
                structureLink) ?
                this.sceneData.structuresData.structures[structureLink].representationsData.curRepresentation() :
                undefined;
            const oldAltCoords = annotation.structureRepresentationInfo.hasOwnProperty(
                curStructureRep) ? Object.assign({},
                annotation.structureRepresentationInfo[curStructureRep].coordinates
            ) : undefined;
            if (moveBack) {
                annotation.updateAlternativeRepresentationCoords(structureRep,
                    structureMoved,
                    invertedOffsets,
                    interactionMode,
                    oldAltRotCoords,
                    oldStructureMid,
                    structureMid,
                    dimensions
                );
            } else {
                annotation.updateAlternativeRepresentationCoords(structureRep,
                    structureMoved,
                    fullOffsets,
                    interactionMode,
                    newAltRotCoords,
                    structureMid,
                    oldStructureMid,
                    dimensions
                );
            }
            if (newCoords && (Object.keys(annotation.structureRepresentationInfo).length === 0 ||
                structureRep === curStructureRep)) {
                const moveToCoords = moveBack ? oldCoords : newCoords;
                const moveToOffset = moveBack ? invertedOffsets : fullOffsets;
                this.updateContainerAndMoveAnnotation(annotation, moveToCoords, moveToOffset);
            } else if (newCoords || (curStructureRep === StructureRepresentation.circle &&
                annotation.structureRepresentationInfo.hasOwnProperty(curStructureRep))) {
                const newAltCoords = annotation.structureRepresentationInfo[curStructureRep].coordinates;
                if (PointCalculation.coordsAlmostEqual(oldAltCoords, newAltCoords)) {
                    return;
                }
                const offs = VectorCalculation.vectorSubstract(newAltCoords, oldAltCoords);
                this.updateContainerAndMoveAnnotation(annotation, newAltCoords, offs);
            }
        };
        coordChange.bindApply(moveFunction, false);
        coordChange.bindRevert(moveFunction, true);
        return coordChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Function to move a annotation to new coordinates and update its data container.
     *
     * @param annotation {Object} - the annotation's container object
     * @param coords {Object} - new coordinates
     * @param offsets {Object} - x- and y-offsets to move annotation by
     */
    updateContainerAndMoveAnnotation(annotation, coords, offsets) {
        annotation.tempCoordinates = Object.assign({}, coords);
        annotation.coordinates = Object.assign({}, coords);
        this.annotationGroupsComponent.moveLabel(annotation.id, offsets);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified annotations in the draw area.
     *
     * @param remAnnotations {Set} - ids of annotations to remove
     * @param remChanges {Array} - Change objects for the history step
     * @param markRequiredRecalcs {Function} - function to memory changes in
     * structure/scene boundaries
     */
    removeAnnotations(remAnnotations, remChanges, markRequiredRecalcs) {
        remAnnotations.forEach(annotationId => {
            if (!this.sceneData.annotationsData.annotations.hasOwnProperty(annotationId)) {
                return;
            }

            const annotation = this.sceneData.annotationsData.annotations[annotationId];
            //filter already removed
            if (!annotation.enabled) {
                return;
            }
            const {xMin, xMax, yMin, yMax} = annotation.globalDrawLimits;
            markRequiredRecalcs('xMin', xMin);
            markRequiredRecalcs('xMax', xMax);
            markRequiredRecalcs('yMin', yMin);
            markRequiredRecalcs('yMax', yMax);
            const remChange = this.createRemoveChangeAnnotation(annotationId, false);
            remChange.apply();
            remChanges.push(remChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Instructs the draw layer to unselect (= hide selection shapes) all
     * currently hovered annotations.
     */
    unselectAllAnnotations() {
        Object.keys(this.sceneData.annotationsData.annotations).forEach(labelId => {
            this.annotationGroupsComponent.unselectLabel(labelId);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates a single annotation around a given midpoint. If the linked structure
     * (if any) has circle as its current representation, the annotation rotates around the circle
     * instead to get a smother feel for the user.
     *
     * @param labelId {Number} - unique id of the annotation to rotate
     * @param angle {Number} - angle (in degree) to rotate by
     * @param midpoint {Object} - x- and y-coordinates of the point to rotate
     * the annotations around
     */
    rotateAnnotation(labelId, angle, midpoint) {
        const annotation = this.sceneData.annotationsData.annotations[labelId];
        const tempCoords = annotation.tempCoordinates;
        let newCoords;
        if (this.sceneData.structuresData.structures.hasOwnProperty(annotation.structureLink) &&
            this.sceneData.structuresData.structures[annotation.structureLink]
                .representationsData.isCurRepresentation(StructureRepresentation.circle) &&
            annotation.structureRepresentationInfo
                .hasOwnProperty(StructureRepresentation.circle)) {
            const repInfo = annotation.structureRepresentationInfo[StructureRepresentation.circle];
            newCoords = PolygonCalculation.rotateRectangleAroundPoint(tempCoords,
                this.annotationGroupsComponent.getAnnotationMinMax(annotation.id),
                this.sceneData.structuresData.structures[annotation.structureLink].representationsData.structureCircle.tempCoordinates,
                angle,
                repInfo.distToCircleMid,
                repInfo.circleMidIsInside
            );
        } else {
            newCoords = PointCalculation.rotatePointAroundAnother(annotation.tempCoordinates,
                midpoint,
                angle,
                false
            );
        }

        this.annotationGroupsComponent.moveLabel(labelId, {
            x: newCoords.x - tempCoords.x, y: newCoords.y - tempCoords.y
        });
        annotation.tempCoordinates = newCoords;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes an annotation from the DOM and the cache.
     *
     * @param labelId {Number} - the unique id of the annotation
     */
    removeAnnotationDOMCache(labelId) {
        this.annotationGroupsComponent.removeLabelFromDOM(labelId);
        this.annotationGroupsComponent.purgeLabelFromCache(labelId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers an annotation in the draw area.
     *
     * @param labelId {Number} - the unique id of the annotation
     */
    hoverAnnotation(labelId) {
        this.annotationGroupsComponent.hoverLabel(labelId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an annotation in the draw area.
     *
     * @param annotationId {Number} - id of the annotation to select
     */
    selectAnnotationDrawarea(annotationId) {
        this.annotationGroupsComponent.selectLabel(annotationId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an annotation in the draw area.
     *
     * @param annotationId {Number} - id of the annotation to unselect
     */
    unselectAnnotationDrawarea(annotationId) {
        this.annotationGroupsComponent.unselectLabel(annotationId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides all annotations in the draw area.
     *
     * @param annotations {Array} - the unique ids of the annotation
     */
    hideAnnotations(annotations) {
        this.annotationGroupsComponent.hideAnnotations(annotations);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an annotation in the draw area and mark it as selected in the annotationData
     * container.
     *
     * @param annotationId {Number} - id of the annotation to select
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    selectAnnotationDrawareaContainer(annotationId, executeCallback = true) {
        const annotation = this.sceneData.annotationsData.annotations[annotationId];
        this.sceneData.annotationsData.selectedAnnotations.add(annotationId);
        this.annotationGroupsComponent.selectLabel(annotationId);
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'annotation',
                selectionType: 'select',
                structureId: parseInt(annotation.structureLink),
                annotationId: parseInt(annotationId),
                additionalInformation: annotation.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an annotation in the draw area and remove its selection status inside
     * the annotationData container.
     *
     * @param annotationId {Number} - id of the annotation to unselect
     * @param hover {Boolean} - whether the annotation is to be shown as hovered
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectAnnotationDrawareaContainer(annotationId, hover = false, executeCallback = true) {
        const annotation = this.sceneData.annotationsData.annotations[annotationId];
        this.sceneData.annotationsData.selectedAnnotations.delete(Number(annotationId));
        if (hover) {
            this.annotationGroupsComponent.hoverLabel(annotationId);
        } else {
            this.annotationGroupsComponent.unselectLabel(annotationId);
        }
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'annotation',
                selectionType: 'unselect',
                structureId: parseInt(annotation.structureLink),
                annotationId: parseInt(annotationId),
                additionalInformation: annotation.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes an annotation from the draw area and data.
     *
     * @param annotationId {Number} - id of the annotation to remove
     */
    removeAnnotationDataView(annotationId) {
        const annotationsData = this.sceneData.annotationsData;
        const annotation = annotationsData.annotations[annotationId];
        const structureId = annotation.structureLink;
        if (structureId !== undefined) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const annotationConnectionData = structure.annotationConnectionData;
            annotationConnectionData.annotations.delete(annotationId);
            const atomLinks = annotation.atomLinks;
            if (atomLinks) {
                const atomAnnotationConnections = annotationConnectionData.atomAnnotationConnections;
                for (const atomId in atomLinks) {
                    atomAnnotationConnections[atomId].delete(annotationId);
                    if (atomAnnotationConnections[atomId].size === 0) {
                        delete atomAnnotationConnections[atomId];
                    }
                }
            }
        }
        this.removeAnnotationDOMCache(annotationId);
        delete annotationsData.annotations[annotationId];
        delete annotationsData.originalAnnotations[annotationId];
        annotationsData.selectedAnnotations.delete(annotationId);
    }
}

/* src/Drawers/HistoryDrawer.js */
/**
 * Drawer that uses scene JSON and change objects for manipulation of the draw area
 * in context of the browsing of the history.
 */
class HistoryDrawer {
    /**
     * Contains instances for configuration options and data storage/access, draw area manipulation.
     * Sets up the history and the possibility to add optional callbacks.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param structureDrawer {Object} - drawer for structures
     */
    constructor(opts, sceneData, structureDrawer) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.structureDrawer = structureDrawer;

        this.history = new History(opts.historyCanClearScene);
        this.jsonBuilder = new JsonBuilder(sceneData, opts);
        //optionally set by the user
        this.sceneChangeCallback = null;
        this.colorCallback = null;
        this.optsCallback = null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a new step to the drawer's history.
     *
     * @param historyStep {HistoryStep} - object detailing the next history
     * step so far
     * @param addedStructureIds {Array} - ids of structure objects added in
     * last history step (can and often will be empty)
     */
    applyStepToHistory(historyStep, addedStructureIds) {
        const curStep = this.history.curStep;
        for (const time in this.sceneData.structuresData.addTimesToStructure) {
            if (time > curStep) {
                this.sceneData.structuresData.addTimesToStructure[time].forEach(structureId => {
                    this.removeStructureFromOtherStructures(structureId);
                    delete this.sceneData.structuresData.structures[structureId];
                    delete this.sceneData.structuresData.originalStructures[structureId];
                    this.sceneData.structuresData.structuresInUse.delete(structureId);
                    this.structureDrawer.purgeStructureFromCache(structureId);
                });
                delete this.sceneData.structuresData.addTimesToStructure[time];
            }
        }
        //structure purge done here, add changes to track in history
        if (addedStructureIds.length > 0) {
            this.sceneData.structuresData.addTimesToStructure[curStep + 1] = addedStructureIds;
        }
        this.history.removeFurtherSteps();
        historyStep.opts = Helpers.deepCloneObject(this.opts);
        this.history.addNewStep(historyStep);
        //call callbacks where necessary
        this.execActionBasedCallbacks(this.history.getCurStep().actions);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Executes the bound sceneChangeCallback with JSON string data detailing
     * the current state of the scene.
     */
    callSceneChangeCallback() {
        if (this.sceneChangeCallback) {
            this.sceneChangeCallback(this.jsonBuilder.getJson());
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Executes the bound colorCallback with JSON string data detailing the
     * current state of the scene.
     */
    callColorCallback() {
        if (this.colorCallback) {
            this.colorCallback(this.jsonBuilder.getJson());
        }
    };

    /*----------------------------------------------------------------------*/

    /**
     * Based on an 'actions' set describing how the scene changed during a
     * recent change, calls necessary callbacks bound to the drawer.
     *
     * @param actions {Set} - actions performed on the scene during recent
     * change
     */
    execActionBasedCallbacks(actions) {
        actions.forEach(action => {
            if (action === 'sceneChange') {
                this.callSceneChangeCallback();
            } else if (action === 'colorChange') {
                this.callColorCallback();
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets back the history by one step, reverting all changes made in that
     * step.
     */
    revertHistory() {
        if (!this.history.canRevert()) {
            return;
        }

        const {changes: lastChanges, actions} = this.history.getCurStep();
        lastChanges.forEach(change => {
            change.revert();
        });
        this.execActionBasedCallbacks(actions);

        this.history.revert();
        if (this.optsCallback) {
            this.optsCallback(this.history.getCurStep().opts);
        }
        let emptyScene = true;
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            if (!structure.hidden && structure.enabled) {
                emptyScene = false
            }
        }
        if (emptyScene && this.history.canRevert()) {
            const {changes: lastChanges, actions} = this.history.getCurStep();
            lastChanges.forEach(change => {
                change.revert();
            });
            this.execActionBasedCallbacks(actions);

            this.history.revert();
            if (this.optsCallback) {
                this.optsCallback(this.history.getCurStep().opts);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Advances the history by one step, applying all changes made in that step.
     */
    advanceHistory() {
        if (!this.history.canAdvance()) {
            return;
        }

        this.history.advance();

        const {changes: nextChanges, actions, opts} = this.history.getCurStep();
        nextChanges.forEach(change => {
            change.apply();
        });
        this.execActionBasedCallbacks(actions);
        if (this.optsCallback) {
            this.optsCallback(opts);
        }
        let emptyScene = true;
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            if (!structure.hidden && structure.enabled) {
                emptyScene = false
            }
        }
        if (emptyScene && this.history.canAdvance()) {
            this.history.advance();

            const {changes: nextChanges, actions, opts} = this.history.getCurStep();
            nextChanges.forEach(change => {
                change.apply();
            });
            this.execActionBasedCallbacks(actions);
            if (this.optsCallback) {
                this.optsCallback(opts);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * On a given structural container (Structure or InteractionDrawer), updates
     * its boundary information based on logged change information.
     *
     * @param structure {Structure/SceneData} - container to
     * update boundaries for
     * @param maxes {BoundaryUpdateInfo} - information on how boundaries of
     * this structure have changed during the last history step
     * @param boundaryName {String} - name of the class field containing the
     * boundary information
     * @param setBoundFnName {String} - name of the class field containing
     * the function to set boundary information
     * @param historyStep {HistoryStep} - object detailing the next history
     * step so far
     */
    setNewLimits(structure, maxes, boundaryName, setBoundFnName, historyStep) {
        let changed = false;
        for (const limitId in maxes) {
            if (maxes[limitId].changeDir) {
                changed = true;
                break;
            }
        }
        if (!changed) {
            return;
        }

        const oldBounds = structure[boundaryName];
        structure[setBoundFnName]();
        this.setNewLimitsToHistory(structure, oldBounds, boundaryName, historyStep);
    }

    /*----------------------------------------------------------------------*/

    /**
     * On a given structural container (Structure or InteractionDrawer), logs its
     * updated boundary information to a given history.
     *
     * @param structure {Structure} - structure container to
     * update boundaries for
     * @param oldBounds {Object} - old boundaries of the structure. Has to contain
     * xMin, xMax, yMin, and yMax
     * @param boundaryName {String} - name of the class field containing the
     * boundary information
     * @param historyStep {HistoryStep} - object detailing the next history
     * step so far
     */
    setNewLimitsToHistory(structure, oldBounds, boundaryName, historyStep) {
        const newBounds = structure[boundaryName];
        const boundChange = new Change();
        const setNew = () => {
            structure[boundaryName] = newBounds;
        };
        const reset = () => {
            structure[boundaryName] = oldBounds;
        };
        boundChange.bindApply(setNew);
        boundChange.bindRevert(reset);
        historyStep.addChange(boundChange);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Cleanup step that removes e.g. connection data of one structure from all other structures.
     * E.g. if an added structure and interaction are removed by browsing back in the history and
     * another structure is added afterwards removing the first two objects from the history.
     *
     * @param structureId {Number} - id of the structure
     */
    removeStructureFromOtherStructures(structureId) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const {
            distances,
            interactions,
            atomPairInteractions,
            piStackings,
            cationPiStackings
        } = structure.getConnectedElements();
        for (const otherStructureId in this.sceneData.structuresData.structures) {
            const otherStructure = this.sceneData.structuresData.structures[otherStructureId];
            if (parseInt(structureId) === parseInt(otherStructureId)) {
                continue;
            }
            for (const interactionId of atomPairInteractions) {
                otherStructure.intermolecularConnectionData.ids.atomPairInteractions.delete(
                    interactionId
                );
            }
            for (const interactionId of atomPairInteractions) {
                otherStructure.intermolecularConnectionData.ids.atomPairInteractions.delete(
                    interactionId
                );
            }
            for (const interactionId of cationPiStackings) {
                otherStructure.intermolecularConnectionData.ids.cationPiStackings.delete(
                    interactionId
                );
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the history.
     */
    reset() {
        this.history = new History(this.opts.historyCanClearScene);
    }
}

/* src/Drawers/HydrophobicDrawer.js */
/**
 * Drawer that uses its own component for the visualization of hydrophobic contacts.
 */
class HydrophobicDrawer {
    /**
     * Contains instances for json validation, configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param hydrophobicGroupsComponent {Object} - component for hydrophobic contacts
     * @param jsonValidator {Object} - validates input JSON
     */
    constructor(opts, sceneData, hydrophobicGroupsComponent, jsonValidator) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.hydrophobicGroupsComponent = hydrophobicGroupsComponent;
        this.jsonValidator = jsonValidator;
        this.closestObjectFinder = new ClosestObjectFinder(opts, sceneData);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the individual components of different hydrophobic contacts based on
     * the "hydrophobicContacts" field of provided scene draw information and
     * link hydrophobic contacts to the structures they belong to. Returns the
     * necessary Change objects to remove and re-add these components.
     *
     * @param hydrophobicInfos {Array} - draw information for the different
     * hydrophobic contacts to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {undefined|Array} - Change objects for the next history step
     */
    applyAddHydrophobic(hydrophobicInfos, globalMaxes) {
        const jsonKey = 'hydrophobicContacts';
        if (this.jsonValidator.checkJSONStructureArray(hydrophobicInfos, jsonKey, true).error) {
            return;
        }
        //apply add for each given info
        const addChanges = [];
        hydrophobicInfos.forEach((hydrophobicInfo, i) => {
            if (this.jsonValidator.hydrophobicJSONerror(hydrophobicInfo, i, jsonKey)) {
                return;
            }
            const structure = this.sceneData.structuresData.structures[hydrophobicInfo.belongsTo];
            if (!this.sceneData.hydrophobicData.hydrophobicContacts.hasOwnProperty(hydrophobicInfo.id)) {
                this.addNewControlPoint(structure, hydrophobicInfo, globalMaxes, addChanges);
            } else {
                this.extendExistingControlPoint(structure,
                    hydrophobicInfo,
                    globalMaxes,
                    addChanges
                );
            }
        });
        return addChanges
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates and adds a new spline to the draw area.
     *
     * @param structure {Object} - structure the control point belongs to
     * @param hydrophobicInfo {Array} - draw information for a hydrophobic contact
     * to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addChanges {Array} - collects this drawing change for the history
     */
    addNewControlPoint(structure, hydrophobicInfo, globalMaxes, addChanges) {
        const {
            id: hId, belongsTo: structureId, controlPoints, controlPointsInsertId
        } = hydrophobicInfo;
        //create spline and reference in memory
        const spline = new Spline(structureId);
        spline.addControlPointsFromData(controlPoints, this.opts.atomSelectorRadius);
        //link control points to atoms
        controlPoints.forEach(({atomLinks, x, y}, cpId) => {
            if (!atomLinks || atomLinks.length === 0) {
                const atom = this.closestObjectFinder.getClosestEnabledAtom({x: x, y: y},
                    [structure.id]
                );
                atomLinks = [atom.id];
                spline.controlPoints[cpId].atomLinks = atomLinks;
            }
            new Set(atomLinks).forEach(atomLink => {
                structure.hydrophobicConnectionData.linkAtomToSplineControlPoint(atomLink,
                    hId,
                    cpId
                );
            });
        });
        structure.hydrophobicConnectionData.addHydrophobicContact(hId, spline);
        this.hydrophobicGroupsComponent.drawHydrophobicContact(structureId,
            hId,
            spline.controlPoints,
            spline.createSplinePath(false)
        );
        //for setting of limits
        spline.getCurveCoords(false).forEach(({x, y}) => {
            const rad = this.opts.lineWidth;
            globalMaxes.setMaxesAdd(x - rad, x + rad, y - rad, y + rad);
        });
        addChanges.push(this.createAddRemoveChangeHydrophobic(structureId, hId));
        this.sceneData.hydrophobicData.hydrophobicContacts[hId] = spline;
        this.sceneData.hydrophobicData.originalHydrophobicContacts[hId] = spline.clone();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Extends an existing spline with respect to data and draw area..
     *
     * @param structure {Object} - structure the control point belongs to
     * @param hydrophobicInfo {Array} - draw information for a hydrophobic contact
     * to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addChanges {Array} - collects this drawing change for the history
     */
    extendExistingControlPoint(structure, hydrophobicInfo, globalMaxes, addChanges) {
        const {
            id: hId, belongsTo: structureId, controlPoints, controlPointsInsertId
        } = hydrophobicInfo;
        const spline = this.sceneData.hydrophobicData.hydrophobicContacts[hId];
        const insertId = controlPointsInsertId !== undefined ? controlPointsInsertId :
            this.sceneData.hydrophobicData.hydrophobicContacts[hId].controlPoints.length;
        spline.addControlPointsFromData(controlPoints, this.opts.atomSelectorRadius, insertId);

        spline.controlPoints.forEach(({atomLinks, x, y}, cpId) => {
            if (!atomLinks || atomLinks.length === 0) {
                const atom = this.closestObjectFinder.getClosestEnabledAtom({x: x, y: y},
                    [structure.id]
                );
                atomLinks = [atom.id];
                spline.controlPoints[cpId].atomLinks = atomLinks;
            }
            new Set(atomLinks).forEach(atomLink => {
                structure.hydrophobicConnectionData.linkAtomToSplineControlPoint(atomLink,
                    hId,
                    cpId
                );
            });
        });
        this.sceneData.hydrophobicData.originalHydrophobicContacts[hId].addControlPointsFromData(Object.assign([], controlPoints),
            this.opts.atomSelectorRadius,
            insertId
        );
        this.hydrophobicGroupsComponent.addHydrophobicControlPoints(structureId,
            hId,
            controlPoints,
            insertId
        );
        this.updateSplineRepresentation(hId);
        spline.getCurveCoords(false).forEach(({x, y}) => {
            const rad = this.opts.lineWidth;
            globalMaxes.setMaxesAdd(x - rad, x + rad, y - rad, y + rad);
        });
        for (let i = insertId; i < insertId + controlPoints.length; i++) {
            addChanges.push(this.createAddRemoveChangeHydrophobicControlPoint(
                structureId,
                hId,
                i,
                true,
                spline.controlPoints[i]
            ));
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to remove/re-add a hydrophobic contact.
     *
     * @param structureId {Number} - id of the structure the hydrophobic
     * contact belongs to
     * @param hydrophobicId {Number} - id of the hydrophobic contact to
     * remove/re-add
     * @param isAdd {Boolean} - whether the change should add the hydrophobic
     * contact as its apply() or revert() function
     * @returns {Change} - Change object to apply/revert removal
     */
    createAddRemoveChangeHydrophobic(structureId, hydrophobicId, isAdd = true) {
        const hydrophobicChange = new Change();
        const remove = () => {
            this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicId].enabled = false;
            this.hydrophobicGroupsComponent.removeHydrophobicContactFromDOM(structureId,
                hydrophobicId
            );
        };
        const readd = () => {
            this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicId].enabled = true;
            this.hydrophobicGroupsComponent.redrawHydrophobicContact(structureId, hydrophobicId);
        };
        if (isAdd) {
            hydrophobicChange.bindApply(readd);
            hydrophobicChange.bindRevert(remove);
        } else {
            hydrophobicChange.bindApply(remove);
            hydrophobicChange.bindRevert(readd);
        }
        return hydrophobicChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to remove/re-add a single control point from a
     * hydrophobic contact. Connsiders that the array index of previously added
     * control points can change upon adding further control points, e.g. 0 becomes
     * 1. Therefore, the control point index is redetermined by coordinates.
     *
     * @param structureId {Number} - id of the structure the hydrophobic
     * contact belongs to
     * @param hydrophobicId {Number} - id of the hydrophobic contact to
     * remove/re-add a control point from
     * @param controlPointId {Number} - id of the control point of the
     * hydrophobic contact to remove/re-add
     * @param isAdd {Boolean} - whether the change should add the control
     * point as its apply() or revert() function
     * @param controlPoint {Object} - the corresponding control point
     * @returns {Change} - Change object to apply/revert removal
     */
    createAddRemoveChangeHydrophobicControlPoint(structureId,
        hydrophobicId,
        controlPointId,
        isAdd ,
        controlPoint = undefined
    ) {
        const hydrophobicChange = new Change();
        const remove = () => {
            const hContact = this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicId];
            let cPoint;
            let tempCpoint;
            let idxCorrected = false;
            for (let idx = 0; idx < hContact.controlPoints.length; idx++) {
                cPoint = hContact.controlPoints[idx];
                tempCpoint = hContact.tempControlPoints[idx];
                if (Helpers.isAlmostEqual(controlPoint.x, cPoint.x) &&
                    Helpers.isAlmostEqual(controlPoint.y, cPoint.y)) {
                    controlPointId = idx;
                    idxCorrected = true;
                    break;
                }
            }
            if (!idxCorrected) {
                cPoint = hContact.controlPoints[controlPointId];
                tempCpoint = hContact.tempControlPoints[controlPointId];
            }
            cPoint.enabled = false;
            tempCpoint.enabled = false;
            this.hydrophobicGroupsComponent.removeHydrophobicControlPoint(structureId,
                hydrophobicId,
                controlPointId
            );
            this.updateSplineRepresentation(hydrophobicId);
        };
        const readd = () => {
            const hContact = this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicId];
            let cPoint;
            let tempCpoint;
            let idxCorrected = false;
            for (let idx = 0; idx < hContact.controlPoints.length; idx++) {
                cPoint = hContact.controlPoints[idx];
                tempCpoint = hContact.tempControlPoints[idx];
                if (Helpers.isAlmostEqual(controlPoint.x, cPoint.x) &&
                    Helpers.isAlmostEqual(controlPoint.y, cPoint.y)) {
                    controlPointId = idx;
                    idxCorrected = true;
                    break;
                }
            }
            if (!idxCorrected) {
                cPoint = hContact.controlPoints[controlPointId];
                tempCpoint = hContact.tempControlPoints[controlPointId];
            }
            cPoint.enabled = true;
            tempCpoint.enabled = true;
            this.hydrophobicGroupsComponent.redrawHydrophobicControlPoint(structureId,
                hydrophobicId,
                controlPointId
            );
            this.updateSplineRepresentation(hydrophobicId);
        };
        if (isAdd) {
            hydrophobicChange.bindApply(readd);
            hydrophobicChange.bindRevert(remove);
        } else {
            hydrophobicChange.bindApply(remove);
            hydrophobicChange.bindRevert(readd);
        }
        return hydrophobicChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Triggers the update of a specific spline representing a hydrophobic
     * contact.
     *
     * @param hydrophobicId {Number} - id of the hydrophobic contact
     */
    updateSplineRepresentation(hydrophobicId) {
        const spline = this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicId];
        const splinePath = spline.createSplinePath(true);
        const controlPoints = spline.getControlPoints(true);
        this.hydrophobicGroupsComponent.updateHydrophobicContact(spline.structureLink,
            hydrophobicId,
            controlPoints,
            splinePath
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the coordinates of control points of a single spline to new values.
     * Returns the necessary Change objects to apply/revert these coordinate
     * changes.
     *
     * @param hydrophobicId {Number} - id of the spline
     * @param spline {Spline} - Spline object representing the spline
     * @param newControlPoints {Object} - map from control point ids to new
     * coordinates
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {Array} - Change objects for the next history step
     */
    applyCoordinateChangesSpline(hydrophobicId, spline, newControlPoints, globalMaxes) {
        const splineChanges = [];
        const oldControlPoints = spline.getControlPoints(false);
        let updateNeeded = false;
        for (const pointId in newControlPoints) {
            //control point update
            const oldInfo = Object.assign({}, oldControlPoints[pointId]);
            const newInfo = Object.assign({}, newControlPoints[pointId]);
            if (PointCalculation.coordsAlmostEqual(oldInfo, newInfo)) {
                continue;
            }
            updateNeeded = true;
            const pointChange = new Change();
            const setPointNew = () => {
                spline.setControlPoint(pointId, newInfo, false);
            };
            const setPointOld = () => {
                spline.setControlPoint(pointId, oldInfo, false);
            };
            pointChange.bindApply(setPointNew);
            pointChange.bindRevert(setPointOld);
            pointChange.apply();
            splineChanges.push(pointChange);
        }
        if (!updateNeeded) return splineChanges; //no changes made
        //update the spline path based on new control points
        const updateChange = new Change();
        const oldCurveCoords = spline.getCurveCoords(false);
        const updateSpline = () => {
            const splinePath = spline.createSplinePath(false);
            const controlPoints = spline.getControlPoints(false);
            this.hydrophobicGroupsComponent.updateHydrophobicContact(spline.structureLink,
                hydrophobicId,
                controlPoints,
                splinePath
            );
        };
        updateChange.bindApplyRevert(updateSpline);
        updateChange.apply();
        splineChanges.push(updateChange);
        //update coordinates based on all the curve coords
        const newCurveCoords = spline.getCurveCoords(false);
        let xMinSet = false, xMaxSet = false, yMinSet = false, yMaxSet = false;
        const rad = this.opts.lineWidth;
        newCurveCoords.forEach(({x, y}) => {
            if (globalMaxes.updateMaxesLim('xMin', x - rad, false)) {
                xMinSet = true;
            }
            if (globalMaxes.updateMaxesLim('xMax', x + rad, true)) {
                xMaxSet = true;
            }
            if (globalMaxes.updateMaxesLim('yMin', y - rad, false)) {
                yMinSet = true;
            }
            if (globalMaxes.updateMaxesLim('yMax', y + rad, true)) {
                yMaxSet = true;
            }
        });
        oldCurveCoords.forEach(({x, y}) => {
            if (!xMinSet) {
                globalMaxes.updateMaxesNeg('xMin', x - rad, false);
            }
            if (!xMaxSet) {
                globalMaxes.updateMaxesNeg('xMax', x + rad, true);
            }
            if (!yMinSet) {
                globalMaxes.updateMaxesNeg('yMin', y - rad, false);
            }
            if (!yMaxSet) {
                globalMaxes.updateMaxesNeg('yMax', y + rad, true);
            }
        });
        return splineChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified hydrophobic contacts (or parts of those) in the draw area.
     *
     * @param remHydrophobicContacts {Set} - ids of hydrophobic contacts to
     * remove. Those are objects which have 'id' as key and can optional have
     * specified control points (key 'controlPoints', values as array of ids)
     * to only remove those
     * @param remChanges {Array} - change objects for the history step
     * @param markRequiredRecalcs {Function} - function to memory changes in
     * structure/scene boundaries
     */
    removeHydrophobicContacts(remHydrophobicContacts, remChanges, markRequiredRecalcs) {
        remHydrophobicContacts
            .forEach(({id: hydroId, controlPoints: cpIds}) => {
                if (!this.sceneData.hydrophobicData.hydrophobicContacts.hasOwnProperty(hydroId)) {
                    return;
                }

                const hydro = this.sceneData.hydrophobicData.hydrophobicContacts[hydroId];
                //filter already removed
                if (!hydro.enabled) {
                    return;
                }
                const rad = this.opts.lineWidth;
                hydro.getCurveCoords(false).forEach(({x, y}) => {
                    markRequiredRecalcs('xMin', x - rad);
                    markRequiredRecalcs('xMax', x + rad);
                    markRequiredRecalcs('yMin', y - rad);
                    markRequiredRecalcs('yMax', y + rad);
                });

                if (cpIds) {
                    for (const cpId of cpIds) {
                        if (!hydro.controlPoints.hasOwnProperty(cpId) ||
                            !hydro.controlPoints[cpId].enabled) {
                            continue;
                        }
                        const remChange = this.createAddRemoveChangeHydrophobicControlPoint(hydro.structureLink,
                            hydroId,
                            cpId,
                            false,
                            hydro.controlPoints[cpId]
                        );
                        remChange.apply();
                        remChanges.push(remChange);
                    }
                } else {
                    const remChange = this.createAddRemoveChangeHydrophobic(hydro.structureLink,
                        hydroId,
                        false
                    );
                    remChange.apply();
                    remChanges.push(remChange);
                }
            });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Instructs the draw layer to unselect (= hide selection shapes) all
     * currently highlighted spline control points.
     */
    unselectAllSplines() {
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            for (const hydrophobicId in structure.hydrophobicConnectionData.hydrophobicConts) {
                structure.hydrophobicConnectionData.hydrophobicConts[hydrophobicId]
                    .getControlPoints(false).forEach((_, idx) => {
                    this.hydrophobicGroupsComponent.unselectHydrophobicControlPoint(structureId,
                        hydrophobicId,
                        idx
                    );
                });
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates given spline control points (by id) of a spline around a given
     * midpoint, then updates the spline accordingly.
     *
     * @param splineId {Number} - id of the spline the control points belong
     * to
     * @param controlPointIds {Array} - ids of control points to rotate
     * @param angle {Number} - angle (in degree) to rotate by
     * @param midpoint {Object} - x- and y-coordinates of the point to rotate
     * the spline control points around
     */
    rotateSplineControlPoints(splineId, controlPointIds, angle, midpoint) {
        const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
        spline.rotateControlPoints(controlPointIds, angle, true, midpoint, true);
        this.updateSplineRepresentation(splineId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Remove hydrophobic contact from the DOM and the views cache.
     *
     * @param structureId {Number} - id of the structure the hydrophobic contact belongs
     * to
     * @param hId {Number} - id of hydrophobic contact
     */
    removeHydrophobicContactDOMCache(structureId, hId) {
        this.hydrophobicGroupsComponent.removeHydrophobicContactFromDOM(structureId, hId);
        this.hydrophobicGroupsComponent.purgeHydrophobicContactFromCache(structureId, hId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers a control point of a hydrophobic contact.
     *
     * @param structureId {Number} - id of the structure the hydrophobic contact belongs
     * to
     * @param hydrophobicId {Number} - id of hydrophobic contact
     * @param controlPointId {Number} - id of control point
     */
    hoverHydrophobicControlPoint(structureId, hydrophobicId, controlPointId) {
        this.hydrophobicGroupsComponent.hoverHydrophobicControlPoint(structureId,
            hydrophobicId,
            controlPointId
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers all control points of a hydrophobic contact.
     *
     * @param structureId {Number} - id of the structure the hydrophobic contact belongs
     * to
     * @param hydrophobicId {Number} - id of hydrophobic contact
     */
    hoverAllHydrophobicControlPoints(structureId, hydrophobicId) {
        this.hydrophobicGroupsComponent.hoverAllHydrophobicControlPoints(structureId,
            hydrophobicId
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Move spline control points based on a given offset-
     *
     * @param controlPoints {Number} - ids of control points
     * @param offset {Object} - offset for movement
     */
    moveSplineControlPoints(controlPoints, offset) {
        for (const splineId in controlPoints) {
            const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
            controlPoints[splineId].forEach(cpId => {
                spline.updateControlPoint(cpId, offset, true);
            });
            this.updateSplineRepresentation(splineId);
        }
    }
}

/* src/Drawers/IntermolecularDrawer.js */
/**
 * Drawer that uses other drawers and its own component for the visualization
 * of various intermolecular edges.
 */
class IntermolecularDrawer {
    /**
     * Contains instances for json validation, configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param intermolecularGroupsComponent {Object} - component for intermolecular edges
     * @param jsonValidator {Object} - validates input JSON
     */
    constructor(opts, sceneData, intermolecularGroupsComponent, jsonValidator) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.intermolecularGroupsComponent = intermolecularGroupsComponent;
        this.jsonValidator = jsonValidator;

        this.selectionCallback = null;
        this.edgeBuilder = new EdgeBuilder(opts, sceneData);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the coordinates of intermolecular forces based on previously
     * set new positions of their related elements. Returns the necessary change
     * objects to apply/revert these coordinate changes.
     *
     * @param intermolecularChanges {Object} - contains the keys 'atomPairInteractions',
     * 'piStackings' and 'cationPiStackings' which contain the ids of
     * corresponding interactions to move
     * @returns {Array} - change objects for the next history step
     */
    applyCoordinateChangesAllIntermolecular({
        distances, interactions, atomPairInteractions, piStackings, cationPiStackings
    }) {
        const intermolecularChanges = [];
        Array.prototype.push.apply(intermolecularChanges,
            this.applyCoordinateChangesIntermolecular(distances, 'distances')
        );
        Array.prototype.push.apply(intermolecularChanges,
            this.applyCoordinateChangesIntermolecular(interactions, 'interactions')
        );
        Array.prototype.push.apply(intermolecularChanges,
            this.applyCoordinateChangesIntermolecular(atomPairInteractions, 'atomPairInteractions')
        );
        Array.prototype.push.apply(intermolecularChanges,
            this.applyCoordinateChangesIntermolecular(piStackings, 'piStackings')
        );
        Array.prototype.push.apply(intermolecularChanges,
            this.applyCoordinateChangesIntermolecular(cationPiStackings, 'cationPiStackings')
        );
        return intermolecularChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the coordinates of cation-pi stacking interactions based on the
     * previously set new position for the connected atom and the new position
     * of the center of the connected ring system. Returns the necessary change
     * objects to apply/revert these coordinate changes.
     *
     * @param interactionIds {Set} - ids of interactions to move
     * @param type {String} - identifier of the intermolecular edge
     * @returns {Array} - change objects for the next history step
     */
    applyCoordinateChangesIntermolecular(interactionIds, type) {
        const container = this.sceneData.intermolecularData[type];
        const interactionChanges = [];
        interactionIds.forEach(interactionId => {
            this.updateSingleIntermolecular(interactionId, type, true);
            const moveToNew = () => {
                this.updateSingleIntermolecular(interactionId, type, true);
            };
            if (type === 'atomPairInteractions') {
                const atomPairInteraction = container[interactionId];
                atomPairInteraction.transferTempHidden();
            }
            const moveBack = () => {
                this.updateSingleIntermolecular(interactionId, type, true);
            };
            const interactionChange = new Change();
            interactionChange.bindApply(moveToNew);
            interactionChange.bindRevert(moveBack);
            if (type === 'cationPiStackings' || type === 'piStackings') {
                interactionChange.apply();
            }
            interactionChanges.push(interactionChange);
        });
        return interactionChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the individual components of different interactions based on the
     * fields of provided scene draw information and link interactions
     * to the endpoints they connect. Returns the necessary change objects to
     * remove and re-add these components.
     *
     * @param interactionInfos {Array} - draw information for the different
     * interaction to be added to the scene
     * @param type {String} - identifier of the intermolecular edge
     * @returns {undefined|Array} - change objects for the next history step
     */
    applyAddIntermolecular(interactionInfos, type) {
        if (this.jsonValidator.checkJSONStructureArray(interactionInfos, type, true).error) {
            return;
        }
        //apply add for each given info
        const addChanges = [];
        interactionInfos.forEach((interactionInfo, i) => {
            interactionInfo.fromStruct =
                this.sceneData.structuresData.structures[interactionInfo.fromStructure];
            interactionInfo.toStruct =
                this.sceneData.structuresData.structures[interactionInfo.toStructure];
            if (this.jsonValidator.intermolecularMolJSONerror(interactionInfo, i, type)) {
                return;
            }
            //destructure required draw information
            if (type === 'atomPairInteractions') {
                interactionInfo.fromObj =
                    interactionInfo.fromStruct.atomsData.getAtom(interactionInfo.from);
                interactionInfo.toObj =
                    interactionInfo.toStruct.atomsData.getAtom(interactionInfo.to);
            } else if (type === 'piStackings') {
                interactionInfo.fromObj =
                    interactionInfo.fromStruct.ringsData.getRing(interactionInfo.from);
                interactionInfo.toObj =
                    interactionInfo.toStruct.ringsData.getRing(interactionInfo.to);
            } else if (type === 'cationPiStackings') {
                interactionInfo.fromObj =
                    interactionInfo.fromStruct.ringsData.getRing(interactionInfo.from);
                interactionInfo.toObj =
                    interactionInfo.toStruct.atomsData.getAtom(interactionInfo.to);
            } else if (type === 'distances' || type === 'interactions') {
                const annotations = this.sceneData.annotationsData.annotations;
                interactionInfo.fromObj = annotations[interactionInfo.from];
                interactionInfo.toObj = annotations[interactionInfo.to];
            }
            if (this.jsonValidator.intermolecularEndPointJSONerror(interactionInfo, i, type)) {
                return;
            }
            IntermolecularDrawer.memorizeConnectionsInStructure(interactionInfo, type);

            this.createNewIntermolecular(interactionInfo, type, addChanges);
        });
        return addChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Memorizes which structure parts are connected by an intermolecular edge.
     *
     * @param interactionInfo {Array} - draw information for an interaction to be added to the scene
     * @param type {String} - identifier of the intermolecular edge
     */
    static memorizeConnectionsInStructure(interactionInfo, type) {
        const {
            fromStruct: fromStruct, toStruct: toStruct, from: from, to: to, id: interactionId
        } = interactionInfo;
        if (type === 'atomPairInteractions') {
            fromStruct.intermolecularConnectionData.addIntermolecularConnection(from,
                interactionId,
                type,
                'atom'
            );
            toStruct.intermolecularConnectionData.addIntermolecularConnection(to,
                interactionId,
                type,
                'atom'
            );
        } else if (type === 'piStackings') {
            fromStruct.intermolecularConnectionData.addIntermolecularConnection(from,
                interactionId,
                type,
                'ring'
            );
            toStruct.intermolecularConnectionData.addIntermolecularConnection(to,
                interactionId,
                type,
                'ring'
            );
        } else if (type === 'cationPiStackings') {
            fromStruct.intermolecularConnectionData.addIntermolecularConnection(from,
                interactionId,
                type,
                'ring'
            );
            toStruct.intermolecularConnectionData.addIntermolecularConnection(to,
                interactionId,
                type,
                'atom'
            );
        } else if (type === 'distances' || type === 'interactions') {
            fromStruct.intermolecularConnectionData.addIntermolecularConnection(from,
                interactionId,
                type,
                'annotation'
            );
            toStruct.intermolecularConnectionData.addIntermolecularConnection(to,
                interactionId,
                type,
                'annotation'
            );
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a new instance and draws the intermolecular edge.
     *
     * @param interactionInfo {Array} - draw information for an interaction to be added to the scene
     * @param type {String} - identifier of the intermolecular edge
     * @param addChanges {Array} - collects this drawing change for the history
     */
    createNewIntermolecular(interactionInfo, type, addChanges) {
        const {
            fromStruct: fromStruct,
            toStruct: toStruct,
            from: from,
            to: to,
            id: interactionId,
            fromStructure: fromStructure,
            toStructure: toStructure,
            additionalInformation: additionalInformation
        } = interactionInfo;
        const color = this.getIntermolecularColor(interactionInfo, type);
        //create bond and fill it with initial draw information
        const newInteraction = new IntermolecularEdge(interactionId,
            from,
            to,
            fromStructure,
            toStructure,
            color,
            additionalInformation
        );
        this.sceneData.intermolecularData[type][interactionId] = newInteraction;
        this.calcIntermolecularConnectionOrder(type, interactionId, false);
        const midpoints = this.edgeBuilder.getNewIntermolecularCoords(interactionId,
            type,
            fromStruct,
            toStruct,
            from,
            to
        );
        const [midFrom, midTo] = midpoints;
        const interactionRep = this.edgeBuilder.createSingleEdge(midFrom, midTo);
        if (!interactionRep) { //no space to draw
            return;
        }
        newInteraction.setDrawInfo(interactionRep, false);
        newInteraction.setHidden(false, false);
        this.intermolecularGroupsComponent.drawIntermolecular(newInteraction, interactionRep, type);
        addChanges.push(this.createRemoveChangeIntermolecular(interactionId, type));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines the color of a new intermolecular edge.
     *
     * @param interactionInfo {Array} - draw information for an interaction to be added to the scene
     * @param type {String} - identifier of the intermolecular edge
     */

    getIntermolecularColor(interactionInfo, type) {
        const colors = this.opts.colors;
        if (type === 'atomPairInteractions') {
            const structures = this.sceneData.structuresData.structures;
            const fromAtomsData = structures[interactionInfo.fromStructure].atomsData;
            const toAtomsData = structures[interactionInfo.toStructure].atomsData;
            const fromAtom = fromAtomsData.getAtom(interactionInfo.from);
            const toAtom = toAtomsData.getAtom(interactionInfo.to);
            if (fromAtom.isMetal() || toAtom.isMetal()) {
                return colors.metalInteractions;
            } else if ((fromAtom.charge > 0 && toAtom.charge < 0) ||
                (fromAtom.charge < 0 && toAtom.charge > 0)) {
                return colors.ionicInteractions;
            }
        }
        return colors[type];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Binds functions for adding and removing of an interaction to a Change object
     *
     * @param change {Change} - change oObject to apply/revert removal
     * @param readd {Boolean} - function for the readding of an interaction
     * @param remove {Boolean} - function for the removing of an interaction
     * @param isAdd {Boolean} - whether the change should add the interaction
     * as its apply() or revert() function
     */
    static bindCreateRemoveChangeInteraction(change, readd, remove, isAdd) {
        if (isAdd) {
            change.bindApply(readd);
            change.bindRevert(remove);
        } else {
            change.bindApply(remove);
            change.bindRevert(readd);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to remove/re-add a cation-pi stacking
     * interaction.
     *
     * @param interactionId {Number} - id of the interaction to remove/re-add
     * @param type {String} - identifier of the intermolecular edge
     * @param isAdd {Boolean} - whether the change should add the interaction
     * as its apply() or revert() function
     * @returns {Change} - Change object to apply/revert removal
     */
    createRemoveChangeIntermolecular(interactionId, type, isAdd = true) {
        const interactionChange = new Change();
        const remove = () => {
            if (this.sceneData.intermolecularData.selectedIntermolecular[type].has(
                parseInt(interactionId))) {
                this.sceneData.intermolecularData.selectedIntermolecular[type].delete(
                    parseInt(interactionId));
                const container = this.sceneData.intermolecularData[type];
                const interaction = container[interactionId];
                interaction.selected = false;
            }
            this.sceneData.intermolecularData[type][interactionId].enabled = false;
            this.intermolecularGroupsComponent.removeIntermolecularFromDOM(interactionId, type);
            this.calcIntermolecularConnectionOrder(type, interactionId, true, false);
        };
        const readd = () => {
            this.sceneData.intermolecularData[type][interactionId].enabled = true;
            this.intermolecularGroupsComponent.redrawIntermolecular(interactionId, type);
            this.calcIntermolecularConnectionOrder(type, interactionId);
        };
        IntermolecularDrawer.bindCreateRemoveChangeInteraction(interactionChange,
            readd,
            remove,
            isAdd
        );
        return interactionChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds/Removes a intermolecular connection to/from intermolecularConnections
     * and recalculates the order to draw those connections if both involved
     * structures are represented as structure circles.
     *
     * @param type {String} - identifier of the intermolecular edge
     * @param id {Number} - id of the connection
     * @param add {Boolean} - add (true, default) or remove (false) the connection
     * @param update {Boolean} - whether to update the draw elements of all
     * connections between the two structures involved in this connection
     */
    calcIntermolecularConnectionOrder(type, id, update = true, add = true) {
        let {
            fromStructure, toStructure
        } = this.sceneData.intermolecularData.getIntermolecularByType(type, id);
        if (fromStructure > toStructure) {
            [fromStructure, toStructure] = [toStructure, fromStructure];
        }
        const connections = this.sceneData.structuresData.intermolecularConnections;
        if (!connections.hasOwnProperty(fromStructure)) {
            connections[fromStructure] = {};
        }
        if (!connections[fromStructure].hasOwnProperty(toStructure)) {
            connections[fromStructure][toStructure] = [];
        }
        const connectionArr = connections[fromStructure][toStructure];
        if (add) {
            connectionArr.push({
                type: type, id: id
            })
        } else {
            let removeId;
            connectionArr.forEach((con, idx) => {
                if (con.type === type && con.id == id) {
                    removeId = idx;
                }
            });
            if (removeId !== undefined) {
                connectionArr.splice(removeId, 1);
            }
        }
        //order the array so that (cation) pi stackings are far away from each
        //other because they are drawn with circles on at least one structure
        //and we want max distance between those circles so they do not overlap.
        const piIdx = [];
        const hIdx = [];
        connectionArr.forEach((con, idx) => {
            if (con.type === 'piStackings' || con.type === 'cationPiStacking') {
                piIdx.push(idx);
            } else {
                hIdx.push(idx);
            }
        });
        if (piIdx.length > 1) {
            const sortedArr = [];
            //how much elements between each (cation) pi
            const hBetween = Math.floor(hIdx.length / (piIdx.length - 1));
            //how much gaps between each (cation) pi are one larger than hBetween
            let extraH = hIdx.length % (piIdx.length - 1);
            let hCount = 0;

            sortedArr.push(connectionArr[piIdx.pop()]);
            for (let i = 1; i < connectionArr.length; i++) {
                if (hCount < hBetween) {
                    sortedArr.push(connectionArr[hIdx.pop()]);
                    hCount++;
                } else if (hCount === hBetween && extraH > 0) {
                    sortedArr.push(connectionArr[hIdx.pop()]);
                    hCount++;
                    extraH--;
                } else {
                    sortedArr.push(connectionArr[piIdx.pop()]);
                    hCount = 0;
                }
            }
            this.sceneData.structuresData.intermolecularConnections[fromStructure][toStructure] =
                sortedArr;
        }
        if (update) {
            this.updateIntermolecularConnections(fromStructure, toStructure);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates intermolecular connections between two structures which
     * representations are both structure circle. This is done after such
     * connections are removed.
     *
     * @param from {Number} - structure id of first structure involved
     * @param to {Number} - structure id of second structure involved
     */
    updateIntermolecularConnections(from, to) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(from) ||
            !this.sceneData.structuresData.structures.hasOwnProperty(to) ||
            this.sceneData.structuresData.structures[from].representationsData.curRepresentation() !==
            StructureRepresentation.circle ||
            this.sceneData.structuresData.structures[to].representationsData.curRepresentation() !==
            StructureRepresentation.circle) {
            return;
        }
        const fromStructure = this.sceneData.structuresData.structures[from];
        const toStructure = this.sceneData.structuresData.structures[to];

        const {
            distances: fromDistances,
            interactions: fromInteractions,
            atomPairInteractions: fromAtomPairInteractions,
            piStackings: fromPiStackings,
            cationPiStackings: fromCationPiStackings
        } = fromStructure.getConnectedElements();
        const {
            distances: toDistances,
            interactions: toInteractions,
            atomPairInteractions: toAtomPairInteractions,
            piStackings: toPiStackings,
            cationPiStackings: toCationPiStackings
        } = toStructure.getConnectedElements();
        this.updateAllIntermolecular(Helpers.getIntersectionOfTwoSets(fromDistances, toDistances),
            Helpers.getIntersectionOfTwoSets(fromInteractions, toInteractions),
            Helpers.getIntersectionOfTwoSets(fromAtomPairInteractions, toAtomPairInteractions),
            Helpers.getIntersectionOfTwoSets(fromPiStackings, toPiStackings),
            Helpers.getIntersectionOfTwoSets(fromCationPiStackings, toCationPiStackings),
            true
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates intermolecular coordinates based on
     * coordinates of the involved atom/structureCircle and center information
     * of the involved ring system/structureCircle.
     *
     * @param intermolecularIds {Array} - intermolecular ids for coordinates updated
     * @param type {String} - identifier of the intermolecular edge
     * @param updateDrawInfo {Boolean} - whether to upgrade the draw info
     * of the intermolecular edge
     * @param byTemp {Boolean} - whether to use temp coordinates
     */
    updateAllIntermolecularOfType(intermolecularIds, type, updateDrawInfo = false, byTemp = false) {
        intermolecularIds.forEach(interactionId => {
            this.updateSingleIntermolecular(interactionId, type, updateDrawInfo, byTemp);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates coordinates of all intermolecular types.
     *
     * @param updateDrawInfo {Boolean} - whether to upgrade the draw info
     * of the intermolecular edge
     * @param byTemp {Boolean} - whether to use temp coordinates.
     */
    updateAllIntermolecular(distances,
        interactions,
        atomPairInteractions,
        piStackings,
        cationPiStackings,
        updateDrawInfo = false,
        byTemp = false
    ) {
        this.updateAllIntermolecularOfType(distances, 'distances', updateDrawInfo, byTemp);
        this.updateAllIntermolecularOfType(interactions, 'interactions', updateDrawInfo, byTemp);
        this.updateAllIntermolecularOfType(atomPairInteractions,
            'atomPairInteractions',
            updateDrawInfo,
            byTemp
        );
        this.updateAllIntermolecularOfType(piStackings, 'piStackings', updateDrawInfo, byTemp);
        this.updateAllIntermolecularOfType(cationPiStackings,
            'cationPiStackings',
            updateDrawInfo,
            byTemp
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Update coordinates of endpoints of one intermolecular endpoints.
     *
     * @param interactionId {Number} - ids of the cation pi stacking to move
     * @param type {String} - identifier of the intermolecular edge
     * @param updateDrawInfo {Boolean} - whether to upgrade this intermolecular
     * draw info
     * @param byTemp {Boolean} - whether to use temp coordinates
     */
    updateSingleIntermolecular(interactionId, type, updateDrawInfo = false, byTemp = false) {
        const interaction = this.sceneData.intermolecularData[type][interactionId];
        const {
            from: from, to: to, fromStructure: fromStructureId, toStructure: toStructureId
        } = interaction;
        const fromStructure = this.sceneData.structuresData.structures[fromStructureId];
        const toStructure = this.sceneData.structuresData.structures[toStructureId];
        if (fromStructure && toStructure) {
            const midpoints = this.edgeBuilder.getNewIntermolecularCoords(interactionId,
                type,
                fromStructure,
                toStructure,
                from,
                to,
                byTemp
            );
            const [midFrom, midTo] = midpoints;
            const interactionInfo = this.edgeBuilder.createSingleEdge(midFrom, midTo);
            if (type === 'atomPairInteractions') {
                this.createUpdateAtomPairInteraction(interactionId, interactionInfo, byTemp, type)();
            } else {
                this.intermolecularGroupsComponent.moveIntermolecular(interactionId,
                    interactionInfo,
                    type
                );
            }
            if (updateDrawInfo) {
                interaction.setDrawInfo(interactionInfo, byTemp);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Similar to createEdgeUpdateFunction(), determines what should happen to a
     * atom pair interaction based on newly calculated bond draw information.
     *
     * @param atomPairInteractionId {Number} - id of the atom pair interaction
     * @param atomPairInteractionInfo {Object} - draw information for the atom pair interaction
     * @param byTemp {Boolean} - whether to base atom pair interaction update on
     * temporary visibility information
     * @returns {Function} - the function to perform the update
     */
    createUpdateAtomPairInteraction(atomPairInteractionId, atomPairInteractionInfo, byTemp, type) {
        const atomPairInteraction = this.sceneData.intermolecularData[type][atomPairInteractionId];
        const hiddenParam = byTemp ? 'tempHidden' : 'hidden';
        if (!atomPairInteractionInfo) {
            if (!atomPairInteraction[hiddenParam]) { //remove representation
                return () => {
                    atomPairInteraction.setHidden(true, byTemp);
                    this.intermolecularGroupsComponent.removeIntermolecularFromDOM(atomPairInteractionId,
                        type
                    );
                }
            } else { //else no need to do anything
                return () => {
                };
            }
        } else {
            if (atomPairInteraction[hiddenParam]) {
                if (!this.intermolecularGroupsComponent.wasAtomPairInteractionDrawnBefore(
                    atomPairInteractionId)) {
                    return () => {
                        atomPairInteraction.setHidden(false, byTemp);
                        this.intermolecularGroupsComponent.drawIntermolecular(atomPairInteraction,
                            atomPairInteractionInfo,
                            type
                        );
                    }
                } else {
                    return () => {
                        atomPairInteraction.setHidden(false, byTemp);
                        this.intermolecularGroupsComponent.redrawIntermolecular(atomPairInteractionId,
                            type
                        );
                        this.intermolecularGroupsComponent.moveIntermolecular(atomPairInteractionId,
                            atomPairInteractionInfo,
                            type
                        );
                    }
                }
            } else {
                return () => {
                    this.intermolecularGroupsComponent.moveIntermolecular(atomPairInteractionId,
                        atomPairInteractionInfo,
                        type
                    );
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified interactions in the draw area.
     *
     * @param remInteractions {Set} - ids of interactions to remove
     * @param remChanges {Array} - change objects for the history step
     * @param type {String} - identifier of the intermolecular edge
     */
    removeIntermolecular(remInteractions, remChanges, type) {
        const container = this.sceneData.intermolecularData[type];
        remInteractions.forEach(interactionId => {
            if (!container.hasOwnProperty(interactionId) || !container[interactionId].enabled) {
                return;
            }
            const remChange = this.createRemoveChangeIntermolecular(interactionId, type, false);
            remChange.apply();
            remChanges.push(remChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates temporary coordinates for atoms of a structure which are part of
     * cation-pi or atom pair interactions to still allow proper update of these
     * interactions during movement of structures by composite layers.
     *
     * @param structureId {Number} - id of structure moved by composite layers
     * @param offset {Object} - x- and y-offsets structure is moved by
     * @param changedAtomIds {StructureIdTracker} - tracker of which atoms'
     * temporary coordinates are changed during movement
     * @param connectionType {String} - name of the intermolecular connection
     */
    updateTempCoordsForIntermolecularAtom(structureId, offset, changedAtomIds, connectionType) {
        const structure = this.sceneData.structuresData.structures[structureId];
        Object.keys(structure.intermolecularConnectionData.connections[connectionType].atom)
            .forEach(atomId => {
                AtomDrawer.updateTempCoordsForAtom(structure,
                    parseInt(atomId),
                    offset,
                    changedAtomIds
                );
            });
    };

    /*----------------------------------------------------------------------*/

    /**
     * For a structure specified by id, note in a provided container which ring
     * systems have to be updated based on connected aromatic ring interactions,
     * i. e. pi-pi and cation-pi
     * @param structureId {Number} - id of the structure
     * @param changedRingSys {StructureIdTracker} - container to mark ring
     * @param type {String} - identifier of the intermolecular edge
     * systems to update in
     */
    findRingSystemsToTempUpdateIntermolecular(structureId, changedRingSys, type) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const ringIds = Object.keys(structure.intermolecularConnectionData.connections[type].ring);
        ringIds.forEach(ringId => {
            RingDrawer.markRingSystemForTempUpdate(structureId,
                parseInt(structure.ringsData.getRing(ringId).ringSystem),
                changedRingSys
            );
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an interaction in the draw area and mark it as selected in the
     * interactions's container.
     *
     * @param interactionId {Number} - id of the interaction to unselect
     * @param type {String} - identifier of the intermolecular edge
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    selectIntermolecularDrawareaContainer(interactionId, type, executeCallback = true) {
        const container = this.sceneData.intermolecularData[type];
        if (!container.hasOwnProperty(interactionId)) {
            return;
        }
        const interaction = container[interactionId];
        this.sceneData.intermolecularData.selectedIntermolecular[type].add(interactionId);
        interaction.selected = true;
        this.intermolecularGroupsComponent.selectIntermolecular(interactionId, type);
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: type,
                selectionType: 'select',
                interactionId: parseInt(interactionId),
                additionalInformation: interaction.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an interaction in the draw area and remove its selection status inside
     * the interaction's container.
     *
     * @param interactionId {Number} - id of the interaction to unselect
     * @param type {String} - identifier of the intermolecular edge
     * @param hover {Boolean} - whether interaction is to be shown as hovered
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectIntermolecularDrawareaContainer(interactionId,
        type,
        hover = false,
        executeCallback = true
    ) {
        const container = this.sceneData.intermolecularData[type];
        if (!container.hasOwnProperty(interactionId)) {
            return;
        }
        const interaction = container[interactionId];
        this.sceneData.intermolecularData.selectedIntermolecular[type].delete(parseInt(interactionId));
        interaction.selected = false;
        if (hover) {
            this.intermolecularGroupsComponent.hoverIntermolecular(interactionId, type);
        } else {
            this.intermolecularGroupsComponent.unselectIntermolecular(interactionId, type);
        }
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: type,
                selectionType: 'unselect',
                interactionId: parseInt(interactionId),
                additionalInformation: interaction.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Instructs the draw layer to unselect all currently hovered intermolecular
     * interactions (atom pair interactions, pi stackings, and cation pi stackings).
     */
    unselectAllIntermolecular() {
        for (const type of this.sceneData.intermolecularData.intermolecularTypes) {
            for (const intermolecularId in this.sceneData.intermolecularData[type]) {
                if (!this.sceneData.intermolecularData.selectedIntermolecular[type].has(parseInt(
                    intermolecularId))) {
                    this.intermolecularGroupsComponent.unselectIntermolecular(intermolecularId,
                        type
                    )
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes an intermolecular edge from the DOM and the view cache.
     *
     * @param interactionId {Number} - id of the interaction to remove
     * @param type {String} - identifier of the intermolecular edge
     */
    removeIntermolecularDOMCache(interactionId, type) {
        this.intermolecularGroupsComponent.removeIntermolecularFromDOM(interactionId, type);
        this.intermolecularGroupsComponent.purgeIntermolecularFromCache(interactionId, type);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers an intermolecular edge.
     *
     * @param interactionId {Number} - id of the interaction to hover
     * @param type {String} - identifier of the intermolecular edge
     */
    hoverIntermolecular(interactionId, type) {
        this.intermolecularGroupsComponent.hoverIntermolecular(interactionId, type);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an intermolecular edge in the draw area only.
     *
     * @param intermolecularId {Number} - id of the intermolecular edge to unselect
     * @param type {String} - identifier of the intermolecular edge
     */
    unselectIntermolecularDrawarea(intermolecularId, type) {
        this.intermolecularGroupsComponent.unselectIntermolecular(intermolecularId, type);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an intermolecular edge in the draw area only.
     *
     * @param intermolecularId {Number} - id of the intermolecular edge to select
     * @param type {String} - identifier of the intermolecular edge
     */
    selectIntermolecularDrawarea(intermolecularId, type) {
        this.intermolecularGroupsComponent.selectIntermolecular(intermolecularId, type);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes an intermolecular edge from the draw area and data.
     *
     * @param intermolecularId {Number} - id of the intermolecular edge to remove
     * @param type {String} - identifier of the intermolecular edge
     */
    removeGeomineQueryPointToPointConstraintDataView(intermolecularId, type) {
        const intermolecularData = this.sceneData.intermolecularData;
        const intermolecularEdge = intermolecularData[type][intermolecularId];
        const fromStructureId = intermolecularEdge.fromStructure;
        const toStructureId = intermolecularEdge.toStructure;
        const fromStructure = this.sceneData.structuresData.structures[fromStructureId];
        const intermolecularConnectionDataFrom = fromStructure.intermolecularConnectionData;
        intermolecularConnectionDataFrom.ids[type].delete(intermolecularId);
        const connectionsFrom = intermolecularConnectionDataFrom.connections;
        delete connectionsFrom[type].annotation[intermolecularEdge.from];
        const toStructure = this.sceneData.structuresData.structures[toStructureId];
        const intermolecularConnectionDataTo = toStructure.intermolecularConnectionData;
        intermolecularConnectionDataTo.ids[type].delete(intermolecularId);
        const connectionsTo = intermolecularConnectionDataTo.connections;
        delete connectionsTo[type].annotation[intermolecularEdge.to];
        this.removeIntermolecularDOMCache(intermolecularId, type);
        intermolecularData.selectedIntermolecular[type].delete(intermolecularId);
        delete intermolecularData[type][intermolecularId];
    }
}

/* src/Drawers/Structure/AtomDrawer.js */
/**
 * Drawer that uses its own component for the visualization of structure atoms.
 */
class AtomDrawer {
    /**
     * Contains instances for configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     * A selection callback can be set optionally.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param atomGroupsComponent {Object} - component for atoms
     */
    constructor(opts, sceneData, atomGroupsComponent) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.atomGroupsComponent = atomGroupsComponent;

        this.selectionCallback = null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the atoms of a structure into the draw area.
     *
     * @param structure {Structure} - Structure object which holds the atom
     * information
     * @param selectedAtoms {Array} - atom ids of atoms to immediately select
     */
    drawStructureAtoms(structure, selectedAtoms) {
        const structureId = structure.id;
        structure.atomsData.atoms.forEach(atom => {
            this.atomGroupsComponent.drawAtom(structure, atom);
            if (atom.isLabel) {
                this.atomGroupsComponent.anchorAtomLabel(structureId, atom);
            }
            this.updateAtomDrawLimits(structureId, atom.id, atom)
        });

        //apply user-defined selection for atoms
        if (selectedAtoms) {
            selectedAtoms.forEach(atomId => {
                if (structure.atomsData.getAtom(atomId)) { //avoid bad input
                    this.selectAtomDrawareaContainer(structureId, atomId);
                }
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to change the color of an atom to a new one.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atom {Atom} - Atom object representing the atom
     * @param oldColor {String} - previous color of the atom
     * @param newColor {String} - new color of the atom
     * @returns {Change} - Change object to apply/revert the recoloring
     */
    createColorChangeAtom(structureId, atom, oldColor, newColor) {
        const atomId = atom.id;
        const colorChange = new Change();
        let colorNew, colorOld;
        //even if atom is not explicitly drawn, its color info must change
        if (atom.element === 'C') {
            colorNew = () => {
                atom.color = newColor;
            };
            colorOld = () => {
                atom.color = oldColor;
            };
        } else {
            colorNew = () => {
                this.atomGroupsComponent.recolorAtom(structureId, atomId, newColor);
                atom.color = newColor;
            };
            colorOld = () => {
                this.atomGroupsComponent.recolorAtom(structureId, atomId, oldColor);
                atom.color = oldColor;
            };
        }
        colorChange.bindApply(colorNew);
        colorChange.bindRevert(colorOld);
        return colorChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified atoms in the draw area.
     *
     * @param remAtoms {Set} - ids of atoms to remove
     * @param remChanges {Array} - Change objects for the history step
     * @param markRequiredRecalcs {Function} - function to memory changes in
     * structure/scene boundaries
     * @returns {Set} - edges affected by this atoms that should be also removed
     */
    removeAtoms(remAtoms, remChanges, markRequiredRecalcs) {
        const remEdges = new Set();
        remAtoms.forEach(atomId => {
            const structureId = this.sceneData.structuresData.atomIdsToStructure[atomId];
            if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
                return;
            }

            const structure = this.sceneData.structuresData.structures[structureId];
            const atom = structure.atomsData.getAtom(atomId);
            //filter nonsense or already removed
            if (!atom || !atom.enabled) {
                return;
            }
            const remChange = this.createAddChangeAtom(structure, atom, false);
            remChange.apply();
            remChanges.push(remChange);

            //check if atom defines the structure's boundaries
            const {coordinates: {x: atomX, y: atomY}} = atom;
            markRequiredRecalcs('xMin', atomX, structureId);
            markRequiredRecalcs('xMax', atomX, structureId);
            markRequiredRecalcs('yMin', atomY, structureId);
            markRequiredRecalcs('yMax', atomY, structureId);

            //on removing an atom, also remove all its outgoing edges
            const neighbors = structure.atomsData.neighbors[atomId];
            neighbors.forEach(({edgeId}) => {
                remEdges.add({structureId: structureId, edgeId: edgeId});
            });
        });
        return remEdges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified carbon atoms in the draw area.
     *
     * @param remCarbonAtoms {Set} - ids of carbons to remove
     * @param remChanges {Array} - Change objects for the history step
     */
    removeCarbonAtoms(remCarbonAtoms, remChanges) {
        remCarbonAtoms.forEach(atomId => {
            const structureId = this.sceneData.structuresData.atomIdsToStructure[atomId];
            if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
                return;
            }

            const structure = this.sceneData.structuresData.structures[structureId];
            let noEdges = true;
            const neighbors = structure.atomsData.neighbors[atomId];
            for (let i = 0, len = neighbors.length; i < len; ++i) {
                const edge = structure.edgesData.getEdge(neighbors[i].edgeId);
                if (edge.enabled) {
                    noEdges = false;
                    break;
                }
            }
            if (noEdges) {
                const atom = structure.atomsData.getAtom(atomId);
                const remChange = this.createAddChangeAtom(structure, atom, false);
                remChange.apply();
                remChanges.push(remChange);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to add/remove an atom.
     *
     * @param structure {Structure} - Structure object which holds the atom
     * @param atom {Atom} - Atom object representing the atom to add
     * @param isAdd {Boolean} - whether the change should add the atom as its
     * apply() or revert() function
     * @returns {DomChange} - Change object to apply/revert adding of the atom
     */
    createAddChangeAtom(structure, atom, isAdd) {
        const structureId = structure.id;
        const atomId = atom.id;
        const addChange = new DomChange(isAdd);
        const wasSelected = structure.atomsData.selectedAtoms.has(atomId);
        let linkedAnnotations = [];
        let linkedControlPoints = [];
        for (const annotationId in this.sceneData.annotationsData.annotations) {
            const annotation = this.sceneData.annotationsData.annotations[annotationId];
            if (annotation.atomLinks && annotation.atomLinks.includes(atomId)) {
                linkedAnnotations.push(annotation);
            }
        }
        for (const hydrophobicContactId in this.sceneData.hydrophobicData.hydrophobicContacts) {
            const hydrophobicContact =
                this.sceneData.hydrophobicData.hydrophobicContacts[hydrophobicContactId];
            hydrophobicContact.controlPoints.forEach((cp, idx) => {
                if (cp.atomLinks && cp.atomLinks.includes(atomId)) {
                    linkedControlPoints.push(cp);
                }
            });
        }
        const rem = () => {
            this.atomGroupsComponent.removeAtom(structureId, atomId, false);
            atom.enabled = false;
            atom.selected = false;
            structure.atomsData.selectedAtoms.delete(atomId);
            for (const controlPoint of linkedControlPoints) {
                controlPoint.atomLinks = controlPoint.atomLinks.filter(id => {
                    return id !== atom.id;
                });
            }
            for (const annotation of linkedAnnotations) {
                annotation.atomLinks = annotation.atomLinks.filter(id => {
                    return id !== atom.id;
                });
            }
        };
        const add = () => {
            this.atomGroupsComponent.redrawAtom(structureId, atom);
            atom.enabled = true;
            for (const controlPoint of linkedControlPoints) {
                controlPoint.atomLinks.push(atom.id);
            }
            for (const annotation of linkedAnnotations) {
                annotation.atomLinks.push(atom.id);
            }
        };
        addChange.bindApplyRevert(add, rem);
        return addChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an atom in the draw area and mark it as selected in the atom's
     * Structure container.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atomId {Number} - id of the atom to select
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    selectAtomDrawareaContainer(structureId, atomId, executeCallback = true) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        const atom = structure.atomsData.getAtom(atomId);
        structure.atomsData.selectAtom(atomId);
        this.atomGroupsComponent.selectAtom(structureId, atomId);
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'atom',
                selectionType: 'select',
                structureId: parseInt(structureId),
                structureName: structure.structureName,
                structureType: structure.structureType,
                atomId: parseInt(atomId),
                additionalInformation: atom.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an atom in the draw area.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atomId {Number} - id of the atom to select
     */
    selectAtomDrawarea(structureId, atomId) {
        this.atomGroupsComponent.selectAtom(structureId, atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For given atoms (by id), updates temporary coordinates based on given
     * offsets.
     *
     * @param atomsToUpdate {Array} - ids of atoms to update
     * @param offset {Object} - x- and y-offsets to apply to temp coordinates
     */
    updateTempCoordsForAtoms(atomsToUpdate, offset) {
        for (const structureId in atomsToUpdate) {
            const structure = this.sceneData.structuresData.structures[structureId];
            atomsToUpdate[structureId].forEach(atomId => {
                const updateAtom = structure.atomsData.getAtom(atomId);
                updateAtom.addOffsetToCoords(offset, true);
            })
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the draw elements associated with the representation of atoms given
     * by id in the draw area based on offsets between their last 'real' and
     * current temporary coordinates.
     *
     * @param atomsToUpdate {Object} - atom ids to move draw elements for
     */
    moveAtomsToTempCoordinates(atomsToUpdate) {
        for (const structureId in atomsToUpdate) {
            const structure = this.sceneData.structuresData.structures[structureId];
            atomsToUpdate[structureId].forEach(atomId => {
                const {coordinates, tempCoordinates} = structure.atomsData.getAtom(atomId);
                const offset = {
                    x: tempCoordinates.x - coordinates.x, y: tempCoordinates.y - coordinates.y
                };
                this.atomGroupsComponent.moveAtom(structureId, atomId, offset);
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the draw elements associated with the representation of atoms not
     * part of any ring given by id in the draw area based on given offsets.
     *
     * @param atomsToUpdate {Array} - atom ids to move draw elements for
     * @param offset {Object} - x- and y-offsets to move draw elements by
     */
    moveNonRingAtomsByOffset(atomsToUpdate, offset) {
        for (const structureId in atomsToUpdate) {
            const structure = this.sceneData.structuresData.structures[structureId];
            atomsToUpdate[structureId].forEach(atomId => {
                if (!structure.atomsData.getAtom(atomId).isInRing) {
                    this.atomGroupsComponent.moveAtom(structureId, atomId, offset);
                }
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * When atoms are moved, the ideal placement of hydrogen labels around the
     * main text label can change. Here, creates the Change object to place the
     * hydrogen text on a given side of the main text.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atom {Atom} - Atom object representing the atom
     * @param newHorientation {String} - "left", "right", "up", or "down"
     * @returns {Change} - Change object to apply/revert placement of hydrogen
     * text
     */
    createHPlacementChange(structureId, atom, newHorientation) {
        const hChange = new Change();
        const oldHorientation = atom.hydrogenOrientation;
        const apply = () => {
            atom.setHydrogenOrientation(newHorientation);
            atom.setTempHydrogenOrientation(newHorientation);
            this.atomGroupsComponent.placeHByOrientation(structureId, atom, false);
        };
        const revert = () => {
            atom.setHydrogenOrientation(oldHorientation);
            atom.setTempHydrogenOrientation(oldHorientation);
            this.atomGroupsComponent.placeHByOrientation(structureId, atom, false);
        };
        hChange.bindApply(apply);
        hChange.bindRevert(revert);
        return hChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For all structures, if two neighboring bonds are selected, also select
     * the atom between these bonds.
     */
    selectAtomsBetweenSelectedEdges() {
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.edgesData.selectedEdges.forEach(edgeId => {
                structure.edgesData.findAtomsToSelectOnEdgeSelect(edgeId)
                    .forEach(atomId => {
                        this.selectAtomDrawareaContainer(structureId, atomId);
                    });
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects an atom in the draw area and mark it as temporally (!) selected
     * in the atom's Structure container.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atomId {Number} - id of the atom to select
     */
    tempSelectAtom(structureId, atomId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.atomsData.tempSelectAtom(atomId);
        this.atomGroupsComponent.selectAtom(structureId, atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an atom in the draw area and remove its selection status inside
     * the Structure container it belongs to.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atomId {Number} - id of the atom to unselect
     * @param hover {Boolean} - whether the atom is to be shown as hovered
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectAtomDrawareaContainer(structureId, atomId, hover = false, executeCallback = true) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        const atom = structure.atomsData.getAtom(atomId);
        structure.atomsData.selectedAtoms.delete(atomId);
        if (hover) {
            this.atomGroupsComponent.hoverAtom(structureId, atomId);
        } else {
            this.atomGroupsComponent.unselectAtom(structureId, atomId);
        }
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'atom',
                selectionType: 'unselect',
                structureId: parseInt(structureId),
                structureName: structure.structureName,
                structureType: structure.structureType,
                atomId: parseInt(atomId),
                additionalInformation: atom.additionalInformation
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects an atom in the draw area.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atomId {Number} - id of the atom to unselect
     */
    unselectAtomDrawarea(structureId, atomId) {
        this.atomGroupsComponent.unselectAtom(structureId, atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates temporary coordinates of an atom based on given offsets. Note the
     * updated atom in a provided container.
     *
     * @param structure {Structure} - Structure object holding the atom
     * @param atomId {Number} - id of the atom to update
     * @param offset {Object} - x- and y-offsets to apply to temp coordinates
     * @param tracker {StructureIdTracker} - container to note the updated atom
     * in
     */
    static updateTempCoordsForAtom(structure, atomId, offset, tracker) {
        if (tracker.hasID(structure.id, atomId)) return;
        //update temp coordinates and mark as updated
        const updateAtom = structure.atomsData.getAtom(atomId);
        updateAtom.addOffsetToCoords(offset, true);
        tracker.addID(structure.id, atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the draw elements associated with the representation of atoms given
     * by id in the draw area based on given offsets.
     *
     * @param atomsToUpdate {Object} - atom ids to move draw elements for
     * @param offset {Object} - x- and y-offsets to move draw elements by
     */
    moveAtomsByOffset(atomsToUpdate, offset) {
        for (const structureId in atomsToUpdate) {
            atomsToUpdate[structureId].forEach(atomId => {
                this.atomGroupsComponent.moveAtom(structureId, atomId, offset)
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates bbox draw limits of all text elements making up the
     * representation of an atom.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - id of Atom object to update limits for
     * @param atom {Atom} - Atom object to update limits for
     */
    updateAtomDrawLimits(structureId, atomId, atom) {
        atom.setSelectorShapes(this.atomGroupsComponent.getAtomSelShapes(structureId, atomId));
        atom.setDrawLimits(this.atomGroupsComponent.getAtomDrawLimits(structureId, atom));
    }

    /*----------------------------------------------------------------------*/

    /**
     * When atoms are moved, the ideal anchor side for labels representing
     * amino acids can change. Here, creates the Change object to re-anchor a
     * label on a new side.
     *
     * @param structureId {Number} - id of the structure the atom belongs to
     * @param atom {Atom} - Atom object representing the atom
     * @param newOrientation {String} - "left", "right", "up", or "down"
     * @returns {Change} - Change object to apply/revert the new anchoring
     */
    createAnchorPlacementChange(structureId, atom, newOrientation) {
        const anchorChange = new Change();
        const oldOrientation = atom.labelOrientation;
        const apply = () => {
            atom.setLabelSide(newOrientation, false);
            this.atomGroupsComponent.anchorAtomLabel(structureId, atom, oldOrientation);
        };
        const revert = () => {
            atom.setLabelSide(oldOrientation, false);
            this.atomGroupsComponent.anchorAtomLabel(structureId, atom, newOrientation);
        };
        anchorChange.bindApply(apply);
        anchorChange.bindRevert(revert);
        return anchorChange;
    };

    /*----------------------------------------------------------------------*/

    /**
     * Moves the draw elements associated with the representation of atoms by
     * individual offsets given in a map of offsets.
     *
     * @param offsetMap {Object} - map from structure ids to atom ids to
     * individual x- and y-offsets to move draw elements by
     */
    moveAtomsByOffsetMap(offsetMap) {
        for (const structureId in offsetMap) {
            const atomOffsets = offsetMap[structureId];
            for (const atomId in atomOffsets) {
                this.atomGroupsComponent.moveAtom(structureId, atomId, atomOffsets[atomId]);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates temporary coordinates of atoms based on individual offsets given
     * in a map of offsets.
     *
     * @param offsetMap {Object} - map from structure ids to atom ids to
     * individual x- and y-offsets to apply to atom temp coordinates
     */
    updateTempCoordsForAtomsByOffsetMap(offsetMap) {
        for (const structureId in offsetMap) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const atomOffsets = offsetMap[structureId];
            for (const atomId in atomOffsets) {
                const updateAtom = structure.atomsData.getAtom(atomId);
                updateAtom.addOffsetToCoords(atomOffsets[atomId], true);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers an atom in the draw area.
     *
     * @param structureId {Number} - the unique id of the structure the atom
     * belongs to
     * @param atomId {Number} - the unique id of the atom to signal as hovered
     */
    hoverAtom(structureId, atomId) {
        this.atomGroupsComponent.hoverAtom(structureId, atomId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a number of structures specified by id, checks and, where necessary,
     * corrects the position of various atom text elements.
     *
     * @param structureIds {Array} - ids of structures to check
     */
    correctAtomTextPlacement(structureIds) {
        this.correctHPlacement(structureIds);
        this.correctLabelPlacement(structureIds);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a number of structures specified by id, checks whether the optimal
     * hydrogen placement on included atoms has changed and corrects it where
     * necessary.
     *
     * @param structureIds {Array} - ids of structures to check
     */
    correctHPlacement(structureIds) {
        structureIds.forEach(structureId => {
            const structure = this.sceneData.structuresData.structures[structureId];
            const changedHs = structure.atomsData.findAtomsWithChangedHPlacement(true);
            for (const atomId in changedHs) {
                const hOrientation = changedHs[atomId];
                const atom = structure.atomsData.getAtom(atomId);
                atom.setTempHydrogenOrientation(hOrientation);
                this.atomGroupsComponent.placeHByOrientation(structureId, atom, true);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a number of structures specified by id, checks whether the optimal
     * anchoring of included atoms representing amino acid labels has changed
     * and corrects it where necessary.
     *
     * @param structureIds {Array} - ids of structures to check
     */
    correctLabelPlacement(structureIds) {
        structureIds.forEach(structureId => {
            const structure = this.sceneData.structuresData.structures[structureId];
            const changedLabels = structure.atomsData.findAtomsWithChangedAnchors(true);
            for (const atomId in changedLabels) {
                const atom = structure.atomsData.getAtom(atomId);
                const prevOrientation = atom.tempLabelOrientation;
                const newOrientation = changedLabels[atomId];
                atom.setLabelSide(newOrientation, true);
                this.atomGroupsComponent.anchorAtomLabel(structureId, atom, prevOrientation);
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates the atoms of a specific structure around a given midpoint.
     *
     * @param structureId {Number} - unique id of structure to rotate
     * @param angle {Number} - angle (in degrees!) to rotate by
     * @param midpoint {Object} - x- and y-coordinates of the point to rotate
     * the structure around. If none given, take midpoint of the structure's
     * bounding box
     */
    rotateStructureAtoms(structureId, angle, midpoint) {
        const structure = this.sceneData.structuresData.structures[structureId];

        const rotationOffsets = structure.calcAtomRotationOffsets(angle, true, midpoint);
        const offsetMap = {
            [structure.id]: rotationOffsets
        };
        //atom labels have to be oriented correctly, need new temp coordinates
        this.updateTempCoordsForAtomsByOffsetMap(offsetMap);
        this.moveAtomsByOffsetMap(offsetMap);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (as groups) of ring system atoms by specified
     * offsets.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to move skeleton of
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     */
    moveRingAtomSkeleton(structureId, ringSysId, xOffset, yOffset) {
        this.atomGroupsComponent.moveRingAtomSkeleton(structureId, ringSysId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for atoms of a certain ring system.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to reset translations
     * for
     */
    resetRingAtomSkeletonTranslation(structureId, ringSysId) {
        this.atomGroupsComponent.resetRingAtomSkeletonTranslation(structureId, ringSysId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a (new) structure, adds new container groups to the svg for atoms.
     * Creates a new wrapper in the atom group. Further
     * prepares the mapping of selectors for later access. In the selector
     * map, the created groups are mapped also, so they may be hidden later.
     *
     * @param structure {Structure} - Structure object
     * @param structureId {structureId} - id of Structure object
     * @param debug {Boolean} - true if debug information shall be visualized
     */
    addAtomsToTrack(structure, structureId, debug) {
        this.atomGroupsComponent.addAtomsToTrack(structure, structureId, debug);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural atom skeleton (as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveAtomSkeleton(structureId, xOffset, yOffset) {
        this.atomGroupsComponent.moveAtomSkeleton(structureId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for atoms of a certain structure.
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetAtomSkeletonTranslation(structureId) {
        this.atomGroupsComponent.resetAtomSkeletonTranslation(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all atoms of a structure from the DOM.
     *
     * @param structureId {Number} - the unique id of the structure to remove
     * its atoms from the DOM
     */
    removeStructureAtomsFromDOM(structureId) {
        this.atomGroupsComponent.removeStructureAtomsFromDOM(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Remove all cached information for a given structure (by its id).
     *
     * @param structureId {Number} - id of structure to remove atom information
     * from.
     */
    purgeStructureAtomsFromCache(structureId) {
        this.atomGroupsComponent.purgeStructureAtomsFromCache(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached atom DOM elements back
     * into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructureAtoms(structureId) {
        this.atomGroupsComponent.redrawStructureAtoms(structureId);
    }
}

/* src/Drawers/Structure/EdgeDrawer.js */
/**
 * Drawer that uses its own component for the visualization of structure edges.
 */
class EdgeDrawer {
    /**
     * Contains instances for configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     * A selection callback can be set optionally.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param edgeGroupsComponent {Object} - component for edges
     */
    constructor(opts, sceneData, edgeGroupsComponent) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.edgeGroupsComponent = edgeGroupsComponent;

        this.selectionCallback = null;
        this.edgeBuilder = new EdgeBuilder(opts, sceneData);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the bonds of a structure into the draw area.
     *
     * @param structure {Structure} - Structure object which holds the bond
     * information
     * @param selectedEdges {Array} - bond ids of bonds to immediately select
     */
    drawStructureEdges(structure, selectedEdges) {
        structure.edgesData.edges.forEach(edge => {
            const fromAtom = structure.atomsData.getAtom(edge.from);
            const toAtom = structure.atomsData.getAtom(edge.to);
            const bondInfo = this.edgeBuilder.createBondByType(edge.from,
                edge.to,
                structure,
                edge,
                false
            );
            //only new draw possible, reject if edge not drawable
            if (!bondInfo) {
                return;
            }
            //does not matter where this happens, drawInfo is initialized with null
            edge.setDrawInfo(bondInfo, false);
            this.edgeGroupsComponent.drawEdge(structure, edge, fromAtom, toAtom, false);
            edge.setHidden(false, false);
        });

        //apply user-defined selection to edges
        if (selectedEdges) {
            selectedEdges.forEach(edgeId => {
                if (structure.edgesData.getEdge(edgeId)) { //avoid bad input
                    this.selectEdgeDrawareaContainer(structure.id, edgeId);
                }
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified edges in the draw area.
     *
     * @param remEdges {Set} - ids of edges to remove
     * @param remChanges {Array} - change objects for the history step
     * @returns {Set} - carbon atoms affected by this edges that should also
     * be removed
     */
    removeEdges(remEdges, remChanges) {
        const remCarbonAtoms = new Set();
        remEdges.forEach(removeEdges => {
            const structureId = removeEdges.structureId;
            const edgeId = removeEdges.edgeId;

            if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
                return;
            }
            const structure = this.sceneData.structuresData.structures[structureId];
            const edge = structure.edgesData.getEdge(edgeId);
            if (!edge || !edge.enabled) {
                return;
            }
            const remChange = this.createAddChangeEdge(structure, edge, false);
            remChange.apply();
            remChanges.push(remChange);
            [edge.from, edge.to].forEach(atomId => {
                const atom = structure.atomsData.getAtom(atomId);
                if (atom.enabled && atom.element === 'C') {
                    remCarbonAtoms.add(atom.id);
                }
            });
        });
        return remCarbonAtoms;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to add/remove a bond.
     *
     * @param structure {Structure} - Structure object which holds the bond
     * @param edge {Edge} - Edge object representing the bond to add
     * @param isAdd {Boolean} - whether the change should add the bond as its
     * apply() or revert() function
     * @returns {DomChange} - Change object to apply/revert adding of the bond
     */
    createAddChangeEdge(structure, edge, isAdd) {
        const structureId = structure.id;
        const edgeId = edge.id;
        const addChange = new DomChange(isAdd);
        const wasSelected = structure.edgesData.selectedEdges.has(edgeId);
        const rem = () => {
            this.edgeGroupsComponent.removeEdge(structureId, edgeId, false);
            edge.enabled = false;
            edge.selected = false;
            structure.edgesData.selectedEdges.delete(edgeId);
        };
        const add = () => {
            this.edgeGroupsComponent.redrawEdge(structureId, edge);
            edge.enabled = true;
        };
        addChange.bindApplyRevert(add, rem);
        return addChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a bond in the draw area and mark it as selected in the bond's
     * Structure container.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to select
     */
    selectEdgeDrawareaContainer(structureId, edgeId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.edgesData.selectEdge(edgeId);
        this.edgeGroupsComponent.selectEdge(structureId, edgeId);
        if (this.selectionCallback) {
            this.selectionCallback({
                type: 'edge',
                selectionType: 'select',
                structureId: parseInt(structureId),
                edgeId: parseInt(edgeId)
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a bond in the draw area.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to select
     */
    selectEdgeDrawarea(structureId, edgeId) {
        this.edgeGroupsComponent.selectEdge(structureId, edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates all bonds including given atoms (by ids) based on the new
     * temporary coordinates of these atoms.
     *
     * @param updatedAtoms {Object} - atom ids affected by interaction
     * @returns {Object} - edge change cases: how the representation of
     * bonds were updated (e.g., moved, hidden, ...)
     */
    moveAffectedEdgesToTempCoordinates(updatedAtoms) {
        const edgeChangeCases = {};
        for (const structureId in updatedAtoms) {
            const sEdgeChangeCases = {};
            const structure = this.sceneData.structuresData.structures[structureId];
            const edgesToMove = structure.edgesData.getEdgesAffectedByAtoms(updatedAtoms[structureId]);
            edgesToMove.forEach(edgeId => {
                const edge = structure.edgesData.getEdge(edgeId);
                if (!edge.enabled) {
                    return;
                }
                //create the information on how to draw the edge
                const edgeInfo = this.edgeBuilder.createBondByType(edge.from,
                    edge.to,
                    structure,
                    edge,
                    true
                );
                //from draw information create update function and changeCase
                const edgeUpdate = this.createEdgeUpdateFunction(structure, edge, edgeInfo, true);
                edgeUpdate.function();
                sEdgeChangeCases[edgeId] = edgeUpdate.changeCase;
            });
            edgeChangeCases[structureId] = sEdgeChangeCases;
        }
        return edgeChangeCases;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines what should happen to a bond based upon a newly calculated
     * draw info (which may be null in error case or not drawable scenarios).
     * Returns a function to apply this determined change and a changeCase to
     * indicate what type of change happened (so that objects that directly
     * rely on bonds, like aromatic edges, may be changed accordingly, e.g.,
     * hidden as well when the bond becomes hidden).
     *
     * @param structure {Structure} - Structure object which holds the bond
     * @param edge {Edge} - Edge object representing the bond
     * @param edgeInfo {Object} - draw information for the bond
     * @param byTemp {Boolean} - whether to base bond update on temporary
     * information
     * @param typeChanged {Boolean} - whether the type of the bond changed
     * during last update step
     * @returns {Object} - the function to perform the update (field
     * "function") and what exact type of change occurred (field "changeCase",
     * see EdgeChangeCase in Enums.js)
     */
    createEdgeUpdateFunction(structure, edge, edgeInfo, byTemp, typeChanged = false) {
        const structureId = structure.id;
        const edgeId = edge.id;
        const hiddenParam = byTemp ? 'tempHidden' : 'hidden';
        let updateFunction, changeCase;
        //edge should not be drawn
        if (!edgeInfo) {
            //edge is currently drawn -> remove representation
            if (!edge[hiddenParam]) {
                updateFunction = () => {
                    edge.setHidden(true, byTemp);
                    this.edgeGroupsComponent.removeEdge(structureId, edgeId, false);
                    changeCase = EdgeChangeCase.remove;
                };
                //edge is not drawn, no need to do anything
            } else {
                updateFunction = () => {
                };
                changeCase = EdgeChangeCase.pass;
            }
            //edge should be drawn
        } else {
            //edge is currently not drawn
            if (edge[hiddenParam]) {
                //edge has not been drawn before -> draw for first time
                if (!this.edgeGroupsComponent.wasEdgeDrawnBefore(structureId, edgeId)) {
                    const fromAtom = structure.atomsData.getAtom(edge.from);
                    const toAtom = structure.atomsData.getAtom(edge.to);
                    //the way things are set up, this only ever happens in temp update
                    updateFunction = () => {
                        this.edgeGroupsComponent.drawEdge(structure,
                            edge,
                            fromAtom,
                            toAtom,
                            byTemp
                        );
                        edge.setHidden(false, byTemp);
                    };
                    changeCase = EdgeChangeCase.draw;
                    //edge has been drawn before -> add representation back and move
                } else {
                    updateFunction = () => {
                        this.edgeGroupsComponent.redrawEdge(structureId, edge);
                        this.edgeGroupsComponent.moveEdge(structure, edge, byTemp, typeChanged);
                        edge.setHidden(false, byTemp);
                    };
                    changeCase = EdgeChangeCase.redraw;
                }
                //edge is currently drawn -> move edge representation
            } else {
                updateFunction = () => {
                    this.edgeGroupsComponent.moveEdge(structure, edge, byTemp, typeChanged);
                };
                changeCase = EdgeChangeCase.move;
            }
        }
        return {
            function: () => {
                edge.setDrawInfo(edgeInfo, byTemp);
                updateFunction();
            }, changeCase: changeCase
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates all non-cyclic bonds including given atoms (by ids) based on the
     * new temporary coordinates of these atoms.
     *
     * @param updatedAtoms {Object} - atom ids affected by interaction
     */
    moveAffectedNonCyclicEdgesToTempCoordinates(updatedAtoms) {
        for (const structureId in updatedAtoms) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const edgesToMove = structure.edgesData.getEdgesAffectedByAtoms(updatedAtoms[structureId]);
            edgesToMove.forEach(edgeId => {
                const edge = structure.edgesData.getEdge(edgeId);
                if (!edge.enabled || edge.cyclic) {
                    return;
                }
                //create the information on how to draw the edge
                const edgeInfo = this.edgeBuilder.createBondByType(edge.from,
                    edge.to,
                    structure,
                    edge,
                    true
                );
                //update based on draw information
                this.createEdgeUpdateFunction(structure, edge, edgeInfo, true)
                    .function();
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to update the representation of a bond by
     * creating new draw information based on updated atom coordinates of the
     * atoms involved in the bond.
     *
     * @param structure {Structure} - Structure object which holds the bond
     * @param edge {Edge} - Edge object representing the bond
     * @param flipEdges {Set} - ids of stereo bonds that have to be flipped
     * @param edgeChangeCases {Object} - map from bond ids to log of how the
     * bond representation changes after immediate coordinate update and on
     * both apply and revert of the Change
     * @returns {Change} - Change object to apply/revert the bond update
     */
    updateEdgeCoordinates(structure, edge, flipEdges, edgeChangeCases) {
        const edgeId = edge.id;
        const edgeInfo = this.edgeBuilder.createBondByType(edge.from,
            edge.to,
            structure,
            edge,
            false
        );
        const oldEdgeInfo = edge.drawInfo;
        const wasFlipped = flipEdges.has(edgeId);
        //update the edge based on prev temp changes, this might be first draw
        const immediateUpdate = this.createEdgeUpdateFunction(structure,
            edge,
            edgeInfo,
            true,
            wasFlipped
        );
        immediateUpdate.function();
        //create full change from last recorded history point
        const edgeChange = new Change();
        const forwardUpdate = this.createEdgeUpdateFunction(structure,
            edge,
            edgeInfo,
            false,
            wasFlipped
        );
        //update the real draw info (missing from tempEdgeUpdate)
        edge.transferTempInformation();
        const backwardUpdate = this.createEdgeUpdateFunction(structure,
            edge,
            oldEdgeInfo,
            false,
            wasFlipped
        );
        //updates for angles
        let angleUpdateForward, angleUpdateBackward;
        if (edge.hidden) {
            angleUpdateForward = () => {
            };
            angleUpdateBackward = () => {
            };
        } else {
            const prevAngles = Object.assign({}, structure.edgesData.angles[edgeId]);
            //angles should be bundled in here
            structure.edgesData.calcRelevantAnglesForEdge(edgeId, true, false);
            const newAngles = Object.assign({}, structure.edgesData.angles[edgeId]);
            angleUpdateForward = () => {
                structure.edgesData.angles[edgeId] = Object.assign({}, newAngles);
            };
            angleUpdateBackward = () => {
                structure.edgesData.angles[edgeId] = Object.assign({}, prevAngles);
            }
        }
        edgeChangeCases[edgeId] = {
            immediate: immediateUpdate.changeCase,
            forward: forwardUpdate.changeCase,
            backward: backwardUpdate.changeCase
        };

        edgeChange.bindApply(() => {
            forwardUpdate.function();
            angleUpdateForward();
        });
        edgeChange.bindRevert(() => {
            backwardUpdate.function();
            angleUpdateBackward();
        });
        return edgeChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to change the type of a stereo bond to the
     * opposite type.
     *
     * @param edge {Edge} - Edge object representing the stereo bond
     * @returns {Change} - Change object to apply/revert type changing
     */
    createEdgeFlipChange(edge) {
        const flipChange = new Change();
        const type = edge.type;
        const newStereo = EdgeInfo.oppositeStereo(type);
        const apply = () => {
            edge.type = newStereo;
        };
        const revert = () => {
            edge.type = type;
        };
        flipChange.bindApply(apply);
        flipChange.bindRevert(revert);
        return flipChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a bond in the draw area and mark it as temporarily (!) selected
     * in the bond's Structure container.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to select
     */
    tempSelectEdge(structureId, edgeId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.edgesData.tempSelectEdge(edgeId);
        this.edgeGroupsComponent.selectEdge(structureId, edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects a bond in the draw area and remove its selection status inside
     * the Structure container it belongs to.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to select
     * @param hover {Boolean} - whether the bond is to be shown as hovered
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectEdgeDrawareaContainer(
        structureId,
        edgeId,
        hover = false,
        executeCallback = true)
    {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.edgesData.selectedEdges.delete(edgeId);
        if (hover) {
            this.edgeGroupsComponent.hoverEdge(structureId, edgeId);
        } else {
            this.edgeGroupsComponent.unselectEdge(structureId, edgeId);
        }
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'edge',
                selectionType: 'unselect',
                structureId: parseInt(structureId),
                edgeId: parseInt(edgeId)
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects a bond in the draw area.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to select
     */
    unselectEdgeDrawarea(structureId, edgeId) {
        this.edgeGroupsComponent.unselectEdge(structureId, edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers an edge in the draw area.
     *
     * @param structureId {Number} - id of the structure the bond belongs to
     * @param edgeId {Number} - id of the bond to hover
     */
    hoverEdge(structureId, edgeId) {
        this.edgeGroupsComponent.hoverEdge(structureId, edgeId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For specified structures, updates the debug text on bonds to new
     * positions based on updated temporary coordinates.
     *
     * @param structureIds {Array|Set} - ids of structures to update bond
     * debug text for
     */
    updateEdgeDebugTextPositions(structureIds) {
        for (const structureId of structureIds) {
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.edgesData.edges.forEach(({id: edgeId, from, to}) => {
                this.edgeGroupsComponent.moveEdgeDebugText(structureId,
                    edgeId,
                    structure.atomsData.getAtom(from).tempCoordinates,
                    structure.atomsData.getAtom(to).tempCoordinates
                );
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to update the coloring of an edge.
     *
     * @param structureId {Number} - id of the structure the edge belongs to
     * @param edgeId {Number} - id of the edge to recolor
     * @param oldFromColor {String} - old edge color of start point of the gradient
     * @param oldToColor {String} - old edge color of end point of the gradient
     * @param newFromColor {String} - new edge color of start point of the gradient
     * @param newToColor {String} - new edge color of end point of the gradient
     * @returns {Change} - Change object to apply/revert the edge coloring update
     */
    createColorChangeEdge(structureId, edgeId, oldFromColor, oldToColor, newFromColor, newToColor) {
        //create edge color change based on inferred colors
        const edgeColorChange = new Change();
        const colorEdgeNew = () => {
            this.edgeGroupsComponent.recolorEdge(structureId, edgeId, newFromColor, newToColor);
        };
        const colorEdgeOld = () => {
            this.edgeGroupsComponent.recolorEdge(structureId, edgeId, oldFromColor, oldToColor);
        };
        edgeColorChange.bindApply(colorEdgeNew);
        edgeColorChange.bindRevert(colorEdgeOld);
        return edgeColorChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotate the EDGE skeleton of a structure (new atom positions to be set
     * separately).
     *
     * @param structureId {Number} - id of structure to move edge skeleton for
     * @param angle {Number} - angle to rotate by
     * @param origin {Object} - point to rotate around
     * @param isDeg {Boolean} - whether the provided angle is given in degrees
     * or radians
     */
    setRotationEdgeSkeleton(structureId, angle, origin, isDeg = true) {
        this.edgeGroupsComponent.setRotationEdgeSkeleton(structureId, angle, origin, isDeg);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reset the rotation of an edge skeleton.
     *
     * @param structureId {Number} - id of structure to reset rotation for
     */
    resetEdgeSkeletonRotation(structureId) {
        this.edgeGroupsComponent.resetEdgeSkeletonRotation(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * createEdgeUpdate() finds change cases for bonds, determining the type
     * of change applied (e.g., move or removal). Mimics this type of change on
     * the related aromatic bond and create a function to update the aromatic
     * bond accordingly.
     *
     * @param ring {Ring} - Ring object which holds the aromatic bond
     * @param edge {Edge} - Edge object representing the aromatic bond
     * @param structureId {Number} - id of the structure which holds the bond
     * @param changeCase {Number} - the type of change which applied to the
     * bond, see EdgeChangeCase in Enums.js
     * @returns {Function} - the function to perform the update
     */
    createAromaticEdgeUpdateFunction(ring, edge, structureId, changeCase) {
        const ringId = ring.id;
        const edgeId = edge.id;
        switch (changeCase) {
            case EdgeChangeCase.remove:
                return () => {
                    this.edgeGroupsComponent.removeAromaticRingEdge(structureId, edgeId, ringId);
                };
            case EdgeChangeCase.draw:
                return () => {
                    const innerPos = ring.findInnerPositionsForEdge(edge);
                    this.edgeGroupsComponent.drawAromaticRingEdge(structureId,
                        edgeId,
                        ringId,
                        innerPos.from,
                        innerPos.to
                    );
                };
            case EdgeChangeCase.redraw:
                return () => {
                    const innerPos = ring.findInnerPositionsForEdge(edge);
                    this.edgeGroupsComponent.redrawAromaticRingEdge(structureId, edgeId, ringId);
                    this.edgeGroupsComponent.moveAromaticRingEdge(structureId,
                        edgeId,
                        ringId,
                        innerPos.from,
                        innerPos.to
                    );
                };
            case EdgeChangeCase.move:
                return () => {
                    const innerPos = ring.findInnerPositionsForEdge(edge);
                    this.edgeGroupsComponent.moveAromaticRingEdge(structureId,
                        edgeId,
                        ringId,
                        innerPos.from,
                        innerPos.to
                    );
                };
            case EdgeChangeCase.pass:
            default:
                return () => {
                };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For all aromatic rings of a given Structure object, draws the aromatic
     * bonds next to the regular bonds of the ring.
     *
     * @param structure {Structure} - Structure object which holds the ring
     * information
     */
    drawAromaticEdgesForRings(structure) {
        Object.values(structure.ringsData.aromaticRings).forEach(ring => {
            ring.edges.forEach(ringEdge => {
                const innerPositions = ring.findInnerPositionsForEdge(ringEdge, false);
                this.edgeGroupsComponent.drawAromaticRingEdge(structure.id,
                    ringEdge.id,
                    ring.id,
                    innerPositions.from,
                    innerPositions.to
                );
            });
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the aromatic bonds (i.e., the dashed bonds inside) of a ring to new
     * positions based on the temporary coordinate based movement on the bonds
     * they are associated with.
     *
     * @param structureId {Number} - id of the structure the bonds belong to
     * @param ring {Ring} - Ring object containing the edges to update
     * @param movedAromEdges {StructureIdTracker} - container to track which
     * aromatic bonds have already been updated
     * @param edgeChangeCases {Object} - how the representation of associated
     * bonds were updated (e.g., moved, hidden, ...), s.t. this update type can
     * be mimicked for the aromatic bonds
     */
    moveAromaticEdgesOfRingToTempCoordinates(structureId, ring, movedAromEdges, edgeChangeCases) {
        const ringId = ring.id;
        ring.edges.forEach(ringEdge => {
            const ringEdgeId = ringEdge.id;
            if (movedAromEdges.hasID(ringId, ringEdgeId)) return;
            //update according to update applied to corresponding edge
            if (edgeChangeCases.hasOwnProperty(ringEdgeId)) {
                this.createAromaticEdgeUpdateFunction(ring,
                    ringEdge,
                    structureId,
                    edgeChangeCases[ringEdgeId]
                )();
                //something happened to neighbor edge -> also move
            } else {
                const nextEid = ring.getNextEdge(ringEdgeId).id;
                const prevEid = ring.getPreviousEdge(ringEdgeId).id;
                if (edgeChangeCases.hasOwnProperty(nextEid) ||
                    edgeChangeCases.hasOwnProperty(prevEid)) {
                    this.createAromaticEdgeUpdateFunction(ring,
                        ringEdge,
                        structureId,
                        EdgeChangeCase.move
                    )();
                }
            }
            movedAromEdges.addID(ringId, ringEdgeId);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Change the color of aromatic bonds of a ring.
     *
     * @param structure {Structure} - structure the bond
     * belongs to
     * @param structureId {Number} - the unique id of the structure the bond
     * belongs to
     * @param ringId {Number} - the unique id of the ring
     * @param colorChanges {Array} - collects change objects for the history step
     */
    createColorChangesRingEdges(structure, structureId, ringId, colorChanges) {
        const ring = structure.ringsData.getRing(ringId);
        ring.edges.forEach(({id: edgeId}) => {
            const ringColorChange = new Change();
            const changeColor = () => {
                this.edgeGroupsComponent.recolorAromaticRingEdge(structureId, edgeId, ringId);
            };
            ringColorChange.bindApplyRevert(changeColor);
            ringColorChange.apply();
            colorChanges.push(ringColorChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves the aromatic bonds (i.e., the dashed bonds inside) of a all rings
     * including given atoms (by ids) based on the temporary coordinate based
     * movement on the bonds they are associated with.
     *
     * @param updatedAtoms {Array} - ids of atoms affected by interaction
     * @param edgeChangeCases {Object} - how the representation of associated
     * bonds were updated (e.g., moved, hidden, ...), s.t. this update type can
     * be mimicked for the aromatic bonds
     */
    moveAromaticEdgesToTempCoordinates(updatedAtoms, edgeChangeCases) {
        //edges can be in multiple rings, make sure to only move once
        const movedAromEdges = new StructureIdTracker();
        for (const structureId in updatedAtoms) {
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.ringsData.getRingsAffectedByAtoms(updatedAtoms[structureId], true)
                .forEach(ringId => {
                    const ring = structure.ringsData.getRing(ringId);
                    ring.update(true);
                    this.moveAromaticEdgesOfRingToTempCoordinates(structureId,
                        ring,
                        movedAromEdges,
                        edgeChangeCases[structureId]
                    );
                });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (as groups) of ring system edges by specified
     * offsets.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to move skeleton of
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     */
    moveRingEdgeSkeleton(structureId, ringSysId, xOffset, yOffset) {
        this.edgeGroupsComponent.moveRingEdgeSkeleton(structureId, ringSysId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for edges of a certain ring system.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to reset translations
     * for
     */
    resetRingEdgeSkeletonTranslation(structureId, ringSysId) {
        this.edgeGroupsComponent.resetRingEdgeSkeletonTranslation(structureId, ringSysId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a (new) structure, adds new container groups to the svg for edges.
     * Creates a new wrapper in the edge group. Further
     * prepares the mapping of selectors for later access. In the selector
     * map, the created groups are mapped also, so they may be hidden later.
     *
     * @param structure {Structure} - Structure object
     * @param structureId {structureId} - id of Structure object
     * @param debug {Boolean} - true if debug information shall be visualized
     */
    addEdgesToTrack(structure, structureId, debug) {
        this.edgeGroupsComponent.addEdgesToTrack(structure, structureId, debug);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural edge skeleton (as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveEdgeSkeleton(structureId, xOffset, yOffset) {
        this.edgeGroupsComponent.moveEdgeSkeleton(structureId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for edges of a certain structure.
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetEdgeSkeletonTranslation(structureId) {
        this.edgeGroupsComponent.resetEdgeSkeletonTranslation(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes edges of a structure from the DOM.
     *
     * @param structureId {Number} - the unique id of the structure to remove its
     * edges from DOM
     */
    removeStructureEdgesFromDOM(structureId) {
        this.edgeGroupsComponent.removeStructureEdgesFromDOM(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached edge information for a given structure (by its id).
     *
     * @param structureId {Number} - id of structure to remove information
     * about.
     */
    purgeStructureEdgesFromCache(structureId) {
        this.edgeGroupsComponent.purgeStructureEdgesFromCache(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached edge DOM elements back
     * into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructureEdges(structureId) {
        this.edgeGroupsComponent.redrawStructureEdges(structureId);
    }
}

/* src/Drawers/Structure/RingDrawer.js */
/**
 * Drawer that uses other drawers for the visualization of structure rings.
 */
class RingDrawer {
    /**
     * Contains instances configuration options and data storage/access, draw area manipulation.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param atomDrawer {Object} - drawer for atoms
     * @param edgeDrawer {Object} - drawer for edges
     */
    constructor(opts, sceneData, atomDrawer, edgeDrawer) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.atomDrawer = atomDrawer;
        this.edgeDrawer = edgeDrawer;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Undoes translations applied to SVG groups representing ring systems which
     * were moved in full. Instead, moves the involved atoms to their new positions.
     */
    resetRingSystemMovement(ringSystems) {
        const atomsToUpdate = {};
        for (const structureId in ringSystems) {
            atomsToUpdate[structureId] = [];
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.resetCurOffset();
            ringSystems[structureId].forEach(ringSysId => {
                this.resetRingSkeletonTranslation(structureId, ringSysId);
                structure.ringsData.ringSystems[ringSysId].atoms.forEach(atomId => {
                    atomsToUpdate[structureId].push(atomId);
                });
            });
        }
        this.atomDrawer.moveAtomsToTempCoordinates(atomsToUpdate);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates temporary coordinates of all atoms contained in a ring system
     * specified by id. Note the updated atoms in a provided container.
     *
     * @param offset {Object} - x- and y-offsets to apply to temp coordinates
     * @param structureId {Number} - id of the structure containing the ring
     * system
     * @param ringSysId {Number} - id of the ring system to update atoms of
     * @param changedAtomIds {StructureIdTracker} - container to note which
     * atoms are updated
     */
    updateTempCoordsForRingSystem(offset, structureId, ringSysId, changedAtomIds) {
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.ringsData.ringSystems[ringSysId].atoms.forEach(atomId => {
            AtomDrawer.updateTempCoordsForAtom(structure, atomId, offset, changedAtomIds);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on temporary coordinates of atoms affected by interaction, updates
     * all ring systems they are part of.
     *
     * @param ringSystems {Array} - ids of ring systems affected by
     * interaction (per structure)
     */
    updateTempCoordsForAffectedRingSystems(ringSystems) {
        for (const structureId in ringSystems) {
            const structure = this.sceneData.structuresData.structures[structureId];
            ringSystems[structureId].forEach(ringSysId => {
                structure.ringsData.updateRingSystem(ringSysId, true);
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * A variation of molecular movement: Moves entire ring systems based on
     * given offsets. To optimize performance, such ring systems are moved
     * through movement of composite layers of SVG groups. Movement offsets are
     * then noted directly on Structure objects the ring systems are part of.
     *
     * @param ringSystems{Object} - ids of ring systems to move
     * @param offset {Object} - x- and y-offsets to move draw elements by
     */
    moveRingSystems(ringSystems, offset) {
        for (const structureId in ringSystems) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const curOffset = structure.curOffset;
            curOffset.x += offset.x;
            curOffset.y += offset.y;
            ringSystems[structureId].forEach(ringSysId => {
                this.moveRingSkeleton(structureId, ringSysId, curOffset.x, curOffset.y);
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * In a given container, notes that a ring system has to be updated.
     *
     * @param structureId {Number} - id of the structure containing the ring
     * system
     * @param ringSysId {Number} - id of the ring system to be updated
     * @param tracker {StructureIdTracker} - container to note the ring system
     * to update in
     */
    static markRingSystemForTempUpdate(structureId, ringSysId, tracker) {
        if (tracker.hasID(structureId, ringSysId)) return;
        tracker.addID(structureId, ringSysId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (as groups) of a ring system by specified
     * offsets.
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to move skeleton of
     * @param xOffset {Number} - offset to move ring system by in x-direction
     * @param yOffset {Number} - offset to move ring system by in y-direction
     */
    moveRingSkeleton(structureId, ringSysId, xOffset, yOffset) {
        this.atomDrawer.moveRingAtomSkeleton(structureId, ringSysId, xOffset, yOffset);
        this.edgeDrawer.moveRingEdgeSkeleton(structureId, ringSysId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for a certain ring system
     *
     * @param structureId {Number} - id of structure containing the ring
     * system
     * @param ringSysId {Number} - id of ring systems to reset translations
     * for
     */
    resetRingSkeletonTranslation(structureId, ringSysId) {
        this.atomDrawer.resetRingAtomSkeletonTranslation(structureId, ringSysId);
        this.edgeDrawer.resetRingEdgeSkeletonTranslation(structureId, ringSysId);
    }
}

/* src/Drawers/Structure/StructureCircleDrawer.js */
/**
 * Drawer that uses other drawers and its own component for the visualization
 * of structure circles of the structure circle representation type.
 */
class StructureCircleDrawer {
    /**
     * Contains instances for json validation, configuration options,
     * data storage/access, draw area manipulation and all relevant components.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param structureCircleGroupsComponent {Object} - component for structure circles
     * @param textLabelDrawer {Object} - drawer for text labels.
     * @param annotationDrawer {Object} - drawer for annotations
     */
    constructor(opts,
        sceneData,
        structureCircleGroupsComponent,
        textLabelDrawer,
        annotationDrawer
    ) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.structureCircleGroupsComponent = structureCircleGroupsComponent;
        this.textLabelDrawer = textLabelDrawer;
        this.annotationDrawer = annotationDrawer;

        this.selectionCallback = null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the circle as an alternative representation of a structure into the
     * draw area.
     *
     * @param structure {Structure} - Structure object
     */
    applyAddStructureCircle(structure) {
        this.structureCircleGroupsComponent.drawStructureCircle(structure);

        const structureMid = structure.boundaries.mid;
        const {
            rad, circleCss, textColor
        } = this.opts.structureCircleOpts[structure.structureType] ||
        this.opts.structureCircleOpts['default'];
        const structureCircle = {
            id: structure.id,
            isStructureCircle: true,
            coordinates: Object.assign({}, structureMid),
            tempCoordinates: Object.assign({}, structureMid),
            rad: rad,
            label: structure.structureLabel,
            circleStyles: circleCss,
            labelColor: textColor,
            selectorShapes: undefined,
            drawLimits: undefined,
            wn: 0 //winding number for free selector
        };
        structure.representationsData.structureCircle = structureCircle;

        this.setStructureCircleDrawLimits(structureCircle);
        this.setStructureCircleSelectionShapes(structureCircle);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds representation of draw limits after creating draw element for the
     * structure circle (for placement concerns).
     *
     * @param structureCircle {Object} - the structure circle
     * @param drawLimits {Object} - object containing draw limits as minima
     * and maxima of the circles bounding box (as xmin, xmax, ymin, ymax). Will be
     * calculated from corresponding drawn circle svg element when omitted
     */
    setStructureCircleDrawLimits(structureCircle, drawLimits = undefined) {
        structureCircle.drawLimits = {
            ...this.structureCircleGroupsComponent.getStructureCircleDrawLimits(structureCircle.id), ...drawLimits
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds representation of the surrounding selector shape of the structure
     * circle after creating its draw element.
     *
     * @param structureCircle {Object} - the structure circle
     * @param selectorShapes {Array} - different selector shapes, objects
     * holding both 'type' and 'coordinates' field. If undefined or omitted
     * this will be extracted from the svg draw elements
     * @param byTemp {Boolean} - whether movement is temporary (not logged to
     * history) or not
     */
    setStructureCircleSelectionShapes(structureCircle, selectorShapes = undefined, byTemp = false) {
        if (!selectorShapes) {
            selectorShapes =
                this.structureCircleGroupsComponent.getStructureCircleSelShapes(structureCircle.id)
        }
        structureCircle.tempSelectorShapes = selectorShapes;
        if (!byTemp) {
            structureCircle.selectorShapes = JSON.parse(JSON.stringify(selectorShapes));
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the coordinates of a single structure circle to new values.
     * Note that this can only be done after updating the boundaries of
     * the structure.
     *
     * @param structure {Object} - structure whose circle to move
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {Array} - Change objects for the next history step
     */
    applyCoordinateChangesStructureCircle(structure, globalMaxes) {
        const structureCircle = structure.representationsData.structureCircle;
        const oldCoords = structureCircle.coordinates;
        const newCoords = structure.boundaries.mid;
        if (PointCalculation.coordsAlmostEqual(oldCoords, newCoords)) return [];

        //update coordinates
        const changes = [];
        const moveFn = (id, offsets) => {
            this.structureCircleGroupsComponent.moveStructureCircle(id, offsets);
        };
        changes.push(this.textLabelDrawer.updateTextLabelCoordinates(structureCircle,
            newCoords,
            moveFn
        ));

        //update draw limits and selector shapes
        const oldDrawLimits = Object.assign({}, structureCircle.drawLimits);
        this.setStructureCircleDrawLimits(structureCircle);
        this.setStructureCircleSelectionShapes(structureCircle);
        const newDrawLimits = structureCircle.drawLimits;

        globalMaxes.updateMaxesByLimits(oldDrawLimits, newDrawLimits);

        const limitChange = new Change();
        const changeLimits = () => {
            this.setStructureCircleDrawLimits(structureCircle);
            this.setStructureCircleSelectionShapes(structureCircle);
        };
        limitChange.bindApplyRevert(changeLimits);
        changes.push(limitChange);

        return changes;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates the structure circle of a structure around a given midpoint.
     * Also rotates all annotations of this structure.
     *
     * @param structureId {Number} - unique Id of structure to rotate
     * @param angle {Number} - angle (in degrees!) to rotate by
     * @param midpoint {Object} - x- and y-coordinates of the point to rotate
     * the structure around
     * @param fullRotate {Boolean} - whether the rotation is around the scenes
     * mid or the structures mid
     */
    rotateStructureCircle(structureId, angle, midpoint, fullRotate) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const offset = structure.calcStructureCircleRotationOffset(angle, true, midpoint);

        if (fullRotate) {
            //the label has to be oriented correctly, need new temp coordinates
            this.updateCoordsForStructureCircleByOffset(structureId, offset, true);
            this.structureCircleGroupsComponent.moveStructureCircle(structureId, offset);

            if (structure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
                //update annotations, move them by the same offset so they stay at the
                //same relative position to the circle during movement
                structure.annotationConnectionData.annotations.forEach(annotationId => {
                    this.annotationDrawer.moveAnnotation(annotationId, offset);
                })
            }
        } else if (structure.representationsData.isCurRepresentation(StructureRepresentation.circle)) {
            //no need to update the circle. Just update annotations.
            structure.annotationConnectionData.annotations.forEach(annotationId => {
                this.annotationDrawer.rotateAnnotation(annotationId, angle, midpoint);
            })
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates temporary coordinates of a structure circle based on an individual
     * offset given.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     * @param offset {Object} - x and y offset values
     * @param byTemp {Boolean} - whether to change temp coordinates or not
     */
    updateCoordsForStructureCircleByOffset(structureId, offset, byTemp) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const circle = structure.representationsData.structureCircle;
        const coords = byTemp ? circle.tempCoordinates : circle.coordinates;
        coords.x = coords.x + offset.x;
        coords.y = coords.y + offset.y;
        if (!byTemp) {
            this.tempCoordinates = Object.assign({}, coords);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the "tempCoordinates" of a structure circle to their "coordinates"
     * values.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    resetStructureCircleTempCoords(structureId) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const circle = structure.representationsData.structureCircle;
        const tempCoords = circle.tempCoordinates;
        const coords = circle.coordinates;
        tempCoords.x = coords.x;
        tempCoords.y = coords.y;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a structure circle in the draw area and mark it as temporarily (!)
     * selected in the corresponding container.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    tempSelectStructureCircle(structureId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.representationsData.tempSelectStructureCircle();
        this.structureCircleGroupsComponent.selectStructureCircle(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a structure circle in the draw area and mark it as selected in the
     * corresponding container.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    selectStructureCircleDrawareaContainer(structureId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.representationsData.selectStructureCircle();
        this.structureCircleGroupsComponent.selectStructureCircle(structureId);
        if (this.selectionCallback) {
            this.selectionCallback({
                type: 'structureCircle', selectionType: 'select', structureId: parseInt(structureId)
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects a structure circle in the draw area.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    selectStructureCircleDrawarea(structureId) {
        this.structureCircleGroupsComponent.selectStructureCircle(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects a structure circle in the draw area and remove its selection status
     * in the corresponding container.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     * @param hover {Boolean} - whether the structure circle is to be shown as
     * hovered
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectStructureCircleDrawareaContainer(
        structureId,
        hover = false,
        executeCallback = true)
    {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId) ||
            !this.sceneData.structuresData.structures[structureId]
                .representationsData.hasRepresentation(StructureRepresentation.circle)) {
            return;
        }
        this.sceneData.structuresData.structures[structureId].representationsData.selectedStructureCircle =
            false;
        if (hover) {
            this.structureCircleGroupsComponent.hoverStructureCircle(structureId);
        } else {
            this.structureCircleGroupsComponent.unselectStructureCircle(structureId);
        }
        if (executeCallback && this.selectionCallback) {
            this.selectionCallback({
                type: 'structureCircle',
                selectionType: 'unselect',
                structureId: parseInt(structureId)
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects a structure circle in the draw area.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    unselectStructureCircleDrawarea(structureId) {
        this.structureCircleGroupsComponent.unselectStructureCircle(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hovers a structure circle in the draw area.
     *
     * @param structureId {Number} - id of the structure the structure circle
     * belongs to
     */
    hoverStructureCircle(structureId) {
        this.structureCircleGroupsComponent.hoverStructureCircle(structureId)
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural circle skeleton (as groups) by specified offsets.
     *
     * @param structureId {Number} - iId of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveStructureCircleSkeleton(structureId, xOffset, yOffset) {
        this.structureCircleGroupsComponent.moveStructureCircleSkeleton(structureId,
            xOffset,
            yOffset
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for structure circles of a certain structure
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetStructureCircleSkeletonTranslation(structureId) {
        this.structureCircleGroupsComponent.resetStructureCircleSkeletonTranslation(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes structure circle only from the DOM
     *
     * @param structureId {Number} - the unique Id of the structure to remove
     * its structure circles from DOM
     */
    removeStructureCirclesFromDOM(structureId) {
        this.structureCircleGroupsComponent.removeFromDOM(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached structure circle information for a given structure (by its Id).
     *
     * @param structureId {Number} - id of structure to remove structure circle information
     * from
     */
    purgeStructureCirclesFromCache(structureId) {
        this.structureCircleGroupsComponent.purgeFromCache(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached structure circles
     * DOM elements back into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructureCircles(structureId) {
        this.structureCircleGroupsComponent.redraw(structureId);
    }
}

/* src/Drawers/Structure/StructureDrawer.js */
/**
 * Drawer that uses other drawers for the visualization of structures.
 */
class StructureDrawer {
    /**
     * Contains instances for JSON validation, configuration options,
     * data storage/access and draw area manipulation.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param svgComponent {Object} - represents the draw area
     * @param viewerDrawer {Object} - drawer for the viewer and viewer control related objects
     * @param atomDrawer {Object} - drawer for atoms
     * @param edgeDrawer {Object} - drawer for edges
     * @param ringDrawer {Object} - drawer for rings
     * @param structureCircleDrawer {Object} - drawer for structure circle representation
     * @param jsonValidator {Object} - validates input JSON
     */
    constructor(opts,
        sceneData,
        svgComponent,
        viewerDrawer,
        atomDrawer,
        edgeDrawer,
        ringDrawer,
        structureCircleDrawer,
        jsonValidator
    ) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.svgComponent = svgComponent;
        this.transformGroupsComponent = svgComponent.transformGroupsComponent;
        this.viewerDrawer = viewerDrawer;
        this.atomDrawer = atomDrawer;
        this.edgeDrawer = edgeDrawer;
        this.ringDrawer = ringDrawer;
        this.structureCircleDrawer = structureCircleDrawer;
        this.jsonValidator = jsonValidator;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the individual components of different structures based on the
     * "structures" field of provided scene draw information. Returns the
     * necessary Change objects to remove and re-add these components.
     *
     * @param structureInfos {Array} - draw information for the different
     * structures to be added to the scene
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addedStructureIds {Array} - log of which structures are newly
     * added to the scene
     * @returns {undefined|Array} - Change objects for the next history step
     */
    applyAddStructures(structureInfos, globalMaxes, addedStructureIds) {
        if (this.jsonValidator.checkJSONStructureArray(structureInfos, 'structures', true).error) {
            return;
        }
        const addChanges = [];
        structureInfos.forEach((structureInfo, i) => {
            //sanity check on structure structure (NOT nested for atoms etc.)
            if (this.jsonValidator.structureJSONerror(structureInfo, i)) {
                return;
            }
            //application of the different fields
            Array.prototype.push.apply(addChanges,
                this.applyAddStructure(structureInfo, i, globalMaxes, addedStructureIds)
            );
        });
        return addChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds the individual components for a single structure based on given draw
     * information. Returns the necessary Change objects to remove and re-add
     * these components.
     *
     * @param structureInfo {Object} - draw information for the different
     * parts of the structure to be added to the scene
     * @param i {Number} - array position in structureInfos
     * @param curLimits {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addedStructureIds {Array} - log of which structures are newly
     * added to the scene
     * @returns {undefined|Array} - Change objects for the next history step
     */
    applyAddStructure(structureInfo, i, curLimits, addedStructureIds) {
        if (this.jsonValidator.structureNestedJSONerror(structureInfo, i)) {
            return;
        }
        //JSON okay, internally create structure and draw it to SVG
        const addChanges = [];
        const structure = this.createStructureData(structureInfo, addedStructureIds);
        //set to good scale so atom representations are drawn well
        const scaleSuggestion = this.viewerDrawer.suggestDrawScaling();
        const currentScale = this.viewerDrawer.interactionState.transformParams.scale;
        if (scaleSuggestion.rescale) {
            this.viewerDrawer.scale(scaleSuggestion.scale);
        }
        this.createNewStructure(structure, structureInfo, curLimits, addChanges);
        //if scene was scaled for drawing, scale back
        if (scaleSuggestion.rescale) {
            this.viewerDrawer.scale(currentScale);
        }
        return addChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates a new structure instance.
     *
     * @param structureInfo {Object} - draw information for the different
     * parts of the structure to be added to the scene
     * @param addedStructureIds {Array} - log of which structures are newly
     * added to the scene
     * @returns {Structure} - new structure instance
     */
    createStructureData(structureInfo, addedStructureIds) {
        //create the structure and add to memory
        const structureId = structureInfo.id;
        const structure = new Structure(structureId,
            structureInfo.structureName,
            structureInfo.structureType,
            structureInfo.structureLabel,
            this.opts.spaceToRing + this.opts.lineWidth,
            structureInfo.additionalInformation
        );
        structure.addStructureInfo(structureInfo.atoms, structureInfo.bonds, {
            ringInfos: structureInfo.rings,
            stereoCenterInfos: structureInfo.stereoCenters,
            ringSystemInfos: structureInfo.ringsystems
        });
        structure.atomsData.atoms.forEach(atom => { //give color to atoms
            if (!atom.color) {
                const upcaseElem = atom.element.toUpperCase();
                atom.color = (upcaseElem in this.opts.colors) ? this.opts.colors[upcaseElem] :
                    this.opts.colors.DEFAULT;
            }
            this.sceneData.structuresData.atomIdsToStructure[atom.id] = structureId;
        });
        structure.representationsData.addAlternativeRepresentations(this.opts.allowedStructureRepresentations);
        this.sceneData.structuresData.structures[structureId] = structure;
        this.sceneData.structuresData.structuresInUse.add(structureId);
        addedStructureIds.push(structureId);
        this.addStructureToTrack(structure);
        return structure;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws a new structure.
     *
     * @param structure {Object} - structure instance
     * @param structureInfo {Object} - draw information for the different
     * parts of the structure to be added to the scene
     * @param curLimits {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @param addChanges {Object} - collects this drawing step as Change object for the history
     */
    createNewStructure(structure, structureInfo, curLimits, addChanges) {
        //draw structure elements step by step
        this.atomDrawer.drawStructureAtoms(structure, structureInfo.selectedAtoms);
        structure.calcBoundaries(); //boundaries need atom draw info
        if (structure.representationsData.hasRepresentation(StructureRepresentation.circle)) {
            this.structureCircleDrawer.applyAddStructureCircle(structure, curLimits);
            structure.addStructureCircleToBoundaries();
        }
        if (structureInfo.afterAdd) { //user-defined post-processing
            structureInfo.afterAdd(structure);
        }
        structure.edgesData.finishEdgeLabeling(); //everything of structure is known, finish build
        this.edgeDrawer.drawStructureEdges(structure, structureInfo.selectedEdges);
        this.edgeDrawer.drawAromaticEdgesForRings(structure);
        //change to remove/readd entire structure, not atom by atom
        addChanges.push(this.createAddRemoveStructureChange(structureInfo.id));

        //change global boundaries as necessary
        const structLimits = structure.boundaries;
        curLimits.setMaxesAdd(structLimits.xMin,
            structLimits.xMax,
            structLimits.yMin,
            structLimits.yMax
        );

        //change if no structure had been loaded before
        if (!this.sceneData.structuresData.structureLoaded) {
            const on = () => {
                this.sceneData.structuresData.structureLoaded = true;
            };
            const off = () => {
                this.sceneData.structuresData.structureLoaded = false;
            };
            const loadChange = new Change();
            loadChange.bindApply(on);
            loadChange.bindRevert(off);
            loadChange.apply();
            addChanges.push(loadChange);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the Change object to remove/re-add a structure.
     *
     * @param structureId {Number} - id of the structure to remove/re-add
     * @param isAdd {Boolean} - whether the re-add function should bind to
     * apply (true) or revert
     * @returns {Change} - Change object to apply/revert removal
     */
    createAddRemoveStructureChange(structureId, isAdd = true) {
        const remStructure = () => {
            this.sceneData.structuresData.structures[structureId].enabled = false;
            this.unselectStructure(structureId);
            this.removeStructureFromDOM(structureId);
        };
        const addStructure = () => {
            this.sceneData.structuresData.structures[structureId].enabled = true;
            this.redrawStructure(structureId);
        };
        const structChange = new Change();
        if (isAdd) {
            structChange.bindApply(addStructure);
            structChange.bindRevert(remStructure);
        } else {
            structChange.bindApply(remStructure);
            structChange.bindRevert(addStructure);
        }
        return structChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a specified structure, recolors atoms and gradients of adjacent bonds
     * by supplying new colors. Returns the necessary Change objects to
     * apply/revert this recoloring.
     *
     * @param structureId {Number} - id of structure for which to recolor
     * atoms and bonds
     * @param newAtomColors {Object} - map from atom ids to new CSS colors
     * @returns {Array} - Change objects for the next history step
     */
    applyColorChanges(structureId, newAtomColors) {
        const structure = this.sceneData.structuresData.structures[structureId];

        const recEdges = {}; //keep track of necessary recoloring for edges
        const recAtoms = new Set(); //atoms that actually changed colors
        const colorChanges = []; //bundle up changes

        for (const atomId in newAtomColors) {
            const atom = structure.atomsData.getAtom(atomId);
            if (!atom || !atom.enabled) {
                continue;
            }
            //create color change based on old and new color
            const oldColor = atom.color;
            const newColor = newAtomColors[atomId];
            if (oldColor === newColor) {
                continue;
            }
            colorChanges.push(this.atomDrawer.createColorChangeAtom(structureId,
                atom,
                oldColor,
                newColor
            ));
            //check which edges have to be color changed
            structure.atomsData.neighbors[atomId].forEach(({edgeId}) => {
                const edge = structure.edgesData.getEdge(edgeId);
                if (!edge.enabled) {
                    return;
                }
                if (!recEdges.hasOwnProperty(edgeId)) {
                    recEdges[edgeId] = {
                        from: undefined, to: undefined
                    };
                }
                if (edge.from === parseInt(atomId)) {
                    recEdges[edgeId].from = newColor;
                } else {
                    recEdges[edgeId].to = newColor;
                }
            });
            recAtoms.add(parseInt(atomId));
        }

        for (const edgeId in recEdges) {
            const edge = structure.edgesData.getEdge(edgeId);
            //find out how to color the edge based on recEdges map
            const newColors = recEdges[edgeId];
            let oldFromColor, newFromColor, oldToColor, newToColor;
            if (newColors.from) {
                oldFromColor = structure.atomsData.getAtom(edge.from).color;
                newFromColor = newColors.from;
            }
            if (newColors.to) {
                oldToColor = structure.atomsData.getAtom(edge.to).color;
                newToColor = newColors.to;
            }
            colorChanges.push(this.edgeDrawer.createColorChangeEdge(structureId,
                edgeId,
                oldFromColor,
                oldToColor,
                newFromColor,
                newToColor
            ));
        }

        //go through with changes until here
        colorChanges.forEach(change => {
            change.apply();
        });

        structure.ringsData.getRingsAffectedByAtoms(recAtoms, true).forEach(ringId => {
            this.edgeDrawer.createColorChangesRingEdges(structure,
                structureId,
                ringId,
                colorChanges
            );
        });

        return colorChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified structures in the draw area.
     *
     * @param remStructures {Set} - ids of structures to remove
     * @param remChanges {Array} - Change objects for the history step
     * @param markRequiredRecalcs {Function} - function to memory changes in
     * structure/scene boundaries
     */
    removeStructures(remStructures, remChanges, markRequiredRecalcs) {
        remStructures.forEach(structureId => {
            if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
                return;
            }

            const structure = this.sceneData.structuresData.structures[structureId];
            //filter already removed
            if (!structure.enabled) {
                return;
            }
            const {xMin, xMax, yMin, yMax} = structure.boundaries;
            markRequiredRecalcs('xMin', xMin, structureId);
            markRequiredRecalcs('xMax', xMax, structureId);
            markRequiredRecalcs('yMin', yMin, structureId);
            markRequiredRecalcs('yMax', yMax, structureId);
            const remChange = this.createAddRemoveStructureChange(structureId, false);
            remChange.apply();
            remChanges.push(remChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects all currently selected elements of a structure.
     *
     * @param structureId {Number} - id of structure to unselect
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    unselectStructure(structureId, executeCallback = true) {
        const structure = this.sceneData.structuresData.structures[structureId];
        //reset atom selections
        structure.atomsData.selectedAtoms.forEach(atomId => {
            this.atomDrawer.unselectAtomDrawareaContainer(
                structureId,
                atomId,
                false,
                executeCallback
            );
            structure.atomsData.getAtom(atomId).wn = 0;
        });
        structure.atomsData.selectedAtoms.clear();
        //reset edge selections
        structure.edgesData.selectedEdges.forEach(edgeId => {
            this.edgeDrawer.unselectEdgeDrawareaContainer(
                structureId,
                edgeId,
                false,
                executeCallback
            );
            structure.edgesData.getEdge(edgeId).wn = 0;
        });
        structure.edgesData.selectedEdges.clear();
        //reset structure circle selection
        if (structure.representationsData.hasRepresentation(StructureRepresentation.circle) &&
            structure.representationsData.selectedStructureCircle) {
            this.structureCircleDrawer.unselectStructureCircleDrawareaContainer(
                structureId,
                executeCallback
            );
            structure.representationsData.selectedStructureCircle = false;
            structure.representationsData.structureCircle.wn = 0;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects all currently selected elements.
     *
     * @param executeCallback {Boolean} - whether to execute the selection callback
     */
    resetSelections(executeCallback = true) {
        for (const structureId in this.sceneData.structuresData.structures) {
            this.unselectStructure(structureId, executeCallback);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Fully selects any temporarily selected atoms and bonds, committing them
     * to structure and firing callbacks only now.
     */
    applyTempSelection() {
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.atomsData.tempSelectedAtoms.forEach(atomId => {
                this.atomDrawer.selectAtomDrawareaContainer(structureId, atomId);
            });
            structure.edgesData.tempSelectedEdges.forEach(edgeId => {
                this.edgeDrawer.selectEdgeDrawareaContainer(structureId, edgeId);
            });
            if (structure.representationsData.hasRepresentation(StructureRepresentation.circle) &&
                structure.representationsData.tempSelectedStructureCircle) {
                this.structureCircleDrawer.selectStructureCircleDrawareaContainer(structureId);
            }
        }
        this.clearTempSelections();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Empties the data structures associated with temporary selections.
     */
    clearTempSelections() {
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            structure.atomsData.tempSelectedAtoms.clear();
            structure.edgesData.tempSelectedEdges.clear();
            if (structure.representationsData.hasRepresentation(StructureRepresentation.circle)) {
                structure.representationsData.tempSelectedStructureCircle = false;
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Unselects selections marked as temp selected in the draw area and clears
     * associated data structures.
     */
    resetTempSelections() {
        for (const structureId in this.sceneData.structuresData.structures) {
            const structure = this.sceneData.structuresData.structures[structureId];
            //reset temp atom selections
            structure.atomsData.tempSelectedAtoms.forEach(atomId => {
                this.atomDrawer.unselectAtomDrawarea(structureId, atomId);
            });
            //reset temp edge selections
            structure.edgesData.tempSelectedEdges.forEach(edgeId => {
                this.edgeDrawer.unselectEdgeDrawarea(structureId, edgeId);
            });
            if (structure.representationsData.hasRepresentation(StructureRepresentation.circle) &&
                structure.representationsData.tempSelectedStructureCircle) {
                this.structureCircleDrawer.unselectStructureCircleDrawareaContainer(structureId);
            }
        }
        this.clearTempSelections();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Selects all atoms, bonds and structure circles in the draw area which are
     * part of a structure specified by id.
     *
     * @param structureId {Number} - unique id of the structure to select
     */
    selectStructure(structureId) {
        if (!this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            return;
        }
        const structure = this.sceneData.structuresData.structures[structureId];
        structure.atomsData.atoms.forEach(({id: atomId}) => {
            this.atomDrawer.selectAtomDrawareaContainer(structureId, atomId);
        });
        structure.edgesData.edges.forEach(({id: edgeId}) => {
            this.edgeDrawer.selectEdgeDrawareaContainer(structureId, edgeId);
        });
        if (structure.representationsData.hasRepresentation(StructureRepresentation.circle)) {
            this.structureCircleDrawer.selectStructureCircleDrawareaContainer(structureId);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a (new) structure, adds new container groups to the svg.
     * Creates a new wrapper in both the atom and the edge group. Further
     * prepares the mapping of selectors for later access. In the selector
     * map, the created groups are mapped also, so they may be hidden later.
     *
     * @param structure {Structure} - Structure object
     */
    addStructureToTrack(structure) {
        const structureId = structure.id;
        const debug = this.opts.debug.atoms;
        this.atomDrawer.addAtomsToTrack(structure, structureId, debug);
        this.edgeDrawer.addEdgesToTrack(structure, structureId, debug);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves structural skeleton (as groups) by specified offsets.
     *
     * @param structureId {Number} - id of structure to move skeleton of
     * @param xOffset {Number} - offset to move structure by in x-direction
     * @param yOffset {Number} - offset to move structure by in y-direction
     */
    moveFullSkeleton(structureId, xOffset, yOffset) {
        this.atomDrawer.moveAtomSkeleton(structureId, xOffset, yOffset);
        this.edgeDrawer.moveEdgeSkeleton(structureId, xOffset, yOffset);
        this.structureCircleDrawer.moveStructureCircleSkeleton(structureId, xOffset, yOffset);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets translations made for a certain structure.
     *
     * @param structureId {Number} - id of structure to reset translations for
     */
    resetFullSkeletonTranslation(structureId) {
        this.atomDrawer.resetAtomSkeletonTranslation(structureId);
        this.edgeDrawer.resetEdgeSkeletonTranslation(structureId);
        this.structureCircleDrawer.resetStructureCircleSkeletonTranslation(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes structure from the DOM and the cache.
     *
     * @param structureId {Number} - id of structure to remove
     */
    removeStructureDOMCache(structureId) {
        this.removeStructureFromDOM(structureId);
        this.purgeStructureFromCache(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Detaches the group elements of a structure from the DOM by calling
     * remove() for atoms, edges and gradients. These exist now in memory as
     * detached trees - this is generally a bad thing, but this way the
     * entire structure can quickly be reattached. As long as the structure may
     * have to be reloaded anyway by the history, it stays in memory. If it
     * becomes irrelevant, it is then purged from memory by calling
     * this.purgeStructureFromCache() - make sure this always does happen.
     *
     * @param structureId {Number} - the unique id of the structure to remove
     * from the DOM
     */
    removeStructureFromDOM(structureId) {
        this.atomDrawer.removeStructureAtomsFromDOM(structureId);
        this.edgeDrawer.removeStructureEdgesFromDOM(structureId);
        this.structureCircleDrawer.removeStructureCirclesFromDOM(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all cached information for a given structure (by its id).
     *
     * @param structureId {Number} - id of structure to remove information
     * about.
     */
    purgeStructureFromCache(structureId) {
        this.atomDrawer.purgeStructureAtomsFromCache(structureId);
        this.edgeDrawer.purgeStructureEdgesFromCache(structureId);
        this.structureCircleDrawer.purgeStructureCirclesFromCache(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * For a previously removed structure, puts its detached DOM elements back
     * into previous positions.
     *
     * @param structureId {Number} - id of structure to add back
     */
    redrawStructure(structureId) {
        this.atomDrawer.redrawStructureAtoms(structureId);
        this.edgeDrawer.redrawStructureEdges(structureId);
        this.structureCircleDrawer.redrawStructureCircles(structureId);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shows parts of a structure or the full structure. Also hides the
     * selectors.
     *
     * @param structureId {Number} - id of structure to show
     * @param structureParts {Object} - which parts of the structure to show/hide. Parts can
     * contain "full, atoms, bonds, structureCircle, hydrophobic, atomPairInteractions,
     * piStackings, cationPiStackings, label" as keys and true (show) or false
     * (do not change visibility) as values
     * @param hiddenStructures {Array} - ids of structures which are currently
     * completely hidden in the draw area
     * @param show {Boolean} - set true if structure parts shall be shown otherwise false
     */
    showHideStructureParts(structureId, structureParts, hiddenStructures, show) {
        this.transformGroupsComponent.showHideStructureParts(structureId,
            structureParts,
            hiddenStructures,
            show
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates visibility of objects in the draw area.
     */
    updateVisibility() {
        this.transformGroupsComponent.updateVisibility();
    }
}

/* src/Drawers/Structure/StructureRepresentationDrawer.js */
/**
 * Drawer that uses other drawers for the visualization of the various types
 * of structure representation.
 */
class StructureRepresentationDrawer {
    /**
     * Contains instances for configuration options, data storage/access and draw area manipulation.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param annotationDrawer {Object} - drawer for annotations
     * @param intermolecularDrawer {Object} - drawer for intermolecular edges
     * @param structureDrawer {Object} - drawer for structures
     */
    constructor(opts, sceneData, annotationDrawer, intermolecularDrawer, structureDrawer) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.annotationDrawer = annotationDrawer;
        this.intermolecularDrawer = intermolecularDrawer;
        this.structureDrawer = structureDrawer;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the initial representation of recently added structures.
     *
     * @param structureInfos {Array} - draw information for the different
     * added structures
     */
    setInitialStructureRepresentation(structureInfos) {
        structureInfos.forEach((structureInfo) => {
            if (!structureInfo.hasOwnProperty('id') ||
                !this.sceneData.structuresData.structures.hasOwnProperty(structureInfo.id)) {
                return;
            }
            const structure = this.sceneData.structuresData.structures[structureInfo.id];
            if (structureInfo.representation) {
                structure.representationsData.currentRepresentation = structureInfo.representation;
                this.changeStructureRepresentationByIds(structure.id, structureInfo.representation);
            } else {
                const representations = this.opts.allowedStructureRepresentations[structure.structureType] ||
                    this.opts.allowedStructureRepresentations.default;
                for (const rep of representations) {
                    if (structure.representationsData.hasRepresentation(rep)) {
                        this.changeStructureRepresentationByIds(structure.id, rep);
                        return
                    }
                }
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the representation of all structures with a specific structure type
     * to a given representation.
     *
     * @param structureType {String} - change the representation off all
     * structures with this type
     * @param representation {string|StructureRepresentation} - the representation
     * to display. Either give a value of a StructureRepresentation object (e.g.
     * 'StructureRepresentation.default') or a string which should be a valid key
     * of a StructureRepresentation object (e.g. 'default')
     */
    changeStructureRepresentationByType(structureType,
        representation = StructureRepresentation.default
    ) {
        if (StructureRepresentation.hasOwnProperty(representation)) {
            representation = StructureRepresentation[representation];
        } else if (!Object.values(StructureRepresentation).includes(representation)) {
            return;
        }

        const structures = Object.values(this.sceneData.structuresData.structures)
            .filter(struct => struct.structureType === structureType);
        const structureIds = structures.map(struct => struct.id);
        this.changeStructureRepresentationByIds(structureIds, representation);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Changes the representation of a structure to a given representation.
     *
     * @param structureId {(number|number[])} - id(s) of structure
     * @param representation {string|StructureRepresentation} - the representation
     * to display. Either give a value of a StructureRepresentation object (e.g.
     * 'StructureRepresentation.default') or a string which should be a valid key
     * of a StructureRepresentation object (e.g. 'default')
     */
    changeStructureRepresentationByIds(structureId,
        representation = StructureRepresentation.default
    ) {
        if (typeof representation === 'string' &&
            StructureRepresentation.hasOwnProperty(representation)) {
            representation = StructureRepresentation[representation];
        } else if (!Object.values(StructureRepresentation).includes(representation)) {
            console.log('representation ' + representation + ' is invalid');
            return;
        }

        if (Array.isArray(structureId)) {
            for (const id of structureId) {
                this.changeStructureRepresentationByIds(id, representation);
            }
            return;
        }

        if (this.sceneData.structuresData.structures.hasOwnProperty(structureId)) {
            const structure = this.sceneData.structuresData.structures[structureId];
            if (structure.representationsData.hasRepresentation(representation)) {
                if (structure.representationsData.curRepresentation() !== representation) {
                    this.structureDrawer.unselectStructure(structureId);
                    const annotationsToDeselect = Object.values(this.sceneData.annotationsData.annotations)
                        .filter(annotation => annotation.structureLink === structureId &&
                            annotation.isStructureLabel);
                    for (const annotation of annotationsToDeselect) {
                        this.annotationDrawer.unselectAnnotationDrawareaContainer(annotation.id,
                            false,
                            false
                        )
                    };
                }
                structure.representationsData.changeInternalRepresentation(representation);
                if (structure.hidden) {
                    return;
                }
                //show/hide svg elements
                const hiddenStructures = this.sceneData.structuresData.getHiddenStructures();
                this.structureDrawer.showHideStructureParts(structureId,
                    {full: true},
                    hiddenStructures,
                    true
                );
                if (representation === StructureRepresentation.default) {
                    this.hideStructureCircleRepresentation(structureId);
                } else if (representation === StructureRepresentation.circle) {
                    this.hideDefaultRepresentation(structureId);
                }
                this.updateAnnotationPositions(structureId, representation);

                //redraw intermolecular
                const {
                    distances, interactions, atomPairInteractions, piStackings, cationPiStackings
                } = structure.getConnectedElements();
                this.intermolecularDrawer.updateAllIntermolecular(distances,
                    interactions,
                    atomPairInteractions,
                    piStackings,
                    cationPiStackings,
                    true
                );
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates annotation positions after changing to a new structure representation.
     *
     * @param structureId {(number|number[])} - id(s) of structure
     * @param structureRepresentation {string|StructureRepresentation} - the representation
     * to display. Either give a value of a StructureRepresentation object (e.g.
     * 'StructureRepresentation.default') or a string which should be a valid key
     * of a StructureRepresentation object (e.g. 'default')
     */
    updateAnnotationPositions(structureId, structureRepresentation) {
        const annotationsToMove = Object.values(this.sceneData.annotationsData.annotations)
            .filter(annotation => annotation.structureLink === structureId &&
                !annotation.isStructureLabel);
        for (const annotation of annotationsToMove) {
            const offsets = VectorCalculation.vectorizeLine(annotation.coordinates,
                annotation.structureRepresentationInfo[structureRepresentation].coordinates
            );
            this.annotationDrawer.moveAnnotation(annotation.id, offsets, false);
            this.annotationDrawer.updateAnnotationLimitsSelectors(annotation);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the structure circle representation of a structure.
     *
     * @param structureId {(number|number[])} - id of structure
     */
    hideStructureCircleRepresentation(structureId) {
        const hideParts = {
            structureCircle: true
        };
        this.structureDrawer.showHideStructureParts(structureId, hideParts, [], false);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the by config set default representation of a structure.
     *
     * @param structureId {(number|number[])} - id of structure
     */
    hideDefaultRepresentation(structureId) {
        const hideParts = {
            atoms: true, bonds: true, hydrophobic: true
        };
        this.structureDrawer.showHideStructureParts(structureId, hideParts, [], false);
        this.annotationDrawer.hideAnnotations(Object.values(this.sceneData.annotationsData.annotations)
            .filter(annotation => annotation.structureLink === structureId &&
                annotation.isStructureLabel)
            .map(annotation => annotation.id));
        this.structureDrawer.updateVisibility();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Toggle the visibility of one or multiple structures, their interactions and
     * annotations.
     *
     * @param structureId {(number|number[])} - id(s) of structure
     * @param show {Boolean} - whether structure(s) should be shown (true) or
     * hidden (false)
     */
    changeStructureVisibility(structureId, show) {
        if (Array.isArray(structureId)) {
            for (const id of structureId) {
                this.changeStructureVisibility(id, show);
            }
            return;
        }

        if (!this.sceneData.structuresData.structuresInUse.has(structureId)) {
            return;
        }

        const structure = this.sceneData.structuresData.structures[structureId];

        if (show && structure.hidden) {
            structure.hidden = false;
            for (const hCont of
                Object.values(structure.hydrophobicConnectionData.hydrophobicConts)) {
                hCont.hidden = false;
            }
            for (const annotation of Object.values(this.sceneData.annotationsData.annotations)) {
                if (annotation.structureLink === structureId) {
                    annotation.hidden = false;
                }
            }
            this.changeStructureRepresentationByIds(structureId,
                structure.representationsData.curRepresentation()
            );
        } else if (!show && !structure.hidden) {
            this.structureDrawer.showHideStructureParts(structureId, {full: true}, [], false);
            structure.hidden = true;
            for (const hCont of
                Object.values(structure.hydrophobicConnectionData.hydrophobicConts)) {
                hCont.hidden = true;
            }
            for (const annotation of Object.values(this.sceneData.annotationsData.annotations)) {
                if (annotation.structureLink === structureId) {
                    annotation.hidden = true;
                }
            }
        }
    }
}

/* src/Drawers/SvgDrawer.js */
/**
 * Validates input JSON, manipulates the data and the draw area (components) with more specialized
 * drawers.
 * Most drawers manage their own component. Some drawers use other drawers
 * creating more complex drawings that consist of combinations of objects these drawers manage.
 * Performs also add, remove and move changes with respect to data and the draw area.
 */
class SvgDrawer {
    /**
     * Contains instances for configuration options, data storage/access, user interaction tracking
     * and draw area manipulation. A callback that will be executed on adding changes to
     * the scene can be set optionally.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param interactionState {Object} - tracks user interactions
     * @param svgComponent {Object} - represents the draw area
     */
    constructor(opts, sceneData, interactionState, svgComponent) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.interactionState = interactionState;
        this.svgComponent = svgComponent;

        this.viewerDrawer =
            new ViewerDrawer(this.opts, this.sceneData, this.interactionState, this.svgComponent);

        this.jsonValidator = new JsonValidator(this.sceneData);

        this.textLabelDrawer = new TextLabelDrawer(this.svgComponent);
        this.hydrophobicDrawer = new HydrophobicDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.hydrophobicGroupsComponent,
            this.jsonValidator
        );
        this.annotationDrawer = new AnnotationDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.annotationGroupsComponent,
            this.textLabelDrawer,
            this.jsonValidator
        );
        this.atomDrawer = new AtomDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.atomGroupsComponent
        );
        this.edgeDrawer = new EdgeDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.edgeGroupsComponent
        );
        this.ringDrawer =
            new RingDrawer(this.opts, this.sceneData, this.atomDrawer, this.edgeDrawer);
        this.intermolecularDrawer = new IntermolecularDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.intermolecularGroupsComponent,
            this.jsonValidator
        );
        this.structureCircleDrawer = new StructureCircleDrawer(this.opts,
            this.sceneData,
            this.svgComponent.transformGroupsComponent.structureCircleGroupsComponent,
            this.textLabelDrawer,
            this.annotationDrawer
        );
        this.structureDrawer = new StructureDrawer(this.opts,
            this.sceneData,
            this.svgComponent,
            this.viewerDrawer,
            this.atomDrawer,
            this.edgeDrawer,
            this.ringDrawer,
            this.structureCircleDrawer,
            this.jsonValidator
        );
        this.structureRepresentationDrawer = new StructureRepresentationDrawer(this.opts,
            this.sceneData,
            this.annotationDrawer,
            this.intermolecularDrawer,
            this.structureDrawer
        );

        this.historyDrawer = new HistoryDrawer(this.opts, this.sceneData, this.structureDrawer);

        this.preprocessCallback = null;
        this.removeCallback = null;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves atoms of a specified structure to new positions. In the following,
     * updates all bond draw elements that infer their positions from the moved
     * atoms. Returns the necessary Change objects to apply/revert these
     * coordinate changes.
     *
     * @param structureId {Number} - id of structure from which to move atoms
     * and bonds
     * @param newAtomCoords {Object} - map from atom ids to new coordinates
     * @param isFlip {Boolean} - whether the movement involves mirroring of
     * the structure and stereo bonds need to change
     * @param structureMaxes {BoundaryUpdateInfo} - log of how the boundaries
     * of the given structure change
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {Object} - Change object array for the next history step and
     * information about affected intermolecular forces
     */
    applyCoordinateChanges(structureId, newAtomCoords, isFlip, structureMaxes, globalMaxes) {
        const structure = this.sceneData.structuresData.structures[structureId];

        const repAtoms = new Set(); //atoms that were really moved
        const repEdges = new Set(); //edges to reposition
        const flipEdges = new Set(); //edges moved by structure flipping
        const coordChanges = []; //bundles up all Change objects for history

        this.createApplyAtomChanges(structure,
            structureId,
            repAtoms,
            repEdges,
            flipEdges,
            coordChanges,
            newAtomCoords,
            isFlip
        );
        this.createApplyStereoAnnotationChange(structure, flipEdges, coordChanges);
        const edgeChangeCases = {};
        this.createApplyEdgeChanges(structure, repEdges, flipEdges, coordChanges, edgeChangeCases);
        this.createApplyHydrogenChanges(structureId, structure, coordChanges);
        this.createApplyAnnotationChanges(structureId, structure, coordChanges);
        this.createApplyAtomDrawLimitsChange(structureId,
            structure,
            repAtoms,
            coordChanges,
            structureMaxes,
            globalMaxes
        );
        this.createApplyAliphaticRingChanges(structure, repAtoms, coordChanges);
        this.createApplyAromaticRingChanges(structureId,
            structure,
            repAtoms,
            coordChanges,
            edgeChangeCases
        );
        const repAtomArr = [...repAtoms];
        this.createApplyRingCenterChanges(structure, repAtomArr, coordChanges);
        const affectedIntermolecular = {};
        this.collectAffectedIntermolecular(structure, repAtomArr, affectedIntermolecular);

        return {
            changes: coordChanges, ...affectedIntermolecular
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates and applies necessary atom movement changes and collects
     * subsequently corresponding edges of a specified structure by
     * checking for coordinate changes.
     *
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param structureId {Number} - id of structure from which to move atoms
     * and bonds
     * @param repAtoms {Set} - collects atoms that were really moved
     * @param repEdges {Set} - collects edges to reposition
     * @param flipEdges {Set} - ids of stereo bonds that have to be flipped
     * @param coordChanges {Array} - bundles up all movement changes
     * @param newAtomCoords {Object} - map from atom ids to new coordinates
     * @param isFlip {Boolean} - whether the movement involves mirroring of
     * the structure and stereo bonds need to change
     */
    createApplyAtomChanges(structure,
        structureId,
        repAtoms,
        repEdges,
        flipEdges,
        coordChanges,
        newAtomCoords,
        isFlip
    ) {
        const oldCoordMap = {};
        for (const atomId in newAtomCoords) {
            const atom = structure.atomsData.getAtom(atomId);
            if (!atom || !atom.enabled) {
                continue;
            }

            const newCoords = newAtomCoords[atomId];
            const oldCoords = atom.coordinates;

            if (!PointCalculation.coordsAlmostEqual(newCoords, oldCoords)) {
                const moveFn = (id, offsets) => {
                    const atomsToMove = {};
                    atomsToMove[structureId] = [id];
                    this.atomDrawer.moveAtomsByOffset(atomsToMove, offsets);
                };
                coordChanges.push(this.textLabelDrawer.updateTextLabelCoordinates(atom,
                    newCoords,
                    moveFn
                ));
                repAtoms.add(parseInt(atomId));
                oldCoordMap[atomId] = oldCoords;
                //find edges to move
                const neighbors = structure.atomsData.neighbors[atomId];
                neighbors.forEach(({edgeId}) => {
                    repEdges.add(edgeId);
                });
            }
            //find edges to flip (and thus, also move)
            const neighbors = structure.atomsData.neighbors[atomId];
            neighbors.forEach(({edgeId}) => {
                const type = structure.edgesData.getEdge(edgeId).type;
                if (isFlip && ([
                    'stereoFront', 'stereoBack', 'stereoFrontReverse', 'stereoBackReverse'
                ]
                    .includes(type))) {
                    flipEdges.add(edgeId);
                    //redraw here also on edges with unchanged coordinates
                    repEdges.add(edgeId);
                }
            });
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates and applies stereo-annotation changes of edges if structure
     * was mirrored.
     *
     * @param structure {Structure} - structure from which to move annotations
     * @param flipEdges {Set} - ids of stereo bonds that have to be flipped
     * @param coordChanges {Array} - bundles up all movement changes
     */
    createApplyStereoAnnotationChange(structure, flipEdges, coordChanges) {
        flipEdges.forEach(edgeId => {
            const edge = structure.edgesData.getEdge(edgeId);
            if (!edge.enabled) {
                return;
            }
            const flipChange = this.edgeDrawer.createEdgeFlipChange(edge);
            flipChange.apply();
            coordChanges.push(flipChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Atoms were moved. Creates and applies necessary changes for corresponding edges.
     *
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repEdges {Set} - collection of edges to reposition
     * @param flipEdges {Set} - ids of stereo bonds that have to be flipped
     * @param coordChanges {Array} - bundles up all movement changes
     * @param edgeChangeCases {Object} - map from bond ids to log of how the
     * bond representation changes after immediate coordinate update and on
     * both apply and revert of the Change
     */
    createApplyEdgeChanges(structure, repEdges, flipEdges, coordChanges, edgeChangeCases) {
        repEdges.forEach(edgeId => {
            const edge = structure.edgesData.getEdge(edgeId);
            if (!edge.enabled) {
                return;
            }
            coordChanges.push(this.edgeDrawer.updateEdgeCoordinates(structure,
                edge,
                flipEdges,
                edgeChangeCases
            ));
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if positions of hydrogens need to be updated and applies changes.
     *
     * @param structureId {Object} - id of the structure from which to move atoms
     * and bonds
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param coordChanges {Array} - bundles up all movement changes
     */
    createApplyHydrogenChanges(structureId, structure, coordChanges) {
        const changedHs = structure.atomsData.findAtomsWithChangedHPlacement(false);
        for (const atomId in changedHs) {
            const atom = structure.atomsData.getAtom(atomId);
            const newHorientation = changedHs[atomId];
            const hChange = this.atomDrawer.createHPlacementChange(structureId,
                atom,
                newHorientation
            );
            //no need to redraw if temp changes have already set h right
            if (atom.tempHydrogenOrientation === newHorientation) {
                atom.setHydrogenOrientation(newHorientation);
            } else {
                hChange.apply();
            }
            coordChanges.push(hChange);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if positions of annotations need to be updated and applies changes.
     *
     * @param structureId {Object} - id of the structure from which to move atoms
     * and bonds
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param coordChanges {Array} - bundles up all movement changes
     */
    createApplyAnnotationChanges(structureId, structure, coordChanges) {
        //check if positions of amino acid labels need to be updated
        const changedLabels = structure.atomsData.findAtomsWithChangedAnchors(false);
        for (const atomId in changedLabels) {
            const atom = structure.atomsData.getAtom(atomId);
            const newOrientation = changedLabels[atomId];
            const anchorChange = this.atomDrawer.createAnchorPlacementChange(structureId,
                atom,
                newOrientation
            );
            //no need to redraw if temp changes have replaced anchor already
            if (atom.tempLabelOrientation === newOrientation) {
                atom.setLabelSide(newOrientation, false);
            } else {
                anchorChange.apply();
            }
            coordChanges.push(anchorChange);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Setting of draw limits is based on all bounding boxes of the atom's
     * drawing, including for hydrogen, so can only happen now.
     *
     * @param structureId {Object} - id of the structure from which to move atoms
     * and bonds
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repAtoms {Set} - collects atoms that were really moved
     * @param coordChanges {Array} - bundles up all movement changes
     * @param structureMaxes {BoundaryUpdateInfo} - log of how the boundaries
     * of the given structure change
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    createApplyAtomDrawLimitsChange(structureId,
        structure,
        repAtoms,
        coordChanges,
        structureMaxes,
        globalMaxes
    ) {
        //function to update both limits simultaneously
        const updateBothMaxes = (prop, oldVal, newVal, largestIsLim) => {
            structureMaxes.updateMaxes(prop, oldVal, newVal, largestIsLim);
            globalMaxes.updateMaxes(prop, oldVal, newVal, largestIsLim);
        };
        repAtoms.forEach(atomId => {
            const atom = structure.atomsData.getAtom(atomId);

            //update draw limits and selector shapes
            const oldDrawLimits = Object.assign({}, atom.globalDrawLimits);
            this.atomDrawer.updateAtomDrawLimits(structureId, atomId, atom);
            const newDrawLimits = atom.globalDrawLimits;

            //update structure and global maxes based on new draw limits
            updateBothMaxes('xMin', oldDrawLimits.xMin, newDrawLimits.xMin, false);
            updateBothMaxes('xMax', oldDrawLimits.xMax, newDrawLimits.xMax, true);
            updateBothMaxes('yMin', oldDrawLimits.yMin, newDrawLimits.yMin, false);
            updateBothMaxes('yMax', oldDrawLimits.yMax, newDrawLimits.yMax, true);

            //change simple limit changes in history
            const limitChange = new Change();
            const changeLimits = () => {
                this.atomDrawer.updateAtomDrawLimits(structureId, atomId, atom);
            };
            limitChange.bindApplyRevert(changeLimits);
            coordChanges.push(limitChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates non aromatic rings as necessary for movements
     *
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repAtoms {Set} - collects atoms that were really moved
     * @param coordChanges {Array} - bundles up all movement changes
     */
    createApplyAliphaticRingChanges(structure, repAtoms, coordChanges) {
        structure.ringsData.getRingsAffectedByAtoms(repAtoms, false).forEach(ringId => {
            const ring = structure.ringsData.getRing(ringId);
            const updateChange = new Change();
            updateChange.bindApplyRevert(() => {
                ring.update(false)
            });
            updateChange.apply();
            coordChanges.push(updateChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates aromatic rings as necessary for movement.
     *
     * @param structureId {Object} - id of the structure from which to move atoms
     * and bonds
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repAtoms {Set} - collects atoms that were really moved
     * @param coordChanges {Array} - bundles up all movement changes
     * @param edgeChangeCases {Map} - map from bond ids to log of how the
     * bond representation changes after immediate coordinate update and on
     * both apply and revert of the change
     */
    createApplyAromaticRingChanges(structureId,
        structure,
        repAtoms,
        coordChanges,
        edgeChangeCases
    ) {
        structure.ringsData.getRingsAffectedByAtoms(repAtoms, true).forEach(ringId => {
            const ring = structure.ringsData.getRing(ringId);
            ring.edges.forEach(ringEdge => {
                const ringEdgeId = ringEdge.id;
                let immediate, forward, backward;

                if (edgeChangeCases.hasOwnProperty(ringEdgeId)) {
                    ({immediate, forward, backward} = edgeChangeCases[ringEdge.id]);
                } else {
                    const nextEdgeId = ring.getNextEdge(ringEdgeId).id;
                    const prevEdgeId = ring.getPreviousEdge(ringEdgeId).id;
                    if (!(edgeChangeCases.hasOwnProperty(nextEdgeId) ||
                        edgeChangeCases.hasOwnProperty(prevEdgeId))) {
                        return;
                    }
                    immediate = forward = backward = 'move';
                }

                this.edgeDrawer.createAromaticEdgeUpdateFunction(ring,
                    ringEdge,
                    structureId,
                    immediate,
                    false
                )();
                const ringEdgeChange = new Change();
                const forwardUpdate = this.edgeDrawer.createAromaticEdgeUpdateFunction(ring,
                    ringEdge,
                    structureId,
                    forward,
                    false
                );
                const backwardUpdate = this.edgeDrawer.createAromaticEdgeUpdateFunction(ring,
                    ringEdge,
                    structureId,
                    backward,
                    false
                );
                ringEdgeChange.bindApply(forwardUpdate);
                ringEdgeChange.bindRevert(backwardUpdate);
                coordChanges.push(ringEdgeChange);
            });
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates aromatic ring centers as necessary for movement.
     *
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repAtomArr {Array} - collects atoms that were really moved
     * @param coordChanges {Array} - bundles up all movement changes
     */
    createApplyRingCenterChanges(structure, repAtomArr, coordChanges) {
        //update centers of ringsystems
        const affectedRingSystems = structure.ringsData.getRingSystemsAffectedByAtoms(repAtomArr);
        affectedRingSystems.forEach(ringSysId => {
            const ringSysChange = new Change();
            const ringSys = structure.ringsData.ringSystems[ringSysId];
            const oldCenter = Object.assign({}, ringSys.center);
            structure.ringsData.updateRingSystem(ringSysId, false);
            const newCenter = Object.assign({}, ringSys.center);
            const update = () => {
                structure.ringsData.setRingSystemCenter(ringSysId, newCenter, false);
            };
            const revert = () => {
                structure.ringsData.setRingSystemCenter(ringSysId, oldCenter, false);
            };
            ringSysChange.bindApply(update);
            ringSysChange.bindRevert(revert);
            coordChanges.push(ringSysChange);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Collects information about by movement affected intermolecular forces.
     *
     * @param structure {Object} - structure from which to move atoms
     * and bonds
     * @param repAtomArr {Array} - collects atoms that were really moved
     * @param affectedIntermolecular {Object} - information about by movement affected
     * intermolecular forces
     */
    collectAffectedIntermolecular(structure, repAtomArr, affectedIntermolecular) {
        if (this.interactionState.interaction.mode === InteractionMode.bondMirror ||
            this.interactionState.interaction.mode === InteractionMode.lineMirror) {
            affectedIntermolecular.affectedDistances =
                structure.intermolecularConnectionData.ids.distances;
            affectedIntermolecular.affectedInteractions =
                structure.intermolecularConnectionData.ids.interactions;
            affectedIntermolecular.affectedAtomPairInteractions =
                structure.intermolecularConnectionData.ids.atomPairInteractions;
            affectedIntermolecular.affectedPiStackings =
                structure.intermolecularConnectionData.ids.piStackings;
            affectedIntermolecular.affectedCationPiStackings =
                structure.intermolecularConnectionData.ids.cationPiStackings;
        } else {
            affectedIntermolecular.affectedDistances =
                structure.intermolecularConnectionData.ids.distances;
            affectedIntermolecular.affectedInteractions =
                structure.intermolecularConnectionData.ids.interactions;
            affectedIntermolecular.affectedAtomPairInteractions =
                structure.intermolecularConnectionData.getAtomPairInteractionsAffectedByAtoms(
                    repAtomArr, this.opts.moveFreedomLevel);
            affectedIntermolecular.affectedPiStackings =
                structure.intermolecularConnectionData.getPiStackingsAffectedByAtoms(repAtomArr);
            affectedIntermolecular.affectedCationPiStackings =
                structure.intermolecularConnectionData.getCationPiStackingsAffectedByAtoms(
                    repAtomArr);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Catch-all function to apply any sort of changes and one step in the history.
     * Creates a new history step array to which gradually new Change objects
     * are added. In the end, also update structural boundaries where necessary.
     *
     * @param colorChanges {Object} - new colors for atoms
     * @param coordinateChanges {Object} - new coordinates for atoms
     * @param splineCoordinateChanges {Object} - new coordinates for spline
     * control points
     * @param annotationCoordinateChanges {Object} - new coordinates for
     * annotations
     * @param remove {Object} - structures, atoms, bonds, annotations and
     * intermolecular interactions to remove from the draw area
     * @param add {Object} - new scene information
     */
    applySceneChanges({
        colorChanges,
        coordinateChanges,
        splineCoordinateChanges,
        annotationCoordinateChanges,
        remove,
        add
    }) {
        //accumulate changes and log what types of changes happen
        const historyStep = new HistoryStep();

        //initiate values to track through all change types
        const globalMaxes = new BoundaryUpdateInfo(this.sceneData.globalLimits);

        const addedStructureIds = [];
        if (add && add.scene) {
            this.applyAdd(add, historyStep, addedStructureIds, globalMaxes);
        }
        const changedStructureMaxes = {};
        if (remove) {
            this.applyRemove(remove, historyStep, changedStructureMaxes, globalMaxes);
        }

        const allCoordChanges = [];
        const intermolecularChanges = {
            atomPairInteractions: new Set(),
            piStackings: new Set(),
            cationPiStackings: new Set(),
            distances: new Set(),
            interactions: new Set()
        };
        if (coordinateChanges) {
            this.applyStructureMovement(coordinateChanges,
                allCoordChanges,
                intermolecularChanges,
                changedStructureMaxes,
                globalMaxes
            );
        }

        this.updateStructuresBoundaries(allCoordChanges,
            historyStep,
            changedStructureMaxes,
            globalMaxes
        );

        if (splineCoordinateChanges) {
            this.applyHydrophobicMovement(splineCoordinateChanges, allCoordChanges, globalMaxes);
        }

        if (annotationCoordinateChanges) {
            this.applyAnnotationMovement(annotationCoordinateChanges, allCoordChanges, globalMaxes);
        }

        this.applyIntermolecularMovement(intermolecularChanges, allCoordChanges);

        if (colorChanges) {
            this.applyColorChanges(colorChanges, historyStep);
        }

        //merge coordinate changes into history step, apply callback if necessary
        if (allCoordChanges.length) {
            historyStep.addChanges(allCoordChanges);
            historyStep.addAction('sceneChange');
        }

        //update global boundaries
        this.historyDrawer.setNewLimits(this.sceneData,
            globalMaxes,
            'globalLimits',
            'calcBoundaries',
            historyStep
        );

        //apply created history step to history
        if (historyStep.hasChanges()) {
            this.historyDrawer.applyStepToHistory(historyStep, addedStructureIds);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies any sort of add changes to scene. Sets a new history step to Array.
     *
     * @param add {Object} - new scene information
     * @param historyStep {Object} - new history step array to which new add
     * Change object is added
     * @param addedStructureIds {Array} - ids of added structures
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    applyAdd(add, historyStep, addedStructureIds, globalMaxes) {
        this.sceneData.loadedJsonStrings.push(JSON.stringify(add));
        const scene = add.scene;
        if (this.preprocessCallback) {
            this.preprocessCallback(scene);
        }
        //gradually add structural units and accumulate changes
        const allAddChanges = [];
        if (scene.structures) {
            Array.prototype.push.apply(allAddChanges,
                this.structureDrawer.applyAddStructures(scene.structures,
                    globalMaxes,
                    addedStructureIds
                )
            );
        }
        if (scene.atomPairInteractions) {
            Array.prototype.push.apply(allAddChanges,
                this.intermolecularDrawer.applyAddIntermolecular(scene.atomPairInteractions,
                    'atomPairInteractions'
                )
            );
        }
        if (scene.piStackings) {
            Array.prototype.push.apply(allAddChanges,
                this.intermolecularDrawer.applyAddIntermolecular(scene.piStackings, 'piStackings')
            );
        }
        if (scene.cationPiStackings) {
            Array.prototype.push.apply(allAddChanges,
                this.intermolecularDrawer.applyAddIntermolecular(scene.cationPiStackings,
                    'cationPiStackings'
                )
            );
        }
        if (scene.distances) {
            Array.prototype.push.apply(allAddChanges,
                this.intermolecularDrawer.applyAddIntermolecular(scene.distances, 'distances')
            );
        }
        if (scene.interactions) {
            Array.prototype.push.apply(allAddChanges,
                this.intermolecularDrawer.applyAddIntermolecular(scene.interactions, 'interactions')
            );
        }
        if (scene.hydrophobicContacts) {
            Array.prototype.push.apply(allAddChanges,
                this.hydrophobicDrawer.applyAddHydrophobic(scene.hydrophobicContacts, globalMaxes)
            );
        }
        if (scene.annotations) {
            Array.prototype.push.apply(allAddChanges,
                this.annotationDrawer.applyAddAnnotations(scene.annotations, globalMaxes)
            );
        }
        //apply add changes to history step
        if (!allAddChanges.length) return;
        historyStep.addChanges(allAddChanges);
        historyStep.addAction('sceneChange');
        addedStructureIds.forEach(structureId => {
            //keep original structure for reset and SMARTS
            this.sceneData.structuresData.originalStructures[structureId] =
                this.sceneData.structuresData.structures[structureId].clone();
        });

        //set the initial representation of all added structures
        if (scene.structures) {
            this.structureRepresentationDrawer.setInitialStructureRepresentation(scene.structures);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes specified elements in the draw area.
     * Returns the necessary Change objects to apply/revert this removal.
     *
     * @param structures {Array|Set} - ids of structure to completely remove
     * @param atoms {Array|Set} - ids of atoms to remove
     * @param edges {Array|Set} - ids of bonds to remove
     * @param annotations {Array|Set} - ids of annotations to remove
     * @param atomPairInteractions {Array|Set} - ids of atom pair interactions to remove
     * @param piStackings {Array|Set} - ids of pi stackings to remove
     * @param cationPiStackings {Array|Set} - ids of cation pi stackings to remove
     * @param hydrophobicContacts {Array|Set} - ids of hydrophobic contacts to remove
     * Those are objects which have 'id' as key and can optional have specified
     * control points (key 'controlPoints', values as array of ids) to only remove
     * those
     * @param historyStep {Object} - new history step array to which new remove
     * Change object is added
     * @param changedStructureMaxes {Object} - log of how the boundaries
     * of the given structures change
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     * @returns {Array} - Change objects for the next history step
     */
    applyRemove({
        structures,
        atoms,
        edges,
        annotations,
        atomPairInteractions,
        piStackings,
        cationPiStackings,
        hydrophobicContacts
    }, historyStep, changedStructureMaxes, globalMaxes) {
        const removeCollector = new RemoveCollector(this.opts, this.sceneData);
        const {
            remStructures,
            remAtoms,
            remEdges,
            remAnnotations,
            remAtomPairInteractions,
            remPiStackings,
            remCationPiStackings,
            remHydrophobicContacts
        } = removeCollector.determineRemoveObjects({
            structures,
            atoms,
            edges,
            annotations,
            atomPairInteractions,
            piStackings,
            cationPiStackings,
            hydrophobicContacts
        });

        const remChanges = []; //bundle up changes

        const markRequiredRecalcs = (prop, val, strucId = undefined) => {
            if (!globalMaxes[prop].changeDir) {
                if (globalMaxes[prop].val === val) {
                    globalMaxes[prop].changeDir = -1;
                }
            }

            if (!strucId) {
                return;
            }

            if (!changedStructureMaxes.hasOwnProperty(strucId)) {
                changedStructureMaxes[strucId] =
                    new BoundaryUpdateInfo(this.sceneData.structuresData.structures[strucId].boundaries);
            }
            if (!changedStructureMaxes[strucId][prop].changeDir) {
                if (changedStructureMaxes[strucId][prop].val === val) {
                    changedStructureMaxes[strucId][prop].changeDir = -1;
                }
            }
        };
        this.structureDrawer.removeStructures(remStructures, remChanges, markRequiredRecalcs);
        const removedAtomEdges = this.atomDrawer.removeAtoms(remAtoms,
            remChanges,
            markRequiredRecalcs
        );
        Helpers.mergeIntoSet(remEdges, removedAtomEdges);
        const remCarbonAtoms = this.edgeDrawer.removeEdges(remEdges, remChanges);
        this.atomDrawer.removeCarbonAtoms(remCarbonAtoms, remChanges);
        this.annotationDrawer.removeAnnotations(remAnnotations, remChanges, markRequiredRecalcs);
        this.hydrophobicDrawer.removeHydrophobicContacts(remHydrophobicContacts,
            remChanges,
            markRequiredRecalcs
        );
        this.intermolecularDrawer.removeIntermolecular(remAtomPairInteractions,
            remChanges,
            'atomPairInteractions'
        );
        this.intermolecularDrawer.removeIntermolecular(remPiStackings, remChanges, 'piStackings');
        this.intermolecularDrawer.removeIntermolecular(remCationPiStackings,
            remChanges,
            'cationPiStackings'
        );
        if (remChanges.length) {
            historyStep.addChanges(remChanges);
            historyStep.addAction('sceneChange');
        }
        if (this.removeCallback) {
            this.removeCallback();
        }
        return remChanges;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves atoms of multiple structures to new positions. In the following,
     * updates all bond draw elements that infer their positions from the moved
     * atoms. Returns the necessary change objects to apply/revert these
     * coordinate changes. Collects data for movement of interactions.
     *
     * @param coordinateChanges {Object} - new coordinates for atoms
     * @param allCoordChanges {Array} - accumulate all types (structures, splines, annotations)
     * of coordinate changes for history
     * @param intermolecularChanges {Object} - contains the keys 'atomPairInteractions',
     * 'piStackings' and 'cationPiStackings' which contain the ids of
     * corresponding interactions to move.
     * @param changedStructureMaxes {Object} - log of how the boundaries
     * of the given structures change
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    applyStructureMovement(coordinateChanges,
        allCoordChanges,
        intermolecularChanges,
        changedStructureMaxes,
        globalMaxes
    ) {
        for (const structureId in coordinateChanges) {
            if (!this.sceneData.structuresData.structuresInUse.has(parseInt(structureId))) {
                continue;
            }
            const {newCoordinates, isFlip} = coordinateChanges[structureId];
            const structureMaxes = changedStructureMaxes[structureId] ?
                changedStructureMaxes[structureId] :
                new BoundaryUpdateInfo(this.sceneData.structuresData.structures[structureId].boundaries);
            const {
                changes,
                affectedDistances,
                affectedInteractions,
                affectedAtomPairInteractions,
                affectedPiStackings,
                affectedCationPiStackings
            } = this.applyCoordinateChanges(structureId,
                newCoordinates,
                isFlip,
                structureMaxes,
                globalMaxes
            );
            if (!changes.length) {
                continue;
            }
            Array.prototype.push.apply(allCoordChanges, changes);
            intermolecularChanges.distances = new Set([
                ...intermolecularChanges.distances, ...affectedDistances
            ]);
            intermolecularChanges.interactions = new Set([
                ...intermolecularChanges.interactions, ...affectedInteractions
            ]);
            intermolecularChanges.atomPairInteractions = new Set([
                ...intermolecularChanges.atomPairInteractions, ...affectedAtomPairInteractions
            ]);
            intermolecularChanges.piStackings = new Set([
                ...intermolecularChanges.piStackings, ...affectedPiStackings
            ]);
            intermolecularChanges.cationPiStackings = new Set([
                ...intermolecularChanges.cationPiStackings, ...affectedCationPiStackings
            ]);
            changedStructureMaxes[structureId] = structureMaxes;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates boundaries of structures and update structure circles.
     *
     * @param allCoordChanges {Array} - accumulate all types (structures, splines, annotations)
     * of coordinate changes for history
     * @param historyStep {Object} - new history step array to which new remove
     * Change object is added
     * @param changedStructureMaxes {Object} - log of how the boundaries
     * of the given structures change
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    updateStructuresBoundaries(allCoordChanges, historyStep, changedStructureMaxes, globalMaxes) {
        for (const structureId in changedStructureMaxes) {
            const structure = this.sceneData.structuresData.structures[structureId];
            this.historyDrawer.setNewLimits(structure,
                changedStructureMaxes[structureId],
                'boundaries',
                'calcBoundaries',
                historyStep
            );
            if (structure.representationsData.hasRepresentation(StructureRepresentation.circle)) {
                Array.prototype.push.apply(allCoordChanges,
                    this.structureCircleDrawer.applyCoordinateChangesStructureCircle(structure,
                        globalMaxes
                    )
                );
                const oldBounds = structure['boundaries'];
                const boundChanged = structure.addStructureCircleToBoundaries();
                if (boundChanged) {
                    this.historyDrawer.setNewLimitsToHistory(structure,
                        oldBounds,
                        'boundaries',
                        historyStep
                    );
                }
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates atom color.
     *
     * @param colorChanges {Object} - new colors for atoms
     * @param historyStep {Object} - new history step array to which new remove
     * Change object is added
     */
    applyColorChanges(colorChanges, historyStep) {
        const allColorChanges = [];
        for (const structureId in colorChanges) {
            if (!this.sceneData.structuresData.structuresInUse.has(parseInt(structureId))) {
                continue;
            }
            Array.prototype.push.apply(allColorChanges,
                this.structureDrawer.applyColorChanges(structureId, colorChanges[structureId])
            );
        }
        if (allColorChanges.length) {
            historyStep.addChanges(allColorChanges);
            historyStep.addAction('colorChange');
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves hydrophobic splines to new positions.
     *
     * @param splineCoordinateChanges {Object} - new coordinates for spline's
     * control points
     * @param allCoordChanges {Array} - accumulate all types (structures, splines, annotations)
     * of coordinate changes for history
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    applyHydrophobicMovement(splineCoordinateChanges, allCoordChanges, globalMaxes) {
        for (const splineId in splineCoordinateChanges) {
            const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
            const newControlPoints = splineCoordinateChanges[splineId];
            Array.prototype.push.apply(allCoordChanges,
                this.hydrophobicDrawer.applyCoordinateChangesSpline(splineId,
                    spline,
                    newControlPoints,
                    globalMaxes
                )
            );
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves annotation to new positions.
     *
     * @param annotationCoordinateChanges {Object} - new coordinates for
     * annotations
     * @param allCoordChanges {Array} - accumulate all types (structures, splines, annotations)
     * of coordinate changes for history
     * @param globalMaxes {BoundaryUpdateInfo} - log of how the global
     * boundaries of the scene change
     */
    applyAnnotationMovement(annotationCoordinateChanges, allCoordChanges, globalMaxes) {
        for (const labelId in annotationCoordinateChanges) {
            if (!this.sceneData.annotationsData.annotations.hasOwnProperty(labelId)) {
                continue;
            }
            Array.prototype.push.apply(allCoordChanges,
                this.annotationDrawer.applyCoordinateChangesAnnotation(labelId,
                    annotationCoordinateChanges[labelId],
                    globalMaxes
                )
            );
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves intermolecular edges to new positions.
     *
     * @param intermolecularChanges {Object} - contains the keys 'atomPairInteractions',
     * 'piStackings' and 'cationPiStackings' which contain the ids of
     * corresponding interactions to move.
     * @param allCoordChanges {Array} - accumulate all types (structures, splines, annotations)
     * of coordinate changes for history
     */
    applyIntermolecularMovement(intermolecularChanges, allCoordChanges) {
        if (Object.keys(intermolecularChanges).length > 0) {
            Array.prototype.push.apply(allCoordChanges,
                this.intermolecularDrawer.applyCoordinateChangesAllIntermolecular(
                    intermolecularChanges)
            );
        }
    }
}

/* src/Drawers/TextLabelDrawer.js */
/**
 * Drawer that manipulates generic text labels in the draw area.
 */
class TextLabelDrawer {
    /**
     * Contains instance of relevant component.
     *
     * @param svgComponent {Object} - represents the draw area
     */
    constructor(svgComponent) {
        this.svgComponent = svgComponent;
        this.transformGroupsComponent = svgComponent.transformGroupsComponent;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Generic function to move a text label (of atoms, structure circle
     * annotations) to new coordinates. Return the Change object to apply/revert
     * this coordinate change.
     *
     * @param label {Object} - the text label's container object
     * @param newCoords {Object} - x- and y-coordinates of the new position
     * @param moveFn {Function} - function to move the text label inside the
     * draw area
     * @returns {Change} - Change object to apply/revert movement
     */
    updateTextLabelCoordinates(label, newCoords, moveFn) {
        const {id: labelId, coordinates: oldCoords} = label;

        const curOffsets = {
            x: newCoords.x - label.tempCoordinates.x, y: newCoords.y - label.tempCoordinates.y
        };
        const fullOffsets = {
            x: newCoords.x - oldCoords.x, y: newCoords.y - oldCoords.y
        };
        const invertedOffsets = {
            x: -fullOffsets.x, y: -fullOffsets.y
        };

        //for NOW: update coordinates in relation to previous temp movement
        label.tempCoordinates = Object.assign({}, newCoords);
        label.coordinates = Object.assign({}, newCoords);
        moveFn(labelId, curOffsets);

        //for HISTORY: add change based on full movements since last step
        const coordChange = new Change();
        const moveToNew = () => {
            label.tempCoordinates = Object.assign({}, newCoords);
            label.coordinates = Object.assign({}, newCoords);
            moveFn(labelId, fullOffsets);
        };
        const moveBack = () => {
            label.tempCoordinates = Object.assign({}, oldCoords);
            label.coordinates = Object.assign({}, oldCoords);
            moveFn(labelId, invertedOffsets);
        };
        coordChange.bindApply(moveToNew);
        coordChange.bindRevert(moveBack);
        return coordChange;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates the height and width of a text element.
     *
     * @param text {String} - text of the text element. Can be omitted if only
     * the height is of interest
     * @return {Object} - key "height" and "width" with values taken from
     * getBBox()
     */
    getTextDimensions(text = 'Test') {
        return this.transformGroupsComponent.getTextDimensions(text);
    }
}

/* src/Drawers/ViewerDrawer.js */
/**
 * Drawer which manipulates the viewer itself and all non molecular objects.
 */
class ViewerDrawer {
    /**
     * Contains instances for configuration options, data storage/access, user interaction tracking,
     * draw area manipulation and all relevant components.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     * @param interactionState {Object} - tracks user interactions
     * @param svgComponent {Object} - represents the draw area
     */
    constructor(opts, sceneData, interactionState, svgComponent) {
        this.opts = opts;
        this.sceneData = sceneData;
        this.interactionState = interactionState;
        this.svgComponent = svgComponent;

        this.transformGroupsComponent = svgComponent.transformGroupsComponent;
        this.backgroundComponent = svgComponent.backgroundComponent;
        this.selectionLineComponent = svgComponent.selectionLineComponent;
        this.interactionElementsGroupComponent =
            this.transformGroupsComponent.interactionElementsGroupComponent;
        this.mirrorLineComponent = this.interactionElementsGroupComponent.mirrorLineComponent;
        this.intermolecularLineComponent =
            this.interactionElementsGroupComponent.intermolecularLineComponent;
        this.annotationFormComponent =
            this.interactionElementsGroupComponent.annotationFormComponent;
        this.structureFormComponent =
            this.interactionElementsGroupComponent.structureFormComponent;
        this.editAnnotationFormComponent =
            this.interactionElementsGroupComponent.editAnnotationFormComponent;
        this.editAtomFormComponent =
            this.interactionElementsGroupComponent.editAtomFormComponent;
        this.editEdgeFormComponent =
            this.interactionElementsGroupComponent.editEdgeFormComponent;
        this.editStructureFormComponent =
            this.interactionElementsGroupComponent.editStructureFormComponent;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets a new color for the background of the draw area.
     *
     * @param color {String} - valid CSS color
     */

    changeBackgroundColor(color) {
        this.backgroundComponent.changeColor(color);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Makes sure that the elements inside the draw area get rescaled properly.
     */

    resize() {
        const bc = this.svgComponent.svgDom.node().getBoundingClientRect();
        this.rescale(bc.width, bc.height);
    }

    /*----------------------------------------------------------------------*/

    /**
     * On change of the size of the draw area associated with the drawer,
     * rescales and re-centers the current scene.
     *
     * @param width {Number} - new width of the draw area
     * @param height {Number} - new height of the draw area
     */
    rescale(width, height) {
        this.sceneData.setInfoForDrawing(width, height);
        this.center();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Zoom into the scene.
     */
    zoomIn() {
        this.scale(
            this.interactionState.transformParams.scale *
            (1 + (this.opts.zoomStrength / 100))
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Zoom out of the scene.
     */
    zoomOut() {
        this.scale(
            this.interactionState.transformParams.scale *
            (1 - (this.opts.zoomStrength / 100))
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Center the current scene (based on its bounding box) within the draw
     * area, leaving some space at the sides defined by .idealMaxHeight
     * and .idealMaxWidth.
     */
    center() {
        if (!this.sceneData.structuresData.structureLoaded) {
            return;
        }
        const {width, height, mid: {x: curMidX, y: curMidY}} = this.sceneData.globalLimits;
        const drawAreaHeight = this.sceneData.drawAreaDim.height;
        const {x: drawAreaMidX, y: drawAreaMidY} = this.sceneData.drawAreaMid;
        const {
            scale: curScale, translate: {x: translateX, y: translateY}
        } = this.interactionState.transformParams;

        //point where we are at currently (in CURRENT scale)
        const transformPoint = {
            x: curMidX + translateX, y: curMidY + translateY
        };

        //point to reach to be centered (also in CURRENT scale)
        const scaledMid = {
            x: drawAreaMidX / curScale, y: drawAreaMidY / curScale
        };

        //how to get to correct point
        const offsetX = scaledMid.x - transformPoint.x;
        const offsetY = scaledMid.y - transformPoint.y;

        //scale s.t. the scene does not go over borders of draw area
        let scale = this.sceneData.idealMaxWidth / width;
        if (height * scale >= drawAreaHeight) {
            scale = this.sceneData.idealMaxHeight / height;
        }

        //correct translation so scale works right
        this.interactionState.transformParams.translate = {
            x: translateX + offsetX, y: translateY + offsetY
        };

        this.scale(scale);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies a scale factor to the draw area. Further apply necessary
     * translations s.t. the center of the scene's bounding box remains at the
     * same relative position.
     *
     * @param scale {Number} - the scale factor
     */
    scale(scale = this.interactionState.transformParams.scale) {
        //apply scaling limits
        scale = scale > this.opts.sceneMaxScale ? this.opts.sceneMaxScale :
            scale < this.opts.sceneMinScale ? this.opts.sceneMinScale : scale;

        //get necessary variables
        const {mid: {x: xMid, y: yMid}} = this.sceneData.globalLimits;

        //easy scaling: no scene loaded, just apply scale
        if (!xMid || !yMid) {
            this.interactionState.transformParams.scale = scale;
            this.transformGroupsComponent.applyTransform(this.interactionState.transformParams);
            return;
        }
        //harder scaling: need to convey feel of zooming into scene
        const {
            scale: prevScale, translate: {x: translateX, y: translateY}
        } = this.interactionState.transformParams;

        //the point to scroll IN to (in CURRENT scale)
        const zoomPoint = {
            x: xMid, y: yMid
        };

        //the point to reach in the end (in NEW scale)
        const scalePoint = {
            x: (zoomPoint.x + translateX) * prevScale / scale,
            y: (zoomPoint.y + translateY) * prevScale / scale
        };

        //how to get to correct point
        const xOffset = scalePoint.x - zoomPoint.x;
        const yOffset = scalePoint.y - zoomPoint.y;

        this.interactionState.transformParams.scale = scale;
        this.interactionState.transformParams.translate = {
            x: xOffset, y: yOffset
        };
        this.transformGroupsComponent.applyTransform(this.interactionState.transformParams);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set the 'cursor' style on the group containing all relevant draw
     * elements of the scene.
     *
     * @param val {String} - the 'cursor' style to use
     */
    setCursorStyle(val) {
        this.transformGroupsComponent.setTransformGroupPointer(val);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hide element representing the mirror line.
     *
     */
    hideMirrorLine() {
        this.mirrorLineComponent.hideMirrorLine();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the rectangular selection shape.
     */
    drawRectSelector(drawnRectPoints) {
        this.selectionLineComponent.drawRectSelector(drawnRectPoints);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Extends and drawers the lasso selection shape.
     */
    addToFreeSelector(drawAreaCoords) {
        this.selectionLineComponent.addToFreeSelector(drawAreaCoords);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the form that allows the editing of objects.
     */
    hideEditForm() {
        const object = this.interactionState.interaction.edit.object;
        if (this.opts.moveFreedomLevel === "free" && object.type === 'atom') {
            this.editAtomFormComponent.hideEditForm();
        } else if (this.opts.moveFreedomLevel === "free" && object.type === 'edge') {
            this.editEdgeFormComponent.hideEditForm();
        } else if (object.type === 'annotation') {
            this.editAnnotationFormComponent.hideEditForm();
        } else if (this.opts.moveFreedomLevel === "structures"
            && (object.type === 'atom' ||
                object.type === 'edge' ||
                object.type === 'structureCircle')) {
            this.editStructureFormComponent.hideEditForm();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Opens a form that allows the editing of objects.
     * @param x {Number} - x coordinate of cursor
     * @param y {Number} - y coordinate of cursor
     */
    openEditForm(x, y) {
        const object = this.interactionState.interaction.edit.object;
        if (this.opts.moveFreedomLevel === "free" && object.type === 'atom') {
            const atom =
                this.sceneData.structuresData.structures[
                    object.structureId
                    ].atomsData.atomById[object.id];
            const data = {};
            data.label = atom.label;
            data.element = atom.element;
            data.charge = atom.charge;
            data.hydrogenCount = atom.hydrogenCount;
            this.editAtomFormComponent.open(x, y, this.sceneData.globalLimits, data);
        } else if (this.opts.moveFreedomLevel === "free" && object.type === 'edge') {
            const edge =
                this.sceneData.structuresData.structures[
                    object.structureId
                    ].edgesData.edgeById[object.id];
            const data = {};
            if (edge.aromatic) {
                data.type = 'aromatic';
            } else {
                data.type = edge.type;
            }
            this.editEdgeFormComponent.open(x, y, this.sceneData.globalLimits, data);
        } else if (object.type === 'annotation') {
            const annotation = this.sceneData.annotationsData.annotations[object.id];
            const data = {};
            data.label = annotation.label;
            this.editAnnotationFormComponent.open(x, y, this.sceneData.globalLimits, data);
        } else if (this.opts.moveFreedomLevel === "structures"
            && (object.type === 'atom' ||
                object.type === 'edge' ||
                object.type === 'structureCircle')) {
            const structure = this.sceneData.structuresData.structures[object.structureId];
            const data = {};
            data.label = structure.structureLabel;
            data.representation = structure.representationsData.currentRepresentation;
            this.editStructureFormComponent.open(x, y, this.sceneData.globalLimits, data);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns user defined info from the edit form.
     *
     * @return {Object} - info of the add edit form plus its coordinates
     */
    getEditFormData() {
        const object = this.interactionState.interaction.edit.object;
        let formData = {};
        if (this.opts.moveFreedomLevel === "free" && object.type === 'atom') {
            formData = this.editAtomFormComponent.getData();
        } else if (this.opts.moveFreedomLevel === "free" && object.type === 'edge') {
            formData = this.editEdgeFormComponent.getData();
        } else if (object.type === 'annotation') {
            formData = this.editAnnotationFormComponent.getData();
        } else if (this.opts.moveFreedomLevel === "structures"
            && (object.type === 'atom' ||
                object.type === 'edge' ||
                object.type === 'structureCircle')) {
            formData = this.editStructureFormComponent.getData();
        }
        formData.coords = this.interactionState.interaction.edit.coords;
        return formData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the form that allows adding of new annotations.
     */
    hideAnnotationAddForm() {
        this.annotationFormComponent.hideAnnotationAddForm();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns user defined info from the annotation form.
     *
     * @return {Object} - info of the add annotation form plus its coordinates
     */
    getAnnotationFormData() {
        const formData = this.annotationFormComponent.getData();
        formData.coords = this.interactionState.interaction.addAnnotation.coords;
        return formData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Opens a form that allows the adding of new annotations.
     * @param x {Number} - x coordinate of cursor
     * @param y {Number} - y coordinate of cursor
     */
    openAnnotationAddForm(x, y) {
        this.annotationFormComponent.open(x, y, this.sceneData.globalLimits);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Hides the form that allows adding of new structures.
     */
    hideStructureAddForm() {
        this.structureFormComponent.hideStructureAddForm();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Returns user defined info from the structure form.
     *
     * @return {Object} - info of the add structure form plus its coordinates
     */
    getStructureFormData() {
        const formData = this.structureFormComponent.getData();
        formData.coords = this.interactionState.interaction.addStructure.coords;
        return formData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Opens a form that allows the adding of new structures.
     * @param x {Number} - x coordinate of cursor
     * @param y {Number} - y coordinate of cursor
     */
    openStructureAddForm(x, y) {
        this.structureFormComponent.open(x, y, this.sceneData.globalLimits);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Applies (cumulative!) translations to the draw area, moving all elements
     * inside. Not tracked by history.
     *
     * @param xOffset {Number} - offset to translate by in x-direction
     * @param yOffset {Number} - offset to translate by in y-direction
     */
    transform({xOffset, yOffset}) {
        const {
            scale, translate: {x: translateX, y: translateY}
        } = this.interactionState.transformParams;
        const newX = translateX + (xOffset / scale);
        const newY = translateY + (yOffset / scale);
        this.interactionState.transformParams.translate = {
            x: newX, y: newY
        };
        this.transformGroupsComponent.applyTransform(this.interactionState.transformParams);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Clears the selector used in rect and lasso selection.
     */
    clearSelector() {
        this.selectionLineComponent.hideSelector();
        this.interactionState.selectionPoints.length = 0; //clear array
    };

    /*----------------------------------------------------------------------*/

    /**
     * During the second step of line mirror interaction, move the mirror line
     * in such a way that one point of it remains at its center and one point
     * on the current cursor position.
     */
    setMirrorLineToCursor() {
        const {
            lineMirror: {curStructureId: structureId, splineControlPoints: splineControlPoints},
            start, origin
        } = this.interactionState.interaction;
        if (structureId === undefined && Object.keys(splineControlPoints).length === 0) return;
        if (structureId === undefined) {
            for (const splineId in splineControlPoints) {
                const realStart = this.interactionState.getRealCoordinates(start);
                const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
                const realMid = PointCalculation.findGeometricCenter(
                    spline.controlPoints.filter(cp => cp.enabled).map(cp => {
                        return cp;
                    })
                );
                const movement = PointCalculation.createMovementBetweenTwoPoints(
                    realMid,
                    realStart
                );
                const first = movement.forward(50);
                const second = movement.backward(100);
                this.mirrorLineComponent.moveMirrorLine(first, second);
                this.interactionState.mirrorLineInfo = {
                    endpoints: {
                        first: first, second: second
                    }, structure: undefined
                };
            }
        } else {
            const structure = this.sceneData.structuresData.structures[structureId];
            const {mid, maxDist: rad} = structure.boundaries;
            const realStart = this.interactionState.getRealCoordinates(start);
            const movement = PointCalculation.createMovementBetweenTwoPoints(mid, realStart);
            const first = movement.forward(rad);
            const second = movement.backward(2 * rad);
            this.mirrorLineComponent.moveMirrorLine(first, second);
            this.interactionState.mirrorLineInfo = {
                endpoints: {
                    first: first, second: second
                }, structure: structureId
            };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets zooming and transformation state of the viewer to the default state.
     */
    reset() {
        this.transformGroupsComponent.applyTransform({scale: 1, translate: {x: 0, y: 0}})
    }

    /*----------------------------------------------------------------------*/

    /**
     * Draws the helper line for the drawing of new intermolecular edges.
     */
    toggleIntermolecularLineDrawing(iContainer, draw, color = undefined, dashed = true) {
        if (draw) {
            this.intermolecularLineComponent.moveAddIntermolecularLine(iContainer.endpoints.first,
                iContainer.endpoints.second,
                color,
                dashed
            );
        } else {
            this.intermolecularLineComponent.hideAddIntermolecularLine();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets viewer to good scale so atom representations are drawn well.
     */
    suggestDrawScaling() {
        return this.transformGroupsComponent.suggestDrawScaling();
    }
}

/* src/GeometryCalculation/AngleCalculation.js */
/**
 * Class (for namespace purposes) containing static helper functions for
 * geometrically motivated calculations with respect to angles.
 */
class AngleCalculation {
    /**
     * Converts an angle value from degrees to radians.
     *
     * @param degree {Number} - angle value in degree
     * @returns {Number} - angle value in radian
     */
    static degreeToRadian(degree) {
        return degree * Math.PI / 180;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Converts an angle value from radians to degrees.
     *
     * @param radian {Number} - angle value in radian
     * @returns {Number} - angle value in degree
     */
    static radianToDegree(radian) {
        return radian * 180 / Math.PI;
    }
}

/* src/GeometryCalculation/LineCalculation.js */
/**
 * Class (for namespace purposes) containing static helper functions for
 * geometrically motivated calculations with respect to lines.
 */
class LineCalculation {
    /**
     * Based on two points (defined by x and y coordinates), returns the
     * linear function that goes through these two points in form of a Line
     * object.
     *
     * @param AX {Number} - x coordinate of first point
     * @param AY {Number} - y coordinate of first point
     * @param BX {Number} - x coordinate of second point
     * @param BY {Number} - y coordinate of second point
     * @param checkVertical {Boolean} - if true a VerticalLine object is returned if x distance is
     * approx. 0
     * @returns {Line|VerticalLine} - Line object defining the linear function
     * through points A and B
     */
    static createLinearFunctionByTwoPoints({x: AX, y: AY}, {x: BX, y: BY}, checkVertical = true) {
        const xDist = BX - AX;
        const yDist = BY - AY;
        if (checkVertical && Helpers.isAlmostEqual(xDist, 0)) {
            return new VerticalLine(AX);
        }
        const slope = yDist / xDist;
        const b = AY - slope * AX;
        return new Line(slope, b);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates line parallel to a given line. This new line can be shorter or
     * larger than the first line, depending on provided angle which defines
     * the angle in which new line end points should lie in relation to
     * original end points.
     *
     * @param fromCoords {Object} - first line end point
     * @param toCoords {Object} - second line end point
     * @param normal {Object} - normal to place second line
     * @param offset {Number} - distance between the two lines
     * @param angle {Number} - angle to place new endpoints
     * @returns {Object} - contains new end points and a secondMakesSense
     * field to annotate if new line is valid
     */
    static createInnerLine(fromCoords, toCoords, normal, offset, angle) {
        const distVec = {
            x: normal.x * offset, y: normal.y * offset
        };

        //move along dist vector to non-shortened line points
        const [movedFrom, movedTo] = VectorCalculation
            .findParallelLineByDistVec(fromCoords, toCoords, distVec);
        const movedLineF = this.createLinearFunctionByTwoPoints(movedFrom, movedTo);

        const rotaAngle = angle;
        let invertedAngle = 360 - rotaAngle;

        //get hit with moved line in specified angle
        const getHit = (point, origin, angle) => {
            const rotaPoint = PointCalculation.rotatePointAroundAnother(point,
                origin,
                angle,
                false
            );
            const hitF = LineCalculation.createLinearFunctionByTwoPoints(rotaPoint, origin);
            return this.findIntersectionTwoLines(movedLineF, hitF);
        };

        //make sure correct angles are applied (and line actually is shortened)
        let secondTo = getHit(fromCoords, toCoords, rotaAngle);
        if (!this.checkPointOnLineSegment(movedFrom, movedTo, secondTo)) {
            secondTo = getHit(fromCoords, toCoords, invertedAngle);
            invertedAngle = rotaAngle;
        }
        const secondFrom = getHit(toCoords, fromCoords, invertedAngle);

        //check if inner line is sane
        const fromToVec = VectorCalculation.vectorizeLine(fromCoords, toCoords);
        const secVec = VectorCalculation.vectorizeLine(secondFrom, secondTo);
        const fromDist = VectorCalculation.getDist2d(fromCoords, toCoords);
        const secDist = VectorCalculation.getDist2d(secondFrom, secondTo);

        return {
            points: [secondFrom, secondTo],
            secondMakesSense: fromDist > secDist &&
                VectorCalculation.checkTwoVectorsPointSameDirection(fromToVec, secVec)
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates the necessary value for the stroke-dashoffset for given
     * stroke-dasharray s.t. the drawn start and end of the line both have the
     * same offset to the actual start coordinates of the line.
     *
     * @param lineLen {Number} - length of the line
     * @param dash {Number} - length of drawn units of the line
     * @param gap {Number} - length of gaps between drawn units of the line
     * @returns {Number} - required stroke-dashoffset
     */
    static calcDashOffset(lineLen, dash, gap) {
        const fullFits = Math.floor(lineLen / (dash + gap));
        let maxOff = (lineLen - dash * fullFits - gap * (fullFits - 1)) / 2;
        if (maxOff > dash) maxOff -= dash;
        return -maxOff;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the point on which two lines (defined by Line objects) intersect.
     *
     * @param line1 {Line|VerticalLine} - first line
     * @param line2 {Line|VerticalLine} - second line
     * @returns {Object} - point where lines intersect
     */
    static findIntersectionTwoLines(line1, line2) {
        //minify drops constructor name, so check for unique parameters of Line
        if (!line1.hasOwnProperty('m')) {
            return this.findIntersectionLineVerticalLine(line1, line2);
        } else if (!line2.hasOwnProperty('m')) {
            return this.findIntersectionLineVerticalLine(line2, line1);
        }
        const {m: m1, b: b1, function: f} = line1;
        const {m: m2, b: b2} = line2;
        if (m1 === m2) {
            return null;
        }
        const x = (b2 - b1) / (m1 - m2);
        return {
            x: x, y: f(x)
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Special case of finding intersection of two lines where one is
     * completely vertical (all points have same y-coordinate).
     *
     * @param vertLine {VerticalLine}- the vertical line
     * @param otherLine {Line|VerticalLine} - second line
     * @returns {Object|null} - point where lines intersect or null if no such
     * point exists (e.g., both lines are vertical)
     */
    static findIntersectionLineVerticalLine(vertLine, otherLine) {
        if (otherLine.constructor.name === 'VerticalLine') {
            return null;
        }
        return {
            x: vertLine.x, y: otherLine.function(vertLine.x)
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether point hits line segment.
     *
     * @param seg_1 {Object} - first point defining line segment
     * @param seg_2 {Object} - second point defining line segment
     * @param point {Object} - point to check
     * @returns {Boolean} - whether hit is found or not
     */
    static checkPointOnLineSegment(seg_1, seg_2, point) {
        const dxP = point.x - seg_1.x;
        const dyP = point.y - seg_1.y;
        const dx_1 = seg_2.x - seg_1.x;
        const dy_1 = seg_2.y - seg_1.y;

        //points are on same line if cross product equals 0 (care with precision)
        const cross = dxP * dy_1 - dyP * dx_1;
        if (!Helpers.isAlmostEqual(cross, 0)) {
            return false;
        }

        //check if point between the segment points
        if (Math.abs(dx_1) >= Math.abs(dy_1)) { //if line is 'more horizontal'
            return dx_1 > 0 ? seg_1.x <= point.x && point.x <= seg_2.x :
                seg_2.x <= point.x && point.x <= seg_1.x;
        } else {
            return dy_1 > 0 ? seg_1.y <= point.y && point.y <= seg_2.y :
                seg_2.y <= point.y && point.y <= seg_1.y;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether two given line segments
     * hit each other.
     *
     * @param p0 {Object} - first point of first line segment
     * @param p1 {Object} - second point of first line segment
     * @param p2 {Object} - first point of second line segment
     * @param p3 {Object} - second point of second line segment
     * @param intersection {Object} - optional parameter into which to write the
     * intersection point
     * @returns {Boolean} - whether hit is found or not
     */
    static checkTwoLineSegmentsInteract(p0, p1, p2, p3, intersection) {
        const s1 = {
            x: p1.x - p0.x, y: p1.y - p0.y
        };
        const s2 = {
            x: p3.x - p2.x, y: p3.y - p2.y
        };
        const s = (-s1.y * (p0.x - p2.x) + s1.x * (p0.y - p2.y)) / (-s2.x * s1.y + s1.x * s2.y);
        const t = (s2.x * (p0.y - p2.y) - s2.y * (p0.x - p2.x)) / (-s2.x * s1.y + s1.x * s2.y);
        if (s >= 0 && s <= 1 && t >= 0 && t <= 1) {
            if (intersection) {
                intersection.x = p0.x + (t * s1.x);
                intersection.y = p0.y + (t * s1.y);
            }
            return true;
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether a line segment (given by
     * its endpoints) intersects a circle.
     *
     * @param a {Object} - first line point
     * @param b {Object} - second line point
     * @param c {Object} - circle (by coordinates and radius)
     * @returns {Boolean} - whether hit is found or not
     */
    static checkIntersectionLineCircle(a, b, c) { //a, b -> rect, c -> circle
        //check if (inf) line and circle intersect
        const d = VectorCalculation.getDist2d(a, b);
        const alpha = (1 / d ** 2) * ((b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y));
        const m = { //nearest point to circle
            x: a.x + (b.x - a.x) * alpha, y: a.y + (b.y - a.y) * alpha
        };
        const mc = VectorCalculation.getDist2d(m, c);
        if (mc > c.rad) {
            return false;
        }

        //check if circle in segment
        const ma = VectorCalculation.getDist2d(m, a);
        const mb = VectorCalculation.getDist2d(m, b);
        if (ma <= d && mb <= d) {
            return true;
        }
        const ac = VectorCalculation.getDist2d(a, c);
        const bc = VectorCalculation.getDist2d(b, c);
        return (ac <= c.rad || bc <= c.rad);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the intersections of a circle and a line where line is defined by
     * slope and y intersection.
     *
     * @param rad {Number} - radius of circle
     * @param xC {Number} - x coordinate of circle mid
     * @param yC {Number} - y coordinate of circle mid
     * @param slope {Number} - slope of line
     * @param y_0 {Number} - y interception of line
     * @returns {Array} - x and y coordinates as objects ({x:.., y:..}) of intersections
     */
    static findCircleLineIntersections(rad, xC, yC, slope, y_0) {
        const xCoords = this.findCircleLineIntersectionsXCoord(rad, xC, yC, slope, y_0);
        const result = [];
        for (const xCoord of xCoords) {
            result.push({
                x: xCoord, y: slope * xCoord + y_0
            })
        }
        return result;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the x coordinates of intersections of a circle and a line.
     *
     * @param rad {Number} - radius of circle
     * @param xC {Number} - x coordinate of circle mid
     * @param yC {Number} - y coordinate of circle mid
     * @param slope {Number} - slope of line
     * @param y_0 {Number} - y interception of line
     * @returns {Array} - x coordinates of intersections
     */
    static findCircleLineIntersectionsXCoord(rad, xC, yC, slope, y_0) {
        const a = 1 + slope * slope;
        const b = -xC * 2 + (slope * (y_0 - yC)) * 2;
        const c = xC * xC + (y_0 - yC) * (y_0 - yC) - rad * rad;
        const d = b * b - 4 * a * c;

        if (d >= 0) {
            const intersections = [
                (-b + Math.sqrt(b * b - 4 * a * c)) / (2 * a),
                (-b - Math.sqrt(b * b - 4 * a * c)) / (2 * a)
            ];
            if (d === 0) {
                //only 1 intersection
                return [intersections[0]];
            }
            return intersections;
        }
        //no intersection
        return [];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the intersections of a circle and a line where line is defined as
     * point and angle.
     *
     * @param rad {Number} - radius of circle
     * @param xC {Number} - x coordinate of circle mid
     * @param yC {Number} - y coordinate of circle mid
     * @param xL {Number} - x coordinate of point one line
     * @param yL {Number} - y coordinate of point one line
     * @param alpha {Number} - angle of line to x axis
     * @returns {Array} - x and y coordinates as objects ({x:.., y:..}) of intersections
     */
    static findCircleLineIntersectionsFromPointAngle(rad, xC, yC, xL, yL, alpha) {
        const {slope, y0} = this.getLineFromPointAngle(xL, yL, alpha);
        return this.findCircleLineIntersections(rad, xC, yC, slope, y0);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out on which side of a line a given point lies. Order of line
     * points is important, as this defines the direction of the line. Result
     * to be interpreted as follows: -1 -> p is on left side of line, 1 -> p
     * is on right side of line.
     *
     * @param l1 {Object} - start point of line
     * @param l2 {Object} - end point of line
     * @param p {Object} - point to determine side of line for
     * @returns {Number} - side of line
     */
    static getSideOfLine(l1, l2, p) {
        return Math.sign((l2.x - l1.x) * (p.y - l1.y) - (l2.y - l1.y) * (p.x - l1.x));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out whether a point lies to the left of a defined line.
     *
     * @param p0 {Object} - first point on line
     * @param p1 {Object} - second point on line
     * @param p2 {Object} - point to find out for if it lies on the left or right of
     * line
     * @returns {Boolean} - whether p2 is left (or right, if false) of line
     */
    static isLeft(p0, p1, p2) {
        return ((p1.x - p0.x) * (p2.y - p0.y) - (p2.x - p0.x) * (p1.y - p0.y)) < 0;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Mirrors given points on a given line.
     *
     * @param points {Array} - points to mirror
     * @param first {Object} - first point to define line by
     * @param second {Object} - second point to define line by
     * @returns {Array} - new coordinates for points
     */
    static mirrorPointsOnLine(points, first, second) {
        //find out how to get offsets (some edge cases to consider)
        let getOffsets;
        if (first.x === second.x) { //edge cases, easy to find offsets
            getOffsets = (x) => {
                return {
                    xOffset: first.x - x, yOffset: 0
                };
            }
        } else if (first.y === second.y) {
            getOffsets = (x, y) => {
                return {
                    xOffset: 0, yOffset: first.y - y
                };
            }
        } else { //have to project to line to find offsets
            let lineVec, yShift = 0;
            if (first.x === 0 && first.y === 0) {
                lineVec = second;
            } else if (second.x === 0 && second.y === 0) {
                lineVec = first;
            } else {
                //get function and b of Line object
                const {function: lineFn, b} = this.createLinearFunctionByTwoPoints(
                    first,
                    second,
                    false
                );
                lineVec = { //guarantee to not be in origin
                    x: 1, y: lineFn(1) - b
                };
                yShift = b;
            }
            getOffsets = (x, y) => {
                const {x: projX, y: projY} = VectorCalculation.calcProjection(lineVec, {
                    x: x, y: y - yShift
                });
                return {
                    xOffset: projX - x, yOffset: projY + yShift - y
                };
            }
        }

        //no matter how offsets are gained, get new positions now
        return points.map(coords => {
            const {xOffset, yOffset} = getOffsets(coords.x, coords.y);
            return {
                x: coords.x + 2 * xOffset, y: coords.y + 2 * yOffset
            }
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds midpoints of line after shortening it a given amount in either or
     * both the direction of its first or second point.
     *
     * @param fromCoords {Object} - coordinates of first line midpoint
     * @param toCoords {Object} - coordinates of second line midpoint
     * @param fromDist {Number} - distance to shorten line from first point on
     * @param toDist {Number} - distance to shorten line from second point on
     * @param directionCheck {Boolean} - if true, return null if shortening
     * leads to a invalid line in the opposite direction.
     * @returns {Array|null} - new midpoints or null if shortening fails/leads
     * to invalid line and directionCheck is set
     */
    static shortenLine(fromCoords, toCoords, fromDist, toDist, directionCheck = false) {
        const lineMov = PointCalculation.createMovementBetweenTwoPoints(fromCoords, toCoords);
        const midFrom = fromDist > 0 ? lineMov.forward(fromDist) : fromCoords;
        const midTo = toDist > 0 ? lineMov.backward(toDist, toCoords) : toCoords;

        //check if midpoints are sane
        if (directionCheck) {
            const fromToVec = VectorCalculation.vectorizeLine(fromCoords, toCoords);
            const midVec = VectorCalculation.vectorizeLine(midFrom, midTo);
            if (!VectorCalculation.checkTwoVectorsPointSameDirection(fromToVec, midVec)) {
                return null;
            }
        }

        return [midFrom, midTo];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the slope and y intersection of a line defined by angle and point.
     *
     * @param x {Number} - x coordinate
     * @param y {Number} - y coordinate
     * @param alpha {Number} - angle (rad)
     * @returns {Object} - slope and y intersection
     */
    static getLineFromPointAngle(x, y, alpha) {
        return {
            slope: Math.tan(alpha), y0: y - Math.tan(alpha) * x
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds normals of a line, than normalize those.
     *
     * @param p1 {Object} - first point of the line
     * @param p2 {Object} - second point of the line
     * @returns {Array} - the two unit normals (normalized normals) of the line
     */
    static findUnitNormals(p1, p2) {
        const normals = this.findNormals(p1, p2);
        return normals.map(normal => {
            return VectorCalculation.normalize(normal);
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds normals for a given line.
     *
     * @param p1 {Object} - first point of the line
     * @param p2 {Object} - second point of the line
     * @returns {Array} - the two normals of the line
     */
    static findNormals(p1, p2) {
        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;
        return [
            {
                x: -dy, y: dx
            }, {
                x: dy, y: -dx
            }
        ];
    }
}

/* src/GeometryCalculation/PointCalculation.js */
/**
 * Class (for namespace purposes) containing static helper functions for
 * geometrically motivated calculations with respect to points.
 */
class PointCalculation {
    /**
     * Rotates a single point around an origin point by some given angle.
     *
     * @param point {Object}- the point to rotate
     * @param origin {Object} - the point to rotate around
     * @param angle {Number} - angle by which to rotate (clockwise)
     * @param isRadian {Boolean} - whether angle is given in radians or
     * degrees (will always convert to radians)
     * @returns {Object} - rotated point
     */
    static rotatePointAroundAnother(point, origin, angle, isRadian) {
        const radian = isRadian ? angle : AngleCalculation.degreeToRadian(angle);
        const sin = Math.sin(radian);
        const cos = Math.cos(radian);
        return this.rotatePointAroundAnotherSinCosKnown(point, origin, sin, cos);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the point in an array with minimum distance to a given point.
     *
     * @param givenPoint {Object} - x- and y-coordinates of point
     * @param points {Array} - coordinates of points to find closest from
     * @returns {Object} - id of the closest point in the array to the
     * given point and the corresponding point (keys: "id" and "point").
     * If given array is empty returns undefined for both
     */
    static getClosestPoint(givenPoint, points) {
        const closest = {
            id: undefined, dist: Infinity, point: undefined
        };
        points.forEach((point, idx) => {
            const dist = VectorCalculation.getDist2d(givenPoint, point);
            if (dist < closest.dist) {
                closest.id = idx;
                closest.dist = dist;
                closest.point = point;
            }
        });
        return {
            id: closest.id, point: closest.point
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates given points around a given rotation point.
     *
     * @param points {Array} - points to rotate
     * @param angle {Number} - angle by which to rotate (clockwise)
     * @param rotationPoint {Object} - point to rotate around
     * @param isDeg {Boolean} - whether angle is given in degree or radians
     * (will always convert to radians)
     * @returns {Array} - new coordinates for points
     */
    static rotatePointsAroundMid(points, angle, rotationPoint, isDeg = false) {
        const radian = isDeg ? AngleCalculation.degreeToRadian(angle) : angle;
        const sin = Math.sin(radian);
        const cos = Math.cos(radian);
        return points.map(point => {
            return (this.rotatePointAroundAnotherSinCosKnown(point, rotationPoint, sin, cos));
        });
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates a single point around an origin point by some given angle.
     * Optimize performance if many points are to be rotated with the same
     * angle, so sin and cos do not have to be constantly computed.
     *
     * @param point {Object}- the point to rotate
     * @param origin {Object} - the point to rotate around
     * @param sin {Number} - sine based on radian of rotation angle
     * @param cos {Number} - cosine based on radian of rotation angle
     */
    static rotatePointAroundAnotherSinCosKnown(point, origin, sin, cos) {
        const rotPoint = Object.assign({}, point);
        rotPoint.x -= origin.x;
        rotPoint.y -= origin.y;

        const newX = rotPoint.x * cos - rotPoint.y * sin;
        const newY = rotPoint.y * cos + rotPoint.x * sin;

        rotPoint.x = newX + origin.x;
        rotPoint.y = newY + origin.y;
        return rotPoint;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection, checks whether point hits circle.
     *
     * @param point {Object} - point to check
     * @param center {Object} - center point of circle
     * @param rad {Number} - radius of circle
     * @returns {Boolean} - whether hit is found or not
     */
    static checkPointInCircle(point, center, rad) {
        const d = Math.sqrt((point.x - center.x) ** 2 + (point.y - center.y) ** 2);
        return d ** 2 < rad ** 2;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the relative position of one point to another.
     *
     * @param fixedPoint {Object} - x- and y-coordinates of fixed point
     * @param relativePoint {Object} - x- and y-coordinates of relative point.
     * This returned position is the relative position of this point to the
     * other (so if result is below that means this point is below the first
     * one)
     * @returns {RelativePosition} - relative position of the points
     */
    static getRelativePositionPointPoint(fixedPoint, relativePoint) {
        let position = RelativePosition.same;
        if (fixedPoint.x < relativePoint.x) {
            position |= RelativePosition.right;
        } else if (fixedPoint.x > relativePoint.x) {
            position |= RelativePosition.left;
        }
        if (fixedPoint.y < relativePoint.y) {
            position |= RelativePosition.above;
        } else if (fixedPoint.y > relativePoint.y) {
            position |= RelativePosition.below;
        }
        return position;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the side of a given point offering the most free space based on the
     * coordinates of relevant neighboring points. This is done by extending
     * infinite lines to each side and then finding the side on which these
     * lines have the smallest angle to any line spanned between the point and
     * a neighboring point.
     *
     * @param center {Object} - x- and y-coordinates of the point to check
     * @param neighbors {Array} - x- and y-coordinates of neighboring points
     * @param permitUpDown {Boolean} - whether direction can be 'up' or
     * 'down' (sometimes this should be suppressed for cleaner drawing)
     * @returns {String} - the side with most free space -> 'left', 'right',
     * 'up' or 'down'
     */
    static findSideMostSpace(center, neighbors, permitUpDown = true) {
        if (neighbors.length === 0) {
            return 'right';
        }

        let maxFreeAngle = 0; //find largest smallest angle
        const testDir = (coord, dir) => {
            const dirPoint = Object.assign({}, center);
            if (dir === 1) {
                dirPoint[coord] += 10;
            } else {
                dirPoint[coord] -= 10;
            }
            //calc angles between line defined by dirPoint and line defined by
            //all possible neighbors, then minimize over these vectors
            let possibleAngle = 360;

            neighbors.forEach(point => {
                const angleToNb = AngleCalculation.radianToDegree(VectorCalculation.findAngleBetweenLines(center,
                    dirPoint,
                    center,
                    point
                ));
                if (angleToNb < possibleAngle) {
                    possibleAngle = angleToNb;
                }
            });
            //check if this is the globally smallest angle
            if (possibleAngle > maxFreeAngle) {
                maxFreeAngle = possibleAngle;
                return true;
            }
            return false;
        };

        //can shortcut if only 'left' and 'right' allowed
        if (!permitUpDown) {
            testDir('x', 1, 'right');
            if (Math.round(maxFreeAngle) >= 60) {
                return 'right';
            }
            return 'left';
        }
        //if all directions allowed: need to perform full check
        let bestDirection;
        testDir('x', 1, 'right');
        bestDirection = 'right';
        if (testDir('x', -1, 'left')) {
            bestDirection = 'left';
        }
        if (testDir('y', 1, 'down')) {
            bestDirection = 'down';
        }
        if (testDir('y', -1, 'up')) {
            bestDirection = 'up';
        }
        return bestDirection;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets a point at a position relative to a given point that is a defined
     * distance away. Note that by positions with more than one attribute
     * (e.g aboveLeft) this will return a point with 45 degrees to either
     * axis.
     *
     * @param givenPoint {Object} - x- and y-coordinates of given point
     * @param position {RelativePosition} - position to get the point for
     * @param distance {Number} - distance of returned point to givenPoint
     * @returns {Object} - x- and y-coordinates of the new point
     */
    static getPointByRelativePosition(givenPoint, position, distance) {
        const vec = {x: 0, y: 0};
        if (position & RelativePosition.above) {
            vec.y = 1
        }
        if (position & RelativePosition.below) {
            vec.y = -1
        }
        if (position & RelativePosition.right) {
            vec.x = 1
        }
        if (position & RelativePosition.left) {
            vec.x = -1
        }
        return VectorCalculation.vectorAdd(givenPoint,
            VectorCalculation.scalarMult(VectorCalculation.normalize(vec), distance)
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Moves a single point a specified number of units (can be negative)
     * towards another point.
     *
     * @param point {Object} - the point to move
     * @param to {Object} - the point in which direction to move
     * @param units {Number} - how many units to move
     * @returns {Object} - x- and y-coordinates of moved point
     */
    static movePointTowardsAnother(point, to, units) {
        const vec = VectorCalculation.scalarMult(VectorCalculation.normalize(VectorCalculation.vectorizeLine(point,
            to
        )), units);
        return {
            x: vec.x + point.x, y: vec.y + point.y
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Vector based movement along the line between two points. Move forward =
     * move toward (x1, y1). Move backward = move toward (x0, y0). Based on
     * current point (starts at (x0, y0), passing start point overrides this).
     *
     * @param x0 {Number} - x coordinate of current point
     * @param y0 {Number} - y coordinate of current point
     * @param x1 {Number} - x coordinate of other point
     * @param y1 {Number} - y coordinate of other point
     * @returns {Object} - container of forward() and backward() functions
     */
    static createMovementBetweenTwoPoints({x: x0, y: y0}, {x: x1, y: y1}) {
        const lineVec = VectorCalculation.normalize({
            x: x1 - x0, y: y1 - y0
        });
        let curPoint = {
            x: x0, y: y0
        };
        const setStartPoint = (startPoint) => {
            if (startPoint) {
                curPoint = {
                    x: startPoint.x, y: startPoint.y
                };
            }
        };
        const moveForward = (distance, startPoint) => {
            if (distance === undefined) {
                distance = 1;
            }
            setStartPoint(startPoint);
            curPoint.x += distance * lineVec.x;
            curPoint.y += distance * lineVec.y;
            return Object.assign({}, curPoint);
        };
        const moveBackward = (distance, startPoint) => {
            if (distance === undefined) {
                distance = 1;
            }
            setStartPoint(startPoint);
            curPoint.x -= distance * lineVec.x;
            curPoint.y -= distance * lineVec.y;
            return Object.assign({}, curPoint);
        };
        return {
            forward: moveForward, backward: moveBackward
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Andrew's algorithm to find the convex hull of a number of given points.
     *
     * @param points {Array} - the points to create a convex hull around
     * @returns {Array} - points on the convex hull
     */
    static findConvexHull(points) {
        const len = points.length;
        if (len < 3) return points;
        const cross = (a, b, o) => {
            return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
        };
        //sort by x-, then y-coordinate
        points.sort((a, b) => {
            return a.x === b.x ? a.y - b.y : a.x - b.x;
        });
        //build lower and upper parts of convex hull
        const lower = [];
        for (let i = 0; i < len; ++i) {
            while (lower.length >= 2 &&
            cross(lower[lower.length - 2], lower[lower.length - 1], points[i]) <= 0) {
                lower.pop();
            }
            lower.push(points[i]);
        }
        const upper = [];
        for (let i = len - 1; i >= 0; --i) {
            while (upper.length >= 2 &&
            cross(upper[upper.length - 2], upper[upper.length - 1], points[i]) <= 0) {
                upper.pop();
            }
            upper.push(points[i]);
        }

        upper.pop();
        lower.pop();
        return lower.concat(upper);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets distance between two points by given x- and y-distances.
     *
     * @param xDist {Number} - distance between points in x-direction
     * @param yDist {Number} - distance between points in y-direction
     * @returns {Number} - actual distance between points
     */
    static getDist2dByDists(xDist, yDist) {
        return Math.sqrt(xDist ** 2 + yDist ** 2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the point in the middle of two given points.
     *
     * @param p1 {Object} - first point
     * @param p2 {Object} - second point
     * @returns {Object} - the midpoint
     */
    static findEdgeMidpoint(p1, p2) {
        return {
            x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the geometric center of given 2D-points
     *
     * @param points {Array} - array containing x and y coordinates as
     * objects.
     * @returns {Object} - center coordinates (x and y)
     */
    static findGeometricCenter(points) {
        const pointCount = points.length;
        if (pointCount === 0) return null;

        const center = {
            x: 0, y: 0
        };

        for (const point of points) {
            center.x += point.x;
            center.y += point.y;
        }

        center.x = center.x / pointCount;
        center.y = center.y / pointCount;

        return center;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Translates global (cursor) position to a local position inside some DOM
     * element (SVG draw area, canvas...)
     *
     * @param x {Number} - x-coordinate of current position (clientX)
     * @param y {Number} - y-coordinate of current position (clientY)
     * @param xMin {Number} - start of element, x-coordinate
     * @param yMin {Number} - start of element, y-coordinate
     * @returns {Object} - coordinates of position in element's coordinate
     * system
     */
    static getCoordinatesInElement({x, y}, {x: xMin, y: yMin}) {
        return {
            x: x - xMin, y: y - yMin
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if two coordinate objects do not differ by more than a given
     * tolerance (checking both x- and y-parameter).
     *
     * @param coord1 {Object} - first coordinates to compare
     * @param coord2 {Object} - second coordinates to compare
     * @param tolerance {Number} - allowed tolerance values may differ by
     * @returns {Boolean} - whether the two values are within the specified
     * tolerance
     */
    static coordsAlmostEqual(coord1, coord2, tolerance = 0.000001) {
        return (Helpers.isAlmostEqual(coord1.x, coord2.x, tolerance) &&
            Helpers.isAlmostEqual(coord1.y, coord2.y, tolerance));
    }
}

/* src/GeometryCalculation/PolygonCalculation.js */
/**
 * Class (for namespace purposes) containing static helper functions for
 * geometrically motivated calculations with respect to polygons.
 */
class PolygonCalculation {
    /**
     * Creates the vertices of a rectangle based on its starts and ends (x and
     * y). Primary use is to convert a bounding box (e.g. through getBBox())
     * into a form that can be used for collision / drawing.
     *
     * @param startX {Number} - x-coordinate where rectangle starts
     * @param endX {Number} - x-coordinate where rectangle ends
     * @param startY {Number} - y-coordinate where rectangle starts
     * @param endY {Number} - y-coordinate where rectangle ends
     * @returns {Array} - the four vertices of the rectangle
     */
    static createRectByBoundaries(startX, endX, startY, endY) {
        const rectPoints = [];
        rectPoints.push({
            x: startX, y: startY
        });
        rectPoints.push({
            x: endX, y: startY
        });
        rectPoints.push({
            x: endX, y: endY
        });
        rectPoints.push({
            x: startX, y: endY
        });
        return rectPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether point hits a path of
     * edges, defined by the points along this path.
     *
     * @param pathPoints {Array} - points along a path of edges
     * @param pathWidth {Number} - width of edges along the path
     * @param point {Object} - point to check
     * @returns {Boolean} - whether hit is found or not
     */
    static checkCollisionPointPath(pathPoints, pathWidth, point) {
        const len = pathPoints.length;
        if (len <= 1) return false;
        for (let i = 0; i < len; ++i) {
            if (i === len - 1) return false;
            const first = pathPoints[i];
            const second = pathPoints[i + 1];
            const normals = LineCalculation.findUnitNormals(first, second);
            const rect = this.createRectFromLine(first, second, normals, pathWidth);
            if (this.checkCollisionPolygonPoint(point, rect)) return true;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether a point lies within a
     * polygon (defined by its edges).
     *
     * @param point {Object} - point to check
     * @param polyEdges {Array} - edges of the polygon
     * @returns {Boolean} - whether hit is found or not
     */
    static checkCollisionPolygonPoint(point, polyEdges) {
        //check point inside polygon
        const windingNr = this.calcWindingNumber(point, polyEdges);
        return windingNr !== 0;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether two polygons (defined by
     * their vertices) hit each other, either by collision of their edges or
     * when one polygon lies completely within the other.
     *
     * @param poly1Vertices {Array} - vertices of first polygon
     * @param poly2Vertices {Array} - vertices of second polygon
     * @returns {Boolean} - whether hit is found or not
     */
    static checkCollisionTwoPolygons(poly1Vertices, poly2Vertices) {
        const poly1Len = poly1Vertices.length;
        const poly2Len = poly2Vertices.length;
        //sanity check
        if (poly1Len === 0 || poly2Len === 0) {
            return false;
        }
        //check if either polygon is COMPLETELY WITHIN the other (enough to
        //just check one point)
        const vertexInFirst = poly1Vertices[0];
        const vertexInSecond = poly2Vertices[0];

        //check if one vertex from first polygon is in the other polygon
        let windingNrFirst = 0;
        if (poly2Len > 2) {
            windingNrFirst = this.calcWindingNumber(vertexInFirst, poly2Vertices);
        }
        //check if one vertex from second polygon is in the first polygon
        let windingNrSecond = 0;
        if (poly1Len > 2) {
            windingNrSecond = this.calcWindingNumber(vertexInSecond, poly1Vertices);
        }

        if (windingNrFirst !== 0 || windingNrSecond !== 0) {
            return true;
        }

        //check intersection of edges (if possible)
        if (poly1Len === 1 && poly2Len === 1) {
            return vertexInFirst.x === vertexInSecond.x && vertexInFirst.y === vertexInSecond.y;
        }

        if (this.polygonCollision(poly1Vertices,
            poly1Len,
            poly2Vertices,
            poly2Len,
            vertexInFirst,
            vertexInSecond
        )) {
            return true;
        }
        return false;
    }

    static polygonCollision(poly1Vertices,
        poly1Len,
        poly2Vertices,
        poly2Len,
        vertexInFirst,
        vertexInSecond
    ) {
        //function for next index
        const getNextIdx = (idx, arrLen) => {
            return (idx === arrLen - 1) ? 0 : idx + 1;
        };
        if (poly1Len === 1) { //poly2Len > 1
            for (let poly2FirstIdx = 0; poly2FirstIdx < poly2Len; ++poly2FirstIdx) {
                const poly2NextIdx = getNextIdx(poly2FirstIdx, poly2Len);
                const poly2First = poly2Vertices[poly2FirstIdx];
                const poly2Second = poly2Vertices[poly2NextIdx];
                if (LineCalculation.checkPointOnLineSegment(poly2First,
                    poly2Second,
                    vertexInFirst
                )) {
                    return true;
                }
            }
        } else if (poly2Len === 1) { //poly1Len > 1
            for (let poly1FirstIdx = 0; poly1FirstIdx < poly1Len; ++poly1FirstIdx) {
                const poly1NextIdx = getNextIdx(poly1FirstIdx, poly1Len);
                const poly1First = poly1Vertices[poly1FirstIdx];
                const poly1Second = poly1Vertices[poly1NextIdx];
                if (LineCalculation.checkPointOnLineSegment(poly1First,
                    poly1Second,
                    vertexInSecond
                )) {
                    return true;
                }
            }
        } else { //both length > 1
            for (let poly1FirstIdx = 0; poly1FirstIdx < poly1Len; ++poly1FirstIdx) {
                const poly1SecondIdx = getNextIdx(poly1FirstIdx, poly1Len);
                const poly1First = poly1Vertices[poly1FirstIdx];
                const poly1Second = poly1Vertices[poly1SecondIdx];

                for (let poly2FirstIdx = 0; poly2FirstIdx < poly2Len; ++poly2FirstIdx) {
                    const poly2SecondIdx = getNextIdx(poly2FirstIdx, poly2Len);
                    const poly2First = poly2Vertices[poly2FirstIdx];
                    const poly2Second = poly2Vertices[poly2SecondIdx];
                    if (LineCalculation.checkTwoLineSegmentsInteract(poly1First,
                        poly1Second,
                        poly2First,
                        poly2Second
                    )) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether a line segment (given by
     * its endpoints) hits a rectangle (intersection or fully inside).
     *
     * @param l1 {Object} - first line point
     * @param l2 {Object} - second line point
     * @param rectPoints {Array} - coordinates of rectangle vertices
     */
    static checkIntersectionLineRectangle(l1, l2, rectPoints) {
        const len = rectPoints.length;
        for (let i = 0; i < len; ++i) {
            const r1 = rectPoints[i];
            const r2 = i === len - 1 ? rectPoints[0] : rectPoints[i + 1];
            if (LineCalculation.checkTwoLineSegmentsInteract(l1, l2, r1, r2)) {
                return true;
            }
        }
        return this.calcWindingNumber(l2, rectPoints) !== 0;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates the vertices of a polygon based on a given line and the width of
     * such a line.
     *
     * @param from {Object} - first point defining the line
     * @param to {Object} - second point defining the line
     * @param normals {Array} - the two normals of the line
     * @param sideOffset {Number} - width of the line
     * @returns {Array} - the four vertices of the rectangle
     */
    static createRectFromLine(from, to, normals, sideOffset) {
        const firstNormal = normals[0];
        const secondNormal = normals[1];
        const firstSideX = firstNormal.x * sideOffset;
        const firstSideY = firstNormal.y * sideOffset;
        const secondSideX = secondNormal.x * sideOffset;
        const secondSideY = secondNormal.y * sideOffset;

        const p1 = {
            x: from.x + firstSideX, y: from.y + firstSideY
        };
        const p2 = {
            x: from.x + secondSideX, y: from.y + secondSideY
        };
        const p3 = {
            x: to.x + secondSideX, y: to.y + secondSideY
        };
        const p4 = {
            x: to.x + firstSideX, y: to.y + firstSideY
        };
        return [p1, p2, p3, p4];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates bounding rectangle coordinates.
     *
     * @param height {Number} - rectangle height
     * @param width {Number} - rectangle width
     * @param coords {Number} - middle coordinate of rectangle
     * @returns {Object} - bounding rectangle coordinates
     */
    static boundingRectangle({height, width, coords}) {
        return {
            xMin: coords.x - width / 2,
            xMax: coords.x + width / 2,
            yMin: coords.y - height / 2,
            yMax: coords.y + height / 2
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the edge of a rectangle by position.
     *
     * @param xMax {Number} - max x-coordinate of the rectangle
     * @param xMin {Number} - min x-coordinate of the rectangle
     * @param yMax {Number} - max y-coordinate of the rectangle
     * @param yMin {Number} - min y-coordinate of the rectangle
     * @param position {RelativePosition} - position of the edge. E.g.
     * above means top edge. Note that this should only hold one position
     * so aboveLeft will get invalid results.
     * @returns {Array} - x- and y-coordinates of the corner points defining
     * the edge or null if position is e.g. inside/same.
     */
    static getRectangleEdgeByPosition({xMax, xMin, yMax, yMin}, position) {
        switch (position) {
            case RelativePosition.below:
                return [
                    {
                        x: xMin, y: yMin
                    }, {
                        x: xMax, y: yMin
                    }
                ];
            case RelativePosition.above:
                return [
                    {
                        x: xMin, y: yMax
                    }, {
                        x: xMax, y: yMax
                    }
                ];
            case RelativePosition.left:
                return [
                    {
                        x: xMin, y: yMin
                    }, {
                        x: xMin, y: yMax
                    }
                ];
            case RelativePosition.right:
                return [
                    {
                        x: xMax, y: yMin
                    }, {
                        x: xMax, y: yMax
                    }
                ];
            default:
                return null;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the corner of a rectangle by position.
     *
     * @param xMax {Number} - max x-coordinate of the rectangle
     * @param xMin {Number} - min x-coordinate of the rectangle
     * @param yMax {Number} - max y-coordinate of the rectangle
     * @param yMin {Number} - min y-coordinate of the rectangle
     * @param position {RelativePosition} - position of the corner. E.g.
     * aboveLeft means top left corner
     * @returns {Object} - x- and y-coordinates of the corner or null if
     * position is e.g. only above
     */
    static getRectangleCornerByPosition({xMax, xMin, yMax, yMin}, position) {
        const corner = {
            x: undefined, y: undefined
        };

        if (position & RelativePosition.below) {
            corner.y = yMin
        } else if (position & RelativePosition.above) {
            corner.y = yMax
        } else {
            return null;
        }

        if (position & RelativePosition.left) {
            corner.x = xMin
        } else if (position & RelativePosition.right) {
            corner.x = xMax
        } else {
            return null;
        }

        return corner;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Converts a axis aligned rectangle given by its mid, height and width
     * to maxes
     *
     * @param mid {Object} - x- and y-coordinates of the rectangle mid
     * @param height {Number} - height of the rectangle
     * @param width {Number} - width of the rectangle
     * @returns {Object} - maxes (xMin, xMax, yMin, yMax) of
     * the rectangle
     */
    static convertRectangleMidDimensionsToMaxes(mid, {height, width}) {
        return {
            xMin: mid.x - width / 2,
            xMax: mid.x + width / 2,
            yMin: mid.y - height / 2,
            yMax: mid.y + height / 2
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Part of collision detection. Finds out whether a polygon (defined by its
     * edges) and a circle interact in any way (either if an edge of the
     * polygon hits the circle, or when the circle lies completely within the
     * polygon.
     *
     * @param circle {Object} - circle (by coordinates and radius)
     * @param polyEdges {Array} - edges of the polygon
     * @returns {Boolean} - whether hit is found or not
     */
    static checkCollisionPolygonCircle(circle, polyEdges) {
        //check circle center inside polygon
        const windingNr = this.calcWindingNumber(circle, polyEdges);
        if (windingNr !== 0) {
            return true;
        }

        //check intersection of edges
        for (let firstIdx = 0, len = polyEdges.length; firstIdx < len; ++firstIdx) {
            const secondIdx = (firstIdx === polyEdges.length - 1) ? 0 : firstIdx + 1;
            const first = polyEdges[firstIdx];
            const second = polyEdges[secondIdx];
            if (LineCalculation.checkIntersectionLineCircle(first, second, circle)) {
                return true;
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out whether a point lies within a polygon (defined by its edges) by
     * calculating the point's Winding Number in respect to the polygon. If the
     * Winding Number is equal 0, the point is outside the polygon, otherwise,
     * inside it.
     *
     * @param point {Object} - point to calculate Winding Number for
     * @param polyEdges {Array} - edges of the polygon
     * @returns {Number} - winding number of the point in respect to the
     * polygon -> equals 0 if point lies outside of polygon
     */
    static calcWindingNumber(point, polyEdges) {
        let wn = 0;

        for (let firstIdx = 0, len = polyEdges.length; firstIdx < len; ++firstIdx) {
            const secondIdx = (firstIdx === polyEdges.length - 1) ? 0 : firstIdx + 1;
            const first = polyEdges[firstIdx];
            const second = polyEdges[secondIdx];

            if (second.y <= point.y) {
                if (first.y > point.y && !LineCalculation.isLeft(second, first, point)) {
                    wn++;
                }
            } else {
                if (first.y <= point.y && LineCalculation.isLeft(second, first, point)) {
                    wn--;
                }
            }
        }

        return wn;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the closest point on the outer lines of a axis aligned rectangle
     * to a given point.
     *
     * @param givenPoint {Object} - x- and y-coordinates of given point
     * @param xMax {Number} - max x-coordinate of the rectangle
     * @param xMin {Number} - min x-coordinate of the rectangle
     * @param yMax {Number} - max y-coordinate of the rectangle
     * @param yMin {Number} - min y-coordinate of the rectangle
     * @returns {Object} - key "point" holds the calculated point, key "dist"
     * the distance to that point key "isInside" is true, if the point is
     * inside (on edge is outside) the rectangle and key "relativePosition"
     * with the relative position of the rectangle
     */
    static getClosestPointOnRectangle(givenPoint, {xMax, xMin, yMax, yMin}) {
        let position = RelativePosition.inside;
        if (givenPoint.y <= yMin) {
            position |= RelativePosition.below;
        } else if (givenPoint.y >= yMax) {
            position |= RelativePosition.above;
        }
        if (givenPoint.x <= xMin) {
            position |= RelativePosition.left;
        } else if (givenPoint.x >= xMax) {
            position |= RelativePosition.right;
        }

        if (position === RelativePosition.inside) {
            //given point is inside. Find closest edge
            let edgeCoord, isX;
            let dist = Infinity;
            [xMin, xMax, yMin, yMax].forEach((val, idx) => {
                const curIsX = idx < 2;
                const curDist = Math.abs(val - (curIsX ? givenPoint.x : givenPoint.y));
                if (curDist < dist) {
                    dist = curDist;
                    edgeCoord = val;
                    isX = curIsX;
                }
            });
            const point = isX ? {x: edgeCoord, y: givenPoint.y} : {x: givenPoint.x, y: edgeCoord};
            return {
                point: point, dist: dist, isInside: true, relativePosition: position
            }
        }

        const point = {};

        if (position & RelativePosition.below) {
            point.y = yMin;
        } else if (position & RelativePosition.above) {
            point.y = yMax;
        } else {
            point.y = givenPoint.y;
        }

        if (position & RelativePosition.left) {
            point.x = xMin;
        } else if (position & RelativePosition.right) {
            point.x = xMax;
        } else {
            point.x = givenPoint.x;
        }

        return {
            point: point,
            dist: VectorCalculation.getDist2d(point, givenPoint),
            isInside: false,
            relativePosition: position
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets the relative position of one point to a axis aligned rectangle.
     * The rectangle has to be defined by its maxes.
     *
     * @param givenPoint {Object} - x- and y-coordinates of given point
     * @param xMax {Number} - max x-coordinate of the rectangle
     * @param xMin {Number} - min x-coordinate of the rectangle
     * @param yMax {Number} - max y-coordinate of the rectangle
     * @param yMin {Number} - min y-coordinate of the rectangle
     * @param onEdgeIsInside {Boolean} - whether the point should be marked
     * as inside the rectangle if it is exactly on one edge
     * @returns {RelativePosition} - relative position of the point to the
     * rectangle
     */
    static getRelativePositionPointRectangle(givenPoint,
        {xMax, xMin, yMax, yMin},
        onEdgeIsInside = true
    ) {
        let position = RelativePosition.inside;

        if (onEdgeIsInside) {
            if (givenPoint.y < yMin) {
                position |= RelativePosition.below;
            } else if (givenPoint.y > yMax) {
                position |= RelativePosition.above;
            }
            if (givenPoint.x < xMin) {
                position |= RelativePosition.left;
            } else if (givenPoint.x > xMax) {
                position |= RelativePosition.right;
            }
        } else {
            if (givenPoint.y <= yMin) {
                position |= RelativePosition.below;
            } else if (givenPoint.y >= yMax) {
                position |= RelativePosition.above;
            }
            if (givenPoint.x <= xMin) {
                position |= RelativePosition.left;
            } else if (givenPoint.x >= xMax) {
                position |= RelativePosition.right;
            }
        }
        return position;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Rotates a axis aligned rectangle around a point. The rectangle stays
     * axis aligned in this process. Rotate the rectangle in such a way, that
     * 1. the midpoint is rotated by a given angle.
     * 2. the shortest distance from the rectangle edges to the given point
     *    remains the same.
     *
     * Further differentiate two cases: The point to rotate about should be
     * inside the final rectangle or not.
     *
     * @param rectangleMid {Object} - x- and y-coordinates of the mid of the
     * rectangle to rotated
     * @param rectangleMaxes {Object} - xMin, xMax, yMin and yMax value
     * of the rectangle
     * @param origin {Object} - x- and y-coordinates of the point to rotate
     * around
     * @param angle {Number} - angle by which to rotate (clockwise)
     * @param dist {Number} - distance of the rectangle to origin
     * @param isInside {Boolean} - whether origin should be inside of the
     * final rectangle
     * @param isRadian {Boolean} - whether angle is given in radians (true) or
     * degrees (false)
     * @returns {Object} - x- and y-coordinates of the rotated rectangle mid
     */
    static rotateRectangleAroundPoint(rectangleMid,
        rectangleMaxes,
        origin,
        angle,
        dist,
        isInside,
        isRadian = false
    ) {
        //The basic idea behind this algorithm is as follows.
        //
        //The algorithm can be split into two different preconditions. The
        //first one is if the point to rotate around should be outside of the
        //rectangle and the second one is if the point should be inside. This
        //is defined by param isInside.
        //
        //First let's have a look at the algorithm when isInside is false.
        //
        //First rotate the the mid of the rectangle by the given angle.
        //Then move that rotated point on the line defined by the rotated point
        //and origin (the point rotated around), so that the rectangle
        //has just one intersection with the circle defined by origin and
        //the defined distance (dist).
        //
        //To get the vector to move the rotated point by for this to happen
        //we need to look at two cases. One case is when the final intersection
        //point of the rectangle and the circle lies at one of the edge of the
        //rectangle and the other one is when the intersection is a corner of
        //the rectangle.
        //
        //First case (intersection on edge):
        //To detect this case we need to define the possible intersection
        //points which lie on the circle and are directly above, below,
        //left or right of the circle mid. Then with help of the relative
        //position of the rotated mid to the circle mid we can exclude
        //at least two of the possible intersection because if the relative
        //position is e.g. above-left, then it is impossible that the
        //intersection is below or right of the circle mid.
        //After that we define a line parallel to the line defined by the
        //circle mid and the rotated mid on which the possible intersection
        //lies on (for each of the two intersections separately).
        //Now if the parallel line through a possible intersection at relative
        //position "x" has a intersection with the edge of the rectangle that
        //has a relative position to the rectangle mid that is opposite to "x",
        //then this case can be applied and we have to move the rectangle mid
        //by the vector defined by the direction and distance of that possible
        //intersection to the edge intersection.
        //
        //Second case (intersection on corner):
        //If the first case is not applied than this has to. So no further
        //detection needed.
        //First get the corner of the rectangle which lies on the same relative
        //position of the rectangle mid as the circle mid has to the rectangle
        //mid, because if the circle mid is e.g. below-right of the rectangle
        //mid then the rectangle corner that will intersect with the circle at
        //final position is the bottom right corner (if first case is false).
        //Then find a parallel to the line defined by the rotated point and the
        //circle mid where the found corner lies on. Now find the intersection
        //with that parallel line and the circle that is closest to the rotated
        //point. Finally move the rectangle by the vector defined by the
        //direction and distance from the corner to that parallel-circle
        //intersection.
        //Note that there will always be a parallel-circle intersection
        //because if there would be none, then the first case would be true
        //and we would not even get to this point in the algorithm.
        //
        //
        //Now let's have a look at the the algorithm when isInside is true.
        //
        //The goal here is to position the final rectangle in a way, that the
        //distance from origin to the closest edge of the rectangle equals the
        //given dist parameter.
        //Here we have a simple approach where the rectangle just moves in a
        //rectangular shape around the origin while it rotates. Note that this
        //might not be the best solution from a user perspective but it is
        //sufficient enough because this case barely occurs. A better solution
        //would be to have the rectangle move in a ellipse shape around the
        //mid. So if you have the time feel free to make an upgrade here.
        //
        //Because movement occurs only in a rectangular shape the intersection
        //point of the final rectangle and the circle defined by origin and
        //dist is either directly below, above, right or left of origin.
        //And we can reduce that further down to two possible final
        //intersections. Those are the opposite of the relative position of
        //the rotated mid to the origin because the origin is inside the
        //rectangle.
        //To find this intersection points we can use the exact same algorithm
        //as for the first case of the first part of the algorithm
        //(isInside = false) only use other possible intersections.
        //This should always yield two possible final intersections of the
        //rectangle and the circle. For each one evaluate the distance of the
        //final rectangle mid to the origin and pick the one which is closest.

        const {xMax, xMin, yMax, yMin} = rectangleMaxes;
        const width = xMax - xMin;
        const height = yMax - yMin;
        //get rotated point that defines (together with origin) a line
        //on which new midpoint lies
        const rotatedMid = PointCalculation.rotatePointAroundAnother(rectangleMid,
            origin,
            angle,
            isRadian
        );
        if (width === 0 || height === 0) return rotatedMid;

        //those are just plain rotated and not the final
        const rotatedMaxes = this.convertRectangleMidDimensionsToMaxes(rotatedMid, {height, width});
        //get relative position to origin
        let positionRotatedMid = PointCalculation.getRelativePositionPointPoint(origin, rotatedMid);
        //special case 1
        if (positionRotatedMid === RelativePosition.same) {
            return rotatedMid;
        }

        //special case 2
        //It does not matter here if left or right / above or below because it
        //would get the same final results.
        if (positionRotatedMid === RelativePosition.above || positionRotatedMid ===
            RelativePosition.below) {
            positionRotatedMid |= RelativePosition.left
        } else if (positionRotatedMid === RelativePosition.left || positionRotatedMid ===
            RelativePosition.right) {
            positionRotatedMid |= RelativePosition.above
        }

        //first check if the final rectangle has a intersection with the circle
        //defined by origin and distance at a edge instead of a corner.
        const checkEdgeIntersects = (posPosition, recEdgePosition) => {
            //get the possible intersection point (directly above, below
            //right or left of the circle mid
            const circleEdgePoint = PointCalculation.getPointByRelativePosition(origin,
                posPosition,
                dist
            );
            //line parallel to line defined by origin and the rotated rectangle
            //mid that goes through circleEdgePoint
            const [p1, p2] = VectorCalculation.findParallelLineByDistVec(origin,
                rotatedMid,
                VectorCalculation.findPerpVecLineToPoint(origin, rotatedMid, circleEdgePoint)
            );
            //corners of the rectangle that define a line by position relative to
            //rotatedMid
            const [re1, re2] = PolygonCalculation.getRectangleEdgeByPosition(rotatedMaxes,
                recEdgePosition
            );
            //intersection of previous defined lines (parallel and line
            //through corners)
            const intersection = LineCalculation.findIntersectionTwoLines(LineCalculation.createLinearFunctionByTwoPoints(p1,
                p2
            ), LineCalculation.createLinearFunctionByTwoPoints(re1, re2));
            //relative position of previous intersection relative to the
            //rotated rectangle.
            const intersectionPos = PolygonCalculation.getRelativePositionPointRectangle(intersection,
                rotatedMaxes
            );
            //if this is true than the intersection is between the previously
            //defined corners and tho the final rectangle will have an
            //intersection with the circle at an edge instead of a corner.
            //RelativePosition.inside is used to mitigate rounding errors
            if (intersectionPos === recEdgePosition || intersectionPos ===
                RelativePosition.inside) {
                //move the rotated mid by that direction and distance so
                //that the edge of rectangle (defined by re1/re2) will
                //intersect with the circle at circleEdgePoint and
                //return the final rectangle mid
                const moveVec = VectorCalculation
                    .vectorSubstract(circleEdgePoint, intersection);
                return VectorCalculation.vectorAdd(rotatedMid, moveVec);
            } else {
                //Intersection is at a corner of the rectangle. Continue
                return null;
            }
        };

        //for when isInside is true
        const possibleMids = [];
        let mindist = Infinity;

        for (const position of [
            RelativePosition.below,
            RelativePosition.above,
            RelativePosition.left,
            RelativePosition.right
        ]) {
            if (!isInside && positionRotatedMid & position) {
                const finalMid = checkEdgeIntersects(position,
                    this.invertRelativePosition(position)
                );
                if (finalMid) return finalMid;
            } else if (isInside && this.invertRelativePosition(positionRotatedMid) & position) {
                const finalMid = checkEdgeIntersects(position, position);
                const finalRectangleMaxes = finalMid ?
                    this.getRelativePositionPointRectangle(origin,
                        this.convertRectangleMidDimensionsToMaxes(finalMid, {height, width})
                    ) : undefined;
                if (finalRectangleMaxes === RelativePosition.inside) {
                    const distToOrigin = VectorCalculation.getDist2d(origin, finalMid);
                    if (distToOrigin < mindist) mindist = distToOrigin;
                    possibleMids.push({
                        point: finalMid, distToOrigin: distToOrigin
                    })
                }
            }
        }

        if (isInside) {
            for (const {point, distToOrigin} of Object.values(possibleMids)) {
                if (distToOrigin === mindist) return point;
            }
            //fallback
            return rotatedMid;
        }

        //corner of rotated rectangle to origin. This corner will eventually
        //be the corner that lies on the defined circle
        const intersectingCorner = this.getRectangleCornerByPosition(rotatedMaxes,
            this.invertRelativePosition(positionRotatedMid)
        );
        //line through intersectingCorner parallel to the line on which the
        //final midpoint should lie
        const [parallelP1, parallelP2] = VectorCalculation.findParallelLineByDistVec(origin,
            rotatedMid,
            VectorCalculation.findPerpVecLineToPoint(origin, rotatedMid, intersectingCorner)
        );
        const parallelLine = LineCalculation.createLinearFunctionByTwoPoints(parallelP1,
            parallelP2
        );
        //find intersection of parallelLine to the circle defined by origin
        //and dist. Use the closest to the rotatedMid.
        //since we tested before if the final intersection of the
        //rectangle and the circle lies on the edge and that was false at
        //this point in code, there will always be two intersection points
        //so there is no need to validate that intersectionPoint is defined
        const intersections = LineCalculation.findCircleLineIntersections(dist,
            origin.x,
            origin.y,
            parallelLine.m,
            parallelLine.b
        );
        const {point: intersectionPoint} = PointCalculation.getClosestPoint(rotatedMid,
            intersections
        );
        //move the rectangle (here: rotatedMid) so that the corner
        //of the rectangle at inverted positionRotatedMid lies
        //on top of the intersectionPoint
        const moveVec = VectorCalculation
            .vectorSubstract(intersectionPoint, intersectingCorner);
        return VectorCalculation.vectorAdd(rotatedMid, moveVec);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Inverts a relative position. Examples of what outcomes to expect:
     * above --> below
     * right --> left
     * belowRight --> aboveLeft
     * inside --> inside (!!SPECIAL CASE!!).
     *
     * @param position {RelativePosition} - position to invert
     * @returns {RelativePosition} - inverted position
     */
    static invertRelativePosition(position) {
        if (position & RelativePosition.below || position & RelativePosition.above) {
            position ^= RelativePosition.below ^ RelativePosition.above;
        }

        if (position & RelativePosition.left || position & RelativePosition.right) {
            position ^= RelativePosition.left ^ RelativePosition.right;
        }

        return position;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the centroid of a convex (!) polygon (can be approximated by convex
     * hull).
     *
     * @param polyVertices {Array} - vertices of the polygon
     * @returns {Object} - centroid coordinates and signed area of the polygon
     */
    static findCenterOfConvexPolygon(polyVertices) {
        const centroid = {
            x: 0, y: 0
        };

        let signedArea = 0;

        let i = 0;
        const addPoint = (p1, p2) => {
            const a = p1.x * p2.y - p2.x * p1.y;
            signedArea += a;
            centroid.x += (p1.x + p2.x) * a;
            centroid.y += (p1.y + p2.y) * a;
        };
        for (const len = polyVertices.length - 1; i < len; ++i) {
            addPoint(polyVertices[i], polyVertices[i + 1]);
        }
        addPoint(polyVertices[i], polyVertices[0]);

        signedArea *= 0.5;
        centroid.x /= (6 * signedArea);
        centroid.y /= (6 * signedArea);

        return {
            centroid: centroid, signedArea: signedArea
        }
    }
}

/* src/GeometryCalculation/SplineInterpolation.js */
class SplineInterpolation {
    static createSplinePath(splinePoints) {
        let started = false, path = '';
        for (let i = 0; i < splinePoints.length; i += 2) {
            const first = splinePoints[i];
            const second = splinePoints[i + 1];
            if (!started) {
                path += ` M ${first} ${second}`;
                started = true;
            } else {
                path += ` L ${first} ${second}`;
            }
        }
        return path;
    }

    /*----------------------------------------------------------------------*/

    static curvePointsToCoords(curvePoints) {
        const coordPoints = [];
        for (let i = 0; i < curvePoints.length; i += 2) {
            coordPoints.push({
                x: curvePoints[i], y: curvePoints[i + 1]
            });
        }
        return coordPoints;
    }

    /*----------------------------------------------------------------------*/

    static getCurvePoints(pts, tension, isClosed, numOfSegments) {

        // use input value if provided, or use a default value
        tension = (typeof tension != 'undefined') ? tension : 0.5;
        isClosed = isClosed ? isClosed : false;
        numOfSegments = numOfSegments ? numOfSegments : 16;

        let _pts = [];
        const res = [];
        let // clone array
            x, y,			// our x,y coords
            t1x, t2x, t1y, t2y,	// tension vectors
            c1, c2, c3, c4,		// cardinal points
            st, t, i;		// steps based on num. of segments

        // clone array so we don't change the original
        //
        _pts = pts.slice(0);

        // The algorithm require a previous and next point to the actual point array.
        // Check if we will draw closed or open curve.
        // If closed, copy end points to beginning and first points to end
        // If open, duplicate first points to befinning, end points to end
        if (isClosed) {
            _pts.unshift(pts[pts.length - 1]);
            _pts.unshift(pts[pts.length - 2]);
            _pts.unshift(pts[pts.length - 1]);
            _pts.unshift(pts[pts.length - 2]);
            _pts.push(pts[0]);
            _pts.push(pts[1]);
        } else {
            _pts.unshift(pts[1]);	//copy 1. point and insert at beginning
            _pts.unshift(pts[0]);
            _pts.push(pts[pts.length - 2]);	//copy last point and append
            _pts.push(pts[pts.length - 1]);
        }

        // ok, lets start..

        // 1. loop goes through point array
        // 2. loop goes through each segment between the 2 pts + 1e point before and after
        for (i = 2; i < (_pts.length - 4); i += 2) {
            for (t = 0; t <= numOfSegments; t++) {

                // calc tension vectors
                t1x = (_pts[i + 2] - _pts[i - 2]) * tension;
                t2x = (_pts[i + 4] - _pts[i]) * tension;

                t1y = (_pts[i + 3] - _pts[i - 1]) * tension;
                t2y = (_pts[i + 5] - _pts[i + 1]) * tension;

                // calc step
                st = t / numOfSegments;

                // calc cardinals
                c1 = 2 * Math.pow(st, 3) - 3 * Math.pow(st, 2) + 1;
                c2 = -(2 * Math.pow(st, 3)) + 3 * Math.pow(st, 2);
                c3 = Math.pow(st, 3) - 2 * Math.pow(st, 2) + st;
                c4 = Math.pow(st, 3) - Math.pow(st, 2);

                // calc x and y cords with common control vectors
                x = c1 * _pts[i] + c2 * _pts[i + 2] + c3 * t1x + c4 * t2x;
                y = c1 * _pts[i + 1] + c2 * _pts[i + 3] + c3 * t1y + c4 * t2y;

                //store points in array
                res.push(x);
                res.push(y);

            }
        }
        return res;
    }
}


/* src/GeometryCalculation/VectorCalculation.js */
/**
 * Class (for namespace purposes) containing static helper functions for
 * geometrically motivated calculations with respect to vectors.
 */
class VectorCalculation {
    /**
     * Calculates length of given vector.
     *
     * @param v1 {Object} - vector to calculate length for
     * @returns {Number} - length of the vector
     */
    static vectorLength(v1) {
        return Math.sqrt(v1.x ** 2 + v1.y ** 2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Subtracts a vector from another.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Object} - new vector
     */
    static vectorSubstract(v1, v2) {
        return {
            x: v1.x - v2.x, y: v1.y - v2.y
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a vector to another.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Object} - new vector
     */
    static vectorAdd(v1, v2) {
        return {
            x: v1.x + v2.x, y: v1.y + v2.y
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Performs scalar multiplication on a given vector.
     *
     * @param v1 {Object} - vector to scalar multiply
     * @param c {Number} - value to multiply by
     * @returns {Object} - new vector
     */
    static scalarMult(v1, c) {
        return {
            x: c * v1.x, y: c * v1.y
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates dot product of two vectors.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Number} - dot product of the two vectors
     */
    static dot(v1, v2) {
        return v1.x * v2.x + v1.y * v2.y;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Normalizes a given vector (to a vector of length 1).
     *
     * @param v {Object} - vector to normalize
     * @returns {Object} - normalized vector
     */
    static normalize(v) {
        const len = Math.sqrt(v.x ** 2 + v.y ** 2);
        return {
            x: v.x / len, y: v.y / len
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out whether two given vectors point into the same direction.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Boolean} - whether the vectors point in the same direction
     */
    static checkTwoVectorsPointSameDirection(v1, v2) {
        const normalized_1 = this.normalize(v1);
        const normalized_2 = this.normalize(v2);
        return Helpers.isAlmostEqual(this.dot(normalized_1, normalized_2), 1);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Creates vector based on line endpoints.
     *
     * @param from {Object} - first line endpoint
     * @param to {Object} - second line endpoint
     * @returns {Object} - line defined as vector
     */
    static vectorizeLine(from, to) {
        return {
            x: to.x - from.x, y: to.y - from.y
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Gets distance between two given vectors.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Number} - distance between the vectors
     */
    static getDist2d(v1, v2) {
        return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds a perpendicular vector from a point on a given line to a
     * given point.
     *
     * @param p1 {Object} - x- and y-coordinates of first point on line
     * @param p2 {Object} - x- and y-coordinates of second point on line
     * @param p0 {Object} - x- and y-coordinates of point to get the vector to
     * @returns {Object} - x- and y-coordinates of perpendicular vector
     */
    static findPerpVecLineToPoint(p1, p2, p0) {
        return this.vectorSubstract(p0, this.findMinDistPointOnLineToPoint(p1, p2, p0))
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds the point on a line with minimal distance to a given point.
     *
     * @param p1 {Object} - x- and y-coordinates of first point on line
     * @param p2 {Object} - x- and y-coordinates of second point on line
     * @param p0 {Object} - x- and y-coordinates of given point
     * @returns {Object} - x- and y-coordinates of point on line
     */
    static findMinDistPointOnLineToPoint(p1, p2, p0) {
        const lineVec = this.normalize(this.vectorizeLine(p1, p2));
        return this.vectorAdd(p1,
            this.scalarMult(lineVec, this.dot(this.vectorSubstract(p0, p1), lineVec))
        )
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines the angle between two given vectors.
     *
     * @param v1 {Object} - first vector
     * @param v2 {Object} - second vector
     * @returns {Number} - angle between the vectors (in degrees)
     */
    static findAngleBetweenTwoVectors(v1, v2) {
        //must be rounded before application of acos, else can become NaN,
        //e.g. acos(-1) is 180 deg, but acos(-1.0000000001) is NaN
        return Math.acos(Helpers.round(this.dot(v1, v2) /
            (this.vectorLength(v1) * this.vectorLength(v2)), 6));
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds line parallel to given line, based on a distance vector between the
     * two lines.
     *
     * @param p1 {Object} - first endpoint of the line
     * @param p2 {Object} - second endpoint of the line
     * @param distVec {Object} - distances between lines (x and y)
     * @returns {Array} - the two endpoints of the second line
     */
    static findParallelLineByDistVec(p1, p2, distVec) {
        return [
            {
                x: p1.x + distVec.x, y: p1.y + distVec.y
            }, {
                x: p2.x + distVec.x, y: p2.y + distVec.y
            }
        ];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines the angle between two lines, defined by their endpoints.
     *
     * @param from_1 {Object} - first endpoint of first line
     * @param to_1 {Object} - second endpoint of first line
     * @param from_2 {Object} - first endpoint of second line
     * @param to_2 {Object} - second endpoint of second line
     * @returns {Number} - angle between the lines (in radians)
     */
    static findAngleBetweenLines(from_1, to_1, from_2, to_2) {
        //get vector representation of lines
        const p1Dir = this.vectorizeLine(from_1, to_1);
        const p2Dir = this.vectorizeLine(from_2, to_2);
        //use vector representation to get angle
        return this.findAngleBetweenTwoVectors(p1Dir, p2Dir);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates the projection of a given point onto a given line (defined by
     * a vector).
     *
     * @param lineVec {Object} - vector defining a line
     * @param p {Object} - point to project onto the line
     * @returns {Object} - projected point
     */
    static calcProjection(lineVec, p) {
        return this.scalarMult(lineVec, this.dot(p, lineVec) / this.dot(lineVec, lineVec));
    }
}

/* src/History/Change.js */
/**
 * Class to log a specific change made to certain aspects of a drawing scene
 * via provided callbacks (to do/undo this change). Callbacks are bound to the
 * apply() and revert() functions of this object.
 */
class Change {
    /**
     * Creates a new Change object.
     */
    constructor() {
        this.apply = () => {
        };
        this.revert = () => {
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Binds function to execute the change to this.apply().
     *
     * @param callbackFn {Function} - callback to execute change
     * @param params {Object} - optional parameter, to be used in provided
     * callbacks.
     */
    bindApply(callbackFn, params = null) {
        if (params) {
            this.apply = () => callbackFn(params);
        } else {
            this.apply = callbackFn;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Binds function to undo the change to this.revert().
     *
     * @param callbackFn {Function} - callback to undo change
     * @param params {Object} - optional parameter, to be used in provided
     * callbacks.
     */
    bindRevert(callbackFn, params = null) {
        if (params) {
            this.revert = () => callbackFn(params);
        } else {
            this.revert = callbackFn;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Shorthand to bind function to both this.apply() and this.revert().
     *
     * @param callbackFn {Function} - callback to both execute and undo change
     */
    bindApplyRevert(callbackFn) {
        this.bindApply(callbackFn);
        this.bindRevert(callbackFn);
    }
}

/*----------------------------------------------------------------------*/

/**
 * Special type of change which affects changes to the DOM.
 */
class DomChange {
    /**
     * Creates a new DomChange object.
     *
     * @param isAdd {Boolean} - whether this change adds an element to the
     * DOM, or is a removal change
     */
    constructor(isAdd) {
        this.isAdd = isAdd;
        this.apply = () => {
        };
        this.revert = () => {
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Binds functions to add/remove elements from the DOM. Association of
     * callbacks to this.apply() or this.remove() is decided by the this.isAdd
     * parameter.
     *
     * @param addCallback {Function} - callback to add element to the DOM
     * @param remCallback {Function} - callback to remove element from DOM
     */
    bindApplyRevert(addCallback, remCallback) {
        const add = () => {
            addCallback();
        };
        const remove = () => {
            remCallback();
        };

        this.apply = this.isAdd ? add : remove;
        this.revert = this.isAdd ? remove : add;
    }
}

/* src/History/History.js */
/**
 * Class to manage the drawer's history (keeping track of changes made).
 */
class History {
    /**
     * Creates a new instance.
     *
     * @param canClearScene {Boolean} - whether the drawer allows the history
     * to revert to its initial clean state (and thus emptying the scene)
     */
    constructor(canClearScene) {
        this.canClearScene = canClearScene;
        this.steps = [];
        this.curStep = -1;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a step to the history's steps array.
     *
     * @param step {HistoryStep} - step to add to the history
     */
    addNewStep(step) {
        this.steps.push(step);
        this.curStep++;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Removes all steps from the history's steps array after the current step.
     */
    removeFurtherSteps() {
        this.steps = this.steps.slice(0, this.curStep + 1);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Get the current history step.
     *
     * @returns {HistoryStep} - the current history step
     */
    getCurStep() {
        return this.steps[this.curStep];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Check whether any further steps exist after the current history step.
     *
     * @returns {Boolean} - whether any further steps exist
     */
    canAdvance() {
        return this.curStep + 1 !== this.steps.length;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Advances the current history step by 1.
     */
    advance() {
        this.curStep++;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether the history can be reverted by 1.
     *
     * @returns {Boolean} - whether the history can be reverted
     */
    canRevert() {
        return this.curStep >= (this.canClearScene ? 0 : 1);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reverts the current history step by 1.
     */
    revert() {
        this.curStep--;
    }
}

/*----------------------------------------------------------------------*/

/**
 * Class to represent a single step of the drawer's history.
 */
class HistoryStep {
    /**
     * Creates a new history step instance.
     */
    constructor() {
        this.changes = [];
        this.actions = new Set();
        this.opts;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a change made during this history step.
     *
     * @param change {Change} - object detailing functions to execute to
     * perform/revert the desired change
     */
    addChange(change) {
        this.changes.push(change);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds multiple changes made during this history step.
     *
     * @param changes {Array} - array of Change objects detailing functions to
     * execute/revert the desired change
     */
    addChanges(changes) {
        Array.prototype.push.apply(this.changes, changes);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Mark in the actions array that a certain type of change happened during
     * this history step.
     *
     * @param action {String} - the type of action to mark
     */
    addAction(action) {
        this.actions.add(action);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether any changes were made during this history step.
     *
     * @returns {Boolean} - whether any changes were made
     */
    hasChanges() {
        return this.changes.length > 0;
    }
}

/* src/InteractionDrawer.js */
/**
 * Initializes the drawer and exposes the main functionality to the user.
 * The sceneData object contains the data of the current scene.
 * The svgComponent object represents the view.
 * The svgDrawer manipulates both in order to update data and view.
 * The userInteractionHandler processes interactions of the user with the draw area with the
 * svgDrawer and interactionState objects.
 * The interactionState tracks the current state of the draw area and user interactions.
 */
class InteractionDrawer {
    /**
     * Sets up the library transferring style preferences from a configuration
     * object and sets up the the main instances for data, view manipulation and
     * user interaction tracking/handling.
     *
     * @param svgId {String} - DOM id of the svg
     * @param opts {Object} - configuration options for the drawer
     */
    constructor(svgId, opts = null) {
        this.optsPreprocessor = new OptsPreprocessor(opts);
        this.optsPreprocessor.processOpts();
        this.opts = this.optsPreprocessor.getOpts();

        if (!InteractionDrawer.svgExists(svgId)) {
            console.log('ERROR: svg does not exist');
            return;
        }

        this.svgDom = d3.select('#' + svgId).style('touch-action', 'none')
        this.svgComponent = new SvgComponent(this.opts, this.svgDom, svgId);
        const info = this.svgComponent.getDrawAreaInfo();

        this.sceneData = new SceneData(this.opts);
        this.sceneData.setInfoForDrawing(info.width, info.height);
        this.interactionState = new InteractionState(this.opts, this.sceneData);

        this.svgDrawer =
            new SvgDrawer(this.opts, this.sceneData, this.interactionState, this.svgComponent);

        this.userInteractionHandler = new UserInteractionHandler(this.opts,
            this.sceneData,
            this.interactionState,
            this.svgDrawer
        );
        this.userInteractionHandler.bindDrawAreaResizeBehavior();
        this.userInteractionHandler.bindUserInteractionHandling();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if draw area svg is available.
     *
     * @param svgId {String} - DOM id of the svg
     * @returns {Boolean} - false if svg element is not valid otherwise true
     */
    static svgExists(svgId) {
        if (typeof svgId === 'string') {
            const drawArea = document.getElementById(svgId);
            if (drawArea.tagName === 'svg') {
                return true;
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the inline browser SVG of the draw area, trim unnecessary
     * parts, then returns a Blob which contains the resulting string.
     *
     * @returns {Blob} - blob of serialized string in XML format containing inline
     * browser SVG information
     */
    getSvgBlob() {
        let xmlData = this.svgComponent.getSvgData()

        //get relevant scene data
        const {xMin, xMax, yMin, yMax} = this.sceneData.globalLimits;
        const {scale} = this.interactionState.transformParams;

        //set tight height and width for returned SVG with some excess space
        const excessSpace = 5;
        const sceneWidth = xMax - xMin + excessSpace * 2;
        const sceneHeight = yMax - yMin + excessSpace;
        //set fixed width and height in returned SVG data as attributes
        xmlData = xmlData.replace(/<svg.*?>/,
            (match) => {
                let xml1 = match.replace(
                    /width="[^"]*"/, `width="${sceneWidth * scale}"`
                );
                return xml1.replace(
                    /height="[^"]*"/, `height="${sceneHeight * scale}"`
                );
            });

        //functions to anchor current scene to upper left corner of draw area
        const curOrigin = this.interactionState.getRealCoordinates({x:0, y:0});
        const spaceLeft = -(curOrigin.x - xMin) - excessSpace / 2;
        const spaceTop = -(curOrigin.y - yMin) - excessSpace / 2;
        const correctWidth = (valStr) => {
            return (parseFloat(valStr) - spaceLeft).toString();
        };
        const correctHeight = (valStr) => {
            return (parseFloat(valStr) - spaceTop).toString();
        };

        //translate positional parameters of SVG elements via regex replace
        //carefully, something like -1e-8 can be set
        const nrRegexBase = '-?[0-9|e]+(?:.[0-9|e]+)?';
        const xParams = ['cx', 'x', 'x1', 'x2'];
        const yParams = ['cy', 'y', 'y1', 'y2'];
        //do not try to match path x- and y-values by a single regex, turns out
        //to be terrible performance-wise, rather match numbers lazy as (.*?)
        const paramRegexStr = `((?: |<))(${xParams.join('|')}|` +
            `${yParams.join('|')}|path d)(=")(.*?)(")`;
        const pathRegexStr = `(${nrRegexBase})( *)(${nrRegexBase})`;
        //define replacement function to be used
        const convertNumbers = (param, nrStr) => {
            if (param === 'path d'){
                return nrStr.replace(new RegExp(pathRegexStr, 'g'),
                    (match, p1, p2, p3) => {
                        return correctWidth(p1) + p2 + correctHeight(p3);
                    })
            } else if (xParams.includes(param)) {
                return correctWidth(nrStr);
            } else { //yParams.includes(param)
                return correctHeight(nrStr);
            }
        };
        //apply the full regex to the data string
        xmlData = xmlData.replace(new RegExp(paramRegexStr, 'g'),
            (match, p0, p1, p2, p3, p4) => {
                return p0 + p1 + p2 + convertNumbers(p1, p3) + p4;
            });
        return new Blob([xmlData], {type: 'image/svg+xml'});
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the JSON data of the draw area and
     * then returns a Blob which contains the resulting string.
     *
     * @returns {Blob} - blob of serialized JSON data
     */
    getJsonBlob() {
        const jsonBuilder = new JsonBuilder(this.sceneData, this.opts);
        return new Blob([jsonBuilder.getJson(true, true)], {type: 'application/json'});
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the JSON data of the draw area including the config
     * and then returns a Blob which contains the resulting string.
     *
     * @returns {Blob} - blob of serialized JSON data including the config
     */
    getJsonBlobWithConfig() {
        const jsonBuilder = new JsonBuilder(this.sceneData, this.opts);
        return new Blob(
            [jsonBuilder.getJsonWithConfig(true, true)],
            {type: 'application/json'}
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the JSON data of the draw area and returns the resulting string.
     *
     * @returns {Object} - JSON data
     */
    getJson() {
        const jsonBuilder = new JsonBuilder(this.sceneData, this.opts);
        return jsonBuilder.getJson(true, true);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Serializes the interaction data of the draw area and then returns a Blob
     * which contains the resulting string.
     *
     * @returns {Object} - blob of serialized interaction data
     */
    getTxtBlob() {
        const textBuilder = new TextBuilder(this.sceneData);
        return new Blob(
            [textBuilder.getInteractionsText(this.sceneData)],
            {type: 'text/plain'}
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Binds a set of interaction modes to specified mouse button presses with
     * optional modifiers. If a combination of mouse button and modifiers already
     * exists to trigger another interaction mode it gets deleted. It is not
     * recommended to bin any interaction to right click and one of the modifiers
     * being shift as this will trigger the contextmenu in firefox by releasing
     * the mouse button.
     *
     * @param interactions {Object} - holds interaction modes and pressed mouse
     * buttons with modifiers. The object of is structured as follows, where
     * interactionMode is e.g. movement, the key corresponds to the mouse button
     * and valid modifiers are 'ctrl','alt', and 'shift'
     * {
     *     interactionMode1:
     *     [
     *         {
     *             key: 0,
     *             modifiers: ['shift', 'alt']
     *         },{
     *             key: 1,
     *             modifiers: []
     *         }
     *     ],
     *     interactionMode2: [...],
     *     ...
     * }
     * @param clearAll {Boolean} - if true removes all previous bound interactions
     */
    addMouseInteractions(interactions, clearAll = false) {
        if (clearAll) this.opts.buttons.mouse = {};
        for (const [mode, configs] of Object.entries(interactions)) {
            for (const config of configs) {
                this.optsPreprocessor.addMouseInteraction(mode, config.key, config.modifiers);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Create a scene in the draw area based on a string in JSON format.
     *
     * @param jsonString {String} - string in JSON format representing the scene
     * @param center {Boolean} - whether to center the scene after adding the new
     * elements
     * added json based on already loaded jsons
     */
    addByJSON(jsonString, center = true) {
        if (!jsonString) {
            console.log('ERROR parsing: no JSON provided');
            return;
        }
        try {
            this.userInteractionHandler.addHandler.addToScene(jsonString, center);
        } catch (err) {
            console.log('ERROR parsing: Could not parse JSON:');
            console.log(err);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Use the ProteinsPlus REST API and create a scene in the draw area based
     * on either a PDB code or ProteinsPlus job id of an uploaded file and a ligand name.
     *
     * @param id {String} - 4 letter PDB code or ProteinsPlus id of an uploaded PDB file
     * @param ligandName {String} - name of the ligand in format molecule_chain_number,
     * e.g., 4SP_A_1298
     * @param reset {Boolean} - resets the scene before adding the diagram
     * @param processingCallback {Function} - callback to be called while the diagram is still
     * loading
     * @param preloadedCallback {Function} -  callback to be called before the drawing of the
     * fetched diagram starts
     * @param loadedCallback {Function} -  callback to be called after the loading of the diagram
     * has finished
     * @param errorCallback {Function} - callback to be called if the diagram could not be loaded
     * and an error occurred
     */
    addById(id, ligandName, reset = true, {
        processingCallback,
        preloadedCallback,
        loadedCallback,
        errorCallback
    } = {}) {
        const download = async () => {
            const responsePost = await fetch(
                'https://proteins.plus/api/poseview2_rest',
                {
                    method: 'POST',
                    body: '{"poseview2": {"pdbCode":"' + id +
                        '","ligand":"' + ligandName + '"}}',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    }
                });
            const jsonPost = await responsePost.json();

            //job will be executed or results already exists
            if (jsonPost.status_code === 202 || jsonPost.status_code === 200) {
                let polling = true;
                const delay = ms => new Promise(res => setTimeout(res, ms));

                while (polling) {

                    const responseGet = await fetch(jsonPost.location, {method: 'GET'});

                    let jsonGetStatus;
                    try {
                        jsonGetStatus = await responseGet.json();
                    } catch(e) {
                        errorCallback();
                        return;
                    }

                    //still calculating?
                    if (jsonGetStatus.status_code === 200) {
                        polling = false;
                        const responseGetResults = await fetch(
                            jsonGetStatus.result_json,
                            {method: 'GET'}
                        );
                        const jsonGetResults = await responseGetResults.json();
                        if (preloadedCallback) {
                            preloadedCallback();
                        }
                        if (reset || !this.sceneData.structuresData.structureLoaded) {
                            this.userInteractionHandler.removeHandler.fullReset();
                            this.addByJSON(JSON.stringify(jsonGetResults));
                        } else {
                            const jsonPreprocessor = new JsonPreprocessor(this.sceneData);
                            const  preprocessedDiagram =
                                jsonPreprocessor.prepAdditionalJsonCoordinatesUIds(
                                JSON.stringify(jsonGetResults)
                            );
                            this.addByJSON(preprocessedDiagram);
                        }
                        if (loadedCallback) {
                            loadedCallback();
                        }
                    } else if (jsonGetStatus.status_code === 202) {
                        if (processingCallback) {
                            processingCallback();
                        }
                        await delay(3000);
                    } else {
                        if (errorCallback) {
                            errorCallback();
                        }
                        console.log('ERROR: Could not download diagram');
                    }
                }
            } else {
                if (errorCallback) {
                    errorCallback();
                }
                console.log('ERROR: Could not download diagram');
            }
        }
        download();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Use the ProteinsPlus REST API and create a scene in the draw area based
     * on the content of a PDB file and a ligand name.
     *
     * @param fileContent {String} - file content of a PDB file
     * @param ligandName {String} - name of the ligand in format molecule_chain_number,
     * e.g., 4SP_A_1298
     * @param reset {Boolean} - resets the scene before loading the diagram
     * @param processingCallback {Function} - callback to be called while the diagram is still
     * loading
     * @param loadedCallback {Function} -  callback to be called after the loading of the diagram
     * has finished
     * @param errorCallback {Function} - callback to be called if the diagram could not be loaded
     * and an error occurred
     */
    addByFile(fileContent, ligandName, reset = true, {
        processingCallback,
        loadedCallback,
        errorCallback
    } = {}) {
        const upload = async () => {
            const form = new FormData();
            form.append(
                'pdb_file[pathvar]',
                new File([fileContent],
                    '/custom.pdb')
            );
            const responsePost = await fetch(
                'https://proteins.plus/api/pdb_files_rest',
                {
                    method: 'POST',
                    headers: {'Accept': 'application/json'},
                    body: form
                }
            );
            const jsonPost = await responsePost.json();

            if (responsePost.status === 202) {
                let polling = true;
                const delay = ms => new Promise(res => setTimeout(res, ms));

                while (polling) {
                    const responseGet = await fetch(jsonPost.location, {method: 'GET'});
                    const jsonGetStatus = await responseGet.json();

                    //still calculating?
                    if (responseGet.status === 200) {
                        polling = false;
                        this.addById(jsonGetStatus.id, ligandName, reset, {
                            processingCallback, loadedCallback, errorCallback
                        })
                    } else if (responseGet.status === 202) {
                        if (processingCallback) {
                            processingCallback();
                        }
                        await delay(3000);
                    } else {
                        if (errorCallback) {
                            errorCallback();
                        }
                        console.log('ERROR: Could not upload file');
                    }
                }
            } else {
                if (errorCallback) {
                    errorCallback();
                }
                console.log('ERROR: Could not upload file');
            }
        }
        upload();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Subscribe a number of callbacks to the drawer which are called at
     * different change steps.
     *
     * @param preprocessCallback {Function} - callback to be called before
     * processing JSON input during the creation of a new scene. Input for the
     * callback is the provided scene data in form of an object
     * Ex.: (scene) => { //preprocess the JSON info, e.g. scene.atoms //}
     *
     * @param sceneChangeCallback {Function} - callback to be called right
     * after fundamental parts of the scene have changed (i.e., coordinates or
     * existence of elements)
     * @param colorCallback {Function} - callback to be called right after
     * color changes have been applied to the scene
     * Ex. (any of the above): (sceneData) => { //do something with given
     * JSON string detailing new configuration of the scene //}
     *
     * @param hoverCallback {Function} - callback to be called after an
     * element has been hit during hover
     * Ex.: (hit) => { //check hit.type to see what element is hit, then
     * perform actions accordingly //}
     *
     * @param selectionCallback {Function} - callback to be called after the
     * current selection (of atoms/bonds) changes
     * Ex.: (info) => { //check info.type to see what element is hit and
     * info.selectionType for type of selection ('select' or 'unselect'), then
     * perform actions accordingly //}
     * @param clickInTheBlankCallback {Function} - callback to be called after the
     * the scene was clicked in the blank
     * @param multiSelectionCallback {Function} - callback to be called after the lasso or rectangle
     * selection has finished
     * @param removeCallback {Function} - callback to be called after removing of objects in the
     * scene
     * @param optsCallback {Function} - callback for the inspection of the opts used for the
     * corresponding history step
     */
    setCallbacks({
        preprocessCallback,
        sceneChangeCallback,
        colorCallback,
        hoverCallback,
        selectionCallback,
        clickInTheBlankCallback,
        multiSelectionCallback,
        removeCallback,
        optsCallback
    }) {
        if (preprocessCallback) {
            this.svgDrawer.preprocessCallback = preprocessCallback;
        }
        if (sceneChangeCallback) {
            this.svgDrawer.historyDrawer.sceneChangeCallback = sceneChangeCallback;
        }
        if (colorCallback) {
            this.svgDrawer.historyDrawer.colorCallback = colorCallback;
        }
        if (optsCallback) {
            this.svgDrawer.historyDrawer.optsCallback = optsCallback;
        }
        if (hoverCallback) {
            this.userInteractionHandler.hoverHandler.hoverCallback = hoverCallback;
        }
        if (selectionCallback) {
            this.svgDrawer.atomDrawer.selectionCallback = selectionCallback;
            this.svgDrawer.edgeDrawer.selectionCallback = selectionCallback;
            this.svgDrawer.annotationDrawer.selectionCallback = selectionCallback;
            this.svgDrawer.intermolecularDrawer.selectionCallback = selectionCallback;
            this.svgDrawer.structureCircleDrawer.selectionCallback = selectionCallback;
        }
        if (clickInTheBlankCallback) {
            this.userInteractionHandler.clickSelectionHandler.clickInTheBlankCallback =
                clickInTheBlankCallback;
        }
        if (multiSelectionCallback) {
            this.userInteractionHandler.lassoSelectionHandler.multiSelectionCallback =
                multiSelectionCallback;
            this.userInteractionHandler.rectangleSelectionHandler.multiSelectionCallback =
                multiSelectionCallback;
        }
        if (removeCallback) {
            this.svgDrawer.removeCallback = removeCallback;
        }
    }
}


/* src/InteractionTracking/BoundaryUpdateInfo.js */
/**
 * Container class to keep track of how the application of different changes
 * alters the boundaries of a geometrical structure.
 */
class BoundaryUpdateInfo {
    /**
     * For each given structural boundary (i.e., xMin, xMax, yMin, yMax),
     * keeps track of the current maximum/minimum and how this value has changed
     * since the last history step (as changeDir: 0 -> no change, 1 -> new
     * max/min was found, -1 -> uncertain about current max/min, marked for
     * required recalculation).
     *
     * @param structBounds {Object} - initial boundaries of the observed
     * structure
     */
    constructor(structBounds) {
        this.xMin = {
            changeDir: 0, val: structBounds.xMin
        };
        this.xMax = {
            changeDir: 0, val: structBounds.xMax
        };
        this.yMin = {
            changeDir: 0, val: structBounds.yMin
        };
        this.yMax = {
            changeDir: 0, val: structBounds.yMax
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on old and new boundaries of the structure, marks changes.
     *
     * @param oldLimits {Object} - boundaries of the observed structure before
     * changes were applied
     * @param newLimits {Object} - boundaries of the observed structure after
     * changes were applied
     */
    updateMaxesByLimits(oldLimits, newLimits) {
        this.updateMaxes('xMin', oldLimits.xMin, newLimits.xMin, false);
        this.updateMaxes('xMax', oldLimits.xMax, newLimits.xMax, true);
        this.updateMaxes('yMin', oldLimits.yMin, newLimits.yMin, false);
        this.updateMaxes('yMax', oldLimits.yMax, newLimits.yMax, true);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks changes to a specific boundary based on its old and new value.
     *
     * @param prop {String} - identifier of the boundary (xMin, xMax, yMin,
     * or yMax)
     * @param oldVal {Number} - old value of the boundary
     * @param newVal {Number} - new value of the boundary
     * @param largestIsLim {Boolean} - whether the boundary describes a
     * maximum or a minimum
     */
    updateMaxes(prop, oldVal, newVal, largestIsLim) {
        if (!this.updateMaxesLim(prop, newVal, largestIsLim)) {
            this.updateMaxesNeg(prop, oldVal, largestIsLim);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks whether a new value is a new maximum/minimum of a boundary and
     * if so, mark the corresponding changeDir as 1.
     *
     * @param prop {String} - identifier of the boundary (xMin, xMax, yMin,
     * or yMax)
     * @param newVal {Number} - new value of the boundary
     * @param largestIsLim {Boolean} - whether the boundary describes a
     * maximum or a minimum
     * @returns {Boolean} - whether input value is new maximum/minimum
     */
    updateMaxesLim(prop, newVal, largestIsLim) {
        const limit = this[prop];
        if (largestIsLim) {
            if (newVal >= limit.val) {
                this.setMaxesLim(prop, newVal);
                return true;
            }
        } else {
            if (newVal <= limit.val) {
                this.setMaxesLim(prop, newVal);
                return true;
            }
        }
        return false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if a (now changed) old value was previously the maximum/minimum
     * of a boundary and if so, mark the corresponding changeDir as -1.
     *
     * @param prop {String} - identifier of the boundary (xMin, xMax, yMin,
     * or yMax)
     * @param oldVal {Number} - the old value of the boundary
     * @param largestIsLim {Boolean} - whether the boundary describes a
     * maximum or a minimum
     */
    updateMaxesNeg(prop, oldVal, largestIsLim) {
        const limit = this[prop];
        if (largestIsLim) {
            if (oldVal === limit.val && !limit.changeDir) { //smaller
                this.setMaxesNeg(prop);
            }
        } else {
            if (oldVal === limit.val && !limit.changeDir) { //larger
                this.setMaxesNeg(prop);
            }
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * During adding of new elements to a structure, updates its boundaries
     * based on the element's boundaries.
     *
     * @param xMin {Number} - minimum x-coordinate of the added element's
     * bounding box
     * @param xMax {Number} - maximum x-coordinate of the added element's
     * bounding box
     * @param yMin {Number} - minimum y-coordinate of the added element's
     * bounding box
     * @param yMax {Number} - maximum y-coordinate of the added element's
     * bounding box
     */
    setMaxesAdd(xMin, xMax, yMin, yMax) {
        if (xMin < this.xMin.val) this.setMaxesLim('xMin', xMin);
        if (xMax > this.xMax.val) this.setMaxesLim('xMax', xMax);
        if (yMin < this.yMin.val) this.setMaxesLim('yMin', yMin);
        if (yMax > this.yMax.val) this.setMaxesLim('yMax', yMax);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Updates the tracking information for a boundary when a new maximum/
     * minimum is found.
     *
     * @param prop {String} - identifier of the boundary (xMin, xMax, yMin,
     * or yMax)
     * @param val {Number} - new maximum/minimum
     */
    setMaxesLim(prop, val) {
        this[prop] = {
            changeDir: 1, val: val
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Marks a boundary for necessary recalculation.
     *
     * @param prop {String} - identifier of the boundary (xMin, xMax, yMin,
     * or yMax)
     */
    setMaxesNeg(prop) {
        this[prop].changeDir = -1;
    }
}


/* src/InteractionTracking/InteractionObject.js */
/**
 * Class to keep track of elements affected by the different interaction modes
 * available for the InteractionDrawer.
 */
class InteractionObject {
    /**
     * Sets up the different containers for information tracking for the
     * different interaction modes.
     *
     * @param moveGrace {Number} - allowed movement until which only selection
     * happens (in px)
     */
    constructor(moveGrace = 0) {
        this.active = false; //whether interaction currently takes place
        //start coordinates - do NOT reset this at disable interaction!
        this.start = null;
        this.mode = undefined; //how the scene is affected
        this.grace = moveGrace;

        //affected elements for the different interaction modes
        this.lineMirror = {
            curMode: InteractionMode.lineMirror
        };
        this.addAnnotation = {
            curMode: InteractionMode.addAnnotation
        };
        this.addStructure = {
            curMode: InteractionMode.addStructure
        };
        this.edit = {
            curMode: InteractionMode.edit
        };
        this.addGeomineQueryVirtualPoint = {
            curMode: InteractionMode.addGeomineQueryVirtualPoint
        };
        this.fullReset();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked information for all interaction modes.
     */
    fullReset() {
        this.resetAllButMirrorInfo();
        this.resetMirrorInfo();
        this.resetAddAnnotationInfo();
        this.resetAddStructureInfo();
        this.resetEditInfo();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked information for all interaction modes except the bond
     * mirror interaction mode which has to retain its information while a bond
     * stays hovered to iteratively mirror different halves of a structure.
     */
    resetAllButMirrorInfo() {
        this.resetMovementInfo();
        this.resetRotationInfo();
        this.resetScaledRotationInfo();
        this.resetLineMirrorInfo();
        this.resetRemoveInfo();
        this.resetSelectionCandidates();
        this.resetAddIntermolecularInfo();
        this.resetAddAtomInfo();
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked draw elements to be moved in the movement interaction
     * mode.
     */
    resetMovementInfo() {
        this.movement = {
            canMove: false, //if movement is permitted currently
            didMove: false, //if movement has occurred
            fullStructures: [], //structures to move all elements for
            partialStructures: [], //structures to move individual atoms for
            ringSystems: {}, //ring systems containing any moved atoms
            //ALL individual atoms to move (including in full structures)
            individualAtoms: {}, //individual atoms to move
            annotations: new Set(), //individual annotations to move
            splineControlPoints: {}, //individual spline points to move
            distances: new Set(), //individual distances to move
            interactions: new Set(), //individual interactions to move
            atomPairInteractions: new Set(), //individual atom pair interactions to move
            piStackings: new Set(), //individual pi-stackings to move
            //individual cation-pi-stackings to move
            cationPiStackings: new Set()
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked draw elements to be rotated in the rotation
     * interaction mode.
     */
    resetRotationInfo() {
        this.rotation = {
            curRotation: 0, //full rotation until now, given in degrees
            type: 'fullScene',
            structures: [], //structures to move all elements for
            annotations: new Set(),
            splineControlPoints: {}, //individual spline points to move
            distances: new Set(), //individual distances to move
            interactions: new Set(), //individual interactions to move
            atomPairInteractions: new Set(), //individual atom pair interactions to move
            piStackings: new Set(), //individual pi-stackings to move
            //individual cation-pi-stackings to move
            cationPiStackings: new Set()
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the additionally required information for the scaled rotation
     * interaction mode (which, as an extension to the rotation mode, uses the
     * data in this.rotation as a base).
     */
    resetScaledRotationInfo() {
        this.scaledRotation = {
            rememberedAngle: 0
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the information on the bond to mirror parts of a structure on in
     * the bond mirror interaction mode.
     */
    resetMirrorInfo() {
        this.mirror = {
            edge: {
                structureId: undefined, edgeId: undefined
            }, side: 'small', atomsSmall: [], atomsLarge: []
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the draw elements to be mirrored on the free mirror line in the
     * line mirror interaction mode.
     */
    resetLineMirrorInfo() {
        //note that the current line mirror mode is not altered
        this.lineMirror.curStructureId = undefined;
        this.lineMirror.annotations = [];
        this.lineMirror.splineControlPoints = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reset the tracked draw elements to be moved in the movement interaction
     * mode.
     */
    resetRemoveInfo() {
        this.remove = {
            structures: new Set(),
            atoms: new Set(),
            edges: new Set(),
            annotations: new Set(),
            hydrophobicContacts: new Set(),
            atomPairInteractions: new Set(),
            piStackings: new Set(),
            cationPiStackings: new Set(),
            selected: false
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked elements to add intermolecular interaction by the
     * interaction mode.
     */
    resetAddIntermolecularInfo() {
        this.addIntermolecular = {
            endpoints: {
                first: undefined, second: undefined
            }, from: undefined, to: undefined, fromHydrophobic: {
                hydrophobicContactId: undefined, controlPointId: undefined
            }, toHydrophobic: {
                hydrophobicContactId: undefined, controlPointId: undefined
            }, fromStructure: undefined, toStructure: undefined
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked elements to add intermolecular interaction by the
     * interaction mode.
     */
    resetAddAtomInfo() {
        this.addAtom = {
            endpoints: {
                first: undefined, second: undefined
            }, from: undefined, fromStructure: undefined
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked elements to add intermolecular interaction by the
     * interaction mode.
     */
    resetAddAnnotationInfo() {
        this.addAnnotation.coords = undefined;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked elements to add structures by the interaction mode.
     */
    resetAddStructureInfo() {
        this.addStructure.coords = undefined;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets the tracked elements to add structures by the interaction mode.
     */
    resetEditInfo() {
        this.edit.coords = undefined;
        this.edit.object = undefined;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Resets information on current candidates for selection after current user
     * interaction is finished.
     */
    resetSelectionCandidates() {
        //structure id -> array of candidates by type ('atom', 'edge' or
        //'structureCircle') and id
        this.selectionCandidates = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Adds a potential candidate for selection.
     *
     * @param structureId {Number} - id of structure the candidate is part of
     * @param id {Number} - id of the candidate
     * @param type {String} - type of the candidate ('atom', 'edge'
     * or 'structureCircle')
     */
    addSelectionCandidate(structureId, id, type) {
        if (!this.selectionCandidates.hasOwnProperty(structureId)) {
            this.selectionCandidates[structureId] = [];
        }
        this.selectionCandidates[structureId].push({
            type: type, id: id
        });
    }
}


/* src/InteractionTracking/InteractionState.js */
/**
 * Class that keeps track of user interactions with the draw area and
 * and currently interacted with draw objects.
 */
class InteractionState {
    /**
     * Contains objects for configuration options, tracking and data access and
     * sets interaction states to default.
     *
     * @param opts {Object} - configuration options for the drawer
     * @param sceneData {Object} - data storage
     */
    constructor(opts, sceneData) {
        this.opts = opts;
        this.sceneData = sceneData;

        this.reset();
        if (this.opts.allowInteraction) {
            this.setMouseDefaultInteractionState();
        }
        this.drawAreaHovered = false;
        this.selectionHovered = false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set many important containers for structural information tracking to their
     * default (often empty) state. Useful when resetting the scene.
     */
    reset() {
        //current transformations on draw area (set when loading structures)
        this.transformParams = {
            scale: 1, translate: {
                x: 0, y: 0
            }, centerTranslate: {
                x: 0, y: 0
            }
        };

        //object to track draw objects with which the user currently interacts
        this.interaction = new InteractionObject(this.opts.selectionGrace);

        //interaction - for selection
        this.selectionPoints = [];
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set info relevant for all types of mouse interaction.
     */
    setMouseDefaultInteractionState() {
        this.cursorPos = null;
        this.mirrorLineInfo = {
            endpoints: {
                first: undefined, second: undefined
            }, structure: undefined
        };
        this.addIntermolecularType = IntermolecularType[Object.keys(IntermolecularType)[0]];
        this.addAtomType = {edit: false, element: 'C'};
        this.editType = EditType[Object.keys(EditType)[0]];
        this.resetEditType = false;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set what kind of atom gets added during the 'addAtom' mode and if an atom edit form
     * should be opened afterward.
     *
     * @param modeData {Object} - defines the data of the atom and how to handle it
     */
    setAddAtomType(modeData) {
        this.addAtomType = modeData;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set the type of what intermolecular interaction gets added during the
     * 'addIntermolecular' mode.
     *
     * @param type {String} - the interaction type (atomPairInteraction, piStacking,
     * cationPiStacking, hydrophobicContact)
     */
    setAddIntermolecularType(type) {
        if (Object.keys(IntermolecularType).includes(type)) {
            this.addIntermolecularType = IntermolecularType[type];
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Set the type of what object gets edited during the 'edit' mode.
     *
     * @param type {String} - the object type (atom, bond, annotation)
     */
    setEditType(type) {
        if (Object.keys(EditType).includes(type)) {
            this.editType = EditType[type];
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * The line mirror mode operates in two stages: choosing a structure to
     * apply mirroring to, and choosing the line to mirror on. This function is
     * used to alternate between the two stages and to adjust the object used
     * to track changes during interaction.
     */
    setNextLineMirrorMode() {
        const curMode = this.interaction.lineMirror.curMode;
        let nextIdentifier, nextMode;
        if (curMode === InteractionMode.lineMirror) {
            nextIdentifier = 'mirrorSelect';
            nextMode = InteractionMode.mirrorSelect;
        } else if (curMode === InteractionMode.mirrorSelect) {
            nextIdentifier = 'lineMirror';
            nextMode = InteractionMode.lineMirror;
        }
        if (this.opts.defaultInteraction === curMode) {
            this.setDefaultInteraction(nextIdentifier, true);
        }
        this.interaction.lineMirror.curMode = nextMode;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the default interaction mode to be chosen during user interaction
     * start when no modifier combinations of any other mode are met.
     *
     * @param identifier {String} - identifier string of the movement mode, see
     * the InteractionMode object in Enums.js
     * @param directSet {Boolean} - whether to also set this interaction mode
     * as the current interaction mode
     */
    setDefaultInteraction(identifier, directSet = false) {
        if (!InteractionMode.hasOwnProperty(identifier)) {
            console.log('Cannot set default interaction mode: Drawer does ' +
                `not recognize mode "${identifier}".`);
            return;
        }
        if (!this.opts.allowedInteraction.includes(identifier)) {
            console.log('Cannot set default interaction mode: Mode ' +
                `"${identifier}" is disabled by configuration.`);
            return;
        }
        const mode = InteractionMode[identifier];
        this.opts.defaultInteraction = mode;
        if (directSet) {
            this.setInteractionMode(mode);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Sets the user interaction mode.
     *
     * @param interactionMode {Number} - enum number of the interaction mode,
     * see the InteractionMode object in Enums.js
     */
    setInteractionMode(interactionMode) {
        this.interaction.mode = interactionMode;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Notes elements to be affected by the edge mirror interaction mode based
     * the currently hovered bond.
     *
     * @param structureId {Number} - id of the structure the hovered bond
     * belongs to
     * @param edgeId {Number} - id of the hovered bond
     */
    setInteractionEdgeMirror(structureId, edgeId) {
        if (this.interaction.mirror.edge.edgeId !== edgeId) {
            this.interaction.resetMirrorInfo();
            this.interaction.mirror.edge = {
                structureId: structureId, edgeId: edgeId
            };
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Notes elements to be affected by the rotation interaction mode based on
     * the currently hovered structure.
     *
     * @param structureId {Number} - id of the hovered structure
     * @param selectionHovered {Boolean} - element is currently hovered
     */
    setInteractionRotation(structureId, selectionHovered) {
        const rotation = this.interaction.rotation;
        if (selectionHovered) {
            const structure = this.sceneData.structuresData.structures[structureId];
            const structures = [], moveUnit = {};
            if (this.opts.moveFreedomLevel === 'structures') {
                this.getAffectedStructuresNoFreedom(selectionHovered,
                    structureId,
                    structure,
                    moveUnit,
                    structures
                );
            }
            //get all affected elements from structures
            const allAnnotations = new Set(), allDistances = new Set(), allInteractions = new Set(),
                allAtomPairInteractions = new Set(), allPiStackings = new Set(),
                allCationPiStackings = new Set(), allSplines = {};
            const merge = (connectedElements) => {
                const {
                    annotations,
                    distances,
                    interactions,
                    atomPairInteractions,
                    piStackings,
                    cationPiStackings,
                    splineControlPoints
                } = connectedElements;
                Helpers.mergeIntoSet(allAnnotations, annotations);
                Helpers.mergeIntoSet(allDistances, distances);
                Helpers.mergeIntoSet(allInteractions, interactions);
                Helpers.mergeIntoSet(allAtomPairInteractions, atomPairInteractions);
                Helpers.mergeIntoSet(allPiStackings, piStackings);
                Helpers.mergeIntoSet(allCationPiStackings, cationPiStackings);
                for (const splineId in splineControlPoints) {
                    allSplines[splineId] = splineControlPoints[splineId];
                }
            };
            structures.forEach(id => {
                const fullStructure = this.sceneData.structuresData.structures[id];
                merge(fullStructure.getConnectedElements());
            });
            rotation.type = 'multipleStructures';
            rotation.structures = structures;
            rotation.annotations = allAnnotations;
            rotation.distances = allDistances;
            rotation.interactions = allInteractions;
            rotation.atomPairInteractions = allAtomPairInteractions;
            rotation.piStackings = allPiStackings;
            rotation.cationPiStackings = allCationPiStackings;
            rotation.splineControlPoints = allSplines;
        } else {
            const structure = this.sceneData.structuresData.structures[structureId];
            const {
                annotations,
                distances,
                interactions,
                atomPairInteractions,
                piStackings,
                cationPiStackings,
                splineControlPoints
            } = structure.getConnectedElements();
            rotation.type = 'singleStructure';
            rotation.structures = [structureId];
            rotation.annotations = annotations;
            rotation.distances = distances;
            rotation.interactions = interactions;
            rotation.atomPairInteractions = atomPairInteractions;
            rotation.piStackings = piStackings;
            rotation.cationPiStackings = cationPiStackings;
            rotation.splineControlPoints = splineControlPoints;
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Notes elements to be affected by the line mirror interaction mode based
     * on the currently hovered structure.
     *
     * @param structureId {Number} - id of the hovered structure
     */
    setInteractionLineMirror(structureId) {
        const structure = this.sceneData.structuresData.structures[structureId];
        const {annotations, splineControlPoints} = structure.getConnectedElements();
        const lineMirror = this.interaction.lineMirror;
        lineMirror.curStructureId = structureId;
        lineMirror.annotations = annotations;
        lineMirror.splineControlPoints = splineControlPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Notes elements to be affected by the rotation interaction mode when the
     * entire scene shall be rotated.
     */
    setInteractionRotationFullScene() {
        const rotation = this.interaction.rotation;
        rotation.type = 'fullScene';
        rotation.structures = Object.keys(this.sceneData.structuresData.structures);
        rotation.annotations = new Set(Object.keys(this.sceneData.annotationsData.annotations));
        const intermolecularData = this.sceneData.intermolecularData;
        rotation.distances = new Set(Object.keys(intermolecularData.distances));
        rotation.interactions = new Set(Object.keys(intermolecularData.interactions));
        rotation.atomPairInteractions =
            new Set(Object.keys(intermolecularData.atomPairInteractions));
        rotation.piStackings = new Set(Object.keys(intermolecularData.piStackings));
        rotation.cationPiStackings = new Set(Object.keys(intermolecularData.cationPiStackings));
        const controlPoints = {};
        const hydrophobicContacts = this.sceneData.hydrophobicData.hydrophobicContacts;
        for (const hydrophobicId in hydrophobicContacts) {
            const spline = hydrophobicContacts[hydrophobicId];
            controlPoints[hydrophobicId] = spline.getControlPointIds();
        }
        rotation.splineControlPoints = controlPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Notes elements to be affected by the movement interaction mode based on
     * the currently hovered atoms, bonds and structure circles.
     *
     * @param structureId {Number} - id of the structure the hovered element
     * belongs to
     * @param id {Number} - id of the hovered element
     * @param type {String} - type of the hovered element ('atom' or 'edge')
     * @param selectionHovered {Boolean} - element is currently hovered
     */
    setInteractionMovement(structureId, id, type, selectionHovered) {
        const structure = this.sceneData.structuresData.structures[structureId];
        //find out which elements are affected by movement
        const fullStructures = [], partialStructures = [], moveUnit = {};
        if (this.opts.moveFreedomLevel === 'structures' || type === 'structureCircle') {
            this.getAffectedStructuresNoFreedom(selectionHovered,
                structureId,
                structure,
                moveUnit,
                fullStructures
            );
        } else { //harder case, need to obtain values first
            if (selectionHovered && this.opts.moveFreedomLevel !== 'rings') {
                this.getAffectedRingsFreedom(moveUnit, fullStructures, partialStructures);
            } else {
                this.getAffectedFullFreedom(structureId,
                    id,
                    type,
                    structure,
                    moveUnit,
                    fullStructures,
                    partialStructures
                );
            }
        }
        //get all affected elements from full and partial affected structures
        const allAnnotations = new Set(), allDistances = new Set(), allInteractions = new Set(),
            allAtomPairInteractions = new Set(), allPiStackings = new Set(),
            allCationPiStackings = new Set(), allSplines = {};
        const merge = (connectedElements) => {
            const {
                annotations,
                distances,
                interactions,
                atomPairInteractions,
                piStackings,
                cationPiStackings,
                splineControlPoints
            } = connectedElements;
            Helpers.mergeIntoSet(allAnnotations, annotations);
            Helpers.mergeIntoSet(allDistances, distances);
            Helpers.mergeIntoSet(allInteractions, interactions);
            Helpers.mergeIntoSet(allAtomPairInteractions, atomPairInteractions);
            Helpers.mergeIntoSet(allPiStackings, piStackings);
            Helpers.mergeIntoSet(allCationPiStackings, cationPiStackings);
            for (const splineId in splineControlPoints) {
                allSplines[splineId] = splineControlPoints[splineId];
            }
        };
        const ringSystems = {};
        fullStructures.forEach(fullSid => {
            const fullStructure = this.sceneData.structuresData.structures[fullSid];
            merge(fullStructure.getConnectedElements());
            ringSystems[fullSid] = Object.keys(fullStructure.ringsData.ringSystems);
        });
        partialStructures.forEach(partSid => {
            const partialStructure = this.sceneData.structuresData.structures[partSid];
            const movedAtoms = moveUnit[partSid];
            merge(partialStructure.getConnectedElementsForAtoms(movedAtoms, this.opts.moveFreedomLevel));
            ringSystems[partSid] = [
                ...partialStructure
                    .ringsData.getRingSystemsAffectedByAtoms(movedAtoms)
            ];
        });
        //mark in Interaction object all that can be moved
        const movement = this.interaction.movement;
        movement.fullStructures = fullStructures;
        movement.partialStructures = partialStructures;
        movement.ringSystems = ringSystems;
        movement.individualAtoms = moveUnit;
        movement.annotations = allAnnotations;
        movement.distances = allDistances;
        movement.interactions = allInteractions;
        movement.atomPairInteractions = allAtomPairInteractions;
        movement.piStackings = allPiStackings;
        movement.cationPiStackings = allCationPiStackings;
        movement.splineControlPoints = allSplines;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Finds out which structures are affected and if full or partial freedom level.
     *
     * @param selectionHovered {Boolean} - element is currently hovered
     * @param structureId {Number} - id of the structure the hovered element
     * belongs to
     * @param structure {Structure} - structure of the hovered element
     * belongs to
     * @param moveUnit {Map} - collects moved atoms (atom ids mapped to structure ids)
     * @param fullStructures {Array} - container to mark structures which are
     * moved as a whole
     */
    getAffectedStructuresNoFreedom(selectionHovered,
        structureId,
        structure,
        moveUnit,
        fullStructures
    ) {
        if (selectionHovered) {
            for (const selStructureId in this.sceneData.structuresData.structures) {
                const selStructure = this.sceneData.structuresData.structures[selStructureId];
                //find other affected elements
                if (selStructure.isSelected()) {
                    fullStructures.push(parseInt(selStructureId));
                    moveUnit[selStructureId] = selStructure.atomsData.atomIds.slice
                }
            }
        } else {
            fullStructures.push(structureId);
            moveUnit[structureId] = structure.atomsData.atomIds.slice();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Find all move units affected by current selection if rings freedom level.
     *
     * @param moveUnit {Map} - collects moved atoms (atom ids mapped to structure ids)
     * @param fullStructures {Array} - container to mark structures which are
     * moved as a whole
     * @param partialStructures {Array} - container to mark structures for
     * which only a subset of atoms is moved
     */
    getAffectedRingsFreedom(moveUnit, fullStructures, partialStructures) {
        for (const selStructureId in this.sceneData.structuresData.structures) {
            const selStructure = this.sceneData.structuresData.structures[selStructureId];
            //find other affected elements
            const movedAtoms = selStructure.edgesData.getAtomsAffectedBySelection();
            if (!movedAtoms.length) continue;
            moveUnit[selStructureId] = movedAtoms;
            this.checkFullStructureAffectedByAtoms(selStructureId,
                movedAtoms,
                fullStructures,
                partialStructures
            );
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Find all move units affected by current selection if full freedom level.
     *
     * @param structureId {Number} - id of the structure the hovered element
     * belongs to
     * @param id {Number} - id of the hovered element
     * belongs to
     * @param type {String} - type of the hovered element
     * belongs to
     * @param structure {Structure} - structure of the hovered element
     * belongs to
     * @param moveUnit {Map} - collects moved atoms (atom ids mapped to structure ids)
     * @param fullStructures {Array} - container to mark structures which are
     * moved as a whole
     * @param partialStructures {Array} - container to mark structures for
     * which only a subset of atoms is moved
     */
    getAffectedFullFreedom(structureId,
        id,
        type,
        structure,
        moveUnit,
        fullStructures,
        partialStructures
    ) {
        let movedAtoms;

        if (type === 'atom') {
            const structure = this.sceneData.structuresData.structures[structureId];
            movedAtoms = structure.getMoveUnitForAtom(id, this.opts.moveFreedomLevel);
        } else if (type === 'edge') {
            movedAtoms = structure.getMoveUnitForEdge(id, this.opts.moveFreedomLevel);
        }
        moveUnit[structureId] = movedAtoms;
        this.checkFullStructureAffectedByAtoms(structureId,
            movedAtoms,
            fullStructures,
            partialStructures
        );
    }

    /*----------------------------------------------------------------------*/

    /**
     * Determines whether a structure specified by id is fully affected by an
     * interaction on a given number of atoms and accordingly add its id to
     * either an array of fully or partially affected structures.
     *
     * @param structureId {Number} - id of the Structure object containing the
     * atoms
     * @param movedAtoms {Array} - ids of atoms to be moved
     * @param fullStructures {Array} - container to mark structures which are
     * moved as a whole
     * @param partialStructures {Array} - container to mark structures for
     * which only a subset of atoms is moved
     */
    checkFullStructureAffectedByAtoms(structureId, movedAtoms, fullStructures, partialStructures) {
        const structure = this.sceneData.structuresData.structures[structureId];
        if (structure.atomsData.isFullStructureAffected(movedAtoms)) {
            fullStructures.push(structureId);
        } else {
            partialStructures.push(structureId);
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on information set in interaction.rotation, finds the angle
     * between the current cursor position and the latest logged interaction
     * start point and infer the midpoint to be used in rotation.
     *
     * @param drawAreaCoords {Object} - x- and y-coordinates of current
     * cursor screen position translated to position in draw area
     * @returns {Object} - angle and scaled midpoint to be used in rotation
     */
    getRotationParameters(drawAreaCoords) {
        const startCoords = this.interaction.start;
        const {
            structures: affectedSids, type: rotaType, splineControlPoints: splineControlPoints
        } = this.interaction.rotation;
        //find out what kind of rotation is happening and its midpoint
        let realMid;
        if (rotaType === 'fullScene') {
            realMid = this.sceneData.midCoords;
        } else if (rotaType === 'singleStructure') {
            realMid =
                this.getTransformedCoordinates(this.sceneData.structuresData.structures[affectedSids[0]].getLimits().mid);
        } else if (rotaType === 'singleSpline') {
            for (const splineId in splineControlPoints) {
                const spline = this.sceneData.hydrophobicData.hydrophobicContacts[splineId];
                realMid = PointCalculation.findGeometricCenter(
                    spline.controlPoints.filter(cp => cp.enabled).map(cp => {
                        return this.getTransformedCoordinates(cp);
                    })
                );
            }
        } else if (rotaType === 'multipleStructures') {
            const midPoints = [];
            for (const affectedSid of affectedSids) {
                midPoints.push(
                    this.getTransformedCoordinates(
                        this.sceneData.structuresData.structures[affectedSid].getLimits().mid)
                );
            }
            realMid = PointCalculation.findGeometricCenter(midPoints);
        }
        //infer angle from midpoint and cursor positions
        let angle = AngleCalculation.radianToDegree(VectorCalculation.findAngleBetweenLines(realMid,
            drawAreaCoords,
            realMid,
            startCoords
        ));
        //infer sign of angle
        if (!Number.isNaN(angle)) {
            const clockwise = !LineCalculation.isLeft(realMid, startCoords, drawAreaCoords);
            if (!clockwise) angle = -angle;
        }
        return {
            angle: angle, //rotation applied around translated and scaled coordinates
            scaledMid: this.getRealCoordinates(realMid)
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * Checks if given offsets for movement exceed required minimum movement
     * specified in interaction.grace.
     *
     * @param offset {Object} - x- and y-offsets to move draw elements by
     * @returns {Boolean} - whether movement is allowed to happen
     */
    decideMovementPossible(offset) {
        let canMove = this.interaction.movement.canMove;
        if (!canMove) {
            if (PointCalculation.getDist2dByDists(offset.x, offset.y) > this.interaction.grace) {
                this.interaction.movement.canMove = true;
                canMove = true;
            }
        }
        return canMove;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Calculates offsets between the noted start of user interaction (which
     * is constantly updated) and the current cursor position.
     *
     * @param drawAreaCoords {Object} - x- and y-coordinates of current
     * cursor screen position translated to position in draw area
     * @returns {Object} - x- and y-offsets
     */
    getOffsetsToInteractionStart(drawAreaCoords) {
        const scale = this.transformParams.scale;
        return {
            x: (drawAreaCoords.x - this.interaction.start.x) / scale,
            y: (drawAreaCoords.y - this.interaction.start.y) / scale
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * Based on its upper left corner and lower right corner, creates the
     * corners of the selection rectangle and scale them based on current
     * translation parameters.
     *
     * @param startX {Number} - x-coordinate of the upper left corner
     * @param startY {Number} - y-coordinate of the upper left corner
     * @param endX {Number} - x-coordinate of the lower right corner
     * @param endY {Number} - y-coordinate of the lower right corner
     * @returns {Array} - corner points of the rectangle with x- and y-
     * coordinates
     */
    createRectSelection({x: startX, y: startY}, {x: endX, y: endY}) {
        let rectPoints = PolygonCalculation.createRectByBoundaries(startX, endX, startY, endY);
        const scale = this.transformParams.scale;
        const {translate: {x: translateX, y: translateY}} = this.transformParams;
        rectPoints = rectPoints.map(({x, y}) => {
            return {
                x: x / scale - translateX, y: y / scale - translateY
            }
        });
        return rectPoints;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Reversal of getRealCoordinates(): Translates a scaled position in the
     * draw area to pixel coordinates.
     *
     * @param x {Number} - x-coordinate of real position
     * @param y {Number} - y-coordinate of real position
     */
    getTransformedCoordinates({x, y}) {
        const {scale, translate: {x: translateX, y: translateY}} = this.transformParams;
        return {
            x: (x + translateX) * scale, y: (y + translateY) * scale
        };
    }

    /*----------------------------------------------------------------------*/

    /**
     * At the end of coordinate manipulating by hover interaction, cleans up internal
     * container tracking elements.
     */
    resetAfterHoverEnd() {
        if (!this.drawAreaHovered) {
            this.interaction.fullReset();
        }
    }

    /*----------------------------------------------------------------------*/

    /**
     * As the coordinate system gets translated / scaled, the parameters on
     * screen do no longer match the real coordinates of the draw area. This
     * function translates a perceived position in the draw area (by pixels)
     * to the real position in the scaled coordinate system.
     *
     * @param x {Number} - x-coordinate of perceived position
     * @param y {Number} - y-coordinate of perceived position
     */
    getRealCoordinates({x, y}) {
        const {scale, translate: {x: translateX, y: translateY}} = this.transformParams;
        return {
            x: x / scale - translateX, y: y / scale - translateY
        };
    }
}

/* src/InteractionTracking/StructureIdTracker.js */
/**
 * Class representing a container to track which unique ids belong to certain
 * outer (structure) ids.
 */
class StructureIdTracker {
    /**
     * Create a new StructureIdTracker object.
     */
    constructor() {
        this.container = {};
    }

    /*----------------------------------------------------------------------*/

    /**
     * Check if anything is currently tracked in the container.
     */
    hasEntries() {
        return Object.keys(this.container).length > 0;
    }

    /*----------------------------------------------------------------------*/

    /**
     * Note that a unique id belongs to a given structure id.
     *
     * @param structureId {Number} - structure id the given id belongs to
     * @param id {Number} - the unique id
     */
    addID(structureId, id) {
        if (!this.container.hasOwnProperty(structureId)) {
            this.container[structureId] = new Set();
        }
        this.container[structureId].add(id);
    }

    /*----------------------------------------------------------------------*/

    /**
     * Check if a unique id belongs to a given structure id.
     *
     * @param structureId {Number} - structure id the given id belongs to
     * @param id {Number} - the unique id
     */
    hasID(structureId, id) {
        if (!this.container.hasOwnProperty(structureId)) {
            return false;
        }
        return this.container[structureId].has(id);
    }
}

